const RAW = [{"q":"Xanh-ximông là đại biểu của trường phái nào?","o":["Chủ nghĩa xã hội không tưởng Pháp","Chủ nghĩa xã hội không tưởng Đức","Triết học cổ điển Đức","Kinh tế chính trị học Anh"],"a":[0],"e":"Xanh-ximông (Saint-Simon, 1760–1825) là nhà tư tưởng Pháp, cùng với Sáclơ Phuriê là đại biểu nổi tiếng nhất của chủ nghĩa xã hội không tưởng Pháp đầu thế kỷ XIX. Giáo trình xếp trào lưu này là một trong ba nguồn gốc lý luận của chủ nghĩa Mác, và là nguồn gốc trực tiếp của chủ nghĩa xã hội khoa học.","w":["","«Chủ nghĩa xã hội không tưởng Đức» không phải là trào lưu tiêu biểu được kể trong ba nguồn gốc lý luận của chủ nghĩa Mác; hơn nữa Xanh-ximông là người Pháp chứ không phải người Đức.","«Triết học cổ điển Đức» gắn với Cantơ, Hêghen, Phoiơbắc; Xanh-ximông không thuộc trường phái triết học này.","«Kinh tế chính trị học Anh» gắn với A. Xmít và Đ. Ricácđô; Xanh-ximông không phải nhà kinh tế chính trị cổ điển Anh."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục II.1 (Tiền đề lý luận ra đời triết học Mác); V.I. Lênin, «Ba nguồn gốc và ba bộ phận cấu thành của chủ nghĩa Mác» (1913).","c":1},{"q":"Quan hệ giữa người với người trong quá trình sản xuất được gọi là gì?","o":["Quan hệ xã hội","Quan hệ tổ chức quản lý","Quan hệ sản xuất","Quan hệ điều tiết"],"a":[2],"e":"Quan hệ sản xuất là quan hệ giữa người với người trong quá trình sản xuất vật chất, gồm ba mặt: quan hệ sở hữu tư liệu sản xuất, quan hệ tổ chức – quản lý sản xuất và quan hệ phân phối sản phẩm. Đây chính là định nghĩa giáo trình đưa ra khi trình bày phương thức sản xuất.","w":["«Quan hệ xã hội» quá rộng: nó bao gồm cả quan hệ chính trị, pháp quyền, đạo đức, gia đình…, không chỉ riêng quan hệ trong sản xuất.","«Quan hệ tổ chức quản lý» chỉ là một mặt (bộ phận) của quan hệ sản xuất, không phải toàn bộ quan hệ giữa người với người trong sản xuất.","","«Quan hệ điều tiết» không phải là một khái niệm của chủ nghĩa duy vật lịch sử để chỉ quan hệ giữa người với người trong sản xuất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất).","c":3},{"q":"Một sinh viên tóm tắt nội dung quy luật về sự phủ hợp giữa quan hệ sản xuất với trình độ như sau. Đáp án nào sau đây là đúng?","o":["Quy luật này vạch rõ sự phụ thuộc khách quan của lực lượng sản xuất vào quan hệ sản xuất","Sự hình thành, biến đổi và phát triển của quan hệ sản xuất được quyết định bởi lực lượng","Lực lượng sản xuất và quan hệ sản xuất là hai mặt của phương thức sản xuất, chúng tồn tại","Quy luật này chỉ tồn tại trong một vài xã hội"],"a":[1],"e":"Nội dung cốt lõi của quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất là: lực lượng sản xuất quyết định sự hình thành, biến đổi và phát triển của quan hệ sản xuất; quan hệ sản xuất tác động trở lại lực lượng sản xuất. Vì vậy câu tóm tắt «sự hình thành, biến đổi và phát triển của quan hệ sản xuất được quyết định bởi lực lượng sản xuất» là đúng.","w":["Câu này đảo ngược quan hệ quyết định: chính quan hệ sản xuất phụ thuộc vào lực lượng sản xuất, chứ không phải lực lượng sản xuất phụ thuộc khách quan vào quan hệ sản xuất.","","Câu «hai mặt của phương thức sản xuất, chúng tồn tại…» chỉ mô tả cấu trúc của phương thức sản xuất; nếu hiểu là hai mặt tồn tại tách rời, độc lập thì sai vì chúng thống nhất biện chứng, và dù sao câu này cũng chưa nêu được nội dung cốt lõi của quy luật là vai trò quyết định của lực lượng sản xuất.","Đây là quy luật phổ biến, tác động trong mọi hình thái kinh tế - xã hội của lịch sử, chứ không chỉ tồn tại trong một vài xã hội."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.2; C. Mác, «Lời tựa Góp phần phê phán khoa kinh tế chính trị» (1859).","c":3},{"q":"Tri thức nào sau đây nảy sinh một cách trực tiếp từ thực tiễn lao động sản xuất?","o":["Tri thức kinh nghiệm","Tri thức lý luận","Tri thức lý luận khoa học","Tri thức lý luận thực tiễn"],"a":[0],"e":"Tri thức kinh nghiệm là kết quả của nhận thức kinh nghiệm, hình thành từ sự quan sát trực tiếp sự vật, hiện tượng trong đời sống và lao động sản xuất hằng ngày (tri thức kinh nghiệm thông thường). Vì thế đây là loại tri thức nảy sinh trực tiếp từ thực tiễn lao động sản xuất.","w":["","«Tri thức lý luận» là nhận thức gián tiếp, trừu tượng, khái quát về bản chất, quy luật; nó được hình thành trên cơ sở tổng kết kinh nghiệm chứ không nảy sinh trực tiếp từ lao động.","«Tri thức lý luận khoa học» là trình độ còn cao và gián tiếp hơn nữa, đòi hỏi khái quát, hệ thống hoá; không nảy sinh trực tiếp từ thực tiễn sản xuất.","«Tri thức lý luận thực tiễn» không phải là một phân loại tri thức trong giáo trình; hơn nữa đã là lý luận thì mang tính gián tiếp."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục III (Lý luận nhận thức – nhận thức kinh nghiệm và nhận thức lý luận).","c":2},{"q":"Theo V.I.Lênin, quan điểm về đời sống, về thực tiễn phải là...của lý luận nhận thức:","o":["Điểm thứ nhất","Quan điểm đầu tiên","Quan điểm thứ nhất và cơ bản","Điều quan trọng"],"a":[2],"e":"Trong «Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán», Lênin viết: «Quan điểm về đời sống, về thực tiễn, phải là quan điểm thứ nhất và cơ bản của lý luận về nhận thức». Câu này nhấn mạnh thực tiễn là cơ sở, động lực, mục đích của nhận thức và là tiêu chuẩn của chân lý.","w":["«Điểm thứ nhất» không đúng nguyên văn và thiếu chữ «cơ bản», làm mất ý nhấn mạnh vai trò nền tảng của thực tiễn.","«Quan điểm đầu tiên» chỉ nói về thứ tự, bỏ mất tính «cơ bản» – ý quan trọng nhất trong câu của Lênin.","","«Điều quan trọng» là cách diễn đạt chung chung, không phải nguyên văn của Lênin."],"s":"V.I. Lênin, «Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán» (1909), Toàn tập, t.18, tr.167; Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục III (Vai trò của thực tiễn đối với nhận thức).","c":2},{"q":"Công lao của C.Mác và Ph.Ăngghen với nhận thức là gì?","o":["Phát hiện ra thế giới khách quan","Đưa phương pháp luận vào nhận thức","Đưa thực tiễn vào triết học","Đề ra tư tưởng đấu tranh chống lại giai cấp tư sản"],"a":[2],"e":"Công lao lớn của Mác và Ăngghen là đưa phạm trù thực tiễn vào triết học, vào lý luận nhận thức, khắc phục «khuyết điểm chủ yếu» của mọi chủ nghĩa duy vật trước đó (chỉ xem hiện thực dưới hình thức khách thể, trực quan). Tư tưởng này được nêu trong «Luận cương về Phoiơbắc», nơi Mác khẳng định chân lý phải được chứng minh trong thực tiễn.","w":["Thế giới khách quan đã được các nhà duy vật trước Mác thừa nhận từ thời cổ đại, nên «phát hiện ra thế giới khách quan» không phải công lao riêng của Mác và Ăngghen.","Phương pháp luận đã có trong triết học từ trước (ví dụ phép biện chứng của Hêghen); đóng góp đặc trưng của Mác và Ăngghen đối với nhận thức là quan điểm thực tiễn.","","Đấu tranh chống giai cấp tư sản là nội dung chính trị – xã hội, không phải công lao trực tiếp đối với lý luận nhận thức."],"s":"C. Mác, «Luận cương về Phoiơbắc» (1845), luận cương 1 và 2; Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục III.","c":2},{"q":"Nhận thức cảm tính được thực hiện dưới những hình thức nào?","o":["Tri giác, phán đoán và suy luận","Cảm giác, tri giác và khái niệm","Cảm giác, tri giác và biểu tượng","Khái niệm và phán đoán"],"a":[2],"e":"Nhận thức cảm tính (trực quan sinh động) là giai đoạn đầu của nhận thức, gồm ba hình thức kế tiếp nhau: cảm giác, tri giác và biểu tượng. Ở giai đoạn này con người phản ánh trực tiếp các thuộc tính bề ngoài của sự vật qua giác quan.","w":["«Phán đoán và suy luận» là hình thức của nhận thức lý tính (tư duy trừu tượng), không thuộc nhận thức cảm tính.","«Khái niệm» là hình thức của nhận thức lý tính, nên tổ hợp này trộn lẫn hai giai đoạn nhận thức.","","«Khái niệm và phán đoán» đều là hình thức của nhận thức lý tính."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục III (Các giai đoạn cơ bản của quá trình nhận thức).","c":2},{"q":"Đứng im, cân bằng chỉ xảy ra trong một số quan hệ nhất định chứ không phải trong mọi quan hệ là tính chất:","o":["Thực tế","Tuyệt đối","Tương đối","Thường xuyên"],"a":[2],"e":"Theo triết học Mác-Lênin, vận động là tuyệt đối còn đứng im là tương đối, tạm thời. Đứng im là tương đối vì nó chỉ xảy ra trong một mối quan hệ nhất định chứ không phải trong mọi quan hệ cùng một lúc, và chỉ với một hình thức vận động nhất định.","w":["«Thực tế» không phải là phạm trù dùng để chỉ tính chất của đứng im trong triết học Mác-Lênin.","«Tuyệt đối» là tính chất của vận động; nói đứng im là tuyệt đối sẽ rơi vào quan điểm siêu hình.","","«Thường xuyên» mâu thuẫn với chính nội dung câu hỏi: đứng im chỉ tạm thời, chỉ trong một số quan hệ nhất định."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục I.1 (Vật chất – Phương thức tồn tại của vật chất: vận động và đứng im).","c":2,"id":"ag6uve"},{"q":"A là một sinh viên có học lực kém, nên gia đình và Thầy/Cô đã khuyên A nên cố gắng. Thấy được vấn đề, A đã ra sức học tập để tích lũy kiến thức, trải qua một khoảng thời gian bạn thành một học sinh giỏi mà còn đạt được học bổng do Đại học FPT cung cấp. Căn cứ vào kiến thức ở môn Triết học, trường hợp bạn A thuộc 1 trong 3 quy luật nào sau đây?","o":["Quy luật từ những sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại","Quy luật thống nhất và đấu tranh giữa các mặt đối lập","Quy luật phủ định của phủ định","Quy luật phát triển"],"a":[0],"e":"Bạn A kiên trì tích lũy kiến thức (thay đổi dần về lượng) đến một giới hạn nhất định thì có bước nhảy, chuyển từ học lực kém thành học sinh giỏi, đạt học bổng (thay đổi về chất). Đây là minh hoạ điển hình cho quy luật chuyển hoá từ những thay đổi về lượng dẫn đến những thay đổi về chất và ngược lại.","w":["","Quy luật thống nhất và đấu tranh của các mặt đối lập vạch ra nguồn gốc, động lực của phát triển (mâu thuẫn); tình huống này nhấn mạnh quá trình tích lũy dẫn đến biến đổi chất.","Quy luật phủ định của phủ định nói về khuynh hướng phát triển theo đường «xoáy ốc», có kế thừa và lặp lại; tình huống không thể hiện chu kỳ phủ định hai lần.","«Quy luật phát triển» không phải là tên của một trong ba quy luật cơ bản của phép biện chứng duy vật."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục II.3 (Các quy luật cơ bản của phép biện chứng duy vật – quy luật lượng – chất).","c":2},{"q":"Đâu là một phát minh vĩ đại của C.Mác đã đem lại một cuộc cách mạng trong triết học về xã hội?","o":["Chủ nghĩa duy vật lịch sử","Chủ nghĩa duy tâm khách quan","Chủ nghĩa duy tâm chủ quan","Chủ nghĩa duy vật chất phát"],"a":[0],"e":"Bằng việc vận dụng chủ nghĩa duy vật biện chứng vào xã hội, Mác sáng lập chủ nghĩa duy vật lịch sử, tạo ra cuộc cách mạng thật sự trong học thuyết về xã hội. Lênin đánh giá: «Chủ nghĩa duy vật lịch sử của Mác là thành tựu vĩ đại nhất của tư tưởng khoa học»; Ăngghen cũng coi đây là một trong hai phát kiến vĩ đại của Mác (cùng học thuyết giá trị thặng dư).","w":["","Chủ nghĩa duy tâm khách quan (ví dụ Platôn, Hêghen) có từ trước Mác và đối lập với lập trường duy vật của Mác.","Chủ nghĩa duy tâm chủ quan (ví dụ Béccơli, Hium) cũng có trước Mác và bị Mác phê phán.","«Chủ nghĩa duy vật chất phác» là hình thức duy vật thời cổ đại, không phải phát minh của Mác."],"s":"V.I. Lênin, «Ba nguồn gốc và ba bộ phận cấu thành của chủ nghĩa Mác» (1913); Ph. Ăngghen, «Bài phát biểu trước mộ Các Mác» (1883); Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục II.1.","c":1},{"q":"Sự khác biệt cơ bản nhất giữa các giai cấp là địa vị của họ trong:","o":["Quyền lực chính trị","Quyền lực nhà nước","Quyền lực quản lý kinh tế","Quyền lực sở hữu tư liệu sản xuất"],"a":[3],"e":"Theo định nghĩa của Lênin trong «Sáng kiến vĩ đại», các giai cấp khác nhau về địa vị trong một hệ thống sản xuất xã hội nhất định, trong đó yếu tố quyết định là quan hệ của họ đối với tư liệu sản xuất. Chính quan hệ sở hữu tư liệu sản xuất quyết định vai trò trong tổ chức lao động và cách thức hưởng thụ của cải.","w":["Quyền lực chính trị là hệ quả của địa vị kinh tế; giai cấp nắm tư liệu sản xuất mới trở thành giai cấp thống trị về chính trị.","Quyền lực nhà nước cũng là biểu hiện về mặt chính trị, phái sinh từ địa vị kinh tế, không phải tiêu chí cơ bản nhất.","Vai trò quản lý kinh tế là một dấu hiệu trong định nghĩa của Lênin nhưng nó phụ thuộc vào quan hệ sở hữu tư liệu sản xuất.",""],"s":"V.I. Lênin, «Sáng kiến vĩ đại» (1919), Toàn tập, t.39, tr.17-18; Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục II.1 (Giai cấp).","c":3},{"q":"Thuyết có thể biết còn gọi là gì?","o":["Thuyết nhận biết","Thuyết khả tri","Thuyết khả tri luận","Thuyết nhận biết luận"],"a":[2],"e":"Khi giải quyết mặt thứ hai của vấn đề cơ bản của triết học (con người có nhận thức được thế giới hay không), học thuyết khẳng định khả năng nhận thức của con người được gọi là «thuyết có thể biết», tức thuyết khả tri (khả tri luận); đối lập với nó là thuyết không thể biết (thuyết bất khả tri). Theo đáp án của đề, tên gọi được chọn là «Thuyết khả tri luận».","w":["«Thuyết nhận biết» không phải là thuật ngữ triết học dùng để gọi thuyết có thể biết.","«Thuyết khả tri» thực chất cũng là tên gọi giáo trình dùng (khả tri = có thể biết), nhưng đề này chọn cách gọi đầy đủ «khả tri luận»; khi làm bài cần chú ý đáp án mà đề chấp nhận.","","«Thuyết nhận biết luận» là cách ghép từ không có trong thuật ngữ triết học."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.2 (Vấn đề cơ bản của triết học – Thuyết có thể biết và thuyết không thể biết).","k":"nghi vấn: Giáo trình 2021 ghi «Thuyết có thể biết (Thuyết Khả tri)», tức trùng khớp nhất với phương án «Thuyết khả tri»; «Thuyết khả tri luận» chỉ là biến thể đồng nghĩa (thừa chữ «thuyết»/«luận»). Hai phương án gần như đồng nghĩa nên đáp án của đề khó bảo vệ.","c":1},{"q":"Nhân tố quyết định xu hướng phát triển của các hình thái kinh tế - xã hội là:","o":["Ý thức của gia cấp nắm quyền lực nhà nước","Ý trí của nhân dân","Quy luật khách quan","Điều kiện khách quan và chủ quan của mỗi xã hội"],"a":[2],"e":"Mác khẳng định sự phát triển của các hình thái kinh tế - xã hội là «một quá trình lịch sử - tự nhiên», tức diễn ra theo các quy luật khách quan (trước hết là quy luật quan hệ sản xuất phù hợp với lực lượng sản xuất và quy luật cơ sở hạ tầng quyết định kiến trúc thượng tầng), chứ không theo ý muốn chủ quan. Do đó quy luật khách quan là nhân tố quyết định xu hướng phát triển chung.","w":["Ý thức của giai cấp cầm quyền chỉ tác động (thúc đẩy hoặc kìm hãm), không quyết định xu hướng khách quan của lịch sử; khẳng định ngược lại là duy tâm.","Ý chí của nhân dân là nhân tố chủ quan; nó có vai trò to lớn nhưng phải phù hợp với quy luật khách quan mới phát huy tác dụng.","","Điều kiện khách quan và chủ quan của mỗi xã hội ảnh hưởng đến con đường, hình thức, tốc độ cụ thể, còn xu hướng chung do quy luật khách quan quyết định."],"s":"C. Mác, «Tư bản», tập I, Lời tựa lần xuất bản thứ nhất (1867); Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.4 (Sự phát triển các hình thái kinh tế - xã hội là một quá trình lịch sử - tự nhiên).","c":3},{"q":"Khi quan hệ sản xuất được xem là phù hợp với tính chất và trình độ phát triển của lực lượng sản xuất?","o":["Thúc đẩy lực lượng sản xuất phát triển","Cải thiện đời sống nhân dân","Tạo điều kiện thực hiện công bằng xã hội","Yêu cầu phải thay thế lực lượng sản xuất mới"],"a":[0],"e":"Quan hệ sản xuất phù hợp với tính chất và trình độ của lực lượng sản xuất khi nó tạo «địa bàn», mở đường cho lực lượng sản xuất phát triển. Tiêu chí khách quan để đánh giá sự phù hợp chính là quan hệ sản xuất đó có thúc đẩy lực lượng sản xuất phát triển hay không.","w":["","Cải thiện đời sống nhân dân là kết quả có thể có của sản xuất phát triển, không phải tiêu chí trực tiếp xác định sự phù hợp giữa quan hệ sản xuất và lực lượng sản xuất.","Công bằng xã hội là mục tiêu xã hội – chính trị, không phải tiêu chí khách quan để đánh giá sự phù hợp của quan hệ sản xuất.","Khi quan hệ sản xuất phù hợp thì không đặt ra yêu cầu thay thế; hơn nữa chính quan hệ sản xuất lỗi thời mới là cái bị thay thế, không phải lực lượng sản xuất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.2 (Quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất).","c":3},{"q":"Theo cách phân chia các hình thức vận động của Ph.Ăngghen, hình thức vận động nào là thấp nhất, đơn giản nhất?","o":["Hình thức vận động cơ học","Hình thức vận động vật lý","Hình thức vận động hoá học","Hình thức vận động xã hội"],"a":[0],"e":"Trong «Biện chứng của tự nhiên», Ăngghen chia vận động thành năm hình thức cơ bản từ thấp đến cao: cơ học, vật lý, hoá học, sinh học và xã hội. Vận động cơ học – sự di chuyển vị trí của vật thể trong không gian – là hình thức thấp nhất, đơn giản nhất.","w":["","Vận động vật lý (vận động của phân tử, hạt cơ bản, nhiệt, điện…) cao hơn vận động cơ học.","Vận động hoá học (hoá hợp, phân giải các chất) cao hơn cả cơ học và vật lý.","Vận động xã hội là hình thức cao nhất, phức tạp nhất, bao hàm các hình thức thấp hơn."],"s":"Ph. Ăngghen, «Biện chứng của tự nhiên»; Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục I.1 (Các hình thức vận động cơ bản của vật chất).","c":2},{"q":"Luận điểm sau thuộc lập trường triết học nào: Quy luật trong các khoa học là sự sáng tạo chủ quan của con người và được áp dụng vào tự nhiên và xã hội.","o":["Chủ nghĩa duy vật siêu hình","Chủ nghĩa duy tâm khách quan","Chủ nghĩa duy vật biện chứng","Chủ nghĩa duy tâm chủ quan"],"a":[3],"e":"Luận điểm coi quy luật là «sự sáng tạo chủ quan của con người» rồi áp đặt vào tự nhiên và xã hội đã phủ nhận tính khách quan của quy luật, đặt ý thức cá nhân chủ thể làm nguồn gốc. Đó là lập trường của chủ nghĩa duy tâm chủ quan.","w":["Chủ nghĩa duy vật siêu hình vẫn thừa nhận thế giới và quy luật tồn tại khách quan, dù nhìn nhận một cách máy móc, cô lập.","Chủ nghĩa duy tâm khách quan coi quy luật là sự thể hiện của một «ý niệm tuyệt đối» hay tinh thần khách quan tồn tại ngoài con người, chứ không phải sáng tạo của chủ thể con người.","Chủ nghĩa duy vật biện chứng khẳng định quy luật mang tính khách quan, con người chỉ nhận thức và vận dụng chứ không sáng tạo ra quy luật.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.2 (Chủ nghĩa duy vật và chủ nghĩa duy tâm); Chương 2, mục II.2 (tính khách quan của quy luật).","c":1},{"q":"Theo quan điểm duy vật lịch sử, sự ra đời của nhà nước là để giải quyết các mâu thuẫn trong xã hội vì:","o":["Xã hội có mâu thuẫn thì cần phải có lực lượng đại diện cho xã hội để giải quyết nó","Kinh nghiệm thực tế cho thấy đúng như vậy","Nếu mâu thuẫn có thể giải quyết được thì không cần đến sự ra đời của nhà nước, sự ra đời của nó chỉ chứng tỏ rằng mâu thuẫn đã phát triển đến chỗ không thể giải quyết được nên cần đến sự ra đời của nhà nước.","Tất yếu của lịch sử nhân loại"],"a":[2],"e":"Theo chủ nghĩa duy vật lịch sử, nguyên nhân trực tiếp ra đời nhà nước là mâu thuẫn giai cấp không thể điều hoà được. Lênin viết: «Nhà nước là sản phẩm và biểu hiện của những mâu thuẫn giai cấp không thể điều hoà được… sự tồn tại của nhà nước chứng tỏ rằng những mâu thuẫn giai cấp là không thể điều hoà được».","w":["Quan niệm nhà nước là «lực lượng đại diện cho xã hội» đứng trên để giải quyết mâu thuẫn là quan điểm phi mácxít (thuyết khế ước, thuyết điều hoà giai cấp); thực chất nhà nước là công cụ của giai cấp thống trị.","«Kinh nghiệm thực tế» chỉ là lập luận cảm tính, không nêu được bản chất và nguyên nhân khách quan ra đời của nhà nước.","","Nói «tất yếu của lịch sử nhân loại» là quá chung chung và không chính xác: nhà nước chỉ ra đời ở một giai đoạn lịch sử nhất định (khi có giai cấp) và sẽ mất đi."],"s":"V.I. Lênin, «Nhà nước và cách mạng» (1917), Toàn tập, t.33, tr.9; Ph. Ăngghen, «Nguồn gốc của gia đình, của chế độ tư hữu và của nhà nước» (1884); Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục III.1 (Nhà nước).","c":3,"id":"1fprb1y"},{"q":"Chủ nghĩa duy vật lịch sử cho rằng, ý thức lý luận đạt trình độ cao và mang tính hệ thống tạo thành các:","o":["Hệ tư tưởng","Hệ kiến thức","Tri thức tổng hợp","Hệ thống tri thức"],"a":[0],"e":"Ý thức xã hội có hai trình độ: ý thức thông thường và ý thức lý luận. Ý thức lý luận là những tư tưởng, quan điểm đã được hệ thống hoá, khái quát hoá thành học thuyết; khi đạt trình độ cao và mang tính hệ thống thì tạo thành các hệ tư tưởng.","w":["","«Hệ kiến thức» không phải thuật ngữ của chủ nghĩa duy vật lịch sử để chỉ trình độ cao của ý thức lý luận.","«Tri thức tổng hợp» là cách gọi chung chung, không phải hình thức trình độ cao của ý thức xã hội.","«Hệ thống tri thức» quá rộng (khoa học tự nhiên cũng là hệ thống tri thức) và thiếu tính quan điểm, giai cấp vốn có của hệ tư tưởng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục IV (Ý thức xã hội – các cấp độ của ý thức xã hội: tâm lý xã hội và hệ tư tưởng).","c":3},{"q":"Chọn câu trả lời sai: Trong một hình thái kinh tế xã hội, quan hệ sản xuất có vai trò:","o":["Là quan hệ cơ bản, quyết định tất cả các quan hệ xã hội khác","Là cơ sở kinh tế của các hiện tượng xã hội","Thể hiện tính liên tục trong sự phát triển của xã hội loài người","Tiêu biểu cho bộ mặt xã hội ở mỗi giai đoạn phát triển nhất định"],"a":[2],"e":"Đây là câu chọn nhận định SAI. Thể hiện tính liên tục, tính kế thừa trong sự phát triển của xã hội loài người là vai trò của lực lượng sản xuất (thế hệ sau tiếp nhận lực lượng sản xuất do thế hệ trước để lại), không phải vai trò của quan hệ sản xuất, vì quan hệ sản xuất thay đổi căn bản khi chuyển từ hình thái này sang hình thái khác.","w":["Nhận định này đúng: giáo trình khẳng định quan hệ sản xuất là quan hệ cơ bản, quyết định các quan hệ xã hội khác, nên không phải câu cần chọn.","Nhận định này đúng: tổng hợp các quan hệ sản xuất hợp thành cơ sở hạ tầng – cơ sở kinh tế của các hiện tượng xã hội.","","Nhận định này đúng: quan hệ sản xuất là tiêu chuẩn khách quan để phân biệt các chế độ xã hội, tiêu biểu cho bộ mặt của xã hội ở từng giai đoạn lịch sử."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.2 và I.3 (Lực lượng sản xuất – quan hệ sản xuất; Cơ sở hạ tầng và kiến trúc thượng tầng); C. Mác, «Thư gửi P.V. Annenkov» (1846) về tính kế thừa của lực lượng sản xuất.","c":3},{"q":"Triết học có mấy vấn đề? Trong vấn đề có mấy mặt?","o":["1 mặt, 2 vấn đề","1 vấn đề, 1 mặt","1 vấn đề, 2 mặt","2 mặt, 2 vấn đề"],"a":[2],"e":"Theo Ăngghen trong «Lútvích Phoiơbắc và sự cáo chung của triết học cổ điển Đức», triết học có một vấn đề cơ bản là quan hệ giữa tư duy và tồn tại (ý thức và vật chất). Vấn đề này có hai mặt: mặt thứ nhất (bản thể luận) – cái nào có trước, cái nào quyết định; mặt thứ hai (nhận thức luận) – con người có khả năng nhận thức thế giới hay không.","w":["Đảo ngược số lượng: triết học có một vấn đề cơ bản, và vấn đề đó có hai mặt, chứ không phải một mặt hai vấn đề.","Vấn đề cơ bản có hai mặt chứ không chỉ một mặt; thiếu mặt nhận thức luận.","","Triết học chỉ có một vấn đề cơ bản, không phải hai."],"s":"Ph. Ăngghen, «Lútvích Phoiơbắc và sự cáo chung của triết học cổ điển Đức» (1886), C.Mác và Ph.Ăngghen Toàn tập, t.21, tr.403; Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.2.","c":1},{"q":"Nguyên nhân là phạm trù triết học chỉ:","o":["Tác động qua lại giữa các mặt, các yếu tố bên trong sự vật hay giữa sự vật này với sự vật khác tạo ra những biến đổi nhất định","Quan hệ giữa các mặt, các yếu tố bên trong sự vật hay giữa sự vật này với sự vật kia tạo nhất định","Sự chuyển hóa giữa các mặt, các yếu tố bên trong sự vật hay giữa sự vật này với sự vật khác biến đổi nhất định","(Không đủ thông tin)"],"a":[0],"e":"Theo phép biện chứng duy vật, nguyên nhân là phạm trù chỉ sự tác động lẫn nhau giữa các mặt trong một sự vật hoặc giữa các sự vật với nhau, gây ra một biến đổi nhất định; còn kết quả là những biến đổi xuất hiện do tác động đó. Điểm mấu chốt của định nghĩa là chữ «tác động» và hệ quả «tạo ra biến đổi».","w":["","«Quan hệ» giữa các mặt chưa đủ: không phải mọi quan hệ đều gây ra biến đổi, nguyên nhân phải là sự tác động gây ra biến đổi.","«Sự chuyển hóa» giữa các mặt mô tả quá trình biến đổi (gần với kết quả hoặc với quy luật lượng-chất), không phải là định nghĩa nguyên nhân.","Câu hỏi có đủ thông tin vì định nghĩa nguyên nhân được nêu rõ trong giáo trình."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục II.3 (các cặp phạm trù cơ bản: nguyên nhân và kết quả)","c":2},{"q":"Điều khẳng định nào sau đây đúng về mối quan hệ giữa lý luận và kinh nghiệm?","o":["Lý luận được hình thành từ kinh nghiệm trên cơ sở kinh nghiệm","Kinh nghiệm nhiều tự phát dẫn đến sự ra đời của lý luận","Mọi lý luận đều được xuất phát từ kinh nghiệm","Lý luận đi trước kinh nghiệm"],"a":[0],"e":"Lý luận là hệ thống tri thức được khái quát từ thực tiễn, nên nó hình thành trên cơ sở tổng kết kinh nghiệm. Tuy vậy, lý luận có tính độc lập tương đối: không phải mọi lý luận đều xuất phát trực tiếp từ kinh nghiệm, và có kinh nghiệm cũng không tự động sinh ra lý luận.","w":["","Kinh nghiệm tự phát không tự động sinh ra lý luận; phải có quá trình tư duy khái quát, trừu tượng hóa một cách tự giác.","«Mọi» lý luận là tuyệt đối hóa; có những lý luận ra đời từ lý luận trước đó hoặc đi trước kinh nghiệm, không xuất phát trực tiếp từ kinh nghiệm.","Nói lý luận đi trước kinh nghiệm như một nguyên tắc là sai, vì về căn bản lý luận được hình thành trên cơ sở kinh nghiệm; nó chỉ có thể vượt trước trong một số trường hợp."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục III (lý luận nhận thức: kinh nghiệm và lý luận)","c":2},{"q":"Điều kiện cơ bản để ý thức xã hội tác động trở lại tồn tại xã hội là:","o":["Ý thức xã hội phải vượt trước tồn tại xã hội","Ý thức xã hội phải phù hợp với tồn tại xã hội","Phải có hoạt động thực tiễn của con người","Phải có điều kiện vật chất bảo đảm"],"a":[2],"e":"Ý thức xã hội có tính độc lập tương đối và có thể tác động trở lại tồn tại xã hội, nhưng tự nó không thay đổi được hiện thực. Sự tác động ấy chỉ diễn ra thông qua hoạt động thực tiễn của con người: tư tưởng phải thâm nhập vào quần chúng và biến thành hành động vật chất.","w":["Vượt trước chỉ là một biểu hiện của tính độc lập tương đối, không phải điều kiện để tác động; ý thức lạc hậu cũng tác động trở lại (theo hướng kìm hãm).","Phù hợp với tồn tại xã hội chỉ quyết định chiều hướng tác động (thúc đẩy hay kìm hãm), không phải điều kiện để có tác động.","","«Điều kiện vật chất bảo đảm» là cách diễn đạt chung chung; giáo trình nhấn mạnh con đường cụ thể là hoạt động thực tiễn của con người."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục III.3 (tính độc lập tương đối của ý thức xã hội)","c":3},{"q":"Ai là người khẳng định \"cái sự hiển nhiên là trước hết con người cần phải ăn, uống, ở và mặc động, trước khi có thể đấu tranh để giành quyền thống trị, trước khi có thể hoạt động chính trị học...\"?","o":["C.Mác","Ph.Ăngghen","Platon","Immanuel Kant"],"a":[1],"e":"Câu này nằm trong «Bài phát biểu trước mộ Các Mác» (1883) của Ph.Ăngghen. Khi tổng kết công lao của Mác (phát hiện quy luật phát triển của lịch sử loài người), Ăngghen nói rằng con người trước hết cần phải ăn, uống, ở và mặc, rồi mới có thể làm chính trị, khoa học, nghệ thuật, tôn giáo. Ý tưởng là của chủ nghĩa duy vật lịch sử do Mác phát hiện, nhưng câu nói là của Ăngghen.","w":["Đây là tư tưởng mà Ăngghen khẳng định là phát hiện của Mác, nhưng câu nói được trích từ lời phát biểu của Ăngghen trước mộ Mác.","","Platon là nhà duy tâm khách quan Hy Lạp cổ đại, coi thế giới ý niệm là gốc, không đề cao nhu cầu vật chất như vậy.","I.Kant là nhà triết học cổ điển Đức theo khuynh hướng duy tâm, không phải tác giả câu nói theo quan niệm duy vật về lịch sử này."],"s":"Ph.Ăngghen, «Bài phát biểu trước mộ Các Mác» (1883), C.Mác và Ph.Ăngghen Toàn tập, t.19; Giáo trình Triết học Mác-Lênin (2021), Chương 3, mục I.1","c":3},{"q":"Quan điểm của chủ nghĩa Mác-Lênin về lãnh tụ là:","o":["Tất cả các đáp án đều đúng","Những cá nhân kiệt xuất có sự gắn bó với quần chúng nhân dân","Những cá nhân kiệt xuất được quần chúng tín nhiệm","Những cá nhân kiệt xuất tự nguyện hy sinh bản thân mình vì lợi ích của quần chúng nhân"],"a":[0],"e":"Theo chủ nghĩa Mác-Lênin, lãnh tụ là cá nhân kiệt xuất, có tri thức khoa học uyên bác, nắm bắt được xu thế của dân tộc và thời đại. Lãnh tụ có năng lực tập hợp quần chúng nên được quần chúng tín nhiệm, gắn bó mật thiết với quần chúng và hy sinh vì lợi ích của quần chúng. Vì vậy cả ba nhận định đều là những phẩm chất của lãnh tụ.","w":["","Đúng nhưng chưa đủ: sự gắn bó với quần chúng chỉ là một trong các phẩm chất của lãnh tụ.","Đúng nhưng chưa đủ: được quần chúng tín nhiệm chỉ là một mặt, còn thiếu tri thức, sự gắn bó và tinh thần hy sinh.","Đúng nhưng chưa đủ: tinh thần hy sinh vì lợi ích quần chúng chỉ là một phẩm chất riêng lẻ."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục V.3 (vai trò của quần chúng nhân dân và lãnh tụ)","c":3,"f":1},{"q":"Trên mạng xã hội hiện nay như Facebook, TikTok... đã xuất hiện nhiều nhân vật không có chủ kiến khi phát ngôn, lối sống của họ đã bị chi phối bởi những điều tiêu cực và trở nên lệch chuẩn, thuần phong mỹ tục, truyền thống văn hóa của dân tộc Việt Nam để câu View, câu like. Theo Anh/chị là hiện tượng gì đã đề cập trong nội dung môn triết học?","o":["Hiện tượng câu Like, câu View trên mạng xã hội","Hiện tượng xem thường người khác","Hiện tượng tha hóa con người","Hiện tượng xã hội"],"a":[2],"e":"Tha hóa là hiện tượng con người đánh mất bản chất người của mình, bị chi phối bởi những lực lượng xa lạ và trở thành cái khác với chính mình. Những người trên mạng chạy theo lượt xem, lượt thích, đánh mất chủ kiến và lệch khỏi chuẩn mực văn hóa chính là biểu hiện của sự tha hóa con người, một vấn đề được phân tích trong phần triết học về con người.","w":["«Câu like, câu view» chỉ mô tả lại hiện tượng bề ngoài, không phải một khái niệm triết học được giáo trình phân tích.","Xem thường người khác là một thái độ đạo đức cụ thể, không bao quát việc con người đánh mất bản chất và bị chi phối bởi cái tiêu cực.","","«Hiện tượng xã hội» quá rộng, hiện tượng nào trong xã hội cũng có thể gọi như vậy, nên không chỉ rõ bản chất vấn đề."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục V.2 (hiện tượng tha hóa con người); C.Mác, «Bản thảo kinh tế-triết học năm 1844»","c":3},{"q":"Trong quá trình nhận thức và hoạt động thực tiễn, chúng ta cần:","o":["Phủ nhận, gạt bỏ cái ngẫu nhiên","Cơ bản là phải căn cứ vào cái ngẫu nhiên nhưng đồng thời phải tính tới cái tất nhiên","Căn cứ vào cái tất nhiên và ngẫu nhiên","Cơ bản là phải căn cứ vào cái tất nhiên nhưng đồng thời phải tính tới cái ngẫu nhiên"],"a":[3],"e":"Cái tất nhiên do nguyên nhân bên trong quyết định và nhất định phải xảy ra, còn cái ngẫu nhiên có thể xảy ra hoặc không. Vì vậy trong nhận thức và thực tiễn, ta phải căn cứ chủ yếu vào cái tất nhiên, nhưng không được bỏ qua cái ngẫu nhiên vì nó có thể làm quá trình diễn ra nhanh hoặc chậm hơn, và cũng là hình thức biểu hiện của cái tất nhiên.","w":["Gạt bỏ cái ngẫu nhiên là sai, vì cái ngẫu nhiên có ảnh hưởng thật và là hình thức biểu hiện, bổ sung cho cái tất nhiên.","Đảo ngược vai trò: lấy cái ngẫu nhiên làm căn cứ cơ bản sẽ khiến hoạt động thiếu cơ sở vững chắc.","Đặt tất nhiên và ngẫu nhiên ngang hàng là không đúng, vì cái tất nhiên mới là căn cứ chủ yếu.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục II.3 (cặp phạm trù tất nhiên và ngẫu nhiên, ý nghĩa phương pháp luận)","c":2},{"q":"Theo quan điểm của triết học Mác - Lênin, \"tồn tại xã hội\" bao gồm:","o":["Dân số, ý thức xã hội, kiến trúc thượng tầng","Lực lượng sản xuất, dân số, phương thức sản xuất, ý thức xã hội","Môi trường tự nhiên, quan hệ sản xuất, tâm lý xã hội, hệ tư tưởng","Môi trường tự nhiên, dân số, phương thức sản xuất"],"a":[3],"e":"Tồn tại xã hội là toàn bộ sinh hoạt vật chất và điều kiện sinh hoạt vật chất của xã hội. Các yếu tố cơ bản của nó gồm phương thức sản xuất vật chất (giữ vai trò quyết định), điều kiện tự nhiên (hoàn cảnh địa lý) và dân số (mật độ dân số). Tất cả đều là yếu tố vật chất.","w":["Ý thức xã hội và kiến trúc thượng tầng là các yếu tố tinh thần hoặc thuộc thượng tầng, không thuộc tồn tại xã hội.","Có lẫn «ý thức xã hội» vào, trong khi ý thức xã hội là mặt đối lập với tồn tại xã hội.","Tâm lý xã hội và hệ tư tưởng là các cấp độ của ý thức xã hội, không phải tồn tại xã hội.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục III.1 (khái niệm tồn tại xã hội)","c":3},{"q":"Đâu là một trong những trường phái của triết học duy tâm?","o":["Duy tâm khách quan","Duy tâm duy lý","Duy tâm biện chứng","Duy tâm tôn giáo"],"a":[0],"e":"Khi giải quyết mặt thứ nhất của vấn đề cơ bản của triết học, chủ nghĩa duy tâm chia thành hai trường phái: duy tâm chủ quan và duy tâm khách quan. Duy tâm khách quan (Platon, Hêghen) coi một «tinh thần khách quan» hay «ý niệm tuyệt đối» có trước và sinh ra thế giới.","w":["","«Duy tâm duy lý» không phải cách phân chia trường phái trong giáo trình; «duy lý» là khuynh hướng nhận thức luận, đối lập với duy cảm.","«Duy tâm biện chứng» không phải một trường phái; Hêghen có phép biện chứng duy tâm nhưng trường phái của ông là duy tâm khách quan.","Tôn giáo có quan hệ gần với chủ nghĩa duy tâm nhưng «duy tâm tôn giáo» không phải một trong hai trường phái được phân loại."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.2 (vấn đề cơ bản của triết học; chủ nghĩa duy vật và chủ nghĩa duy tâm)","c":1},{"q":"Một trong những nguồn gốc ra đời của Triết học là:","o":["Tự nhiên","Lao động","Ngôn ngữ","Xã hội"],"a":[3],"e":"Triết học ra đời từ hai nguồn gốc: nguồn gốc nhận thức (tư duy đạt đến trình độ khái quát, trừu tượng hóa) và nguồn gốc xã hội (phân công lao động trí óc với lao động chân tay, xuất hiện tư hữu, giai cấp, nhà nước). Trong các lựa chọn, chỉ «Xã hội» là một trong hai nguồn gốc đó.","w":["Tự nhiên là đối tượng mà triết học phản ánh, không phải nguồn gốc ra đời của triết học theo giáo trình.","Lao động là nguồn gốc xã hội của ý thức (cùng với ngôn ngữ), không phải tên gọi nguồn gốc ra đời của triết học.","Ngôn ngữ là nguồn gốc xã hội của ý thức, không phải một trong hai nguồn gốc ra đời của triết học.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.1 (nguồn gốc của triết học)","c":1},{"q":"Một trong những nguyên nhân ra đời của triết học là:","o":["Tâm lý","Tư tưởng","Nhận thức","Tự nhiên"],"a":[2],"e":"Giáo trình nêu hai nguồn gốc (nguyên nhân) ra đời của triết học là nhận thức và xã hội. Về nhận thức, triết học chỉ xuất hiện khi tư duy con người đạt tới trình độ khái quát cao, có khả năng xây dựng hệ thống tri thức lý luận chung nhất về thế giới, vượt lên trên tư duy huyền thoại.","w":["Tâm lý không được giáo trình coi là nguồn gốc ra đời của triết học.","Tư tưởng là sản phẩm của nhận thức; triết học chính là một hình thức tư tưởng nên không thể coi tư tưởng là nguyên nhân sinh ra nó.","","Tự nhiên là đối tượng phản ánh, không phải nguồn gốc nhận thức hay xã hội của triết học."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.1 (nguồn gốc nhận thức và nguồn gốc xã hội của triết học)","c":1},{"q":"Hạt nhân cơ bản trong quần chúng nhân dân là ai?","o":["Những người lao động sản xuất ra của cải vật chất","Những bộ phận dân cư chống lại giai cấp thống trị áp bức bóc lột, đối kháng với nhân dân","Những tầng lớp xã hội khác nhau thúc đẩy sự tiến bộ của xã hội","Những tầng lớp dân cư lao động"],"a":[0],"e":"Quần chúng nhân dân là bộ phận dân cư có chung lợi ích căn bản, gồm nhiều thành phần, tầng lớp, giai cấp. Hạt nhân cơ bản của quần chúng nhân dân là những người lao động sản xuất ra của cải vật chất và các giá trị tinh thần, vì đây là lực lượng quyết định sự tồn tại và phát triển của xã hội.","w":["","Đây là một bộ phận cấu thành quần chúng nhân dân (lực lượng chống áp bức), nhưng không phải hạt nhân cơ bản.","Các tầng lớp thúc đẩy tiến bộ xã hội cũng là một bộ phận của quần chúng nhân dân, chưa phải hạt nhân.","«Tầng lớp dân cư lao động» quá chung; giáo trình chỉ rõ hạt nhân là người lao động trực tiếp sản xuất ra của cải vật chất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục V.3 (khái niệm quần chúng nhân dân)","c":3},{"q":"Ý thức được gọi là hình ảnh chủ quan của:","o":["Hiện thực khách quan","Thế giới khách quan","Thế giới chủ quan","Thế giới vật chất"],"a":[1],"e":"Theo chủ nghĩa duy vật biện chứng, ý thức là sự phản ánh năng động, sáng tạo thế giới khách quan vào bộ óc con người, tức là «hình ảnh chủ quan của thế giới khách quan». Nội dung của ý thức do thế giới khách quan quy định, còn hình thức biểu hiện thì mang tính chủ quan của con người.","w":["«Hiện thực khách quan» gần nghĩa nhưng không phải cách diễn đạt chuẩn của giáo trình và của Mác, Lênin; câu hỏi kiểm tra đúng cụm từ «thế giới khách quan».","","«Thế giới chủ quan» sai về bản chất: ý thức phản ánh cái tồn tại bên ngoài, độc lập với con người, chứ không phản ánh chính cái chủ quan.","«Thế giới vật chất» đúng ý nhưng không phải thuật ngữ được dùng trong định nghĩa kinh điển về bản chất của ý thức."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục I.2 (bản chất của ý thức); C.Mác, Lời bạt «Tư bản» (tái bản lần 2)","c":2},{"q":"Chân lý là gì?","o":["Ý kiến của những người có kinh nghiệm","Sự phù hợp giữa tri thức với hiện thực khách quan và được thực tiễn kiểm nghiệm","Những quan điểm thuộc về đa số","Là những thứ đúng đắn trong khoa học"],"a":[1],"e":"Theo triết học Mác-Lênin, chân lý là tri thức phù hợp với hiện thực khách quan và đã được thực tiễn kiểm nghiệm. Tiêu chuẩn của chân lý là thực tiễn, không phải ý kiến của số đông hay của người có uy tín.","w":["Kinh nghiệm hay uy tín của một người không bảo đảm tri thức đúng; lấy đó làm chân lý là sai lầm chủ quan.","","Quan điểm của đa số có thể sai; số đông không phải tiêu chuẩn của chân lý.","Định nghĩa vòng vo và hẹp: chân lý không chỉ có trong khoa học, và «đúng đắn» phải được xác định bằng sự phù hợp với hiện thực qua thực tiễn."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục III.4 (vấn đề chân lý); C.Mác, «Luận cương về Phoiơbắc», luận điểm 2","c":2},{"q":"Triết học Mác-Lênin ra đời một phần là kết quả kế thừa trực tiếp từ:","o":["Thế giới quan duy vật của Hêghen và phép biện chứng của Phobaxh","Thế giới quan duy vật của Phoiơbắc và phép biện chứng của Hêghen","Thế giới quan duy vật và phép biện chứng của cả Hêghen và Phoiơbắc","Chủ nghĩa duy tâm của Hồn bách và biện chứng pháp của Aristốt"],"a":[1],"e":"Tiền đề lý luận trực tiếp của triết học Mác là triết học cổ điển Đức. Mác và Ăngghen kế thừa «hạt nhân hợp lý» là phép biện chứng của Hêghen (loại bỏ vỏ duy tâm) và «hạt nhân cơ bản» là chủ nghĩa duy vật của Phoiơbắc (khắc phục tính siêu hình), rồi kết hợp thành chủ nghĩa duy vật biện chứng.","w":["Đảo ngược: Hêghen là nhà duy tâm khách quan, còn Phoiơbắc là nhà duy vật nhưng siêu hình.","","Hêghen không có thế giới quan duy vật, Phoiơbắc không có phép biện chứng hoàn chỉnh, nên không thể kế thừa «cả hai» từ cả hai người.","Mác không kế thừa chủ nghĩa duy tâm; còn phép biện chứng được kế thừa trực tiếp từ Hêghen chứ không phải Arixtốt."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục II.1 (tiền đề lý luận của sự ra đời triết học Mác); V.I.Lênin, «Ba nguồn gốc và ba bộ phận cấu thành của chủ nghĩa Mác»","c":1,"id":"ofrwrw"},{"q":"Khái niệm cơ sở hạ tầng là dùng để chỉ:","o":["Quan hệ kinh kế của xã hội","Kết cấu vật chất - kỹ thuật làm cơ sở để phát triển kinh tế","Quan hệ sản xuất của xã hội","Quan hệ sản xuất hợp thành cơ cấu kinh tế của xã hội"],"a":[3],"e":"Cơ sở hạ tầng là toàn bộ những quan hệ sản xuất hợp thành cơ cấu kinh tế của một xã hội nhất định. Nó gồm quan hệ sản xuất thống trị, quan hệ sản xuất tàn dư và quan hệ sản xuất mầm mống, trong đó quan hệ sản xuất thống trị giữ vai trò chủ đạo.","w":["«Quan hệ kinh tế» nói chung quá rộng và không chính xác bằng «tổng hợp các quan hệ sản xuất hợp thành cơ cấu kinh tế».","Đây là nghĩa thông thường của «cơ sở hạ tầng» (đường sá, điện, nước…), không phải khái niệm triết học.","Chưa đủ: cơ sở hạ tầng không phải một quan hệ sản xuất riêng lẻ mà là tổng hợp các quan hệ sản xuất hợp thành cơ cấu kinh tế.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.2 (biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng)","c":3},{"q":"Điền cụm từ thích hợp vào chỗ (...): \"Không thể đem lại cho hai khái niệm ... này một định nghĩa cách chỉ rõ rằng trong hai khái niệm đó, cái nào được coi là có trước\".","o":["Nhận thức luận","Bản thể luận","Nhất nguyên luận","Nhị nguyên luận"],"a":[0],"e":"Câu trích của V.I.Lênin trong «Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán»: vật chất và ý thức là hai khái niệm nhận thức luận rộng nhất, nên không thể định nghĩa chúng bằng cách quy về khái niệm rộng hơn. Chỉ có thể định nghĩa bằng cách chỉ rõ trong hai khái niệm đó cái nào được coi là có trước. Đây là phương pháp định nghĩa vật chất trong quan hệ đối lập với ý thức.","w":["","Bản thể luận bàn về bản chất của tồn tại; Lênin dùng chữ «nhận thức luận» vì đang xét quan hệ giữa vật chất và ý thức trong nhận thức.","Nhất nguyên luận là quan điểm coi thế giới có một bản nguyên, không phải cách Lênin gọi cặp khái niệm vật chất - ý thức.","Nhị nguyên luận coi vật chất và tinh thần song song, độc lập, trái với điều Lênin muốn khẳng định là cái nào có trước."],"s":"V.I.Lênin, «Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán» (1909), Toàn tập t.18; Giáo trình Triết học Mác-Lênin (2021), Chương 2, mục I.1","c":2},{"q":"Theo quan điểm của triết học Mác - Lênin, luận điểm nào sau đây chưa chính xác khi đề cập giữa tồn tại xã hội và ý thức xã hội?","o":["Một bộ phận ý thức xã hội có thể vượt trước tồn tại xã hội","Ý thức xã hội mang tính kế thừa","Ý thức xã hội luôn thay đổi ngay lập tức khi tồn tại xã hội thay đổi","Ý thức xã hội thường lạc hậu, bảo thủ so với tồn tại xã hội"],"a":[2],"e":"Ý thức xã hội có tính độc lập tương đối: nó thường lạc hậu so với tồn tại xã hội, một bộ phận có thể vượt trước, nó mang tính kế thừa và tác động trở lại tồn tại xã hội. Vì vậy ý thức xã hội không thay đổi ngay lập tức khi tồn tại xã hội thay đổi, và đó là luận điểm chưa chính xác.","w":["Luận điểm đúng: tư tưởng khoa học tiên tiến có thể dự báo, đi trước tồn tại xã hội.","Luận điểm đúng: ý thức xã hội mỗi thời đại kế thừa các giá trị tư tưởng của thời đại trước.","","Luận điểm đúng: do sức ỳ của thói quen, truyền thống và lợi ích của các nhóm lạc hậu, ý thức xã hội thường đi sau tồn tại xã hội."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục III.3 (tính độc lập tương đối của ý thức xã hội)","c":3},{"q":"Thales, Heraclitus, Anaximenes là những đại biểu thuộc trường phái nào?","o":["Chủ nghĩa duy tâm chủ quan","Chủ nghĩa duy vật chất phác","Chủ nghĩa duy tâm khách quan","Chủ nghĩa duy vật biện chứng trước Mác"],"a":[1],"e":"Thales (nước), Anaximenes (không khí), Heraclitus (lửa) đều quy cái bắt đầu của thế giới về một dạng vật chất cụ thể, cảm tính. Đây là đặc trưng của chủ nghĩa duy vật chất phác thời cổ đại: đúng về hướng (lấy vật chất giải thích thế giới) nhưng còn mang tính trực quan, ngây thơ.","w":["Duy tâm chủ quan coi cảm giác, ý thức cá nhân là cái có trước (như Berkeley), trái hẳn với việc lấy nước, lửa, không khí làm khởi nguyên.","","Duy tâm khách quan coi ý niệm hay tinh thần khách quan là gốc (như Platon), không phải các nhà triết học tự nhiên này.","Phép biện chứng của Heraclitus mới là biện chứng tự phát; «duy vật biện chứng» chỉ ra đời với Mác và Ăngghen."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.2 (các hình thức của chủ nghĩa duy vật)","c":1},{"q":"Trong lực lượng sản xuất, đâu là yếu tố động nhất, cách mạng nhất?","o":["Công cụ lao động","Bộ óc con người","Con người lao động","Tư liệu sản xuất"],"a":[0],"e":"Lực lượng sản xuất gồm người lao động và tư liệu sản xuất, trong đó công cụ lao động là yếu tố động nhất, cách mạng nhất. Công cụ luôn được cải tiến, thay đổi, là thước đo trình độ chinh phục tự nhiên và là tiêu chí phân biệt các thời đại kinh tế. Cần phân biệt với «người lao động», là yếu tố hàng đầu, quan trọng nhất.","w":["","«Bộ óc con người» không phải một yếu tố cấu thành lực lượng sản xuất theo giáo trình.","Người lao động là yếu tố hàng đầu, quan trọng nhất (Lênin), nhưng không phải yếu tố «động nhất, cách mạng nhất».","Tư liệu sản xuất là khái niệm rộng, gồm cả đối tượng lao động vốn ít biến đổi; yếu tố động nhất trong đó là công cụ lao động."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.1 (lực lượng sản xuất)","c":3},{"q":"Triết học nghiên cứu thế giới như thế nào?","o":["Như một đối tượng vật chất cụ thể","Như một hệ đối tượng vật chất nhất định","Như một chỉnh thể thống nhất","(Không đủ thông tin)"],"a":[2],"e":"Khác với các khoa học cụ thể chỉ nghiên cứu một lĩnh vực hay một bộ phận của thế giới, triết học nghiên cứu thế giới như một chỉnh thể thống nhất. Triết học tìm ra những quy luật chung nhất, phổ biến nhất chi phối cả tự nhiên, xã hội và tư duy, nhờ đó trở thành hạt nhân lý luận của thế giới quan.","w":["«Một đối tượng vật chất cụ thể» là cách tiếp cận của các khoa học chuyên ngành (vật lý, sinh học...), không phải của triết học.","«Một hệ đối tượng vật chất nhất định» vẫn chỉ là một bộ phận, một lĩnh vực của thế giới — đó là đối tượng của khoa học cụ thể, chưa phải cái nhìn bao quát toàn bộ thế giới.","","Câu hỏi có đủ thông tin: giáo trình nêu rõ triết học nghiên cứu thế giới như một chỉnh thể thống nhất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.1 (Khái niệm và đối tượng của triết học)","c":1},{"q":"Quan điểm nào sau đây cho rằng các sự vật, hiện tượng, các quá trình khác nhau vừa tồn tại định, tác động qua lại, chuyển hóa lẫn nhau?","o":["Quan điểm siêu hình","Quan điểm biện chứng","Quan điểm duy tâm","Quan điểm duy vật"],"a":[1],"e":"Quan điểm biện chứng xem xét sự vật, hiện tượng trong mối liên hệ phổ biến và sự vận động, phát triển: chúng vừa tồn tại tương đối độc lập, vừa tác động qua lại, ràng buộc và chuyển hóa lẫn nhau. Đây chính là nội dung của nguyên lý về mối liên hệ phổ biến trong phép biện chứng duy vật.","w":["Quan điểm siêu hình xem xét sự vật trong trạng thái cô lập, tách rời, tĩnh tại, phủ nhận sự tác động qua lại và chuyển hóa lẫn nhau.","","«Duy tâm» là câu trả lời cho vấn đề thứ nhất của triết học (ý thức có trước vật chất), không phải phương pháp xem xét mối liên hệ, chuyển hóa giữa các sự vật.","«Duy vật» chỉ khẳng định vật chất có trước, quyết định ý thức; chủ nghĩa duy vật vẫn có thể mang tính siêu hình (như duy vật thế kỷ XVII–XVIII), nên không đồng nhất với quan điểm biện chứng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.4 (Biện chứng và siêu hình); Chương 2, mục II.2 (Nguyên lý về mối liên hệ phổ biến)","c":1},{"q":"Chức năng, nhiệm vụ của nhà nước xã hội chủ nghĩa biểu hiện tập trung ở việc quản lý xã hội lĩnh vực bằng:","o":["Khoa học","Công cụ tiền","Pháp luật","Kế hoạch"],"a":[2],"e":"Nhà nước xã hội chủ nghĩa thực hiện chức năng quản lý xã hội trên mọi lĩnh vực chủ yếu bằng pháp luật — công cụ mang tính quyền lực nhà nước, bắt buộc chung đối với mọi chủ thể. Vì vậy, xây dựng nhà nước pháp quyền và hoàn thiện hệ thống pháp luật là yêu cầu trọng tâm để nhà nước xã hội chủ nghĩa thực hiện chức năng, nhiệm vụ của mình.","w":["Khoa học là cơ sở, căn cứ để hoạch định chính sách, nhưng bản thân nó không phải công cụ quản lý mang tính cưỡng chế của nhà nước.","Tiền tệ chỉ là một công cụ kinh tế trong quản lý vĩ mô, không bao quát được việc quản lý xã hội trên mọi lĩnh vực.","","Kế hoạch là một công cụ quản lý kinh tế, không phải phương thức quản lý xã hội tập trung, bao trùm như pháp luật."],"s":"Giáo trình Chủ nghĩa xã hội khoa học (Bộ GD&ĐT, 2021), Chương 4, mục II (Nhà nước xã hội chủ nghĩa: chức năng và đặc trưng)","c":4},{"q":"Triết học phổ biến ở Tây Âu thời Trung cổ là Triết học gì?","o":["Triết học tự nhiên","Triết học kinh viện","Triết học khoa học xã hội","Triết học chính trị"],"a":[1],"e":"Thời Trung cổ ở Tây Âu, triết học trở thành «đầy tớ của thần học» và mang hình thức triết học kinh viện (scholasticism, tiêu biểu là Tô-mát Đa-canh). Triết học kinh viện dùng lập luận lôgic hình thức để chứng minh, bảo vệ giáo lý Kitô giáo, xa rời thực tiễn và khoa học thực nghiệm.","w":["Triết học tự nhiên (nhận thức thế giới như một chỉnh thể thống nhất, mang tính trực quan) là đặc trưng của triết học Hy Lạp cổ đại, không phải thời Trung cổ.","","«Triết học khoa học xã hội» không phải tên một trào lưu lịch sử; thời Trung cổ khoa học bị thần học chi phối nặng nề.","«Triết học chính trị» là một lĩnh vực nghiên cứu, không phải hình thái triết học thống trị ở Tây Âu thời Trung cổ."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.1 (Sự phát triển của triết học — triết học Tây Âu thời Trung cổ)","c":1},{"q":"Theo quan điểm của duy vật về lịch sử, nhân tố quyết định trong lịch sử xét đến cùng là gì?","o":["Lao động, tái sản xuất ra con người","Sở hữu về tư liệu sản xuất, phân phối sản phẩm","Kết cấu xã hội, giai cấp","Sự sản xuất và tái sản xuất ra đời sống hiện thực"],"a":[3],"e":"Ph. Ăngghen trong thư gửi I. Blốc (1890) khẳng định: theo quan niệm duy vật về lịch sử, nhân tố quyết định trong lịch sử, xét đến cùng, là sự sản xuất và tái sản xuất ra đời sống hiện thực. Sự sản xuất này bao gồm sản xuất vật chất, sản xuất tinh thần và sản xuất ra bản thân con người, trong đó sản xuất vật chất giữ vai trò nền tảng.","w":["«Lao động, tái sản xuất ra con người» chỉ là một mặt của sản xuất xã hội, chưa bao quát toàn bộ quá trình sản xuất ra đời sống hiện thực.","Sở hữu tư liệu sản xuất và phân phối sản phẩm là các mặt của quan hệ sản xuất — bản thân chúng do trình độ sản xuất quyết định, nên không phải nhân tố quyết định «xét đến cùng».","Kết cấu xã hội, giai cấp là kết quả phát sinh từ sự phát triển của sản xuất, không phải nguyên nhân quyết định cuối cùng của lịch sử.",""],"s":"Ph. Ăngghen, Thư gửi I. Blốc (21–22/9/1890), C.Mác và Ph.Ăngghen Toàn tập, t.37; Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.1","c":3},{"q":"Thuyết bất khả tri còn gọi là gì?","o":["Thuyết không thể biết","Thuyết khả tri","Thuyết khả tri luận","Thuyết nhận biết luận"],"a":[0],"e":"Thuyết bất khả tri (agnosticism) còn gọi là «thuyết không thể biết»: cho rằng con người về nguyên tắc không thể nhận thức được bản chất của thế giới, hoặc chỉ biết được hiện tượng bề ngoài. Đại biểu tiêu biểu là Hium và Cantơ.","w":["","«Thuyết khả tri» là quan điểm đối lập, khẳng định con người có khả năng nhận thức được thế giới.","«Khả tri luận» cũng là thuyết có thể biết — trái ngược hoàn toàn với bất khả tri.","«Thuyết nhận biết luận» không phải tên gọi được dùng trong giáo trình cho thuyết bất khả tri, và về nghĩa còn gợi đến khả năng nhận biết."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.3 (Vấn đề cơ bản của triết học — thuyết có thể biết và thuyết không thể biết)","c":1},{"q":"Điền vào dấu \"...là tổng hợp những mặt, những yếu tố trong quá trình tạo nên sự vật\":","o":["Khả năng","Hiện thực","Nội dung","Hình thức"],"a":[2],"e":"Theo phép biện chứng duy vật, nội dung là phạm trù chỉ tổng hợp tất cả những mặt, những yếu tố, những quá trình tạo nên sự vật. Còn hình thức là phương thức tồn tại và phát triển của sự vật, tức hệ thống các mối liên hệ tương đối bền vững giữa các yếu tố ấy.","w":["«Khả năng» là cái chưa xảy ra nhưng sẽ xảy ra khi có điều kiện thích hợp — không phải tổng hợp các yếu tố tạo nên sự vật.","«Hiện thực» là cái đang tồn tại thực sự, đối lập với khả năng; không mô tả thành phần cấu tạo của sự vật.","","«Hình thức» là phương thức tồn tại, cách liên kết giữa các yếu tố, chứ không phải bản thân tổng hợp các yếu tố đó."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục II.3 (Các cặp phạm trù cơ bản — Nội dung và hình thức)","c":2},{"q":"Yếu tố chủ thể của lực lượng sản xuất là:","o":["Con người với kỹ năng, kỹ xảo và tri thức được tích luỹ lại","Tư liệu sản xuất hiện đại","Khoa học công nghệ tiên tiến","Các phương án trả lời đều đúng"],"a":[0],"e":"Lực lượng sản xuất gồm người lao động (yếu tố chủ thể) và tư liệu sản xuất (yếu tố khách thể). Người lao động là con người có tri thức, kinh nghiệm, kỹ năng, kỹ xảo lao động và năng lực sáng tạo — là yếu tố giữ vai trò quyết định trong lực lượng sản xuất.","w":["","Tư liệu sản xuất, dù hiện đại, vẫn là yếu tố khách thể (vật chất) của lực lượng sản xuất, không phải chủ thể.","Khoa học công nghệ ngày nay trở thành lực lượng sản xuất trực tiếp, nhưng không phải là yếu tố chủ thể — chủ thể vẫn là con người lao động.","Không thể «đều đúng» vì chỉ người lao động mới là chủ thể; các yếu tố còn lại thuộc mặt khách thể hoặc là nhân tố thâm nhập vào lực lượng sản xuất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":3,"f":1},{"q":"Nội dung trước tiên của cách mạng xã hội chủ nghĩa là phải giành chính quyền về tay giai cấp công nhân, nhân dân lao động, đưa những người lao động:","o":["Thành người lao động tập thể","Làm chủ tư liệu sản xuất","Thành người quản lý xã hội","Lên địa vị làm chủ xã hội"],"a":[3],"e":"Trên lĩnh vực chính trị, nội dung trước tiên của cách mạng xã hội chủ nghĩa là đập tan nhà nước của giai cấp bóc lột, giành chính quyền về tay giai cấp công nhân và nhân dân lao động, đưa những người lao động từ địa vị bị áp bức lên địa vị làm chủ xã hội. Đây là điều kiện tiên quyết để sau đó cải tạo kinh tế, văn hóa, xã hội.","w":["«Thành người lao động tập thể» gắn với việc cải tạo quan hệ sản xuất trên lĩnh vực kinh tế, là nội dung đến sau, không phải nội dung trước tiên về chính trị.","«Làm chủ tư liệu sản xuất» là nội dung kinh tế, chỉ một mặt của quyền làm chủ, và chỉ thực hiện được sau khi đã có chính quyền.","«Thành người quản lý xã hội» chỉ là một biểu hiện cụ thể của quyền làm chủ; cách diễn đạt đầy đủ, chuẩn xác là đưa người lao động lên địa vị làm chủ xã hội.",""],"s":"Giáo trình Những nguyên lý cơ bản của chủ nghĩa Mác-Lênin (Bộ GD&ĐT, 2009), Chương VII (Cách mạng xã hội chủ nghĩa); Giáo trình Chủ nghĩa xã hội khoa học (Bộ GD&ĐT, 2021), Chương 2, mục nội dung chính trị - xã hội của sứ mệnh lịch sử giai cấp công nhân","c":2},{"q":"Chủ nghĩa duy vật lịch sử cho rằng sự ra đời, tồn tại của nhà nước là để duy trì trật tự xã hội mâu thuẫn giai cấp như thế nào?","o":["Đi đến giải quyết","Phải được giải quyết","Có thể giải quyết","Không thể điều hòa được"],"a":[3],"e":"Theo V.I. Lênin trong «Nhà nước và cách mạng», nhà nước là sản phẩm và biểu hiện của những mâu thuẫn giai cấp không thể điều hòa được. Ở đâu và khi nào mâu thuẫn giai cấp không thể điều hòa được thì nhà nước xuất hiện, để giữ cho xung đột giai cấp nằm trong một «trật tự» có lợi cho giai cấp thống trị.","w":["«Đi đến giải quyết» sai vì nhà nước không giải quyết mâu thuẫn giai cấp mà chỉ kìm giữ nó trong vòng trật tự của giai cấp thống trị.","«Phải được giải quyết» không đúng luận điểm của Lênin; nhà nước ra đời chính vì mâu thuẫn đó không thể điều hòa, chứ không phải để giải quyết nó.","«Có thể giải quyết» trái ngược với luận điểm gốc: nếu mâu thuẫn giai cấp điều hòa được thì nhà nước đã không ra đời.",""],"s":"V.I. Lênin, «Nhà nước và cách mạng» (1917), Chương I; Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục IV.2 (Nhà nước — nguồn gốc)","c":3},{"q":"Hạt nhân lý luận của thế giới quan khoa học là chủ nghĩa:","o":["Duy vật","Mác","Duy vật biện chứng","Lênin"],"a":[2],"e":"Triết học là hạt nhân lý luận của thế giới quan, và chủ nghĩa duy vật biện chứng — sự thống nhất hữu cơ giữa chủ nghĩa duy vật và phép biện chứng — là hình thức phát triển cao nhất của chủ nghĩa duy vật. Vì thế, chủ nghĩa duy vật biện chứng là hạt nhân lý luận của thế giới quan khoa học.","w":["«Duy vật» nói chung còn bao gồm duy vật chất phác cổ đại và duy vật siêu hình, có hạn chế nên chưa thể là hạt nhân của thế giới quan khoa học.","«Chủ nghĩa Mác» là cả một hệ thống gồm triết học, kinh tế chính trị và chủ nghĩa xã hội khoa học — rộng hơn hạt nhân lý luận của thế giới quan.","","«Chủ nghĩa Lênin» là giai đoạn phát triển của chủ nghĩa Mác, không phải tên gọi chỉ hạt nhân lý luận của thế giới quan khoa học."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.2 (Triết học — hạt nhân lý luận của thế giới quan) và mục I.4","c":1},{"q":"Chủ nghĩa Mác-Lênin ra đời dựa trên bao nhiêu tiền đề?","o":["Ba tiền đề","Bốn tiền đề","Năm tiền đề","Sáu tiền đề"],"a":[0],"e":"Chủ nghĩa Mác ra đời dựa trên ba điều kiện, tiền đề cơ bản: điều kiện kinh tế - xã hội, tiền đề lý luận và tiền đề khoa học tự nhiên. Riêng tiền đề lý luận cũng gồm ba nguồn gốc (triết học cổ điển Đức, kinh tế chính trị cổ điển Anh, chủ nghĩa xã hội không tưởng Pháp), và tiền đề khoa học tự nhiên gồm ba phát minh lớn — nên con số «ba» là nhất quán.","w":["","«Bốn tiền đề» không khớp với cách phân chia nào trong giáo trình.","«Năm tiền đề» không đúng; giáo trình chỉ nêu ba nhóm điều kiện, tiền đề.","«Sáu tiền đề» có thể do cộng nhầm các nguồn gốc lý luận và phát minh khoa học, nhưng không phải cách phân loại của giáo trình."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục II.1 (Những điều kiện, tiền đề của sự ra đời triết học Mác)","c":1},{"q":"Điều kiện cần và đủ để sinh ra ý thức là gì? Chọn 3 đáp án đúng.","o":["Nghiên cứu khoa học","Lao động, ngôn ngữ","Bộ óc người","Các sự vật, hiện tượng trong thế giới khách quan"],"a":[1,2,3],"e":"Ý thức có nguồn gốc tự nhiên và nguồn gốc xã hội. Nguồn gốc tự nhiên gồm bộ óc người và thế giới khách quan (các sự vật, hiện tượng) tác động lên bộ óc tạo ra sự phản ánh; nguồn gốc xã hội — trực tiếp và quan trọng nhất — là lao động và ngôn ngữ. Ba yếu tố này hợp thành điều kiện cần và đủ cho sự ra đời của ý thức.","w":["«Nghiên cứu khoa học» là một hình thức hoạt động của ý thức đã phát triển, xuất hiện muộn hơn nhiều, nên không phải điều kiện sinh ra ý thức.","","",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục I.2 (Nguồn gốc của ý thức); Ph. Ăngghen, «Vai trò của lao động trong quá trình chuyển biến từ vượn thành người»","c":2},{"q":"Theo Lênin, khách quan là cái đang tồn tại:","o":["Phụ thuộc nhận thức con người","Trong thế giới con người","Trong thế giới tự nhiên","Độc lập, không phụ thuộc vào ý thức"],"a":[3],"e":"Theo Lênin, «khách quan» là cái tồn tại độc lập, không phụ thuộc vào ý thức của con người — đây cũng là thuộc tính cơ bản nhất của vật chất trong định nghĩa vật chất của ông. Vật chất là thực tại khách quan, tồn tại dù con người có nhận thức được nó hay không.","w":["«Phụ thuộc nhận thức con người» là đặc điểm của cái chủ quan, trái ngược hẳn với khách quan.","«Trong thế giới con người» chỉ phạm vi, không nói lên tính độc lập với ý thức; nhiều hiện tượng trong xã hội loài người vẫn là chủ quan.","«Trong thế giới tự nhiên» quá hẹp: các quan hệ xã hội (như quan hệ sản xuất) cũng là khách quan dù không thuộc tự nhiên.",""],"s":"V.I. Lênin, «Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán» (1909), Chương II; Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục I.1 (Định nghĩa vật chất của Lênin)","c":2},{"q":"Sự phân chia giai cấp trong xã hội bắt đầu từ hình thái kinh tế - xã hội nào?","o":["Cộng sản nguyên thủy","Tư bản chủ nghĩa","Phong kiến","Chiếm hữu nô lệ"],"a":[3],"e":"Khi lực lượng sản xuất phát triển, xuất hiện sản phẩm dư thừa và chế độ tư hữu, xã hội phân chia thành giai cấp. Hình thái kinh tế - xã hội chiếm hữu nô lệ là xã hội có giai cấp đầu tiên trong lịch sử, với hai giai cấp cơ bản là chủ nô và nô lệ.","w":["Cộng sản nguyên thủy dựa trên chế độ công hữu, chưa có tư hữu và chưa có giai cấp.","Tư bản chủ nghĩa là xã hội có giai cấp nhưng xuất hiện muộn, không phải nơi bắt đầu sự phân chia giai cấp.","Phong kiến cũng có giai cấp (địa chủ – nông dân) nhưng ra đời sau chế độ chiếm hữu nô lệ.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục IV.1 (Giai cấp — nguồn gốc); Ph. Ăngghen, «Nguồn gốc của gia đình, của chế độ tư hữu và của nhà nước»","c":3},{"q":"Xét đến cùng, mục đích của sự sản xuất xã hội là để làm gì?","o":["Sản xuất ra của cải vật chất","Sản xuất và tái sản xuất ra đời sống hiện thực","Sản xuất ra con người, nuôi sống con người","Sản xuất ra con người"],"a":[1],"e":"Sản xuất là hoạt động sáng tạo ra giá trị vật chất và tinh thần nhằm thỏa mãn nhu cầu tồn tại và phát triển của con người; quá trình đó trong xã hội chính là sản xuất xã hội — sự sản xuất và tái sản xuất ra đời sống hiện thực. Xét đến cùng, mục đích của sản xuất xã hội là duy trì, tái tạo và phát triển toàn bộ đời sống hiện thực của con người và xã hội.","w":["«Sản xuất ra của cải vật chất» chỉ là một mặt (sản xuất vật chất) — nền tảng nhưng chưa phải toàn bộ mục đích cuối cùng.","","«Sản xuất ra con người, nuôi sống con người» vẫn chỉ là một bộ phận, chưa bao gồm sản xuất tinh thần và các quan hệ xã hội của đời sống hiện thực.","«Sản xuất ra con người» chỉ là một trong ba mặt của sản xuất xã hội (sản xuất vật chất, tinh thần, con người), nên quá hẹp."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.1 (Sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội); Ph. Ăngghen, Thư gửi I. Blốc (1890)","c":3},{"q":"Nguyên lý về sự phát triển là cơ sở khoa học để định hướng cho nhận thức và cải tạo thế giới. Theo đó, trong hoạt động nhận thức và hoạt động thực tiễn con người phải đặt sự vật, hiện tượng theo khuynh hướng:","o":["Đi thẳng","Đi lên của nó","Không tụt lùi","Vận động"],"a":[1],"e":"Nguyên lý về sự phát triển cho thấy phát triển là vận động theo khuynh hướng đi lên, từ thấp đến cao, từ kém hoàn thiện đến hoàn thiện hơn. Do đó quan điểm phát triển đòi hỏi trong nhận thức và thực tiễn phải đặt sự vật, hiện tượng theo khuynh hướng đi lên của nó, đồng thời thấy được tính quanh co, phức tạp của quá trình ấy.","w":["«Đi thẳng» sai vì phát triển không theo đường thẳng mà theo đường xoáy ốc, quanh co, có cả bước thụt lùi tạm thời.","","«Không tụt lùi» sai vì giáo trình thừa nhận trong quá trình phát triển có thể có những bước thụt lùi tạm thời.","«Vận động» quá rộng: vận động bao gồm mọi biến đổi, kể cả đi xuống, tuần hoàn; chỉ vận động đi lên mới là phát triển."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục II.2 (Nguyên lý về sự phát triển — ý nghĩa phương pháp luận)","c":2},{"q":"Vai trò của lãnh tụ đối với phong trào của quần chúng nhân dân?","o":["Thúc đẩy hoặc kìm hãm sự tiến bộ của xã hội","Là người sáng lập ra các tổ chức chính trị, xã hội và là linh hồn của các tổ chức đó","Lãnh tụ của mỗi thời đại chỉ có thể hoàn thành những nhiệm vụ đặt ra của thời đại đó","Tất cả các đáp án đều đúng"],"a":[3],"e":"Giáo trình nêu nhiều vai trò của lãnh tụ: nắm bắt xu thế của dân tộc, thời đại; tổ chức, lãnh đạo quần chúng; là người sáng lập và là linh hồn của các tổ chức chính trị - xã hội; có thể thúc đẩy hoặc kìm hãm tiến bộ xã hội. Đồng thời lãnh tụ của mỗi thời đại chỉ hoàn thành được nhiệm vụ do thời đại đó đặt ra, nên cả ba nhận định đều đúng.","w":["Nhận định này đúng nhưng chỉ là một phần; chọn riêng nó sẽ bỏ sót các vai trò khác.","Nhận định này đúng nhưng chưa đầy đủ, vì lãnh tụ còn tác động thúc đẩy/kìm hãm tiến bộ và bị giới hạn bởi nhiệm vụ thời đại.","Nhận định này đúng (không có lãnh tụ chung cho mọi thời đại) nhưng chỉ là một khía cạnh, nên không đầy đủ bằng lựa chọn bao gồm tất cả.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục VI.3 (Vai trò của quần chúng nhân dân và lãnh tụ trong lịch sử)","c":3,"f":1},{"q":"Cái ngẫu nhiên là cái:","o":["Diễn ra hoàn toàn không chịu sự chi phối của quy luật nào","Hoàn toàn diễn ra theo quy luật","Biểu hiện của quy luật","Không biểu hiện của bất cứ quy luật nào"],"a":[2],"e":"Cái ngẫu nhiên do nguyên nhân bên ngoài, sự kết hợp ngẫu hợp các hoàn cảnh gây ra, nhưng nó không nằm ngoài quy luật: cái tất nhiên «vạch đường đi» cho mình thông qua vô số cái ngẫu nhiên. Vì vậy, ngẫu nhiên là hình thức biểu hiện, là cái bổ sung cho cái tất nhiên — tức là biểu hiện của quy luật.","w":["Sai vì phủ nhận mối quan hệ giữa ngẫu nhiên và tất nhiên; không có cái ngẫu nhiên thuần túy tách khỏi mọi quy luật.","«Hoàn toàn diễn ra theo quy luật» là đặc điểm của cái tất nhiên (nhất định phải xảy ra như thế), không phải của cái ngẫu nhiên.","","Sai vì ngẫu nhiên chính là hình thức qua đó tất nhiên, quy luật bộc lộ ra; nói nó không biểu hiện quy luật nào là quan điểm phi biện chứng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục II.3 (Cặp phạm trù tất nhiên và ngẫu nhiên); Ph. Ăngghen, «Lút-vích Phoi-ơ-bắc và sự cáo chung của triết học cổ điển Đức»","c":2},{"q":"Cái riêng là một phạm trù dùng để chỉ:","o":["Những mặt, những thuộc tính chung của nhiều sự vật","Một sự vật, một hiện tượng, một quá trình riêng lẻ nhất định","Những nét, những thuộc tính chỉ có ở một sự vật","Các yếu tố cấu thành một hệ thống"],"a":[1],"e":"Cái riêng là phạm trù triết học dùng để chỉ một sự vật, một hiện tượng, một quá trình riêng lẻ nhất định. Trong cái riêng vừa có cái chung (những thuộc tính lặp lại ở nhiều sự vật) vừa có cái đơn nhất (những nét chỉ có ở sự vật đó).","w":["«Những mặt, những thuộc tính chung của nhiều sự vật» là định nghĩa của cái chung, không phải cái riêng.","","«Những nét, thuộc tính chỉ có ở một sự vật» là cái đơn nhất — chỉ là một bộ phận bên trong cái riêng.","«Các yếu tố cấu thành một hệ thống» gần với phạm trù kết cấu/nội dung, không phải định nghĩa cái riêng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục II.3 (Cặp phạm trù cái riêng và cái chung)","c":2},{"q":"Theo quan điểm của chủ nghĩa Mác-Lênin, khái niệm nào dùng để chỉ lực lượng sản xuất cơ bản của xã hội, trực tiếp sản xuất ra của cải vật chất, là cơ sở của sự tồn tại và phát triển của xã hội?","o":["Quần chúng nhân dân","Tất cả các đáp án đều đúng","Lãnh tụ","Vĩ nhân"],"a":[0],"e":"Theo chủ nghĩa duy vật lịch sử, quần chúng nhân dân (trước hết là đông đảo người lao động chân tay và trí óc) là lực lượng sản xuất cơ bản của xã hội, trực tiếp làm ra của cải vật chất bảo đảm sự tồn tại và phát triển của xã hội. Đây là vai trò thứ nhất trong ba vai trò quyết định của quần chúng nhân dân (cùng với: động lực cơ bản của các cuộc cách mạng xã hội và người sáng tạo giá trị tinh thần).","w":["","Không thể «tất cả đều đúng» vì lãnh tụ và vĩ nhân chỉ là những cá nhân kiệt xuất, không phải lực lượng đông đảo trực tiếp sản xuất của cải vật chất.","Lãnh tụ có vai trò định hướng, tổ chức phong trào nhưng là cá nhân xuất sắc, không phải lực lượng sản xuất cơ bản của xã hội.","Vĩ nhân chỉ là cá nhân nổi bật trong một lĩnh vực; họ không trực tiếp tạo ra phần lớn của cải vật chất của xã hội."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục V.2 – Vai trò của quần chúng nhân dân và lãnh tụ trong lịch sử","c":3,"f":1},{"q":"Ai là người đã đưa ra định nghĩa về giai cấp: \"Người ta gọi là giai cấp là những tập đoàn người to lớn, khác nhau về địa vị của họ trong một hệ thống sản xuất xã hội nhất định trong lịch sử...\"","o":["Heraclit","Khổng Tử","V.I Lênin","Chủ tịch Hồ Chí Minh"],"a":[2],"e":"Định nghĩa kinh điển về giai cấp («những tập đoàn người to lớn, khác nhau về địa vị trong một hệ thống sản xuất xã hội nhất định trong lịch sử, khác nhau về quan hệ đối với tư liệu sản xuất, về vai trò trong tổ chức lao động xã hội và về cách thức hưởng thụ phần của cải xã hội...») do V.I. Lênin nêu ra trong tác phẩm «Sáng kiến vĩ đại» (1919). Định nghĩa này chỉ ra nguồn gốc kinh tế của giai cấp, mà cốt lõi là quan hệ sở hữu tư liệu sản xuất.","w":["Hêraclít là nhà triết học Hy Lạp cổ đại nổi tiếng với tư tưởng biện chứng «mọi vật đều trôi chảy», không đưa ra định nghĩa khoa học về giai cấp.","Khổng Tử là nhà tư tưởng Trung Hoa cổ đại bàn về đạo đức, chính trị (lễ, nhân, chính danh), không đưa ra định nghĩa giai cấp theo quan hệ sản xuất.","","Chủ tịch Hồ Chí Minh vận dụng sáng tạo học thuyết giai cấp vào Việt Nam, nhưng định nghĩa được trích dẫn là của Lênin."],"s":"V.I. Lênin, «Sáng kiến vĩ đại» (1919), Toàn tập, t.39, NXB Chính trị quốc gia; Giáo trình Triết học Mác-Lênin (2021), Chương 3, mục III.1","c":3},{"q":"Trong các yếu tố sau, yếu tố nào thuộc về kiến trúc thượng tầng?","o":["Cơ sở kinh tế","Cơ sở vật chất kỹ thuật","Công nghệ thông tin","Các học thuyết, tư tưởng"],"a":[3],"e":"Kiến trúc thượng tầng là toàn bộ những quan điểm, tư tưởng xã hội (chính trị, pháp quyền, đạo đức, tôn giáo, nghệ thuật, triết học...) cùng các thiết chế tương ứng (nhà nước, đảng phái, giáo hội...) được hình thành trên một cơ sở hạ tầng nhất định. Vì vậy các học thuyết, tư tưởng thuộc về kiến trúc thượng tầng.","w":["Cơ sở kinh tế (toàn bộ quan hệ sản xuất hợp thành cơ cấu kinh tế) chính là cơ sở hạ tầng, là cái quyết định kiến trúc thượng tầng chứ không thuộc về nó.","Cơ sở vật chất kỹ thuật thuộc lực lượng sản xuất (tư liệu sản xuất), không phải kiến trúc thượng tầng.","Công nghệ thông tin là yếu tố khoa học – công nghệ thuộc lực lượng sản xuất, không phải hệ thống tư tưởng hay thiết chế chính trị – xã hội.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.2 – Biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng","c":3},{"q":"Tâm lý, tính cách tiểu nông của người Việt Nam truyền thống căn bản là do những yếu tố nào quyết định? (Chọn 3)","o":["Bản tính cố hữu của người Việt Nam","Bị phong kiến, đế quốc nhiều thế kỷ áp bức thống trị","Phương thức sản xuất tiểu nông, lạc hậu tồn tại lâu dài trong lịch sử","Điều kiện tổ chức dân cư khép kín của các làng xã"],"a":[1,2,3],"e":"Theo nguyên lý tồn tại xã hội quyết định ý thức xã hội, tâm lý tiểu nông (tầm nhìn hẹp, bảo thủ, cục bộ, trông chờ...) được hình thành từ điều kiện sống vật chất lâu dài: phương thức sản xuất tiểu nông lạc hậu, kết cấu làng xã khép kín, tự cấp tự túc, cùng hoàn cảnh lịch sử bị phong kiến, đế quốc áp bức kìm hãm nhiều thế kỷ khiến nền sản xuất nhỏ chậm chuyển biến. Ba yếu tố này đều thuộc tồn tại xã hội nên được chọn.","w":["Không có «bản tính cố hữu» bẩm sinh của một dân tộc; quan điểm này là duy tâm vì coi tâm lý là cái có sẵn, tách khỏi điều kiện sống vật chất – lịch sử.","","",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục IV.1 – Tồn tại xã hội quyết định ý thức xã hội (tâm lý xã hội); C. Mác, «Lời tựa Góp phần phê phán khoa kinh tế chính trị» (1859)","c":3},{"q":"Sản xuất vật chất có vai trò gì đối với xã hội?","o":["Quyết định sự tồn tại và phát triển xã hội","Quyết định sự vận động của xã hội","Quyết định tính chất và nội dung của xã hội","(Không đủ thông tin)"],"a":[0],"e":"Sản xuất vật chất là cơ sở của sự tồn tại và phát triển của xã hội loài người: nó tạo ra tư liệu sinh hoạt nuôi sống con người, là tiền đề của mọi hoạt động lịch sử khác, và quá trình phát triển của nó quyết định sự phát triển của xã hội từ thấp đến cao. Đây là khẳng định trực tiếp trong giáo trình về vai trò của sản xuất vật chất.","w":["","«Sự vận động của xã hội» chỉ nói một mặt và không đúng cách diễn đạt của giáo trình; sản xuất vật chất quyết định cả sự tồn tại lẫn phát triển, không chỉ sự vận động.","Tính chất, nội dung của xã hội được nói đến khi bàn về phương thức sản xuất/quan hệ sản xuất quyết định kết cấu và tính chất xã hội; đây không phải công thức về vai trò của sản xuất vật chất nói chung.","Đề đã đủ thông tin để trả lời: giáo trình nêu rõ sản xuất vật chất quyết định sự tồn tại và phát triển của xã hội."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.1 – Sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội; C. Mác – Ph. Ăngghen, «Hệ tư tưởng Đức»","c":3},{"q":"Phủ định biện chứng có đặc trưng cơ bản nào?","o":["Tính khách quan và tính mâu thuẫn","Tính mâu thuẫn và tính kế thừa","Tất cả các đáp án đều sai","Tính khách quan và tính kế thừa"],"a":[3],"e":"Phủ định biện chứng có hai đặc trưng cơ bản: tính khách quan (nguyên nhân phủ định nằm ngay trong bản thân sự vật, là kết quả giải quyết mâu thuẫn bên trong) và tính kế thừa (cái mới không phá bỏ hoàn toàn cái cũ mà giữ lại, cải tạo những yếu tố tích cực của nó). Nhờ kế thừa mà phát triển diễn ra theo hình xoáy ốc.","w":["Mâu thuẫn là nguồn gốc của phủ định chứ không được giáo trình xếp là «đặc trưng» của phủ định biện chứng; cặp đúng phải là khách quan và kế thừa.","Thiếu tính khách quan và lại đưa «tính mâu thuẫn» vào – không khớp với hai đặc trưng mà giáo trình nêu.","Có một cặp đặc trưng đúng (tính khách quan và tính kế thừa) nên không thể «tất cả đều sai».",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục II.3 – Quy luật phủ định của phủ định","c":2,"f":1},{"q":"Sự phản ánh có tính chủ động lựa chọn thông tin, xử lý thông tin là hình thức phản ánh:","o":["Tâm lý","Năng động, sáng tạo","Tiên tiến","Không thụ động"],"a":[1],"e":"Phản ánh năng động, sáng tạo là hình thức phản ánh cao nhất, chỉ có ở con người (ý thức): nó tiếp nhận, chủ động lựa chọn, xử lý thông tin để tạo ra thông tin mới, phát hiện ý nghĩa của thông tin. Đặc điểm «chủ động lựa chọn, xử lý thông tin» chính là dấu hiệu của hình thức phản ánh này.","w":["Phản ánh tâm lý là hình thức phản ánh của động vật có hệ thần kinh trung ương, dựa trên phản xạ có điều kiện, chưa có khả năng chủ động xử lý thông tin để tạo thông tin mới.","","«Tiên tiến» không phải là một hình thức phản ánh trong phân loại của giáo trình (vật lý – hóa học, sinh học, tâm lý, năng động sáng tạo).","«Không thụ động» chỉ là cách nói mô tả, không phải tên một hình thức phản ánh trong hệ thống khái niệm."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục I.3 – Nguồn gốc tự nhiên của ý thức (các hình thức phản ánh)","c":2},{"q":"Theo quan niệm của chủ nghĩa duy vật biện chứng về lịch sử thì trong xã hội có giai cấp, hệ tư tưởng thống trị xã hội bao giờ cũng là hệ tư tưởng của giai cấp:","o":["Tiên tiến nhất","Lãnh đạo xã hội","Thống trị xã hội","Đứng đầu xã hội"],"a":[2],"e":"Mác và Ăngghen khẳng định: trong mỗi thời đại, tư tưởng của giai cấp thống trị là tư tưởng thống trị, vì giai cấp nắm tư liệu sản xuất vật chất thì cũng chi phối tư liệu sản xuất tinh thần. Do đó trong xã hội có giai cấp, hệ tư tưởng thống trị luôn là hệ tư tưởng của giai cấp thống trị về kinh tế và chính trị.","w":["Giai cấp tiên tiến nhất (ví dụ giai cấp mới đang lên) có thể chưa nắm quyền nên tư tưởng của nó chưa phải tư tưởng thống trị.","«Lãnh đạo xã hội» là cách diễn đạt mơ hồ, không phải thuật ngữ của luận điểm; điều quyết định là địa vị thống trị về kinh tế – chính trị.","","«Đứng đầu xã hội» không phải phạm trù khoa học, không nói lên địa vị nắm tư liệu sản xuất và quyền lực nhà nước."],"s":"C. Mác – Ph. Ăngghen, «Hệ tư tưởng Đức» (1845–1846), Toàn tập t.3; Giáo trình Triết học Mác-Lênin (2021), Chương 3, mục IV.2","c":3},{"q":"Thế nào là phương pháp siêu hình?","o":["Xem xét các sự vật trong mối liên hệ tác động qua lại lẫn nhau, nhưng không vận động, không phát triển","Xem xét các sự vật trong trạng thái cô lập, tách rời nhau, và không vận động, không phát triển","Xem xét các sự vật trong mối liên hệ tác động qua lại lẫn nhau, và luôn vận động, luôn phát triển","Xem xét các sự vật trong trạng thái cô lập, tách rời nhau, nhưng luôn vận động, luôn phát triển"],"a":[1],"e":"Phương pháp siêu hình là phương pháp xem xét sự vật trong trạng thái cô lập, tách rời, tĩnh tại; nếu có thừa nhận biến đổi thì chỉ là tăng giảm về lượng, nguyên nhân ở bên ngoài. Nó đối lập với phương pháp biện chứng vốn xem xét sự vật trong mối liên hệ phổ biến và sự vận động, phát triển.","w":["Đã thừa nhận mối liên hệ tác động qua lại – đó là yếu tố của biện chứng, nên mô tả này không đúng phương pháp siêu hình.","","Xem xét sự vật trong liên hệ và luôn vận động, phát triển chính là định nghĩa phương pháp biện chứng.","Thừa nhận sự vật luôn vận động, phát triển là mặt biện chứng; phương pháp siêu hình nhìn sự vật ở trạng thái tĩnh."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.4 – Biện chứng và siêu hình; Ph. Ăngghen, «Chống Đuy-rinh»","c":1},{"q":"Ở xã hội Việt Nam hiện nay:","o":["Còn đấu tranh giai cấp","Không còn đấu tranh giai cấp","Các phương án trả lời đều sai","Đấu tranh giai cấp gay gắt"],"a":[0],"e":"Trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam, đấu tranh giai cấp vẫn còn tồn tại vì còn nhiều thành phần kinh tế, còn tàn dư tư tưởng cũ và sự chống phá của các thế lực thù địch. Tuy nhiên nó diễn ra với nội dung, hình thức mới, chủ yếu là đấu tranh thực hiện thắng lợi mục tiêu «dân giàu, nước mạnh, dân chủ, công bằng, văn minh».","w":["","Cho rằng đã «không còn đấu tranh giai cấp» là sai, vì cơ sở kinh tế – xã hội của sự khác biệt giai cấp và các thế lực chống phá vẫn tồn tại.","Có phương án đúng (còn đấu tranh giai cấp) nên «đều sai» là không đúng.","Đảng xác định đấu tranh giai cấp hiện nay mang nội dung, hình thức mới, chủ yếu là xây dựng; không phải đấu tranh «gay gắt» dưới dạng đối kháng bạo lực."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục III.1 – Đấu tranh giai cấp trong thời kỳ quá độ ở Việt Nam; Cương lĩnh xây dựng đất nước (bổ sung, phát triển 2011)","c":4,"f":1},{"q":"Trong chủ nghĩa Mác - Lênin thì:","o":["Triết học là cơ sở nền tảng của kinh tế chính trị và chủ nghĩa xã hội khoa học","Kinh tế chính trị học là cơ sở nền tảng của triết học và chủ nghĩa xã hội khoa học","Chủ nghĩa xã hội khoa học là cơ sở của kinh tế chính trị và triết học","(Không đủ thông tin)"],"a":[0],"e":"Chủ nghĩa Mác-Lênin gồm ba bộ phận: triết học, kinh tế chính trị và chủ nghĩa xã hội khoa học, trong đó triết học Mác-Lênin cung cấp thế giới quan duy vật biện chứng và phương pháp luận biện chứng, là cơ sở lý luận nền tảng cho hai bộ phận còn lại. Chính nhờ phép duy vật lịch sử mà Mác phát hiện học thuyết giá trị thặng dư và luận chứng sứ mệnh lịch sử của giai cấp công nhân.","w":["","Kinh tế chính trị là bộ phận vận dụng thế giới quan và phương pháp luận triết học vào nghiên cứu kinh tế, không phải nền tảng của triết học.","Chủ nghĩa xã hội khoa học là kết luận, kết quả tất yếu của triết học và kinh tế chính trị Mác-Lênin, chứ không phải cơ sở của chúng.","Đề đã đủ thông tin; vai trò nền tảng của triết học được giáo trình khẳng định rõ."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục II–III; V.I. Lênin, «Ba nguồn gốc và ba bộ phận cấu thành của chủ nghĩa Mác» (1913)","c":1},{"q":"Theo chủ nghĩa duy vật lịch sử, các chính sách và pháp luật của nhà nước suy đến cùng chỉ là phản ánh nhu cầu thống trị về kinh tế của giai cấp nắm giữ yếu tố nào của xã hội?","o":["Lực lượng sản xuất chủ yếu của xã hội","Quyền tổ chức-quản lý xã hội","Nhà nước","Quyền sở hữu các tư liệu sản xuất chủ yếu"],"a":[3],"e":"Theo chủ nghĩa duy vật lịch sử, nhà nước và pháp luật thuộc kiến trúc thượng tầng, bị quy định bởi cơ sở hạ tầng; giai cấp nắm quyền sở hữu tư liệu sản xuất chủ yếu là giai cấp thống trị về kinh tế, nên cũng thống trị về chính trị. Vì vậy chính sách, pháp luật suy đến cùng chỉ là ý chí của giai cấp ấy được «đề lên thành luật» để bảo vệ lợi ích kinh tế của nó.","w":["Lực lượng sản xuất chủ yếu (người lao động) thường là giai cấp bị trị trong xã hội có đối kháng, nên pháp luật không phản ánh nhu cầu thống trị của họ.","Quyền tổ chức – quản lý là hệ quả của địa vị kinh tế, không phải yếu tố gốc quyết định; gốc rễ là quyền sở hữu tư liệu sản xuất.","Nhà nước chính là công cụ ban hành pháp luật, không phải «yếu tố» mà giai cấp nắm giữ để quyết định pháp luật; trả lời như vậy là vòng vo.",""],"s":"C. Mác – Ph. Ăngghen, «Tuyên ngôn của Đảng Cộng sản» (1848); Giáo trình Triết học Mác-Lênin (2021), Chương 3, mục I.2 và mục III.2 (Nhà nước)","c":3},{"q":"Cơ sở, động lực, mục đích của nhận thức là:","o":["Lý luận","Thực tiễn","Triết học","Tinh thần"],"a":[1],"e":"Thực tiễn là cơ sở, động lực, mục đích của nhận thức và là tiêu chuẩn của chân lý: thực tiễn cung cấp tài liệu cho nhận thức, đặt ra nhu cầu thúc đẩy nhận thức phát triển, và nhận thức suy cho cùng là để phục vụ cải tạo thực tiễn. Lênin nhấn mạnh quan điểm về đời sống, về thực tiễn phải là quan điểm thứ nhất và cơ bản của lý luận nhận thức.","w":["Lý luận là kết quả, là trình độ cao của nhận thức; nó hình thành từ thực tiễn chứ không phải cơ sở, mục đích của nhận thức.","","Triết học là một hình thái ý thức, một hệ thống lý luận – cũng là sản phẩm của nhận thức, không phải cơ sở hay động lực của nhận thức.","Coi «tinh thần» là cơ sở của nhận thức là quan điểm duy tâm, trái với chủ nghĩa duy vật biện chứng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục III.2 – Thực tiễn và vai trò của thực tiễn đối với nhận thức; V.I. Lênin, «Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán» (1909)","c":2},{"q":"Định nghĩa phạm trù vật chất phụ thuộc chủ yếu vào:","o":["Sự phát triển khoa học kỹ thuật","Sự phát triển của logic hình thức","Sự phát triển của logic biện chứng","Tất cả các đáp án đều đúng"],"a":[0],"e":"Lịch sử phạm trù vật chất cho thấy quan niệm về vật chất luôn gắn với trình độ khoa học từng thời kỳ: từ quy vật chất về các chất cụ thể (nước, lửa...) thời cổ đại, đến nguyên tử thời cận đại; khi vật lý cuối thế kỷ XIX – đầu XX phát hiện điện tử, phóng xạ... thì quan niệm cũ khủng hoảng và Lênin phải đưa ra định nghĩa mới. Vì vậy, theo cách hỏi của đề, định nghĩa vật chất phụ thuộc chủ yếu vào sự phát triển của khoa học (khoa học tự nhiên, kỹ thuật).","w":["","Logic hình thức chỉ là công cụ tư duy chặt chẽ, không phải nhân tố quyết định nội dung quan niệm về vật chất.","Logic biện chứng là phương pháp tư duy giúp khái quát, nhưng chính các phát minh khoa học mới là cái buộc quan niệm vật chất phải thay đổi.","Không phải «tất cả đều đúng» vì logic hình thức và logic biện chứng không phải yếu tố chủ yếu quyết định định nghĩa vật chất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục I.1 – Vật chất và các hình thức tồn tại của vật chất; V.I. Lênin, «Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán» (1909)","c":2,"f":1},{"q":"Theo quan điểm của triết học Mác - Lênin, mối quan hệ giữa tồn tại xã hội và ý thức xã hội thể hiện như thế nào?","o":["Ý thức xã hội quyết định tồn tại xã hội; tồn tại xã hội có tính độc lập tương đối, tác động trở lại ý thức xã hội","Tồn tại xã hội quyết định ý thức xã hội; ý thức xã hội có tính độc lập tương đối, tác động trở lại tồn tại xã hội","Tồn tại xã hội và ý thức xã hội tồn tại độc lập, không liên quan gì đến nhau","Tồn tại xã hội quyết định tồn tại xã hội, ý thức xã hội quyết định ý thức xã hội"],"a":[1],"e":"Nguyên lý cơ bản của chủ nghĩa duy vật lịch sử là tồn tại xã hội quyết định ý thức xã hội; nhưng ý thức xã hội có tính độc lập tương đối (thường lạc hậu hoặc vượt trước, có tính kế thừa, tác động qua lại giữa các hình thái) và tác động trở lại tồn tại xã hội. Mác viết: không phải ý thức quyết định tồn tại mà tồn tại xã hội quyết định ý thức.","w":["Đảo ngược quan hệ, coi ý thức quyết định tồn tại – đó là quan điểm duy tâm về lịch sử.","","Phủ nhận mối liên hệ giữa tồn tại và ý thức xã hội là sai, vì giữa chúng có quan hệ biện chứng quyết định và tác động lại.","Cho rằng mỗi mặt chỉ tự quyết định chính mình là phủ nhận mối quan hệ giữa hai mặt, trái với nguyên lý duy vật lịch sử."],"s":"C. Mác, «Lời tựa Góp phần phê phán khoa kinh tế chính trị» (1859); Giáo trình Triết học Mác-Lênin (2021), Chương 3, mục IV","c":3},{"q":"Theo chủ nghĩa duy vật lịch sử, quan hệ sản xuất có thể tác động tới lực lượng sản xuất theo hướng:","o":["Thúc đẩy hoặc kìm hãm sự phát triển","Thúc đẩy","Hỗ trợ","Tạo điều kiện"],"a":[0],"e":"Quan hệ sản xuất tác động trở lại lực lượng sản xuất theo hai chiều: nếu phù hợp với trình độ lực lượng sản xuất thì thúc đẩy nó phát triển; nếu không phù hợp (lạc hậu hoặc «vượt trước») thì kìm hãm, thậm chí phá hoại lực lượng sản xuất. Vì vậy phải nói đủ cả «thúc đẩy hoặc kìm hãm».","w":["","Chỉ nêu chiều thúc đẩy là phiến diện, bỏ qua trường hợp quan hệ sản xuất không phù hợp sẽ kìm hãm lực lượng sản xuất.","«Hỗ trợ» chỉ là một dạng của tác động tích cực, không bao quát tác động tiêu cực (kìm hãm).","«Tạo điều kiện» cũng chỉ là chiều tích cực, chưa phản ánh đầy đủ hai chiều tác động."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.1 – Quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất","c":3},{"q":"Một sinh viên định nghĩa bệnh chủ quan duy ý chí bằng các biểu hiện đặc trưng. Hãy chỉ ra một biểu hiện không thuộc chủ quan duy ý chí:","o":["Suy nghĩ và hành động nóng vội","Chạy theo nguyện vọng chủ quan","Quyết tâm thực hiện mục tiêu","Không tính tới điều kiện và khả năng thực tế"],"a":[2],"e":"Chủ quan duy ý chí là tuyệt đối hóa vai trò ý chí, coi thường quy luật khách quan và điều kiện thực tế, biểu hiện ở suy nghĩ, hành động giản đơn, nóng vội, chạy theo nguyện vọng chủ quan. Còn «quyết tâm thực hiện mục tiêu» là phẩm chất tích cực của nhân tố chủ quan; nó chỉ thành bệnh khi tách rời điều kiện khách quan, nên bản thân nó không phải biểu hiện của chủ quan duy ý chí.","w":["Suy nghĩ và hành động nóng vội, đốt cháy giai đoạn là biểu hiện điển hình của bệnh chủ quan duy ý chí (Đại hội VI đã chỉ rõ).","Chạy theo nguyện vọng chủ quan, lấy mong muốn thay cho thực tế, chính là bản chất của bệnh chủ quan duy ý chí.","","Không tính tới điều kiện và khả năng thực tế là xa rời nguyên tắc khách quan – biểu hiện cốt lõi của bệnh chủ quan duy ý chí."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục I.3 – Ý nghĩa phương pháp luận của mối quan hệ vật chất – ý thức; Văn kiện Đại hội VI của Đảng (1986)","c":4},{"q":"Triết học ra đời từ đâu?","o":["Từ thực tiễn, do nhu cầu của thực tiễn","Từ sự tư duy của con người về bản thân mình","Từ sự vận động của ý muốn chủ quan của con người","Từ thực tiễn, do sự phát triển của khoa học kỹ thuật"],"a":[0],"e":"Triết học ra đời từ thực tiễn, do nhu cầu của thực tiễn, với hai nguồn gốc: nguồn gốc nhận thức (tư duy đạt trình độ khái quát, trừu tượng cao) và nguồn gốc xã hội (phân công lao động trí óc – chân tay, xuất hiện giai cấp, tầng lớp trí thức). Chính hoạt động thực tiễn và nhu cầu hiểu biết, cải tạo thế giới đã làm nảy sinh triết học.","w":["","Tư duy của con người về bản thân chỉ là một phần của nhận thức; tách nó khỏi thực tiễn là quan điểm duy tâm về nguồn gốc triết học.","«Ý muốn chủ quan» không thể là nguồn gốc của triết học; đây là cách giải thích duy tâm chủ quan.","Triết học ra đời từ thời cổ đại khi khoa học kỹ thuật còn sơ khai; khoa học kỹ thuật không phải nguyên nhân ra đời của triết học."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.1 – Nguồn gốc của triết học","c":1},{"q":"Đứng im được hiểu là trạng thái như thế nào?","o":["Tuyệt đối","Tương đối","Vừa tuyệt đối vừa tương đối","Không có đáp án đúng"],"a":[1],"e":"Vận động là tuyệt đối, còn đứng im là tương đối, tạm thời: đứng im chỉ xảy ra trong một quan hệ nhất định (không phải mọi quan hệ), với một hình thức vận động nhất định và là sự ổn định tạm thời của vận động. Ăngghen viết: mọi sự cân bằng chỉ là tương đối và tạm thời.","w":["Nếu đứng im là tuyệt đối thì sẽ phủ nhận vận động – thuộc tính cố hữu của vật chất; đây là quan điểm siêu hình.","","Đứng im không thể «vừa tuyệt đối» vì chỉ vận động mới tuyệt đối; đứng im luôn là trường hợp riêng, tương đối.","Có đáp án đúng là «tương đối» nên phương án này sai."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục I.1 – Vận động và đứng im; Ph. Ăngghen, «Biện chứng của tự nhiên»","c":2,"f":1},{"q":"Sự ra đời và tồn tại của nhà nước:","o":["Là hiện tượng mang tính khách quan, bị quyết định bởi quá trình phát triển của xã hội","Là hiện tượng mang tính chủ quan, phụ thuộc vào nguyện vọng của giai cấp cầm quyền","Là hiện tượng mang tính chủ quan phụ thuộc vào nguyện vọng của mỗi quốc gia, mỗi dân tộc","(Không đủ thông tin)"],"a":[0],"e":"Nhà nước ra đời một cách khách quan khi lực lượng sản xuất phát triển, xuất hiện của dư, chế độ tư hữu và giai cấp với mâu thuẫn không thể điều hòa. Lênin khẳng định nhà nước là sản phẩm và biểu hiện của những mâu thuẫn giai cấp không thể điều hòa được; nó sẽ tiêu vong khi cơ sở giai cấp không còn.","w":["","Nhà nước không do ý muốn chủ quan của giai cấp cầm quyền sinh ra; giai cấp thống trị chỉ nắm và sử dụng nhà nước khi điều kiện khách quan đã xuất hiện.","Nhà nước không phụ thuộc vào nguyện vọng của từng quốc gia, dân tộc mà là kết quả tất yếu của sự phát triển kinh tế – xã hội có giai cấp.","Đề đã đủ thông tin; quan điểm về tính khách quan của sự ra đời nhà nước được nêu rõ trong lý luận Mác-Lênin."],"s":"V.I. Lênin, «Nhà nước và cách mạng» (1917); Ph. Ăngghen, «Nguồn gốc của gia đình, của chế độ tư hữu và của nhà nước» (1884); Giáo trình Triết học Mác-Lênin (2021), Chương 3, mục III.2","c":3},{"q":"Theo quan điểm của phép biện chứng duy vật thì trong những điều kiện xác định cái đơn nhất và cái gì có thể chuyển hóa lẫn nhau?","o":["Cái đặc thủ","Cái cái riêng","Cái chung","Quy luật"],"a":[2],"e":"Giáo trình khẳng định: trong những điều kiện xác định, cái đơn nhất và cái chung có thể chuyển hóa lẫn nhau. Cái mới lúc đầu xuất hiện dưới dạng cái đơn nhất, rồi hoàn thiện dần và trở thành cái chung; ngược lại cái cũ vốn là cái chung, khi không còn phù hợp sẽ mất dần và trở thành cái đơn nhất. Vì vậy cặp chuyển hóa ở đây là cái đơn nhất – cái chung.","w":["«Cái đặc thù» không phải là phạm trù được giáo trình đặt trong cặp chuyển hóa với cái đơn nhất; giáo trình chỉ nói về cái riêng, cái chung và cái đơn nhất.","«Cái riêng» là chỉnh thể chứa cả cái chung lẫn cái đơn nhất, nên nó không phải là cái chuyển hóa qua lại với cái đơn nhất.","","«Quy luật» là mối liên hệ bản chất, tất nhiên, lặp lại; nó không phải là phạm trù trong cặp cái chung – cái đơn nhất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục II.3 (Các cặp phạm trù cơ bản: cái riêng – cái chung – cái đơn nhất).","c":2},{"q":"Theo quan niệm duy vật biện chứng về lịch sử thì đỉnh cao của sự phát triển đấu tranh giai cấp là đấu tranh trong lĩnh vực nào?","o":["Chính trị","Võ trang","Kinh tế","Giải phóng"],"a":[0],"e":"Theo chủ nghĩa duy vật lịch sử, đấu tranh giai cấp đi từ đấu tranh kinh tế lên đấu tranh chính trị, mà đấu tranh chính trị là hình thức cao nhất vì nó nhằm vào vấn đề cơ bản là giành chính quyền nhà nước. Đỉnh cao của đấu tranh chính trị chính là cách mạng xã hội, lật đổ giai cấp thống trị và xác lập quyền lực của giai cấp cách mạng.","w":["","«Võ trang» chỉ là một phương pháp, hình thức thể hiện của đấu tranh chính trị (khởi nghĩa, chiến tranh cách mạng), không phải một lĩnh vực đấu tranh riêng ở cấp cao nhất.","«Kinh tế» là hình thức đấu tranh ban đầu, thấp nhất (đòi tăng lương, giảm giờ làm), chưa đụng đến chính quyền nhà nước.","«Giải phóng» là mục tiêu, kết quả mà đấu tranh giai cấp hướng tới, không phải một lĩnh vực đấu tranh."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục II.1 (Giai cấp và đấu tranh giai cấp); V.I. Lênin, «Làm gì?».","c":3},{"q":"Quan điểm tiến bộ và cách mạng nhất của chủ nghĩa Mác-Lênin về vấn đề con người là:","o":["Giải thích được nguồn gốc tự nhiên và xã hội của con người dưới ánh sáng khoa học","Mô tả được quá trình hoạt động sống và lao động sản xuất của con người theo tinh thần của chủ nghĩa duy vật","Đưa ra được học thuyết cách mạng và triệt để về đấu tranh giải phóng con người","Giải thích được một cách khoa học nguồn gốc của ý thức của con người"],"a":[2],"e":"Điểm tiến bộ và cách mạng nhất của chủ nghĩa Mác-Lênin về con người không chỉ dừng ở việc giải thích con người, mà là đưa ra học thuyết cách mạng triệt để về giải phóng con người: xóa bỏ chế độ tư hữu, áp bức bóc lột, tha hóa, hướng tới sự phát triển tự do và toàn diện của mỗi người. Đúng như Mác viết trong Luận cương về Feuerbach: vấn đề là cải tạo thế giới.","w":["Giải thích nguồn gốc tự nhiên và xã hội của con người là thành tựu khoa học quan trọng, nhưng mới ở mức lý giải, chưa phải điểm cách mạng nhất.","Mô tả quá trình hoạt động sống và lao động là cơ sở lý luận, nhưng chỉ mang tính mô tả, không thể hiện tính cách mạng là cải tạo và giải phóng con người.","","Giải thích nguồn gốc ý thức thuộc về bản thể luận và nhận thức luận, không phải là nội dung cách mạng nhất trong vấn đề con người."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục VI (Triết học về con người); C. Mác, «Luận cương về Feuerbach» (luận cương 11).","c":3},{"q":"Theo quan điểm của chủ nghĩa duy vật biện chứng thì thông qua vận động mà các dạng cụ thể của vật chất:","o":["Tạo ra ý thức","Không tồn tại","Mất dẫn đi","Biểu hiện"],"a":[3],"e":"Vận động là phương thức tồn tại của vật chất: vật chất chỉ tồn tại bằng cách vận động, và thông qua vận động mà các dạng cụ thể của vật chất biểu hiện sự tồn tại của mình. Ăngghen nói: chỉ trong vận động vật thể mới bộc lộ mình là gì; về một vật không vận động thì không có gì để nói cả.","w":["Vận động không «tạo ra ý thức» cho mọi dạng vật chất; ý thức chỉ là sản phẩm của bộ óc người và của đời sống xã hội, lao động, ngôn ngữ.","Nói «không tồn tại» là ngược hẳn với luận điểm vận động là phương thức tồn tại của vật chất.","Vận động không làm vật chất «mất dần đi»; vật chất và vận động không tự sinh ra, không mất đi mà chỉ chuyển hóa từ hình thức này sang hình thức khác.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục I.1 (Phương thức và hình thức tồn tại của vật chất); Ph. Ăngghen, «Biện chứng của tự nhiên».","c":2},{"q":"Bản chất của nhà nước là:","o":["Cơ quan phúc lợi chung của toàn xã hội","Cơ quan trọng tài thực hiện chức năng phân xử và hòa giải các xung đột xã hội","Công cụ của giai cấp thống trị xã hội","(Không đủ thông tin)"],"a":[2],"e":"Theo chủ nghĩa duy vật lịch sử, nhà nước ra đời từ sự không thể điều hòa được của mâu thuẫn giai cấp; về bản chất, nhà nước là công cụ (bộ máy) chuyên chính của giai cấp thống trị về kinh tế nhằm bảo vệ lợi ích và trật tự của giai cấp đó. Lênin gọi nhà nước là «bộ máy dùng để duy trì sự thống trị của giai cấp này đối với giai cấp khác».","w":["Coi nhà nước là «cơ quan phúc lợi chung» là quan điểm phi giai cấp, che giấu bản chất giai cấp của nhà nước; chức năng xã hội chỉ là một mặt phục vụ cho chức năng giai cấp.","Coi nhà nước là «trọng tài» đứng trên các giai cấp để hòa giải là quan niệm mà Lênin đã phê phán; nhà nước không đứng trung lập mà thuộc về giai cấp thống trị.","","Lựa chọn «không đủ thông tin» không đúng vì giáo trình nêu rõ bản chất giai cấp của nhà nước."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục III.2 (Nhà nước); V.I. Lênin, «Nhà nước và cách mạng»; Ph. Ăngghen, «Nguồn gốc của gia đình, của chế độ tư hữu và của nhà nước».","c":3},{"q":"Khi chất mới của sự vật ra đời có thể làm thay đổi những gì của sự vận động và phát triển của sự vật?","o":["Bản chất, hình thức","Kết cấu, quy mô","Hình thức kết cấu","Hình thức vận động"],"a":[1],"e":"Trong quy luật lượng – chất, chất mới ra đời lại tác động trở lại lượng của sự vật: nó có thể làm thay đổi kết cấu, quy mô, trình độ, nhịp điệu của sự vận động và phát triển của sự vật. Trong các lựa chọn, «kết cấu, quy mô» là cặp khớp với nội dung giáo trình (đều là những biểu hiện về lượng).","w":["«Bản chất, hình thức» không phải là những gì giáo trình liệt kê; ở đây đang nói đến tác động của chất mới lên lượng, chứ không phải lên cặp bản chất – hiện tượng hay nội dung – hình thức.","","«Hình thức kết cấu» là cụm từ ghép lệch, không đúng nội dung giáo trình; giáo trình nói kết cấu đi cùng quy mô, trình độ, nhịp điệu.","«Hình thức vận động» thay đổi gắn với sự chuyển sang một chất khác, nhưng giáo trình không nêu nó là cái mà chất mới tác động trở lại để thay đổi."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục II.4 (Quy luật chuyển hóa từ những sự thay đổi về lượng thành những sự thay đổi về chất và ngược lại).","c":2},{"q":"Chất và lượng có mối quan hệ với nhau như thế nào?","o":["Không có mối quan hệ gì với nhau","Chỉ có mối quan hệ giữa chất với lượng","Chỉ có mối quan hệ giữa lượng với chất","Có mối quan hệ biện chứng với nhau"],"a":[3],"e":"Chất và lượng là hai mặt thống nhất trong mỗi sự vật, quy định lẫn nhau: lượng thay đổi vượt quá độ sẽ dẫn đến chất đổi, và chất mới ra đời lại quy định một lượng mới. Vì vậy, quan hệ giữa chúng là quan hệ biện chứng, tác động qua lại hai chiều.","w":["Nói chất và lượng «không có quan hệ» là quan điểm siêu hình; thực tế mỗi sự vật là sự thống nhất của chất và lượng.","Chỉ thừa nhận chiều tác động từ chất sang lượng là phiến diện, bỏ qua việc lượng đổi dẫn đến chất đổi.","Chỉ thừa nhận chiều tác động từ lượng sang chất cũng phiến diện, bỏ qua việc chất mới quy định lượng mới.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục II.4 (Quy luật lượng – chất).","c":2,"id":"1xo5v5p"},{"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử, trong xã hội khi xuất hiện mâu thuẫn gay gắt giữa lực lượng sản xuất và quan hệ sản xuất thì:","o":["Quan hệ sản xuất sẽ tự động thay đổi cho phù hợp với lực lượng sản xuất","Quan hệ sản xuất không thể thay đổi được vì nó được bảo vệ bằng quyền lực nhà nước","Lực lượng sản xuất phải tự điều chỉnh cho phù hợp với quan hệ sản xuất","Quan hệ sản xuất được thay đổi thông qua những cuộc cải cách và các cuộc cách mạng xã hội"],"a":[3],"e":"Khi lực lượng sản xuất phát triển mà quan hệ sản xuất cũ trở thành «xiềng xích» kìm hãm, mâu thuẫn trở nên gay gắt và đòi hỏi phải thay đổi quan hệ sản xuất. Sự thay đổi đó không tự động diễn ra mà phải thông qua hoạt động của con người: cải cách, và ở mức triệt để là cách mạng xã hội. Mác viết: khi ấy «bắt đầu thời đại một cuộc cách mạng xã hội».","w":["Quan hệ sản xuất không «tự động» thay đổi, vì nó gắn với lợi ích của giai cấp thống trị; phải có hoạt động cải cách hoặc cách mạng của con người.","Nói quan hệ sản xuất «không thể thay đổi» là sai; quyền lực nhà nước chỉ có thể trì hoãn, không ngăn được tính tất yếu của quy luật.","Đảo ngược quan hệ quyết định: lực lượng sản xuất quyết định quan hệ sản xuất, nên quan hệ sản xuất phải thay đổi cho phù hợp, chứ không phải ngược lại.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.2 (Quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất); C. Mác, «Lời tựa Góp phần phê phán khoa kinh tế chính trị» (1859).","c":3},{"q":"Lực lượng sản xuất được hiểu là khái niệm dùng để chỉ:","o":["Quan hệ giữa con người với tự nhiên trong quá trình sản xuất","Quan hệ giữa người với xã hội trong quá trình sản xuất","Quan hệ giữa người sản xuất trong quá trình sản xuất","Quan hệ giữa những người lao động trong quá trình tác động vào giới tự nhiên"],"a":[0],"e":"Lực lượng sản xuất là sự kết hợp giữa người lao động với tư liệu sản xuất, tạo ra sức sản xuất và năng lực thực tiễn cải biến giới tự nhiên. Vì vậy, nó biểu hiện quan hệ giữa con người với tự nhiên trong quá trình sản xuất, khác với quan hệ sản xuất là quan hệ giữa người với người.","w":["","Quan hệ giữa người với xã hội trong sản xuất thuộc về mặt xã hội của sản xuất, gần với quan hệ sản xuất, không phải lực lượng sản xuất.","Quan hệ giữa những người sản xuất với nhau chính là định nghĩa của quan hệ sản xuất.","Quan hệ giữa những người lao động với nhau vẫn là quan hệ người – người (thuộc quan hệ sản xuất), chứ không phải quan hệ người – tự nhiên."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.2 (Lực lượng sản xuất và quan hệ sản xuất).","c":3},{"q":"Kiến trúc thượng tầng là gì?","o":["Các quan hệ sản xuất hiện có trong xã hội","Hệ tư tưởng của giai cấp thống trị","Cơ sở kinh tế của xã hội","Những quan điểm, tư tưởng và các thiết chế của xã hội tương ứng được hình thành trên cơ sở hạ tầng"],"a":[3],"e":"Kiến trúc thượng tầng là toàn bộ những quan điểm chính trị, pháp quyền, triết học, đạo đức, tôn giáo, nghệ thuật… cùng với những thiết chế xã hội tương ứng (nhà nước, đảng phái, giáo hội, đoàn thể…), được hình thành trên một cơ sở hạ tầng nhất định. Định nghĩa này bao gồm cả hai mặt: hệ thống quan điểm, tư tưởng và hệ thống thiết chế.","w":["Tổng hợp các quan hệ sản xuất hợp thành cơ cấu kinh tế là định nghĩa của cơ sở hạ tầng, không phải kiến trúc thượng tầng.","Hệ tư tưởng của giai cấp thống trị chỉ là một bộ phận (dù giữ vai trò chủ đạo) của kiến trúc thượng tầng, chưa bao gồm các thiết chế và các tư tưởng khác.","Cơ sở kinh tế của xã hội chính là cơ sở hạ tầng, là cái quyết định kiến trúc thượng tầng.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.3 (Biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng).","c":3},{"q":"Điền vào dấu (...): \"Quan điểm nhất quán từ xưa đến nay của các nhà triết học duy vật là thừa nhận sự tồn tại .... lấy bản thân giới tự nhiên để giải thích tự nhiên\".","o":["Chủ quan của thế giới vật chất","Song song với thế giới vật chất","Khách quan của thế giới vật chất","Có tính trật tự, nguyên tắc của thế giới vật chất"],"a":[2],"e":"Các nhà duy vật từ cổ đại đến nay đều thừa nhận sự tồn tại khách quan của thế giới vật chất, tức tồn tại độc lập với ý thức con người, và dùng chính giới tự nhiên để giải thích tự nhiên, không viện đến thần linh hay lực lượng siêu nhiên. Đây là điểm cốt lõi phân biệt chủ nghĩa duy vật với chủ nghĩa duy tâm.","w":["«Chủ quan» là sai vì nói thế giới vật chất phụ thuộc ý thức chủ thể chính là lập trường duy tâm chủ quan.","«Song song với thế giới vật chất» là lập trường nhị nguyên luận (vật chất và tinh thần song song tồn tại), không phải quan điểm duy vật.","","Tính trật tự, có quy luật là một đặc điểm của thế giới, nhưng điều cốt lõi các nhà duy vật nhất quán thừa nhận là tính khách quan của nó."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục I.1 (Quan niệm của chủ nghĩa duy tâm và chủ nghĩa duy vật trước C. Mác về phạm trù vật chất).","c":2},{"q":"Chủ nghĩa Mác-Lênin gồm ba bộ phận cấu thành đó là:","o":["Triết học, Kinh tế chính trị học và Chủ nghĩa xã hội khoa học","Triết học, Kinh tế chính trị học và Chính trị học","Triết học, Kinh tế học và Chủ nghĩa xã hội khoa học","(Không đủ thông tin)"],"a":[0],"e":"Chủ nghĩa Mác-Lênin gồm ba bộ phận lý luận cấu thành: triết học Mác-Lênin, kinh tế chính trị Mác-Lênin và chủ nghĩa xã hội khoa học. Lênin đã trình bày điều này trong «Ba nguồn gốc và ba bộ phận cấu thành của chủ nghĩa Mác», tương ứng với ba nguồn gốc là triết học cổ điển Đức, kinh tế chính trị cổ điển Anh và chủ nghĩa xã hội không tưởng Pháp.","w":["","«Chính trị học» không phải là bộ phận cấu thành; bộ phận thứ ba là chủ nghĩa xã hội khoa học.","«Kinh tế học» là sai tên gọi; bộ phận cấu thành là kinh tế chính trị học (nghiên cứu quan hệ sản xuất), không phải kinh tế học nói chung.","Lựa chọn «không đủ thông tin» sai vì ba bộ phận cấu thành đã được xác định rõ ràng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục II; V.I. Lênin, «Ba nguồn gốc và ba bộ phận cấu thành của chủ nghĩa Mác» (1913).","c":1},{"q":"Hãy chỉ ra sai lầm của các nhà triết học thế kỷ XVII-XVIII trong quan niệm về vật chất (3 đáp án):","o":["Vật chất biểu hiện qua không gian và thời gian","Đồng nhất vật chất với vật thể","Đề cập đến vai trò của vật thể","Đồng nhất vật chất với một số tính chất phổ biến của vật thể"],"a":[1,2,3],"e":"Chủ nghĩa duy vật thế kỷ XVII–XVIII mang tính máy móc, siêu hình: họ đồng nhất vật chất nói chung với vật thể cụ thể (nguyên tử), đồng nhất vật chất với một thuộc tính phổ biến của vật thể là khối lượng, và quy vật chất về vai trò của các vật thể vĩ mô theo cơ học Niutơn. Ba lựa chọn được chọn đều phản ánh khuynh hướng quy vật chất về vật thể và thuộc tính của vật thể.","w":["Nói vật chất biểu hiện qua không gian và thời gian không phải là sai lầm; ngược lại, phép biện chứng duy vật khẳng định không gian, thời gian là hình thức tồn tại của vật chất (sai lầm của họ là tách không gian, thời gian thành tuyệt đối, tách rời vật chất).","","",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục I.1 (Quan niệm về vật chất của chủ nghĩa duy vật thế kỷ XVII–XVIII); V.I. Lênin, «Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán».","k":"nghi vấn: «Đề cập đến vai trò của vật thể» bản thân không phải là sai lầm (có thể là phương án bị cắt/biên tập lệch); chỉ hiểu được là sai lầm nếu ngầm hiểu là «quy vật chất về vật thể»; B và D là chắc chắn.","c":2},{"q":"Theo quan điểm duy vật lịch sử, quan hệ cơ bản nhất, quyết định mọi mối quan hệ xã hội là:","o":["Quan hệ quyền lực nhà nước","Quan hệ văn hóa","Quan hệ kinh tế","Quan hệ tôn giáo"],"a":[2],"e":"Theo chủ nghĩa duy vật lịch sử, sản xuất vật chất là cơ sở của đời sống xã hội, nên quan hệ kinh tế (quan hệ sản xuất) là quan hệ cơ bản, ban đầu, quyết định mọi quan hệ xã hội khác như chính trị, pháp quyền, đạo đức, văn hóa, tôn giáo. Cơ sở hạ tầng quyết định kiến trúc thượng tầng.","w":["«Quan hệ quyền lực nhà nước» thuộc kiến trúc thượng tầng, bị quan hệ kinh tế quyết định, dù có tác động trở lại mạnh mẽ.","«Quan hệ văn hóa» thuộc đời sống tinh thần, là cái phái sinh từ quan hệ kinh tế.","","«Quan hệ tôn giáo» là một hình thái ý thức xã hội, bị tồn tại xã hội và quan hệ kinh tế quy định."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I (Học thuyết hình thái kinh tế – xã hội).","c":3},{"q":"Theo quan điểm triết học Mácxít, khẳng định nào sau đây sai?","o":["Thế giới là một chỉnh thể trong sự liên hệ, ràng buộc lẫn nhau","Con người không thể tách khỏi các mối quan hệ với tự nhiên","Giữa các loài luôn có những khâu trung gian nối chúng với nhau","Thế giới tinh thần và thế giới vật chất tồn tại độc lập nhau"],"a":[3],"e":"Câu hỏi tìm khẳng định SAI. Theo triết học Mác, thế giới thống nhất ở tính vật chất; ý thức là thuộc tính của bộ óc người, là sự phản ánh thế giới vật chất, nên thế giới tinh thần không thể tồn tại độc lập với thế giới vật chất. Khẳng định chúng «tồn tại độc lập nhau» là quan điểm nhị nguyên luận, trái với chủ nghĩa duy vật biện chứng.","w":["Đây là khẳng định đúng, phù hợp nguyên lý về mối liên hệ phổ biến: thế giới là một chỉnh thể thống nhất mà các bộ phận liên hệ, ràng buộc nhau.","Đây là khẳng định đúng: con người là một bộ phận của tự nhiên, sống nhờ tự nhiên và luôn quan hệ với tự nhiên.","Đây là khẳng định đúng: Ăngghen chỉ ra giữa các loài, các lĩnh vực luôn có những khâu trung gian, không có ranh giới tuyệt đối cứng nhắc.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục I.3 (Tính thống nhất vật chất của thế giới) và II.2 (Nguyên lý về mối liên hệ phổ biến); Ph. Ăngghen, «Biện chứng của tự nhiên».","c":2},{"q":"Hình thức nhận thức nào cần có sự tác động trực tiếp của vật vào cơ quan giác quan của con người?","o":["Cảm giác","Tri giác","Suy luận","Phán đoán"],"a":[0],"e":"Cảm giác là hình thức đầu tiên, đơn giản nhất của nhận thức cảm tính, nảy sinh khi sự vật tác động trực tiếp vào từng giác quan của con người, phản ánh từng thuộc tính riêng lẻ của sự vật. Đây là nguồn gốc của mọi hiểu biết, nên là đáp án được chọn.","w":["","Tri giác cũng nảy sinh khi sự vật tác động trực tiếp vào giác quan, nhưng nó là tổng hợp nhiều cảm giác; đề bài theo đáp án hướng tới hình thức cơ sở, đầu tiên là cảm giác.","«Suy luận» là hình thức của nhận thức lý tính, rút ra tri thức mới từ các phán đoán, không cần sự tác động trực tiếp của vật vào giác quan.","«Phán đoán» cũng thuộc nhận thức lý tính (liên kết các khái niệm), mang tính gián tiếp, trừu tượng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục III.2 (Các giai đoạn cơ bản của quá trình nhận thức: cảm giác, tri giác, biểu tượng).","k":"nghi vấn: theo giáo trình, cả cảm giác lẫn tri giác đều nảy sinh khi sự vật tác động trực tiếp vào giác quan (chỉ biểu tượng là không cần tác động trực tiếp), nên tri giác cũng thỏa đề; đáp án cảm giác chỉ hợp lý nếu hiểu là hình thức cơ bản, đầu tiên.","c":2},{"q":"Quan hệ biện chứng giữa \"cái riêng\" và \"cái chung\" thì cái chung tồn tại:","o":["Ngoài cái riêng","Cùng cái riêng","Trong cái riêng","Bên cái riêng"],"a":[2],"e":"Theo phép biện chứng duy vật, cái chung chỉ tồn tại trong cái riêng, thông qua cái riêng mà biểu hiện sự tồn tại của mình; không có cái chung thuần túy tồn tại tách rời cái riêng. Lênin viết: cái chung chỉ tồn tại trong cái riêng, thông qua cái riêng.","w":["«Ngoài cái riêng» là quan điểm duy thực (kiểu Platôn) coi cái chung tồn tại độc lập, sinh ra cái riêng; phép biện chứng duy vật bác bỏ điều này.","«Cùng cái riêng» ngụ ý hai thứ tồn tại song song bên cạnh nhau, chưa diễn đạt đúng việc cái chung nằm bên trong, là một bộ phận của cái riêng.","","«Bên cái riêng» cũng hàm ý cái chung đứng cạnh, tách khỏi cái riêng, nên sai."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục II.3 (Cái riêng và cái chung); V.I. Lênin, «Bút ký triết học» (Bàn về phép biện chứng).","c":2},{"q":"\"Cân bằng động\" trong sự phù hợp giữa lực lượng sản xuất và quan hệ sản xuất là gì?","o":["Lực lượng sản xuất và quan hệ sản xuất phù hợp trong suốt quá trình phát triển của con người","Lực lượng sản xuất thay đổi, quan hệ sản xuất không cần thay đổi","Sự phù hợp cụ thể nào đó giữa quan hệ sản xuất và lực lượng sản xuất luôn bị phá vỡ để thay bằng một sự phù hợp khác cao hơn","Khi lực lượng sản xuất đã đến lúc cần thay đổi thì nhất định là quan hệ sản xuất cũng sẽ"],"a":[2],"e":"Sự phù hợp giữa lực lượng sản xuất và quan hệ sản xuất là một trạng thái «cân bằng động»: nó chỉ tương đối, luôn vận động; lực lượng sản xuất không ngừng phát triển làm phá vỡ sự phù hợp cũ, đòi hỏi thiết lập một sự phù hợp mới ở trình độ cao hơn. Quá trình phù hợp – không phù hợp – phù hợp mới lặp lại liên tục, tạo nên sự phát triển của phương thức sản xuất.","w":["Phù hợp «trong suốt quá trình phát triển» là hiểu sự phù hợp là tĩnh, vĩnh viễn; thực tế sự phù hợp luôn bị phá vỡ khi lực lượng sản xuất phát triển.","«Quan hệ sản xuất không cần thay đổi» trái với quy luật: lực lượng sản xuất thay đổi thì sớm muộn quan hệ sản xuất cũng phải thay đổi theo.","","Câu này (dù bị cắt) chỉ nêu tính tất yếu quan hệ sản xuất thay đổi theo, chưa diễn đạt được bản chất «cân bằng động» là sự phù hợp liên tục bị phá vỡ và tái lập ở trình độ cao hơn."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 3, mục I.2 (Quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất).","c":3},{"q":"Triết học duy tâm khách quan và duy tâm chủ quan đều có điểm chung là:","o":["Đề cao lĩnh vực tinh thần của con người","Đề cao lĩnh vực vật chất và tinh thần của con người","Đề cao đời sống tâm linh của con người","(Không đủ thông tin)"],"a":[0],"e":"Duy tâm khách quan (coi «ý niệm», «ý niệm tuyệt đối» là cái có trước) và duy tâm chủ quan (coi cảm giác, ý thức cá nhân là cái có trước) khác nhau ở chỗ tinh thần đó là khách quan hay của chủ thể. Nhưng cả hai đều thừa nhận tinh thần, ý thức là tính thứ nhất, tức đều đề cao lĩnh vực tinh thần của con người, tuyệt đối hóa nó thành cái quyết định.","w":["","Đề cao cả vật chất lẫn tinh thần là lập trường nhị nguyên luận, không phải điểm chung của chủ nghĩa duy tâm.","«Đời sống tâm linh» quá hẹp, gắn với tôn giáo, tín ngưỡng; chủ nghĩa duy tâm đề cao toàn bộ lĩnh vực tinh thần (ý thức, lý tính, cảm giác), không chỉ tâm linh.","Lựa chọn «không đủ thông tin» sai vì điểm chung của hai trường phái duy tâm đã rõ."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 1, mục I.3 (Vấn đề cơ bản của triết học; chủ nghĩa duy vật và chủ nghĩa duy tâm).","c":1},{"q":"Chân lý bao gồm các tính chất: (4 đáp án)","o":["Tính phong phú, đa dạng","Tính khách quan","Tính tương đối","Tính cụ thể","Tính tuyệt đối"],"a":[1,2,3,4],"e":"Giáo trình nêu chân lý là tri thức phù hợp với hiện thực khách quan và đã được thực tiễn kiểm nghiệm, với các tính chất: tính khách quan (nội dung không phụ thuộc ý thức con người), tính tương đối (phù hợp nhưng chưa hoàn toàn đầy đủ), tính tuyệt đối (phù hợp hoàn toàn, đầy đủ trong giới hạn xác định) và tính cụ thể (gắn với đối tượng, điều kiện lịch sử cụ thể). Bốn tính chất này đúng với bốn lựa chọn được chọn.","w":["«Tính phong phú, đa dạng» là đặc điểm của thế giới hiện thực hoặc của tri thức nói chung, không thuộc danh mục tính chất của chân lý trong giáo trình.","","","",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Chương 2, mục III.3 (Chân lý và các tính chất của chân lý); V.I. Lênin, «Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán».","c":2},{"q":"Nhân tố đảm bảo cho sự thắng lợi cuối cùng của một chế độ xã hội là","o":["Có nền khoa học tiên tiến","Có nhân tố chính trị tiến bộ","Có nền văn hóa tiên tiến, đậm đà bản sắc dân tộc","Có thể tạo ra năng suất lao động cao hơn"],"a":[3],"e":"V.I. Lênin (tác phẩm «Sáng kiến vĩ đại») chỉ rõ: xét đến cùng, năng suất lao động là cái quan trọng nhất, chủ yếu nhất bảo đảm cho thắng lợi của chế độ xã hội mới. Vì vậy nhân tố đảm bảo thắng lợi cuối cùng của một chế độ xã hội là khả năng tạo ra năng suất lao động cao hơn chế độ cũ. ([Giáo trình Triết học Mác-Lênin 2021, Chương 1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Khoa học tiên tiến là điều kiện thúc đẩy lực lượng sản xuất, nhưng giáo trình không coi nó là nhân tố quyết định thắng lợi cuối cùng của chế độ xã hội.","Chính trị thuộc kiến trúc thượng tầng, do cơ sở hạ tầng quyết định; Lênin nhấn mạnh năng suất lao động chứ không phải nhân tố chính trị.","Văn hóa cũng thuộc kiến trúc thượng tầng; tiêu chí quyết định mà Lênin nêu là năng suất lao động.",""],"s":"GT Triết học Mác-Lênin (2021), Chương 1, đoạn nói về V.I. Lênin phát triển tư tưởng nâng cao năng suất lao động trong «Sáng kiến vĩ đại»; chưa đối chiếu số mục","c":3,"v":"khớp"},{"q":"Trong thực tế chúng ta phải dựa vào","o":["Hiện thực và dự đoán các khả năng","Cả khả năng và hiện thực","Hiện thực vì khả năng là cái chưa tồn tại","Khả năng vì khả năng có thể chứa hiện thực"],"a":[0],"e":"Giáo trình nêu: vì hiện thực là cái đang tồn tại thực sự, còn khả năng là cái hiện chưa có, nên trong thực tiễn cần dựa vào hiện thực để định chủ trương, phương hướng hành động; đồng thời cũng phải tính đến các khả năng để kế hoạch sát hợp hơn. Do đó đáp án A (dựa vào hiện thực và dự đoán các khả năng) là đúng. ([Giáo trình Triết học Mác-Lênin, bản tái bản lần 3, mục Khả năng và hiện thực](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Giáo trình nói «không dựa vào khả năng» mà chỉ tính đến khả năng; đặt khả năng ngang hiện thực làm chỗ dựa là sai.","Đúng một nửa (dựa vào hiện thực) nhưng sai ở chỗ bỏ qua việc tính đến các khả năng; khả năng tuy chưa tồn tại nhưng biểu hiện khuynh hướng phát triển nên vẫn phải dự đoán.","Chỉ dựa vào cái còn ở dạng khả năng thì dễ rơi vào ảo tưởng; hiện thực mới là chỗ dựa."],"s":"GT Triết học Mác-Lênin (bản cũ), Chương VII, mục VII (Khả năng và hiện thực), phần kết luận phương pháp luận; bản 2021: Chương 2, mục II.2","c":2,"v":"khớp"},{"q":"Thế giới quan được hiểu là gì?","o":["Quan niệm của con người về thế giới","Hệ thống quan niệm của con người về thế giới","Hệ thống quan niệm, quan điểm lý luận của con người về thế giới","Hệ thống quan niệm, quan điểm chung nhất của con người về thế giới"],"a":[3],"e":"Giáo trình định nghĩa thế giới quan là toàn bộ những quan niệm, quan điểm của con người về thế giới và về vị trí của con người trong thế giới đó; triết học là hạt nhân lý luận của thế giới quan. Trong các phương án, D là đầy đủ nhất (hệ thống, quan niệm - quan điểm, tính chung nhất) nên là đáp án của đề. ([Giáo trình Triết học Mác-Lênin 2021, Chương 1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quá sơ lược: thiếu tính «hệ thống» và tính «chung nhất».","Gần với cách nói ngắn gọn của giáo trình 2021 («hệ thống quan điểm của con người về thế giới») nhưng thiếu «chung nhất» nên kém đầy đủ hơn D.","Có «hệ thống», «quan điểm lý luận» nhưng thiếu tính «chung nhất»; «lý luận» là đặc trưng của triết học chứ không phải của thế giới quan nói chung.",""],"s":"GT Triết học Mác-Lênin (2021), Chương 1, mục I.1 và mục II.2 (chức năng thế giới quan); bản cũ: Chương I, mục II.1","c":1,"v":"dễ nhầm","k":"Các bản giáo trình diễn đạt khác nhau (bản cũ: «toàn bộ những quan niệm của con người về thế giới…»; bản 2021: «hệ thống quan điểm…»). Không bản nào có nguyên văn câu D; B và D đều gần đúng, hãy nhớ đáp án đề là D."},{"q":"Chủ nghĩa duy vật lịch sử cho rằng giai cấp nắm được yếu tố nào thì cũng chiếm được địa vị chính trị, có khả năng khách quan thành giai cấp thống trị xã hội?","o":["Tư liệu sản xuất chủ yếu","Quan hệ sản xuất thống trị","Lực lượng sản xuất","Lực lượng sản xuất mới"],"a":[0],"e":"Giáo trình chỉ rõ trong các khác biệt của giai cấp, khác biệt về sở hữu tư liệu sản xuất có ý nghĩa quyết định: tập đoàn người nào nắm tư liệu sản xuất sẽ trở thành giai cấp thống trị xã hội. Giai cấp nào nắm tư liệu sản xuất chủ yếu thì nắm vai trò chi phối tổ chức quản lý sản xuất và phân phối, từ đó có địa vị chính trị. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục II.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Quan hệ sản xuất thống trị là kết quả của việc nắm tư liệu sản xuất chủ yếu, không phải thứ giai cấp «nắm được» đầu tiên.","Lực lượng sản xuất gồm cả người lao động; điều quyết định địa vị giai cấp là quan hệ đối với tư liệu sản xuất, không phải lực lượng sản xuất nói chung.","«Lực lượng sản xuất mới» là nhân tố làm nảy sinh mâu thuẫn xã hội, không phải yếu tố đem lại địa vị thống trị."],"s":"GT Triết học Mác-Lênin (2021), Chương 3, mục II.1 (Giai cấp và đấu tranh giai cấp); bản cũ: Chương XI, mục II.1","c":3,"v":"khớp"},{"q":"Trong xã hội có giai cấp, tính chất kế thừa của ý thức xã hội có gắn với tính chất giai cấp của","o":["Tùy trường hợp cụ thể","Không kế thừa","Có kế thừa"],"a":[2],"e":"Giáo trình khẳng định ý thức xã hội có tính kế thừa; trong xã hội có giai cấp thì các giai cấp khác nhau kế thừa những di sản khác nhau (giai cấp tiến bộ chọn tư tưởng tiến bộ, giai cấp lỗi thời chọn tư tưởng bảo thủ). Vậy sự kế thừa có gắn với tính giai cấp, nên chọn C (có kế thừa). ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục IV](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Tính kế thừa là đặc điểm chung của ý thức xã hội, không phụ thuộc «tùy trường hợp».","Phủ nhận kế thừa là sai; giáo trình nêu rõ ngay cả chủ nghĩa Mác cũng kế thừa triết học cổ điển Đức, kinh tế chính trị Anh, chủ nghĩa xã hội không tưởng Pháp.",""],"s":"GT Triết học Mác-Lênin (2021), Chương 3, mục IV (Ý thức xã hội), phần tính kế thừa; bản cũ: Chương XIII","c":3,"v":"nghi vấn","k":"nghi vấn: Câu hỏi bị cụt chữ («…gắn với tính chất giai cấp của …» thiếu vế sau) nên các phương án rời rạc; C vẫn là lựa chọn hợp lý duy nhất theo nội dung giáo trình."},{"q":"Theo chủ nghĩa duy vật lịch sử, khái niệm \"cách mạng xã hội\" dùng để chỉ yếu tố nào?","o":["Sự tiến bộ, tiền hóa mọi lĩnh vực trong một xã hội nhất định","Sự thay thế chế độ xã hội này bằng một chế độ xã hội khác","Sự thay thế thể chế kinh tế này bằng một thể chế kinh tế khác","Sự thay thế hình thái kinh tế - xã hội này bằng hình thái kinh tế - xã hội khác cao hơn"],"a":[3],"e":"Theo giáo trình, nghĩa rộng của cách mạng xã hội là sự biến đổi có tính chất bước ngoặt và căn bản về chất trong mọi lĩnh vực đời sống xã hội, là phương thức thay thế hình thái kinh tế - xã hội lỗi thời bằng hình thái kinh tế - xã hội cao hơn. Vì vậy D là đáp án đúng. ([Giáo trình Triết học Mác-Lênin, bản tái bản lần 3, Chương XII mục II](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đó là tiến hóa xã hội (phát triển tuần tự, biến đổi cục bộ trong một hình thái), khác với cách mạng xã hội.","«Thay chế độ xã hội» gần với nghĩa hẹp (lật đổ chế độ chính trị) chứ chưa nêu bản chất thay hình thái kinh tế - xã hội cao hơn.","Thay thể chế kinh tế chỉ là một mặt, không phải thay đổi căn bản toàn bộ các lĩnh vực của đời sống xã hội.",""],"s":"GT Triết học Mác-Lênin (bản cũ), Chương XII, mục II.1; bản 2021: Chương 3, mục III.2 (Cách mạng xã hội)","c":3,"v":"khớp"},{"q":"Không phải mọi sự thay đổi về lượng đều","o":["Có khả năng dẫn đến thay đổi về chất","Ngay lập thức thay đổi về chất","Không thể lập tức làm thay đổi về chất","Không làm thay đổi về chất"],"a":[0],"e":"Theo giáo trình, quá trình thay đổi của lượng diễn ra theo xu hướng tăng hoặc giảm nhưng không lập tức dẫn đến sự thay đổi về chất; chỉ khi lượng thay đổi đến giới hạn nhất định (đến độ) mới dẫn đến thay đổi về chất. Đáp án đề chọn là A. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Theo giáo trình lượng đổi «không lập tức» làm chất đổi; phương án này chính là vế mà nội dung quy luật bác bỏ, và đề đã chọn đáp án khác (xem ghi chú).","Nói «không thể lập tức» chỉ lặp lại ý của câu dẫn, không bổ sung nội dung nào.","Lượng tích lũy đến giới hạn độ thì chắc chắn dẫn đến thay đổi chất, nói «không làm thay đổi về chất» là sai."],"s":"GT Triết học Mác-Lênin (2021), Chương 2, mục II.2 (quy luật lượng - chất); bản cũ: Chương VIII, mục II","c":2,"v":"nghi vấn","k":"nghi vấn: Câu dẫn lủng củng (có thể thiếu chữ «ngay lập tức» hay «thay đổi về lượng nào cũng»). Theo nội dung giáo trình, vế «không lập tức đổi chất» khớp với B/C hơn A, nên đáp án A đáng nghi; vẫn giữ đáp án của đề."},{"q":"Chọn phương án đúng để điền vào chỗ trống: \" Điểm xuất phát của ... là sự khẳng định những sự vật hiện tượng của tự nhiên đều bao hàm những mâu thuẫn vốn có của chúng\"","o":["Phép siêu hình","Phép biện chứng","Phép biện chứng duy tâm","Chủ nghĩa duy vật"],"a":[1],"e":"Phép biện chứng xuất phát từ sự thừa nhận mọi sự vật, hiện tượng đều chứa đựng mâu thuẫn nội tại; giáo trình coi quy luật thống nhất và đấu tranh của các mặt đối lập là hạt nhân của phép biện chứng, vì nó nói về nguyên nhân, động lực của vận động và phát triển. Ngược lại phương pháp siêu hình xem sự vật là tĩnh tại, nguyên nhân biến đổi nằm bên ngoài. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf); đối chiếu thêm [câu hỏi tương tự trên tracnghiem.net](https://tracnghiem.net/cntt/cau-hoi-chon-cum-tu-dung-de-dien-vao-cho-trong-diem-xuat-phat-cua-la-su-khang-dinh-nhung-su-vat-va-hi-5737.html))","w":["Phép siêu hình nhìn sự vật tĩnh tại, cô lập, nguyên nhân biến đổi ở bên ngoài, không thừa nhận mâu thuẫn nội tại.","","Phép biện chứng duy tâm (Hêghen) xuất phát từ mâu thuẫn của ý niệm, không phải của sự vật, hiện tượng tự nhiên.","Chủ nghĩa duy vật là lập trường về mối quan hệ vật chất - ý thức, không phải phương pháp xuất phát từ mâu thuẫn."],"s":"GT Triết học Mác-Lênin (2021), Chương 2, mục II.2 (quy luật thống nhất và đấu tranh của các mặt đối lập); chưa đối chiếu nguồn gốc nguyên văn câu hỏi","c":2,"v":"khớp"},{"q":"Theo C.Mác, con người muốn sống thì trước hết cần có thức ăn, đồ mặc v.v. Như vậy, hành vi lịch sử đầu tiên là sản xuất ra:","o":["Tư liệu sinh hoạt","Tư liệu sản xuất","Của cải","Tư liệu lao động"],"a":[0],"e":"Trong «Hệ tư tưởng Đức», C. Mác và Ph. Ăngghen cho rằng sản xuất vật chất là hành vi lịch sử đầu tiên của con người; giáo trình giải thích sản xuất vật chất là tiền đề trực tiếp tạo ra tư liệu sinh hoạt nhằm duy trì sự tồn tại và phát triển của con người. Do đó, với ý «có thức ăn, đồ mặc», hành vi lịch sử đầu tiên là sản xuất ra tư liệu sinh hoạt. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục I.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Tư liệu sản xuất chỉ là phương tiện để làm ra tư liệu sinh hoạt, không phải thứ thỏa mãn trực tiếp nhu cầu ăn, mặc.","«Của cải» là cách nói chung, không khớp với đối tượng mà đề nêu (thức ăn, đồ mặc).","Tư liệu lao động là bộ phận của tư liệu sản xuất, không dùng trực tiếp để ăn, mặc."],"s":"GT Triết học Mác-Lênin (2021), Chương 3, mục I.1 (Sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội); bản cũ: Chương III (Hệ tư tưởng Đức)","c":3,"v":"khớp"},{"q":"Chọn phương án đúng theo quan điểm duy tâm về lịch sử. Trong mối quan hệ giữa tồn tại xã hội và ý thức xã hội.","o":["Suy đến cùng, tồn tại xã hội quyết định ý thức xã hội","Suy đến cùng, ý thức xã hội quyết định tồn tại xã hội","Tồn tại trong mối quan hệ phụ thuộc vào nhau, không cái nào quyết định cái nào","Tùy từng điều mà xem xét cái nào quyết định cái nào"],"a":[1],"e":"Quan điểm duy tâm về lịch sử cho rằng ý thức, tư tưởng quyết định tồn tại xã hội. Ngược lại, theo C. Mác, không phải ý thức của con người quyết định tồn tại của họ mà tồn tại xã hội quyết định ý thức của họ: đó là quan điểm duy vật lịch sử. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục IV.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Đây là quan điểm duy vật lịch sử (tồn tại xã hội quyết định ý thức xã hội).","","Thuyết cho rằng hai yếu tố phụ thuộc nhau, không cái nào quyết định cái nào là quan điểm nhị nguyên, không phải duy tâm.","Quan điểm «tùy từng trường hợp» là chiết trung, không trả lời vấn đề cơ bản của triết học."],"s":"GT Triết học Mác-Lênin (2021), Chương 3, mục IV.1; bản cũ: Chương XIII, mục I","c":3,"v":"khớp"},{"q":"Hình thái ý thức xã hội nào phản ánh bản chất và tính quy luật của thế giới khách quan?","o":["Ý thức chính trị","Ý thức pháp quyền","Ý thức khoa học","Ý thức đạo đức"],"a":[2],"e":"Giáo trình nêu ý thức khoa học phản ánh hiện thực một cách chân thực, chính xác; khác các hình thái ý thức khác, nó phản ánh sự vận động, phát triển của tự nhiên, xã hội và tư duy bằng tư duy logic, thông qua hệ thống khái niệm, phạm trù, quy luật, lý thuyết. Do đó C là đáp án. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục IV](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Ý thức chính trị phản ánh quan hệ giữa các giai cấp, dân tộc, quốc gia; gắn với lợi ích.","Ý thức pháp quyền phản ánh quan hệ lợi ích dưới dạng chuẩn mực pháp luật, không phải quy luật khách quan của thế giới.","","Ý thức đạo đức phản ánh quan hệ ứng xử, chuẩn mực giữa người với người."],"s":"GT Triết học Mác-Lênin (2021), Chương 3, mục IV, phần các hình thái ý thức xã hội (ý thức khoa học); bản cũ: Chương XIII, mục II","c":3,"v":"khớp"},{"q":"Trong 3 đặc trưng của giai cấp thì đặc trưng nào giữ vai trò chi phối các đặc trưng khác ?","o":["Khác nhau về vai trò trong tổ chức lao động xã hội","Khác nhau về địa vị trong hệ thống tổ chức xã hội","Khác nhau về quan hệ sở hữu tư liệu sản xuất xã hội","Tập đoàn này có thể chiếm hữu đoạt lao động của tập đoàn khác"],"a":[2],"e":"Từ định nghĩa giai cấp của V.I. Lênin, giáo trình nêu ba khác biệt (quan hệ sở hữu tư liệu sản xuất, vai trò trong tổ chức quản lý lao động, cách thức và quy mô thu nhập) và khẳng định khác biệt về sở hữu tư liệu sản xuất có ý nghĩa quyết định. Quan hệ đối với tư liệu sản xuất là quan hệ cơ bản, chủ yếu nhất quyết định địa vị kinh tế - xã hội của giai cấp. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục II.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Vai trò trong tổ chức lao động xã hội là đặc trưng bị chi phối bởi quan hệ sở hữu tư liệu sản xuất.","Địa vị trong hệ thống tổ chức xã hội là hệ quả của quan hệ sở hữu, không phải đặc trưng chi phối.","","Đây là hệ quả (tập đoàn này chiếm đoạt lao động của tập đoàn khác), không phải một đặc trưng chi phối."],"s":"V.I. Lênin, «Sáng kiến vĩ đại»; GT Triết học Mác-Lênin (2021), Chương 3, mục II.1; bản cũ: Chương XI, mục II.1","c":3,"v":"khớp"},{"q":"Triết học Mác là thế giới quan khoa học của giai cấp nào?","o":["Giai cấp tư sản tiến bộ","Giai cấp công nhân","Tầng lớp trí thức","Giai cấp lao động"],"a":[1],"e":"Giáo trình khẳng định triết học Mác - Lênin trở thành thế giới quan và phương pháp luận khoa học của giai cấp công nhân và chính đảng của nó để nhận thức và cải tạo thế giới; thế giới quan duy vật biện chứng là hạt nhân hệ tư tưởng của giai cấp công nhân. ([Giáo trình Triết học Mác-Lênin 2021, Chương 1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Giai cấp tư sản tiến bộ không phải chủ thể của triết học Mác; giai cấp tư sản sau khi cầm quyền còn chống lại nó.","","Trí thức là tầng lớp xã hội, không phải giai cấp đại diện cho lực lượng sản xuất tiên tiến và sứ mệnh lịch sử.","«Giai cấp lao động» không phải thuật ngữ của giáo trình; giáo trình dùng «giai cấp công nhân»."],"s":"GT Triết học Mác-Lênin (2021), Chương 1, mục II (triết học Mác - Lênin và vai trò của nó); chưa đối chiếu số tiểu mục","c":1,"v":"khớp"},{"q":"Theo quan điểm của triết học Mác-Lênin, tiêu chí cơ bản để đánh giá phẩm chất của mỗi cá nhân","o":["Địa vị xã hội của cá nhân","Thái độ, hành vi đạo đức của cá nhân","Sự thực hiện khả năng làm chủ đối với hoàn cảnh và hành động thực tiễn của cá nhân","Tất cả đều đúng"],"a":[2],"e":"Theo triết học Mác - Lênin, bản chất con người là tổng hòa các quan hệ xã hội, nên không được đánh giá con người chỉ qua một mặt, một phương diện. Phẩm chất cá nhân được bộc lộ và kiểm nghiệm qua hoạt động thực tiễn, cho nên chọn tiêu chí là sự thực hiện khả năng làm chủ hoàn cảnh và hành động thực tiễn (đáp án C). ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục V](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Địa vị xã hội chỉ là một mặt của các quan hệ xã hội, không phản ánh đầy đủ phẩm chất của cá nhân.","Thái độ, hành vi đạo đức chỉ là một phương diện, chưa bao quát hoạt động thực tiễn của cá nhân.","","A và B không phải tiêu chí cơ bản nên «tất cả đều đúng» sai."],"s":"GT Triết học Mác-Lênin (2021), Chương 3, mục V.1 (bản chất con người là tổng hòa các quan hệ xã hội); câu hỏi này chưa tìm được nguồn nguyên văn","c":3,"v":"chưa kiểm chứng","k":"chưa kiểm chứng được nguồn cho câu này. Giáo trình chỉ nêu bản chất con người là tổng hòa các quan hệ xã hội và không nêu nguyên văn «tiêu chí đánh giá phẩm chất cá nhân»; câu hỏi có vẻ lấy từ bài giảng/đề cương. Đáp án C là suy luận hợp lý, chưa tìm được nguồn xác nhận trực tiếp.","f":1},{"q":"Đâu là nguồn gốc lý luận của chủ nghĩa Mác?","o":["Tư tưởng xã hội phương Đông cổ đại","Triết học cổ điển Đức, kinh tế chính trị cổ điển Anh và chủ nghĩa xã hội không tưởng Pháp","Chủ nghĩa duy vật siêu hình thế kỷ XVII - XVIII ở Tây Âu","Học thuyết tiến hoá"],"a":[1],"e":"Theo V.I. Lênin, chủ nghĩa Mác có ba nguồn gốc lý luận: triết học cổ điển Đức, kinh tế chính trị học cổ điển Anh và chủ nghĩa xã hội không tưởng Pháp. Giáo trình xác nhận chủ nghĩa xã hội không tưởng Pháp (Xanh Ximông, Phuriê) là một trong ba nguồn gốc lý luận của chủ nghĩa Mác. ([Giáo trình Triết học Mác-Lênin 2021, Chương 1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Tư tưởng xã hội phương Đông cổ đại không nằm trong ba nguồn gốc lý luận.","","Chủ nghĩa duy vật siêu hình thế kỷ XVII - XVIII chỉ là yếu tố tham khảo (Phoiơbắc, duy vật Pháp), không phải một trong ba nguồn gốc.","Học thuyết tiến hóa là một trong các thành tựu khoa học tự nhiên (tiền đề khoa học tự nhiên), không phải nguồn gốc lý luận."],"s":"V.I. Lênin, «Ba nguồn gốc và ba bộ phận cấu thành chủ nghĩa Mác» (1913); GT Triết học Mác-Lênin (2021), Chương 1; bản cũ: Chương III, mục I","c":1,"v":"khớp"},{"q":"Ý thức tôn giáo là niềm tin của bộ phận nhân dân, thường là yếu tố bền vững nhất trong đời sống mỗi con người, mỗi xã hội. Vậy, nguyên nhân sự tồn tại bền vững của ý thức tôn giáo là gì?","o":["Nhận thức","Trình độ","Văn hóa","Tâm lý"],"a":[3],"e":"Giáo trình chia ý thức tôn giáo thành tâm lý tôn giáo (biểu tượng, tình cảm, tâm trạng, thói quen của quần chúng về tín ngưỡng) và hệ tư tưởng tôn giáo; tâm lý tôn giáo tạo cơ sở cho hệ tư tưởng tôn giáo xâm nhập quần chúng. Tôn giáo bền vững chủ yếu vì gắn với tâm lý (tình cảm, niềm tin, nhu cầu bù đắp hư ảo), nên đáp án là D. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục IV](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Giáo trình coi nâng cao trình độ nhận thức là điều kiện để khắc phục tôn giáo, không coi đó là nguyên nhân làm nó bền vững.","Trình độ (học vấn) không giải thích tính bền vững của niềm tin tôn giáo.","Văn hóa là yếu tố tác động, không phải nguyên nhân gốc của sự bền vững của ý thức tôn giáo.",""],"s":"GT Triết học Mác-Lênin (2021), Chương 3, mục IV (ý thức tôn giáo); bản cũ: Chương XIII, mục II.6","c":3,"v":"dễ nhầm","k":"Giáo trình không có câu nguyên văn «yếu tố bền vững nhất» hay «nguyên nhân bền vững là tâm lý»; giáo trình giải thích sức sống lâu dài của tôn giáo bằng chức năng đền bù - hư ảo và nguồn gốc xã hội. D là đáp án suy ra từ vai trò của tâm lý tôn giáo, các phương án A, B, C đều có thể gây nhầm."},{"q":"Một sinh viên chuẩn bị bài seminar trong 1 tuần theo cách thức: ngày đầu phác thảo đề cương sơ lược sau đó hằng ngày dành 15 phút sửa chữa và bổ sung bài chuẩn bị đó cả kết cấu, nội dung. Đúng vào buổi seminar, sinh viên đó đã có một bản chuẩn bị hoàn chỉnh. Công việc trên diễn ra theo nguyên lí, quy luật nào?","o":["Quy luật mâu thuẫn","Quy luật lượng - chất","Quy luật phủ định của phủ định","Nguyên lý về mối liên hệ phổ biến"],"a":[1],"e":"Mỗi ngày sinh viên tích lũy một chút (15 phút sửa chữa, bổ sung) nên lượng tăng dần, đến buổi seminar thì bản chuẩn bị thành hoàn chỉnh, tức chất mới ra đời. Giáo trình nêu sự thay đổi về lượng diễn ra từ từ, đạt giới hạn nhất định thì dẫn đến thay đổi về chất, đó là quy luật lượng - chất. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Tình huống không mô tả hai mặt đối lập thống nhất và đấu tranh với nhau.","","Không có sự phủ định rồi phủ định lại theo đường xoáy ốc; đây là quá trình tích lũy dần.","Mối liên hệ phổ biến là nguyên lý chung, không phải trọng tâm của tình huống tích lũy từ từ rồi hoàn thiện."],"s":"GT Triết học Mác-Lênin (2021), Chương 2, mục II.2 (quy luật lượng - chất); bản cũ: Chương VIII, mục II","c":2,"v":"khớp"},{"q":"Định nghĩa của V.I.Lênin về giai cấp là những tập đoàn người to lớn có sự phân biệt về:","o":["Địa vị của họ trong một hệ thống sản xuất xã hội nhất định trong lịch sử","Địa vị của họ trong quá trình quản lý và phân phối của cải xã hội","Địa vị của họ trong quản lý chính trị, văn hóa và xã hội","Địa vị của họ trong việc nắm quyền lực nhà nước"],"a":[0],"e":"V.I. Lênin định nghĩa: giai cấp là những tập đoàn to lớn gồm những người khác nhau về địa vị của họ trong một hệ thống sản xuất xã hội nhất định trong lịch sử, về quan hệ đối với tư liệu sản xuất, về vai trò trong tổ chức lao động xã hội và về cách thức, phần của cải xã hội được hưởng. Vế đầu của định nghĩa chính là phương án A. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục II.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Quản lý và phân phối chỉ là các mặt cụ thể bên trong định nghĩa, không phải vế mở đầu của nó.","Quản lý chính trị, văn hóa, xã hội thuộc kiến trúc thượng tầng; Lênin dựa vào địa vị trong hệ thống sản xuất.","Nắm quyền lực nhà nước là hệ quả của việc nắm tư liệu sản xuất, không được nêu trong định nghĩa."],"s":"V.I. Lênin, «Sáng kiến vĩ đại»; GT Triết học Mác-Lênin (2021), Chương 3, mục II.1; bản cũ: Chương XI, mục II.1","c":3,"v":"khớp"},{"q":"Trong tư liệu lao động, bộ phận nào cần được phát triển đi trước một bước so với đầu tư sản xuất trực tiếp?","o":["Kết cấu hạ tầng sản xuất","Công cụ sản xuất","Các bộ phận chứa đựng, bảo quản","Các phương án trả lời đều đúng"],"a":[0],"e":"Kết cấu hạ tầng của sản xuất (đường sá, bến cảng, sân bay, hệ thống điện, thông tin...) thuộc tư liệu lao động và cần được phát triển đi trước một bước so với đầu tư sản xuất trực tiếp. Nội dung này nằm trong chương trình GDCD phổ thông về tư liệu lao động, các bộ đề trắc nghiệm đều chọn «kết cấu hạ tầng của sản xuất». ([Hoc247](https://hoc247.net/cau-hoi-trong-tu-lieu-lao-dong-bo-phan-nao-sau-day-can-duoc-phat-trien-di-truoc-mot-buoc-so-voi-dau-tu-san--qid311311.html); [Doctailieu](https://doctailieu.com/trac-nghiem/trong-tu-lieu-lao-dong-bo-phan-nao-can-duoc-phat-trien-di-truoc-mot-buoc-so-voi-38259))","w":["","Công cụ sản xuất là bộ phận trực tiếp tác động vào đối tượng lao động, không phải bộ phận cần đi trước so với đầu tư sản xuất trực tiếp.","Bộ phận chứa đựng, bảo quản chỉ là yếu tố phụ trợ của tư liệu lao động.","Chỉ kết cấu hạ tầng sản xuất mới cần đi trước, nên «tất cả đều đúng» là sai."],"s":"Chương trình GDCD phổ thông (bài về sản xuất của cải vật chất, tư liệu lao động); không nằm trong Giáo trình Triết học Mác-Lênin đại học","c":3,"v":"khớp","k":"Nguồn là kiến thức GDCD phổ thông; hai bản giáo trình Triết học Mác-Lênin được kiểm tra không có câu «đi trước một bước».","f":1},{"q":"Theo quan điểm của phép biện chứng duy vật thì phạm trù chỉ một sự vật, một hiện tượng, một quá trình nhất định là","o":["Đặc thù","Bản chất","Cái riêng","Hiện tượng"],"a":[2],"e":"Giáo trình định nghĩa: cái riêng là phạm trù triết học dùng để chỉ một sự vật, một hiện tượng nhất định; cái đơn nhất chỉ các mặt, đặc điểm chỉ có ở một cái riêng; cái chung là những mặt, thuộc tính lặp lại ở nhiều cái riêng. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Đặc thù» không phải phạm trù chuẩn trong cặp cái riêng - cái chung - cái đơn nhất của giáo trình.","Bản chất là tổng thể các mối liên hệ khách quan, tất nhiên, tương đối ổn định bên trong sự vật.","","Hiện tượng là biểu hiện ra bên ngoài của bản chất, không phải thuật ngữ chỉ một sự vật nhất định."],"s":"GT Triết học Mác-Lênin (2021), Chương 2, mục II.2 (cái riêng và cái chung); bản cũ: Chương VII, mục II","c":2,"v":"khớp","id":"1ddw781"},{"q":"Theo Ph. Ăngghen, tính thống nhất của vật chất được chứng minh bởi:","o":["Thực tiễn lịch sử","Thực tiễn cách mạng","Sự phát triển lâu dài của khoa học","Sự phát triển lâu dài và khó khăn của triết học và khoa học tự nhiên"],"a":[3],"e":"Ph. Ăngghen kết luận: tính thống nhất thực sự của thế giới là tính vật chất của nó, tính vật chất này được chứng minh không phải bằng vài ba lời lẽ khéo léo mà bằng sự phát triển lâu dài và khó khăn của triết học và khoa học tự nhiên. Vì vậy D là đáp án đúng. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục I.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Thực tiễn lịch sử không phải chứng cứ mà Ăngghen nêu trong luận điểm này.","Thực tiễn cách mạng không được nêu làm cơ sở chứng minh tính thống nhất vật chất.","Thiếu chữ «triết học» và tính chất «khó khăn» trong nhận định của Ăngghen; phương án D mới đầy đủ.",""],"s":"Ph. Ăngghen, «Chống Đuyrinh» (trích trong giáo trình); GT Triết học Mác-Lênin (2021), Chương 2, mục I.1; bản cũ: Chương V","c":2,"v":"khớp"},{"q":"Theo V.I. Lênin \"Chủ nghĩa Mác đã mở đường cho việc nghiên cứu rộng rãi và toàn diện quá trình phát sinh, phát triển và suy tàn của...\"","o":["Hệ thống vật chất trong giới tự nhiên","Các quá trình kinh tế và chính trị - xã hội","Các sự vật, hiện tượng trong thế giới tự nhiên, xã hội và tư duy","Các hình thái kinh tế - xã hội"],"a":[3],"e":"Câu trích nói về phạm vi nghiên cứu mà chủ nghĩa Mác mở ra, gắn với học thuyết hình thái kinh tế - xã hội, tức quá trình phát sinh, phát triển và suy tàn của các hình thái kinh tế - xã hội. Đó là cơ sở để chọn D. Chưa xác định được tác phẩm gốc của câu trích của Lênin, nên đây là suy luận từ nội dung học thuyết. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục I](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quá hẹp (chỉ giới tự nhiên) và lệch khỏi đối tượng xã hội mà câu trích nói tới.","Chỉ là một số mặt của hình thái kinh tế - xã hội, chưa phải đối tượng toàn diện.","Là phạm vi chung của triết học, không khớp ý «phát sinh, phát triển và suy tàn» của một thể chế xã hội.",""],"s":"GT Triết học Mác-Lênin (2021), Chương 3, mục I (học thuyết hình thái kinh tế - xã hội); chưa tìm được tác phẩm gốc của câu trích Lênin","c":3,"v":"chưa kiểm chứng","k":"chưa kiểm chứng được nguồn cho câu này. Không tìm được nguyên văn câu trích và tác phẩm của Lênin trên các nguồn truy cập được (marxists.org bị lỗi kết nối); bản nháp nêu «Những người bạn dân là thế nào» chưa được xác nhận nên đã bỏ."},{"q":"Theo quan niệm duy vật biện chứng về lịch sử thì do khác nhau và đối lập nhau về yếu tố nào tạo ra khả năng khách quan dẫn đến tập đoàn này có thể chiếm đoạt lao động của tập đoàn khác?","o":["Quyền lực","Sở hữu","Địa vị","Tài sản"],"a":[2],"e":"Định nghĩa của V.I. Lênin kết thúc: giai cấp là những tập đoàn người mà tập đoàn này có thể chiếm đoạt lao động của tập đoàn khác, do chỗ các tập đoàn đó có địa vị khác nhau trong một chế độ kinh tế - xã hội nhất định. Vì vậy yếu tố khác nhau, đối lập nhau tạo ra khả năng đó là địa vị. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục II.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quyền lực là hệ quả của địa vị kinh tế, không phải nguyên nhân được định nghĩa nêu.","Sở hữu là một nội dung quyết định địa vị, nhưng câu cuối của định nghĩa dùng chữ «địa vị».","","Tài sản không phải khái niệm được dùng trong định nghĩa của Lênin."],"s":"V.I. Lênin, «Sáng kiến vĩ đại»; GT Triết học Mác-Lênin (2021), Chương 3, mục II.1; bản cũ: Chương XI, mục II.1","c":3,"v":"dễ nhầm","k":"Nội dung giáo trình cũng nhấn mạnh sở hữu tư liệu sản xuất là yếu tố quyết định, nên B dễ gây nhầm; câu hỏi bám theo chữ «địa vị» ở câu cuối của định nghĩa."},{"q":"Theo quan điểm của phép biện chứng duy vật thì chất là sự thống nhất hữu cơ của các thuộc tính cấu thành nó và là phạm trù dùng để chỉ tính quy định gì của sự vật, hiện tượng?","o":["Có tổ chức","Khách quan vốn có","Về kết cấu","Về kết quả"],"a":[1],"e":"Giáo trình định nghĩa: chất là khái niệm chỉ tính quy định khách quan vốn có của sự vật, hiện tượng; là sự thống nhất hữu cơ của các thuộc tính, yếu tố tạo nên sự vật, làm cho nó là nó mà không phải cái khác. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Có tổ chức» không phải nội dung của định nghĩa chất.","","Kết cấu (phương thức liên kết các yếu tố) thuộc về lượng, không phải định nghĩa về chất.","Kết quả không phải tính quy định của chất; chất là tính quy định vốn có của sự vật."],"s":"GT Triết học Mác-Lênin (2021), Chương 2, mục II.2 (quy luật lượng - chất); bản cũ: Chương VIII, mục II","c":2,"v":"khớp","id":"8l5qz"},{"q":"Trong mối quan hệ giữa \"lực lượng sản xuất và quan hệ sản xuất\", yếu tố nào là nội dung, yếu tố nào là hình thức?","o":["Lực lượng sản xuất là nội dung - quan hệ sản xuất là hình thức","Quan hệ sản xuất là nội dung- lực lượng sản xuất là hình thức","Lực lượng sản xuất và quan hệ sản xuất đều là nội dung","Lực lượng sản xuất và quan hệ sản xuất đều là hình thức"],"a":[0],"e":"Giáo trình nêu lực lượng sản xuất là nội dung của quá trình sản xuất (năng động, cách mạng, thường xuyên vận động), còn quan hệ sản xuất là hình thức xã hội của quá trình sản xuất có tính ổn định tương đối. Lực lượng sản xuất quyết định quan hệ sản xuất. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục I.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Đảo ngược quan hệ: quan hệ sản xuất là hình thức, không phải nội dung.","Hai mặt không cùng là nội dung vì quan hệ sản xuất là hình thức xã hội của sản xuất.","Hai mặt không cùng là hình thức vì lực lượng sản xuất là nội dung."],"s":"GT Triết học Mác-Lênin (2021), Chương 3, mục I.2 (biện chứng giữa lực lượng sản xuất và quan hệ sản xuất); bản cũ: Chương X, mục II","c":3,"v":"khớp","id":"jxupkw"},{"q":"Trong lý luận nhận thức, cần nhìn nhận sự vật trong trạng thái vận động và phát triển. Điều đó dựa trên cơ sở lý luận của nguyên lý nào?","o":["Nguyên lý về mối liên hệ phổ biến","Nguyên lý về sự phát triển","Nguyên lý về tính thống nhất vật chất của thế giới"],"a":[1],"e":"Giáo trình nêu nguyên lý về sự phát triển yêu cầu khi nghiên cứu phải đặt đối tượng vào sự vận động, phát hiện xu hướng biến đổi của nó. Quan điểm xem xét sự vật trong trạng thái vận động và phát triển (quan điểm phát triển) dựa trên nguyên lý về sự phát triển. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Nguyên lý về mối liên hệ phổ biến dẫn tới quan điểm toàn diện, lịch sử - cụ thể, không phải quan điểm phát triển.","","Nguyên lý thống nhất vật chất của thế giới là nền tảng bản thể luận, không nhấn mạnh vận động và phát triển."],"s":"GT Triết học Mác-Lênin (2021), Chương 2, mục II.2 (hai nguyên lý của phép biện chứng duy vật); bản cũ: Chương VI","c":2,"v":"khớp"},{"q":"Tiêu chí nào là quan trọng nhất để phân biệt các hình thái kinh tế xã hội","o":["Lực lượng sản xuất","Quan hệ sản xuất","Tồn tại xã hội","Kiến trúc thượng tầng"],"a":[1],"e":"Giáo trình viết: quan hệ sản xuất là tiêu chuẩn quan trọng nhất để phân biệt bản chất các chế độ xã hội khác nhau; còn lực lượng sản xuất là tiêu chuẩn khách quan để phân biệt các thời đại kinh tế. Vì câu hỏi hỏi phân biệt các hình thái kinh tế - xã hội, đáp án là quan hệ sản xuất (B). ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục I.4](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Lực lượng sản xuất là nền tảng vật chất, tiêu chuẩn để phân biệt các thời đại kinh tế (công cụ lao động), chứ không phải tiêu chí quan trọng nhất phân biệt bản chất các chế độ xã hội.","","Tồn tại xã hội là khái niệm rộng (toàn bộ sinh hoạt vật chất), không phải tiêu chí phân biệt hình thái kinh tế - xã hội.","Kiến trúc thượng tầng do cơ sở hạ tầng (quan hệ sản xuất) quyết định, không phải tiêu chí phân biệt."],"s":"GT Triết học Mác-Lênin (2021), Chương 3, mục I.4 (phạm trù hình thái kinh tế - xã hội); chưa đối chiếu số mục của bản cũ","c":3,"v":"dễ nhầm","k":"Cần phân biệt hai cách diễn đạt của giáo trình: lực lượng sản xuất phân biệt các thời đại kinh tế (theo công cụ lao động), quan hệ sản xuất phân biệt bản chất các chế độ xã hội. Đề có thể gây nhầm giữa A và B."},{"q":"Nguyên tác thống nhất giữa lý luận và thực tiễn là nguyên tắc được rút ra (trực tiếp) từ mối quan hệ nào?","o":["Mối quan hệ giữa vật chất và ý thức.","Lý luận và nhận thức.","Quan hệ giữa khả năng và hiện thực","Phán đoán suy luận"],"a":[1],"e":"Giáo trình nêu nguyên tắc thực tiễn rút ra từ vai trò của thực tiễn đối với nhận thức, và yêu cầu tuân thủ nghiêm ngặt nguyên tắc thống nhất giữa lý luận và thực tiễn. Nguyên tắc này rút ra trực tiếp từ mối quan hệ giữa lý luận và thực tiễn (trong lý luận nhận thức). Đáp án B ghi «Lý luận và nhận thức» có thể là lỗi chép từ «lý luận và thực tiễn». ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục III](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quan hệ vật chất - ý thức dẫn tới nguyên tắc khách quan, không phải nguyên tắc thống nhất lý luận - thực tiễn.","","Quan hệ khả năng - hiện thực dẫn tới việc dựa vào hiện thực và tính đến khả năng.","Phán đoán, suy luận chỉ là hình thức của tư duy, không sinh ra nguyên tắc này."],"s":"GT Triết học Mác-Lênin (2021), Chương 2, mục III.3 (thực tiễn và vai trò của thực tiễn đối với nhận thức) và phần mở đầu; bản cũ: Chương IX","c":2,"v":"nghi vấn","k":"nghi vấn: Phương án B ghi «Lý luận và nhận thức» chứ không phải «lý luận và thực tiễn», nhiều khả năng là lỗi chép; B vẫn là phương án gần đúng nhất."},{"q":"Theo quan điểm của phép biện chứng duy vật thì quy luật nào vạch ra nguồn gốc của sự phát triển cơ bản phổ biến của sự vận động và phát triển","o":["Quy luật thống nhất và đấu tranh của các mặt đối lập","Quy luật về chuyển hóa sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại","Quy luật phủ định của phủ định","Quy luật về sự phù hợp của QHSX và trình độ LLSX"],"a":[0],"e":"Giáo trình nêu quy luật thống nhất và đấu tranh của các mặt đối lập đề cập vấn đề cơ bản nhất của phép biện chứng duy vật: nguyên nhân, động lực (nguồn gốc) của sự vận động, phát triển. Lênin coi đó là hạt nhân của phép biện chứng. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Quy luật lượng - chất chỉ ra cách thức chung nhất của vận động, phát triển.","Quy luật phủ định của phủ định chỉ ra khuynh hướng, hình thức xoáy ốc, kết quả của phát triển.","Quy luật quan hệ sản xuất phù hợp với lực lượng sản xuất là quy luật xã hội, không phải quy luật phổ biến của phép biện chứng duy vật."],"s":"GT Triết học Mác-Lênin (2021), Chương 2, mục II.2; bản cũ: Chương VIII, mục III","c":2,"v":"khớp"},{"q":"Theo quan điểm của phép biện chứng duy vật thì quy luật nào vạch ra cách thức / hình thức của sự phát triển cơ bản phổ biến của sự vận động và phát triển","o":["Quy luật thống nhất và đấu tranh của các mặt đối lập","Quy luật về chuyển hóa sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại (Quy luật lượng - chất)","Quy luật phủ định của phủ định","Quy luật về sự phù hợp của QHSX và trình độ LLSX"],"a":[1],"e":"Giáo trình nêu quy luật từ những thay đổi về lượng dẫn đến những thay đổi về chất chỉ ra cách thức chung nhất của sự vận động và phát triển: thay đổi về chất chỉ xảy ra khi lượng tích lũy đạt đến ngưỡng nhất định. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quy luật mâu thuẫn chỉ ra nguyên nhân, động lực (nguồn gốc) của phát triển.","","Quy luật phủ định của phủ định chỉ ra khuynh hướng, hình thức xoáy ốc của phát triển.","Là quy luật xã hội, không thuộc ba quy luật cơ bản của phép biện chứng duy vật."],"s":"GT Triết học Mác-Lênin (2021), Chương 2, mục II.2; bản cũ: Chương VIII, mục II","c":2,"v":"khớp"},{"q":"Triết học của các nhà tư tưởng thời kỳ Phục Hưng có đặc điểm gì?","o":["Có tính chất duy vật tự phát","Có tính chất duy tâm khách quan","Còn pha trộn giữa các yếu tố duy vật và duy tâm","Còn pha trộn giữa các yếu tố duy tâm thần bí và siêu hình"],"a":[2],"e":"Giáo trình nhận xét triết học của hầu hết các nhà tư tưởng thời kỳ Phục hưng còn lẫn lộn các yếu tố duy vật với duy tâm và có tính chất phiếm thần luận (ví dụ Brunô cho rằng Thượng đế và tự nhiên chỉ là một). ([Giáo trình Triết học Mác-Lênin, bản tái bản lần 3, Chương II, mục III.1](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Duy vật tự phát là đặc trưng của triết học cổ đại; triết học Phục hưng còn pha trộn yếu tố duy tâm.","Giáo trình không coi triết học Phục hưng mang tính duy tâm khách quan.","","Không phải «duy tâm thần bí và siêu hình»; xu hướng chung là hướng về khoa học tự nhiên, có yếu tố duy vật."],"s":"GT Triết học Mác-Lênin (bản cũ), Chương II, mục III.1 (Triết học Tây Âu thời kỳ Phục hưng thế kỷ XV - XVI); bản 2021 không có phần này","c":1,"v":"khớp"},{"q":"Một trong các nội dung định nghĩa của Lênin về vật chất đó là, vật chất được cảm giác của chúng ta chép lại, chụp lại, phản ánh và tồn tại.","o":["Lệ thuộc vào cảm giác","Không lệ thuộc vào cảm giác","Tuỳ thuộc vào nhận thức","Tuỳ theo ý thức"],"a":[1],"e":"Định nghĩa vật chất của V.I. Lênin: vật chất là thực tại khách quan được đem lại cho con người trong cảm giác, được cảm giác của chúng ta chép lại, chụp lại, phản ánh và tồn tại không lệ thuộc vào cảm giác. ([Giáo trình Triết học Mác-Lênin, bản tái bản lần 3, Chương V](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["«Lệ thuộc vào cảm giác» là quan điểm duy tâm chủ quan, trái định nghĩa.","","«Tùy thuộc vào nhận thức» là quan điểm duy tâm, trái với tính khách quan của vật chất.","«Tùy theo ý thức» là quan điểm duy tâm, trái với tính khách quan của vật chất."],"s":"V.I. Lênin, «Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán»; GT Triết học Mác-Lênin (bản cũ), Chương V, mục I; bản 2021: Chương 2, mục I.1","c":2,"v":"khớp"},{"q":"Theo Lênin, vật chất dưới hình thức thế nào thì là cái có thể gây nên cảm giác của con người khi nó trực tiếp hay gián tiếp tác động đến giác quan của con người?","o":["Những dạng cụ thể","Tồn tại khách quan","Khái quát của nó","Tự nhiên của nó"],"a":[0],"e":"Giáo trình nêu V.I. Lênin khẳng định vật chất luôn biểu hiện sự tồn tại hiện thực của mình dưới dạng các thực thể, các sự vật, hiện tượng cụ thể; các thực thể ấy khi trực tiếp hoặc gián tiếp tác động vào giác quan thì đem lại cho con người cảm giác. Vậy vật chất dưới dạng cụ thể mới gây nên cảm giác (đáp án A). ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục I.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Tồn tại khách quan là thuộc tính chung của vật chất, không phải hình thức cụ thể gây nên cảm giác.","«Khái quát» là sản phẩm của tư duy trừu tượng; vật chất nói chung là phạm trù trừu tượng nên không tác động trực tiếp lên giác quan.","«Tự nhiên của nó» không phải cách diễn đạt trong định nghĩa vật chất của Lênin."],"s":"V.I. Lênin, «Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán»; GT Triết học Mác-Lênin (2021), Chương 2, mục I.1","c":2,"v":"khớp"},{"q":"Chủ nghĩa duy vật lịch sử cho rằng, cuộc đấu tranh giữa những người lao động làm thuê, những người nô lệ bị áp bức về chính trị - xã hội và bị bóc lột về kinh tế chống lại bọn áp bức và bóc lột nó là thực chất","o":["Đấu tranh giai cấp","Ra đời giai cấp","Cách mạng","Ra đời nhà nước"],"a":[0],"e":"Giáo trình nêu thực chất của đấu tranh giai cấp là cuộc đấu tranh của quần chúng lao động bị áp bức, bóc lột chống lại giai cấp áp bức, bóc lột nhằm lật đổ ách thống trị của chúng. Các giai cấp bị trị còn bị áp bức về chính trị, xã hội, tinh thần. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục II.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Sự ra đời giai cấp là tiền đề của đấu tranh giai cấp, không phải bản thân cuộc đấu tranh.","Cách mạng xã hội là đỉnh cao của đấu tranh giai cấp (kết quả tất yếu), không phải thực chất của nó.","Sự ra đời nhà nước là kết quả của mâu thuẫn giai cấp không thể điều hòa."],"s":"GT Triết học Mác-Lênin (2021), Chương 3, mục II.1 (đấu tranh giai cấp); bản cũ: Chương XI, mục II","c":3,"v":"khớp"},{"q":"Chủ nghĩa duy vật lịch sử cho rằng, tồn tại xã hội là khái niệm dùng để chỉ phương diện sinh hoạt vật chất và những điều kiện gì của xã hội?","o":["Văn hoá tinh thần","Sinh hoạt tinh thần","Sinh hoạt vật chất","Kinh tế"],"a":[2],"e":"Giáo trình định nghĩa tồn tại xã hội là toàn bộ sinh hoạt vật chất và những điều kiện sinh hoạt vật chất của xã hội. Do đó chỗ trống là «sinh hoạt vật chất» (đáp án C). ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục IV.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Văn hóa tinh thần thuộc ý thức xã hội, không thuộc tồn tại xã hội.","Sinh hoạt tinh thần thuộc ý thức xã hội.","","Kinh tế chỉ là một yếu tố của sinh hoạt vật chất, không phải toàn bộ."],"s":"GT Triết học Mác-Lênin (2021), Chương 3, mục IV.1 (khái niệm tồn tại xã hội); bản cũ: Chương XIII, mục I","c":3,"v":"khớp"},{"q":"Tồn tại xã hội là gì?","o":["Sinh hoạt vật chất và những điều kiện sinh hoạt vật chất của xã hội","Toàn bộ các giá trị tinh thần của xã hội","Toàn bộ các điều kiện sinh hoạt của xã hội","Toàn bộ hệ tư tưởng về sự tồn tại của xã hội"],"a":[0],"e":"Giáo trình: tồn tại xã hội là toàn bộ sinh hoạt vật chất và những điều kiện sinh hoạt vật chất của xã hội, gồm phương thức sản xuất vật chất, điều kiện tự nhiên, hoàn cảnh địa lý, dân số, mật độ dân số, trong đó phương thức sản xuất vật chất là yếu tố cơ bản nhất. Nó quyết định ý thức xã hội. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục IV.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Các giá trị tinh thần thuộc ý thức xã hội.","Quá rộng («toàn bộ điều kiện sinh hoạt») vì bao gồm cả điều kiện tinh thần; giáo trình giới hạn ở sinh hoạt vật chất.","Hệ tư tưởng về sự tồn tại của xã hội thuộc ý thức xã hội, không phải tồn tại xã hội."],"s":"GT Triết học Mác-Lênin (2021), Chương 3, mục IV.1; bản cũ: Chương XIII, mục I","c":3,"v":"khớp","id":"1jnm0hf"},{"q":"Chủ nghĩa xã hội không tưởng đề cao yếu tố gì?","o":["Tinh thần nhân đạo","Xã hội đại đồng","Sự bình đẳng","Một xã hội không còn sự bóc lột"],"a":[0],"e":"Chủ nghĩa xã hội không tưởng phê phán xã hội tư bản, chứa đựng tinh thần nhân đạo cao cả, thể hiện lòng yêu thương, bênh vực người lao động và mong muốn giải phóng họ, nhưng thiếu cơ sở khoa học và không chỉ ra lực lượng thực hiện. Vì vậy đề chọn «tinh thần nhân đạo». ([Chủ nghĩa xã hội không tưởng - giá trị và hạn chế (ĐH Duy Tân)](https://xhnv.duytan.edu.vn/van-o414c/chu-nghia-xa-hoi-khong-tuong-gia-tri-va-han-che-lich-subdoaq))","w":["","Xã hội đại đồng là hình ảnh xã hội tương lai mà họ mơ ước, không phải điểm đề cao nổi bật được nêu.","Bình đẳng là một giá trị họ nêu nhưng không phải nhận định đặc trưng của đề.","Xã hội không còn bóc lột là mục tiêu chung, không phải yếu tố được nhấn mạnh như tinh thần nhân đạo."],"s":"Nội dung chủ nghĩa xã hội khoa học (giá trị và hạn chế của chủ nghĩa xã hội không tưởng); không phải nội dung của Giáo trình Triết học Mác-Lênin; chưa đối chiếu số chương giáo trình CNXHKH","c":1,"v":"dễ nhầm","k":"Bốn phương án đều là những nét của chủ nghĩa xã hội không tưởng, nên dễ nhầm; chưa mở trực tiếp giáo trình CNXHKH của Bộ GD&ĐT để so nguyên văn.","id":"1le2azp"},{"q":"Vị trí của quy luật phủ định của phủ định trong phép biện chứng duy vật","o":["Chỉ ra cách thức của sự phát triển","Chỉ ra nguồn gốc của sự phát triển","Chỉ ra nguyên nhân của sự phát triển","Chỉ ra khuynh hướng của sự phát triển"],"a":[3],"e":"Giáo trình nêu quy luật phủ định của phủ định chỉ ra khuynh hướng (đi lên), hình thức (xoáy ốc) và kết quả (sự vật mới ra đời từ sự vật cũ) của sự phát triển, thông qua sự thống nhất giữa tính thay đổi và tính kế thừa. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Cách thức của phát triển là nội dung quy luật lượng - chất.","Nguồn gốc (nguyên nhân, động lực) của phát triển là nội dung quy luật thống nhất và đấu tranh của các mặt đối lập.","Nguyên nhân của phát triển không phải vị trí của quy luật này; nó chỉ ra khuynh hướng.",""],"s":"GT Triết học Mác-Lênin (2021), Chương 2, mục II.2; bản cũ: Chương VIII, mục IV","c":2,"v":"khớp"},{"q":"Hệ thống những quan điểm lý luận chung nhất về thế giới và về vị trí của con người trong thế giới đó là:","o":["Quan điểm biện chứng","Chủ nghĩa duy vật","Chủ nghĩa duy vật biện chứng","Triết học"],"a":[3],"e":"Với sự ra đời của triết học Mác - Lênin, giáo trình định nghĩa triết học là hệ thống quan điểm lý luận chung nhất về thế giới và vị trí của con người trong thế giới đó, là khoa học về những quy luật vận động, phát triển chung nhất của tự nhiên, xã hội và tư duy. ([Giáo trình Triết học Mác-Lênin 2021, Chương 1, mục I.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quan điểm biện chứng chỉ là một phương pháp nhìn nhận (đối lập với siêu hình), không phải toàn bộ hệ thống quan điểm về thế giới.","Chủ nghĩa duy vật là một trường phái triết học (lập trường về mối quan hệ vật chất - ý thức), không phải định nghĩa chung về triết học.","Chủ nghĩa duy vật biện chứng là một hình thức cụ thể của triết học Mác - Lênin, không phải định nghĩa chung của triết học.",""],"s":"GT Triết học Mác-Lênin (2021), Chương 1, mục I.1 (khái lược về triết học); bản cũ: Chương I, mục I.1","c":1,"v":"khớp"},{"q":"Quan điểm ủng hộ cái mới tiến bộ, từ đó chống lại cái cũ, cái lỗi thời kìm hãm sự phát triển là quan điểm được rút ra trực tiếp từ:","o":["Quy luật từ những thay đổi về lượng dẫn đến những thay đổi về chất và ngược lại","Quy luật thống nhất và quy luật đấu tranh của các mặt đối lập","Quy luật phủ định của phủ định"],"a":[2],"e":"Giáo trình nêu từ quy luật phủ định của phủ định rút ra: sự vật, hiện tượng mới ra đời phù hợp quy luật phát triển, nên cần ủng hộ cái mới, tạo điều kiện cho nó phát triển hợp quy luật, đồng thời kế thừa có chọn lọc yếu tố tích cực của cái cũ. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quy luật lượng - chất dẫn tới quan điểm tích lũy dần về lượng, tránh nóng vội hay chần chừ khi chất đổi, không phải quan điểm ủng hộ cái mới.","Quy luật mâu thuẫn dẫn tới quan điểm phân tích mâu thuẫn và giải quyết mâu thuẫn bằng đấu tranh.",""],"s":"GT Triết học Mác-Lênin (2021), Chương 2, mục II.2 (ý nghĩa phương pháp luận của quy luật phủ định của phủ định); bản cũ: Chương VIII, mục IV","c":2,"v":"khớp"},{"q":"Học thuyết Hình thái kinh tế - xã hội là nội dung của","o":["Phép biện chứng","Tất cả các đáp án đều đúng","Chủ nghĩa duy vật biện chứng","Chủ nghĩa duy vật lịch sử"],"a":[3],"e":"Giáo trình nêu rằng sự ra đời học thuyết hình thái kinh tế - xã hội đã đem lại cho khoa học xã hội một phương pháp nghiên cứu thực sự khoa học: lấy sản xuất vật chất làm cơ sở của đời sống xã hội, coi phương thức sản xuất quyết định các mặt của đời sống xã hội. Đây là học thuyết do Mác xây dựng trên lập trường duy vật về lịch sử, tức nội dung của chủ nghĩa duy vật lịch sử. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Phép biện chứng nghiên cứu những quy luật chung nhất của tự nhiên, xã hội và tư duy, không riêng về cấu trúc và sự vận động của các hình thái xã hội.","Đáp án D đúng còn A, C không đúng nên phương án «tất cả đều đúng» sai.","Chủ nghĩa duy vật biện chứng bàn về vật chất, ý thức và các quy luật chung của thế giới; việc vận dụng vào xã hội để hình thành học thuyết hình thái kinh tế - xã hội thuộc chủ nghĩa duy vật lịch sử.",""],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, bản tái bản lần 3), Ch.X «Hình thái kinh tế - xã hội», mục IV.1 (giá trị khoa học của học thuyết); chưa đối chiếu số chương của bản 2021","c":3,"v":"khớp","f":1},{"q":"Cách thức mà con người dùng để tiến hành quá trình sản xuất của xã hội ở những giai đoạn lịch sử nhất định gọi là:","o":["Phương thức sản xuất","Nghệ thuật sản xuất","Kỹ thuật sản xuất","Công nghệ sản xuất"],"a":[0],"e":"Giáo trình định nghĩa: phương thức sản xuất là cách thức con người thực hiện quá trình sản xuất vật chất ở những giai đoạn lịch sử nhất định của xã hội loài người. Nó là sự thống nhất giữa lực lượng sản xuất ở một trình độ nhất định và quan hệ sản xuất tương ứng. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","«Nghệ thuật sản xuất» không phải thuật ngữ của giáo trình để chỉ cách thức tiến hành sản xuất vật chất.","Kỹ thuật chỉ là một mặt (công cụ, phương pháp) gắn với lực lượng sản xuất, chưa bao quát cả quan hệ sản xuất.","Công nghệ cũng chỉ là một yếu tố thuộc mặt kỹ thuật của sản xuất, không phải khái niệm chỉ cách thức sản xuất trong từng giai đoạn lịch sử."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục II.1.a «Phương thức sản xuất»","c":3,"v":"khớp"},{"q":"Đâu là nhận định sai về Triết học Mác ?","o":["Triết học Mác cho rằng triết học là khoa học của mọi khoa học","Theo quan điểm của triết học Mác triết học không thay thế được các khoa học cụ thể","Theo quan điểm của triết học Mác thì sự phát triển của triết học quan hệ chặt chẽ với sự phát triển của khoa học tự nhiên","Triết học Mác là sự tổng hợp của các trường phái triết học trong lịch sử"],"a":[0],"e":"Câu hỏi tìm nhận định sai. Giáo trình nêu triết học Mác đã chấm dứt tham vọng coi triết học là «khoa học của các khoa học» đứng trên mọi khoa học; tham vọng đó thuộc triết học Hêghen. Mác và Ăngghen xây dựng triết học trên cơ sở khái quát thành tựu khoa học tự nhiên và khoa học xã hội, nên nhận định A sai. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.I-III](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Đúng: triết học Mác không đứng trên hay thay thế các khoa học cụ thể mà dựa vào thành tựu của chúng.","Đúng: giáo trình nhấn mạnh mỗi phát minh vạch thời đại của khoa học tự nhiên buộc chủ nghĩa duy vật phải thay đổi hình thức, tức triết học gắn chặt với khoa học tự nhiên.","Đúng theo cách diễn đạt của đề: triết học Mác kế thừa tinh hoa tư tưởng nhân loại (triết học cổ điển Đức, v.v.), không phải là học thuyết hoàn toàn tách biệt với lịch sử triết học."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), phần về đối tượng triết học Mác (Ch.I) và sự ra đời triết học Mác (Ch.III); chưa đối chiếu số mục","c":1,"v":"khớp"},{"q":"Từ thế kỉ VIII trước công nguyên với nhà nước đầu tiên trong lịch sử, giai cấp tư hữu đã dùng pháp luật và bộ máy thống trị của mình để chiếm mất quyền lực của đông đảo quần chúng nhân dân lao động là những...","o":["Nông dân","Người tự do","Người nô lệ","Nông nô"],"a":[2],"e":"Từ thế kỷ VIII trước công nguyên, ở Hy Lạp (điển hình là Aten) hình thành nhà nước chiếm hữu nô lệ, tức nhà nước dân chủ chủ nô: giai cấp chủ nô dùng pháp luật và bộ máy nhà nước để thống trị, loại đông đảo nô lệ khỏi quyền lực chính trị. Vì vậy lực lượng bị tước quyền là người nô lệ. ([Giáo trình CNXH khoa học - Dân chủ XHCN và nhà nước XHCN, VOER](https://voer.edu.vn/m/nen-dan-chu-xa-hoi-chu-nghia-va-nha-nuoc-xa-hoi-chu-nghia/477852c3))","w":["Nông dân là lực lượng lao động chủ yếu ở xã hội phong kiến, không phải giai cấp bị loại khỏi quyền lực trong nhà nước chủ nô đầu tiên.","Người tự do (công dân) là tầng lớp được tham gia nhà nước chủ nô, nên không bị chiếm mất quyền lực.","","Nông nô là giai cấp bị bóc lột của thời phong kiến, xuất hiện sau nhà nước chủ nô."],"s":"Chủ nghĩa xã hội khoa học (dân chủ chủ nô, nhà nước đầu tiên); câu hỏi không thuộc phần Triết học nên chưa đối chiếu số chương giáo trình Triết","c":3,"v":"khớp","k":"Không mở được trang VOER để đọc nguyên văn (lỗi kết nối); kết luận dựa trên kết quả tìm kiếm nêu nhà nước dân chủ chủ nô ở Aten từ thế kỷ VIII TCN và lập luận lịch sử. Chưa thấy đoạn trùng khớp từng chữ với đề."},{"q":"Theo quan điểm của chủ nghĩa duy vật biện chứng lịch sử, xã hội loài người đã trải qua bao nhiêu hình thái kinh tế xã hội?","o":["Bốn hình thái kinh tế xã hội","Ba hình thái kinh tế xã hội","Năm hình thái kinh tế xã hội"],"a":[2],"e":"Theo chủ nghĩa duy vật lịch sử, lịch sử nhân loại đã trải qua và sẽ trải qua năm hình thái kinh tế - xã hội nối tiếp nhau: nguyên thủy, chiếm hữu nô lệ, phong kiến, tư bản chủ nghĩa và cộng sản chủ nghĩa (giai đoạn đầu là xã hội chủ nghĩa). Giáo trình mô tả bốn cuộc cách mạng xã hội đưa nhân loại qua năm hình thái đó. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.XII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Bốn hình thái là thiếu một hình thái so với lập luận của giáo trình.","Ba hình thái là thiếu hai hình thái so với lập luận của giáo trình.",""],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.XII, mục II.1.c «Vai trò của cách mạng xã hội»","c":3,"v":"khớp"},{"q":"Hãy xác định luận điểm nào sai khi đề cập đến \"mối quan hệ biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng\"?","o":["Sự phát triển của lực lượng sản xuất trực tiếp làm thay đổi quan hệ sản xuất, và thông qua đó làm thay đổi kiến trúc thượng tầng","Cơ sở hạ tầng thay đổi thì sớm muộn gì kiến trúc thượng tầng cũng thay đổi theo","Trong xã hội có giai cấp, giai cấp nào thống trị về kinh tế thì sẽ thống trị về chính trị, tư tưởng","Các mâu thuẫn trong chính trị, tư tưởng xét đến cùng quyết định các mâu thuẫn trong lĩnh vực kinh tế"],"a":[3],"e":"Câu hỏi tìm luận điểm sai. Giáo trình viết: các mâu thuẫn trong kinh tế, xét đến cùng, quyết định các mâu thuẫn trong lĩnh vực chính trị tư tưởng; đấu tranh giai cấp về chính trị tư tưởng chỉ là biểu hiện đối kháng trong đời sống kinh tế. Phương án D đảo ngược quan hệ quyết định này. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đúng: sự phát triển của lực lượng sản xuất làm thay đổi quan hệ sản xuất (tức cơ sở hạ tầng) và thông qua đó làm thay đổi kiến trúc thượng tầng.","Đúng: cơ sở hạ tầng thay đổi thì sớm hay muộn kiến trúc thượng tầng cũng thay đổi theo.","Đúng: trong xã hội có giai cấp, giai cấp thống trị về kinh tế cũng chiếm địa vị thống trị về chính trị và đời sống tinh thần.",""],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục III.2 «Quan hệ biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng»","c":3,"v":"khớp"},{"q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, trong thực tế chúng ta phải dựa vào điều gì?","o":["Dựa vào tất nhiên, đề phòng ngẫu nhiên","Dựa vào ngẫu nhiên, đề phòng tất nhiên","Dựa vào cả tất nhiên và ngẫu nhiên","Không dựa vào các yếu tố nào mang tính tất nhiên, ngẫu nhiên"],"a":[0],"e":"Giáo trình kết luận phương pháp luận: trong hoạt động thực tiễn phải dựa vào cái tất nhiên (gắn với bản chất, xảy ra theo quy luật nội tại), không thể dựa vào cái ngẫu nhiên; nhưng cũng không được bỏ qua hoàn toàn cái ngẫu nhiên vì nó có thể ảnh hưởng sâu sắc, nên cần có phương án dự phòng. Do đó chọn A (dựa vào tất nhiên, đề phòng ngẫu nhiên). ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.VII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Đảo ngược: ngẫu nhiên không gắn với bản chất sự vật, có thể xảy ra hoặc không, nên không thể làm chỗ dựa chính.","Dựa «cả hai» ngang nhau là sai: tất nhiên chi phối sự phát triển còn ngẫu nhiên chỉ làm cho nó nhanh hay chậm; ngẫu nhiên chỉ cần lưu ý, dự phòng.","Phủ nhận cả hai yếu tố; giáo trình khẳng định cả tất nhiên lẫn ngẫu nhiên đều tồn tại khách quan và có vai trò nhất định."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.VII, mục IV.3 «Một số kết luận về mặt phương pháp luận» (cặp tất nhiên - ngẫu nhiên)","c":2,"v":"dễ nhầm","k":"Cụm «đề phòng ngẫu nhiên» là cách diễn đạt của đề; giáo trình viết «không thể dựa vào cái ngẫu nhiên» và «không được bỏ qua hoàn toàn», nên C dễ gây nhầm."},{"q":"Đấu tranh giai cấp có vai trò gì đối với sự phát triển của xã hội?","o":["Kìm hãm sự phát triển của xã hội","Tất cả đều sai","Không có vai trò gì","Là động lực thúc đẩy"],"a":[3],"e":"Giáo trình nêu đấu tranh giai cấp là một trong những động lực phát triển của xã hội có giai cấp: đỉnh cao của nó là cách mạng xã hội thay thế phương thức sản xuất cũ bằng phương thức sản xuất mới tiến bộ hơn, mở địa bàn mới cho sản xuất phát triển. Vì vậy đáp án là động lực thúc đẩy (D). ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.XI](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Sai: đấu tranh giai cấp góp phần xóa bỏ thế lực phản động, lạc hậu chứ không kìm hãm xã hội.","Đáp án D đúng nên phương án «tất cả đều sai» sai.","Sai: đấu tranh giai cấp có vai trò lớn, đỉnh cao là cách mạng xã hội, đòn bẩy thay đổi hình thái kinh tế - xã hội.",""],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.XI, mục II.2.b «Đấu tranh giai cấp là một trong những động lực phát triển của xã hội có giai cấp»","c":3,"v":"khớp","k":"Giáo trình nói «một trong những động lực» và chỉ của xã hội có giai cấp; đáp án D của đề nói gọn hơn nên cần hiểu theo ngữ cảnh này (xem thêm câu 158).","f":1},{"q":"Cơ sở trực tiếp và chủ yếu nhất để hình thành khái niệm là","o":["Thế giới tự nhiên","Thực tiễn","Cảm giác","Tri giác và biểu tượng"],"a":[1],"e":"Giáo trình khẳng định thực tiễn là cơ sở, động lực, mục đích của nhận thức; khái niệm là kết quả khái quát, tổng hợp biện chứng các thuộc tính của sự vật nên rốt cuộc cũng bắt nguồn từ thực tiễn. Vì vậy cơ sở trực tiếp và chủ yếu nhất để hình thành khái niệm là thực tiễn. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.IX](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Thế giới tự nhiên là đối tượng được phản ánh, nhưng con người nhận thức nó thông qua hoạt động thực tiễn chứ không trực tiếp từ tự nhiên.","","Cảm giác là hình thức đầu tiên của nhận thức cảm tính, còn khái niệm thuộc nhận thức lý tính nên không thể chỉ dựa vào cảm giác.","Tri giác và biểu tượng là các hình thức của nhận thức cảm tính, cung cấp tư liệu chứ không phải cơ sở trực tiếp, chủ yếu nhất."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.IX (vai trò của thực tiễn đối với nhận thức; khái niệm là hình thức tư duy trừu tượng); chưa đối chiếu số mục","c":2,"v":"dễ nhầm","k":"Cụm «cơ sở trực tiếp và chủ yếu nhất» là cách nói của đề, chưa thấy nguyên văn trong giáo trình; đáp án suy ra từ luận điểm thực tiễn là cơ sở của nhận thức.","id":"1wch0ca"},{"q":"Trong chủ nghĩa Mác - Lênin, bộ phận lý luận nào có chức năng làm sáng tỏ bản chất và những quy luật chung nhất của mọi sự vận động, phát triển của thế giới?","o":["Triết học Mác - Lênin","Kinh tế chính trị Mác - Lênin","Chủ nghĩa xã hội khoa học","Không có bộ phận nào giữ chức năng đó vì chủ nghĩa Mác - Lênin thuộc khoa học xã hội"],"a":[0],"e":"Giáo trình xác định đối tượng của triết học Mác - Lênin là nghiên cứu những quy luật chung nhất của tự nhiên, xã hội và tư duy, và giải quyết mối quan hệ vật chất - ý thức trên lập trường duy vật triệt để. Kinh tế chính trị và chủ nghĩa xã hội khoa học là hai bộ phận khác với đối tượng riêng. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.I](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Kinh tế chính trị nghiên cứu các quy luật kinh tế (nhất là của phương thức sản xuất tư bản chủ nghĩa), không phải quy luật chung nhất của mọi sự vận động.","Chủ nghĩa xã hội khoa học nghiên cứu quy luật chính trị - xã hội của quá trình chuyển lên chủ nghĩa xã hội và cộng sản.","Sai: chủ nghĩa Mác - Lênin có bộ phận là triết học đảm nhiệm đúng chức năng này, và việc là khoa học xã hội không loại trừ điều đó."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.I, mục về đối tượng của triết học Mác; chưa đối chiếu số mục","c":1,"v":"khớp"},{"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử, yếu tố cơ bản nhất tạo thành điều kiện sinh hoạt vật chất của xã hội là các yếu tố thuộc về","o":["Điều kiện tự nhiên","Điều kiện dân cư","Phương thức sản xuất ra của cải vật chất","Không có yếu tố nào là cơ bản nhất mà tùy thuộc các điều kiện lịch sử cụ thể khác nhau"],"a":[2],"e":"Giáo trình nhấn mạnh sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội; sự phát triển của sản xuất vật chất quyết định sự biến đổi các mặt của đời sống xã hội, nên phải tìm cơ sở sâu xa của các hiện tượng xã hội ở nền sản xuất vật chất. Vì thế yếu tố cơ bản nhất trong điều kiện sinh hoạt vật chất là phương thức sản xuất ra của cải vật chất. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Điều kiện tự nhiên là môi trường, tiền đề của xã hội nhưng không quyết định sự phát triển của xã hội.","Điều kiện dân cư chỉ là một điều kiện cần, không phải yếu tố cơ bản nhất.","","Sai: chủ nghĩa duy vật lịch sử chỉ rõ phương thức sản xuất giữ vai trò quyết định, không phải tùy hoàn cảnh cụ thể."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục I.3 «Sản xuất vật chất - cơ sở của sự tồn tại và phát triển xã hội»","c":3,"v":"dễ nhầm","k":"Bộ ba «điều kiện tự nhiên, dân cư, phương thức sản xuất» là cách trình bày của bản giáo trình khác; trong bản tái bản lần 3 chưa thấy nguyên cụm, đáp án vẫn nhất quán với luận điểm sản xuất vật chất là cơ sở."},{"q":"Chủ nghĩa Mác - Lênin sẽ phát triển đạt đến đâu?","o":["Đã phát triển đến mức hoàn toàn đầy đủ","Trong đó mọi vấn đề được giải quyết triệt để, chỉ cần nghiên cứu và vận dụng trong thực tiễn","Có thể thay thế cho mọi khoa học","Không ngừng phát triển trên cơ sở tổng kết những thành tựu mới của sự phát triển các khoa học và thực tiễn"],"a":[3],"e":"Giáo trình nêu Mác và Ăngghen tiếp tục bổ sung, phát triển học thuyết của mình trên cơ sở tổng kết kinh nghiệm thực tiễn của phong trào công nhân và khái quát các thành tựu khoa học. Vì vậy chủ nghĩa Mác - Lênin là học thuyết mở, không ngừng phát triển. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.III](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Sai: học thuyết không bao giờ hoàn toàn đầy đủ vì còn phải bổ sung theo khoa học và thực tiễn.","Sai: không có vấn đề nào được giải quyết triệt để một lần, mà phải nghiên cứu, vận dụng sáng tạo và phát triển.","Sai: triết học Mác chấm dứt tham vọng thay thế mọi khoa học (ví dụ quan niệm «khoa học của các khoa học»).",""],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.III, mục về giai đoạn Mác - Ăngghen bổ sung, phát triển lý luận triết học; chưa đối chiếu số mục","c":1,"v":"khớp"},{"q":"Theo quan điểm duy tâm, lực lượng sáng tạo ra lịch sử là :","o":["Quần chúng nhân dân lao động","Giai cấp thống trị xã hội","Các vĩ nhân, những cá nhân kiệt xuất","Giai cấp bị trị xã hội"],"a":[2],"e":"Giáo trình nêu các nhà tư tưởng trước Mác không nhận thức đúng vai trò quần chúng nhân dân, do quan điểm duy tâm hoặc siêu hình về xã hội; chủ nghĩa duy vật lịch sử mới khẳng định quần chúng nhân dân là chủ thể sáng tạo chân chính. Quan điểm duy tâm quy công lao cho vĩ nhân, cá nhân kiệt xuất (đề chọn C). ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.XIV](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đây là quan điểm của chủ nghĩa duy vật lịch sử, đối lập với quan điểm duy tâm.","Giai cấp thống trị không được duy tâm coi là lực lượng sáng tạo lịch sử theo cách nêu trong đề; quan điểm điển hình là đề cao vĩ nhân.","","Giai cấp bị trị (cũng là quần chúng lao động) thuộc về lực lượng mà chủ nghĩa duy vật lịch sử đề cao, không phải đáp án của quan điểm duy tâm."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.XIV, mục III «Vai trò quần chúng nhân dân và cá nhân trong lịch sử»","c":3,"v":"khớp"},{"q":"Chủ nghĩa nào mà sự tồn tại phát triển của nó thường gắn với lợi ích giai cấp và các lực lượng tiến bộ trong lịch sử?","o":["Duy vật thô sơ","Duy vật","Duy tâm khách quan","Chiết trung"],"a":[1],"e":"Giáo trình nêu chủ nghĩa duy vật biện chứng là công cụ giúp các lực lượng tiến bộ trong xã hội cải tạo hiện thực, còn chủ nghĩa duy tâm tôn giáo thường biện hộ cho sự thống trị và chịu sự chống đối của các lực lượng tiến bộ. Do đó chủ nghĩa duy vật gắn với lợi ích giai cấp và lực lượng tiến bộ. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.I-II](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Duy vật thô sơ (chất phác) chỉ là hình thức đầu tiên, hạn chế của chủ nghĩa duy vật, không phải trường phái được nêu chung là gắn với lực lượng tiến bộ.","","Duy tâm khách quan thường gắn với lực lượng bảo thủ, biện hộ cho sự thống trị.","Chiết trung là lập trường dung hòa các quan điểm đối lập, không gắn với lợi ích giai cấp hay lực lượng tiến bộ cụ thể."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.I (các hình thức của chủ nghĩa duy vật) và Ch.II (đấu tranh duy vật - duy tâm); chưa đối chiếu số mục","c":1,"v":"dễ nhầm","k":"Câu hỏi nói chung chung, duy vật thô sơ cũng thuộc duy vật; chưa thấy nguyên văn «gắn với lợi ích giai cấp và lực lượng tiến bộ» trong giáo trình. Học theo đáp án của đề."},{"q":"Hình thức hoạt động thực tiễn cơ bản nhất quy định các hình thức hoạt động khác là hình thức nào sau đây?","o":["Hoạt động chính trị xã hội","Hoạt động quan sát và thực nghiệm khoa học","Hoạt động sản xuất vật chất","Hoạt động kinh tế"],"a":[2],"e":"Giáo trình nêu thực tiễn có ba hình thức cơ bản: hoạt động sản xuất vật chất, hoạt động chính trị - xã hội và hoạt động thực nghiệm khoa học; trong đó sản xuất vật chất là hình thức hoạt động cơ bản, đầu tiên của thực tiễn. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.IX](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Hoạt động chính trị - xã hội là một trong ba hình thức nhưng không phải hình thức cơ bản đầu tiên.","Thực nghiệm khoa học là một hình thức của thực tiễn, không quy định các hình thức khác.","","«Hoạt động kinh tế» không phải một trong ba hình thức cơ bản mà giáo trình nêu; phần kinh tế thực chất nằm trong sản xuất vật chất."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.IX, mục về phạm trù thực tiễn và ba hình thức cơ bản của thực tiễn","c":2,"v":"khớp"},{"q":"Theo quan điểm duy vật lịch sử thì xã hội có các loại hình sản xuất cơ bản nào?","o":["Sản xuất ra của cải vật chất, đời sống tinh thần và nghệ thuật","Sản xuất ra văn hóa, con người và đời sống tinh thần","Sản xuất ra của cải vật chất, tinh thần và văn hóa","Sản xuất ra của cải vật chất, tinh thần và con người"],"a":[3],"e":"Giáo trình nêu sản xuất xã hội bao gồm sản xuất vật chất, sản xuất tinh thần và sản xuất ra bản thân con người; ba quá trình gắn bó chặt chẽ, tác động qua lại, trong đó sản xuất vật chất là cơ sở. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Thiếu sản xuất ra con người; «nghệ thuật» chỉ là một bộ phận của sản xuất tinh thần, không phải một loại hình riêng.","Thiếu sản xuất ra của cải vật chất, là loại hình cơ bản nhất.","Thiếu sản xuất ra con người; «văn hóa» nằm trong sản xuất tinh thần.",""],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục I.3 «Sản xuất vật chất - cơ sở của sự tồn tại và phát triển xã hội»","c":3,"v":"khớp"},{"q":"Theo quan điểm duy vật lịch sử, nguồn gốc sâu xa của các cuộc cách mạng là do đâu?","o":["Mâu thuẫn gay gắt giữa lực lượng sản xuất và quan hệ sản xuất","Giai cấp cầm quyền bị khủng hoảng về đường lối cai trị","Quần chúng lao động bị áp bức","Quần chúng lao động bị áp bức nặng nề"],"a":[0],"e":"Giáo trình viết nguyên nhân sâu xa của cách mạng xã hội là mâu thuẫn giữa lực lượng sản xuất và quan hệ sản xuất: quan hệ sản xuất cũ trở thành «xiềng xích» kìm hãm lực lượng sản xuất, khi đó bắt đầu thời đại một cuộc cách mạng xã hội. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.XII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Khủng hoảng đường lối cai trị của giai cấp cầm quyền chỉ là điều kiện, biểu hiện chính trị chứ không phải nguyên nhân sâu xa.","Quần chúng bị áp bức chỉ là hệ quả, biểu hiện của mâu thuẫn xã hội bên trên mâu thuẫn kinh tế.","Áp bức nặng nề chỉ là biểu hiện, yếu tố thúc đẩy, không phải nguồn gốc sâu xa; phương án này gần như lặp lại C."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.XII, mục II.1.b «Nguyên nhân của cách mạng xã hội»","c":3,"v":"khớp"},{"q":"Chọn phương án đúng về đấu tranh giai cấp?","o":["Đấu tranh giai cấp là một trong những động lực phát triển của xã hội có giai cấp","Đấu tranh giai cấp là động lực mạnh mẽ nhất làm thay đổi xã hội","Đấu tranh giai cấp là một trong những động lực phát triển của xã hội","Đấu tranh giai cấp là động lực phát triển của xã hội"],"a":[0],"e":"Giáo trình đặt mục: «Đấu tranh giai cấp là một trong những động lực phát triển của xã hội có giai cấp». Tức là nó chỉ tồn tại ở xã hội có giai cấp và không phải động lực duy nhất; quy luật đấu tranh giai cấp sẽ chấm dứt khi xã hội hết phân chia giai cấp đối kháng. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.XI](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","«Mạnh mẽ nhất» là so sánh tuyệt đối mà giáo trình không khẳng định.","Thiếu giới hạn «xã hội có giai cấp», nên chưa chính xác về phạm vi tác động.","Tuyệt đối hóa: bỏ cả «một trong những» lẫn giới hạn xã hội có giai cấp."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.XI, mục II.2.b","c":3,"v":"khớp"},{"q":"\"Những thời đại kinh tế khác nhau không phải ở chỗ chúng sản xuất ra cái gì, mà là ở chỗ chúng sản xuất bằng cách nào, với những tư liệu lao động nào\". Câu nói trên là của ai?","o":["Ph.Ăngghen","D. Ricardo","Mác"],"a":[2],"e":"Câu nói là của C. Mác trong bộ «Tư bản» (quyển I), nhấn mạnh tư liệu lao động, đặc biệt công cụ lao động, là thước đo trình độ chinh phục tự nhiên và tiêu chuẩn phân biệt các thời đại kinh tế. Giáo trình Triết học cũng nêu ý này khi bàn về lực lượng sản xuất. ([Tài liệu trắc nghiệm trích Tư bản, tr.388 bản NXB Sự thật](https://doctailieu.com/trac-nghiem/nhung-thoi-dai-kinh-te-khac-nhau-khong-phai-o-cho-chung-san-xuat-ra-cai-gi-ma-38249); [GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Ăngghen là người cùng sáng lập chủ nghĩa Mác nhưng câu trích này được dẫn là của Mác trong «Tư bản».","D. Ricardo là nhà kinh tế chính trị cổ điển Anh, không phải tác giả của câu trích.",""],"s":"C. Mác, «Tư bản», quyển I (nguồn thứ cấp: ngân hàng câu hỏi); GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục II.1.b","c":3,"v":"khớp","k":"Chưa mở được bản gốc «Tư bản» trên marxists.org; xuất xứ dựa trên tài liệu thứ cấp.","id":"1h5qs1n"},{"q":"Chọn câu trả lời đúng theo quan điểm duy vật lịch sử: Quá trình \"lịch sử tự nhiên\" của sự phát triển các hình thái kinh tế xã hội là quá trình phát triển theo","o":["Ý niệm tuyệt đối","Quy luật khách quan của xã hội","Quy luật của tự nhiên","Ý muốn chủ quan của con người"],"a":[1],"e":"Mác kết luận sự phát triển của những hình thái kinh tế - xã hội là một quá trình lịch sử - tự nhiên. Giáo trình giải thích đó là sự tác động của các quy luật khách quan của xã hội, kể cả việc một dân tộc bỏ qua một hay vài hình thái cũng diễn ra theo quá trình lịch sử - tự nhiên chứ không theo ý muốn chủ quan. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Ý niệm tuyệt đối là quan điểm duy tâm của Hêghen.","","Quy luật xã hội mang tính khách quan nhưng khác quy luật tự nhiên ở chỗ được thực hiện thông qua hoạt động có ý thức của con người.","Ý muốn chủ quan là quan điểm duy tâm, trái với tính khách quan của quy luật xã hội."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục IV.1 «Phạm trù hình thái kinh tế - xã hội» và mục I.2 (đặc điểm của quy luật xã hội)","c":3,"v":"khớp"},{"q":"Chọn câu trả lời đúng theo quan điểm duy vật lịch sử: Chủ thể sáng tạo chân chính ra lịch sử là:","o":["Quần chúng nhân dân","Các cá nhân kiệt xuất, các vĩ nhân","Giai cấp thống trị","Tầng lớp tri thức trong xã hội"],"a":[0],"e":"Giáo trình khẳng định chủ nghĩa duy vật lịch sử coi quần chúng nhân dân là chủ thể sáng tạo chân chính ra lịch sử, vì mọi lý tưởng giải phóng chỉ được chứng minh qua hoạt động của quần chúng; họ là lực lượng sản xuất cơ bản và động lực cơ bản của mọi cuộc cách mạng xã hội. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.XIV](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Vĩ nhân, cá nhân kiệt xuất có vai trò quan trọng nhưng không phải chủ thể sáng tạo chân chính; đề cao họ là quan điểm duy tâm.","Giai cấp thống trị không phải chủ thể sáng tạo chân chính ra lịch sử.","Tầng lớp tri thức chỉ là bộ phận của nhân dân, không thể thay cho quần chúng nhân dân nói chung."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.XIV, mục III.2 (vai trò của quần chúng nhân dân)","c":3,"v":"khớp"},{"q":"Chọn câu trả lời đúng theo quan điểm duy vật lịch sử: Mỗi phương thức sản xuất đều được tạo nên bởi hai mặt:","o":["Kỹ thuật và công nghệ","Kỹ thuật và lao động","Kỹ thuật và kinh tế","Kỹ thuật và tổ chức"],"a":[2],"e":"Phương thức sản xuất là sự thống nhất giữa lực lượng sản xuất (mặt kỹ thuật: công cụ, phương pháp, công nghệ) và quan hệ sản xuất (mặt kinh tế: quan hệ giữa người với người trong sản xuất). Vì vậy hai mặt tạo nên phương thức sản xuất được diễn đạt là kỹ thuật và kinh tế. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Công nghệ thuộc mặt kỹ thuật; cặp «kỹ thuật và công nghệ» không nêu mặt quan hệ sản xuất.","Lao động thuộc lực lượng sản xuất; cặp này không có mặt quan hệ sản xuất (kinh tế).","","«Tổ chức» chỉ là một mặt của quan hệ sản xuất (quan hệ tổ chức quản lý), không phải cả mặt kinh tế."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục II.1.a (phương thức sản xuất là sự thống nhất lực lượng sản xuất và quan hệ sản xuất); chưa đối chiếu số chương của bản có cách nói «mặt kỹ thuật, mặt kinh tế»","c":3,"v":"chưa kiểm chứng","k":"chưa kiểm chứng được nguồn cho câu này. Cách nói «hai mặt kỹ thuật và kinh tế» chưa thấy nguyên văn trong bản giáo trình đã đối chiếu; phần giải thích là suy ra từ định nghĩa phương thức sản xuất."},{"q":"Chọn câu trả lời đúng theo quan điểm duy vật lịch sử: Thực chất của quá trình sản xuất vật chất là quá trình:","o":["Con người thực hiện sự cải biến giới tự nhiên","Con người nhận thức thế giới và bản thân mình","Con người thực hiện sáng tạo trong tư duy","Con người thực hiện lợi ích của mình"],"a":[0],"e":"Giáo trình định nghĩa sản xuất vật chất là quá trình con người sử dụng công cụ lao động tác động vào tự nhiên, cải biến các dạng vật chất của giới tự nhiên nhằm tạo ra của cải vật chất thỏa mãn nhu cầu tồn tại và phát triển của con người. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Nhận thức thế giới và bản thân là hoạt động tinh thần, không phải thực chất của sản xuất vật chất.","Sáng tạo trong tư duy thuộc sản xuất tinh thần, không phải quá trình cải biến giới tự nhiên.","Thực hiện lợi ích là mục đích gián tiếp, chưa nêu được thực chất của quá trình sản xuất vật chất."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục I.3","c":3,"v":"khớp"},{"q":"Chọn câu trả lời đúng theo quan điểm duy vật lịch sử: Nhân tố quyết định trong lực lượng sản xuất là nhân tố:","o":["Tư liệu sản xuất","Người lao động","Công cụ lao động"],"a":[1],"e":"Giáo trình nêu lực lượng sản xuất là sự kết hợp người lao động và tư liệu sản xuất, trong đó «lực lượng sản xuất hàng đầu của toàn thể nhân loại là công nhân, là người lao động»; người lao động là chủ thể của quá trình lao động sản xuất. Vì vậy nhân tố quyết định là người lao động. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Tư liệu sản xuất (công cụ và đối tượng lao động) là yếu tố cần thiết nhưng do con người tạo ra và chỉ phát huy khi người lao động sử dụng.","","Giáo trình nói công cụ lao động là yếu tố động nhất và «đóng vai trò quyết định trong tư liệu sản xuất», tức quyết định trong phạm vi tư liệu sản xuất, không phải nhân tố quyết định của cả lực lượng sản xuất."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục II.1.b «Lực lượng sản xuất»","c":3,"v":"dễ nhầm","k":"Câu chỉ có 3 phương án (không có D); phương án C dễ nhầm vì giáo trình gọi công cụ lao động là yếu tố động nhất, quyết định trong tư liệu sản xuất. Học theo đáp án B của đề.","id":"1xlkhk7"},{"q":"Chọn câu trả lời đúng, đầy đủ nhất theo quan niệm duy vật lịch sử: Cách mạng xã hội giữ vai trò là","o":["Nguồn gốc và động lực tiến bộ của xã hội","Động lực phát triển của mọi xã hội","Một trong những phương thức, động lực phát triển xã hội","Phương thức, động lực cơ bản nhất của sự phát triển xã hội trong điều kiện xã hội có sự phân hóa thành đối kháng giai cấp"],"a":[3],"e":"Giáo trình nêu cách mạng xã hội là phương thức thay thế hình thái kinh tế - xã hội lỗi thời bằng hình thái cao hơn, là đỉnh cao của đấu tranh giai cấp và bước nhảy vọt tất yếu trong sự phát triển của xã hội có giai cấp. Vì vậy phương án đầy đủ nhất là D, nêu cả vai trò cơ bản nhất lẫn điều kiện xã hội phân hóa thành các giai cấp đối kháng. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.XII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Quá chung chung, không nêu điều kiện xã hội có giai cấp đối kháng.","Không phải xã hội nào cũng cần cách mạng xã hội: nó gắn với xã hội có giai cấp đối kháng.","Quá yếu: «một trong những» chưa nêu được vai trò phương thức, động lực cơ bản nhất.",""],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.XII, mục II.1.a-c (khái niệm, nguyên nhân, vai trò của cách mạng xã hội)","c":3,"v":"dễ nhầm","k":"Cụm «phương thức, động lực cơ bản nhất ... trong điều kiện đối kháng giai cấp» chưa thấy nguyên văn trong bản đã đối chiếu (bản này chỉ nói «phương thức thay thế hình thái» và «đòn bẩy»); đáp án đúng theo dạng câu «đầy đủ nhất»."},{"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử, nguồn gốc, động lực cơ bản nhất của mọi quá trình phát triển xã hội là gì?","o":["Sự phát triển của khoa học","Sự vận động của mâu thuẫn giữa lực lượng sản xuất và quan hệ sản xuất","Sự phát triển của khoa học công nghệ","Đấu tranh giai cấp"],"a":[1],"e":"Giáo trình khẳng định quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất là quy luật cơ bản nhất của sự vận động, phát triển xã hội; sự tác động biện chứng giữa hai mặt này làm cho lịch sử xã hội là lịch sử kế tiếp nhau của các phương thức sản xuất. Vì vậy nguồn gốc, động lực cơ bản nhất là mâu thuẫn giữa lực lượng sản xuất và quan hệ sản xuất. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Khoa học chỉ là một yếu tố, nó trở thành lực lượng sản xuất trực tiếp trong lực lượng sản xuất hiện đại, không phải nguồn gốc cơ bản nhất.","","Khoa học công nghệ là yếu tố của lực lượng sản xuất hiện đại, không thay thế được mâu thuẫn cơ bản.","Đấu tranh giai cấp là động lực trực tiếp của xã hội có giai cấp, còn nguồn gốc sâu xa là mâu thuẫn lực lượng sản xuất - quan hệ sản xuất."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục II.2 (quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất)","c":3,"v":"khớp"},{"q":"Xét đến cùng, nhân tố quan trọng nhất quyết định sự thắng lợi của một trật tự xã hội mới là","o":["Năng suất lao động","Luật pháp","Chính trị","Kinh tế"],"a":[0],"e":"Lênin viết rằng, suy cho cùng, năng suất lao động là điều quan trọng nhất, chủ yếu nhất cho thắng lợi của trật tự (chế độ) xã hội mới. Chủ nghĩa xã hội phải tạo ra năng suất lao động cao hơn chủ nghĩa tư bản mới chiến thắng được nó. ([Lênin, Những nhiệm vụ trước mắt của chính quyền Xô viết, Tư liệu Văn kiện](https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/v-i-lenin/nghien-cuu-hoc-tap-tu-tuong/nhung-nhiem-vu-truoc-mat-cua-chinh-quyen-xoviet-3151))","w":["","Luật pháp thuộc kiến trúc thượng tầng, do cơ sở kinh tế quyết định.","Chính trị cũng thuộc kiến trúc thượng tầng, không phải nhân tố quyết định sau cùng.","Kinh tế là khái niệm quá rộng; Lênin dùng cụm «năng suất lao động» để nói điều quyết định thắng lợi."],"s":"V.I. Lênin, «Những nhiệm vụ trước mắt của chính quyền Xô viết» (1918) và «Sáng kiến vĩ đại» (1919); chưa đối chiếu số chương giáo trình","c":3,"v":"khớp","k":"Trang Tư liệu Văn kiện cho câu «cái quan trọng nhất, căn bản nhất đảm bảo cho thắng lợi của trật tự xã hội mới» thuộc tác phẩm 1918. Cách diễn đạt «suy cho cùng... chủ yếu nhất» thường được dẫn từ «Sáng kiến vĩ đại»; chưa mở được văn bản này để xác minh."},{"q":"Quan hệ sản xuất là phạm trù dùng để chỉ","o":["Quan hệ giữa con người sản xuất với người tiêu dùng trong quá trình sản xuất","Quan hệ giữa người với người trong quá trình sản xuất","Quan hệ giữa con người với tự nhiên trong quá trình sản xuất"],"a":[1],"e":"Giáo trình định nghĩa: quan hệ sản xuất là quan hệ giữa người với người trong quá trình sản xuất (sản xuất và tái sản xuất xã hội), gồm quan hệ sở hữu tư liệu sản xuất, quan hệ tổ chức - quản lý sản xuất và quan hệ phân phối sản phẩm. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Quan hệ sản xuất không chỉ là quan hệ giữa người sản xuất với người tiêu dùng, mà bao gồm sở hữu, tổ chức - quản lý và phân phối.","","Quan hệ giữa người với tự nhiên trong sản xuất là mặt lực lượng sản xuất, không phải quan hệ sản xuất."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục II.1.c «Quan hệ sản xuất»","c":3,"v":"khớp","id":"1hh0koi"},{"q":"Chọn câu trả lời đúng. Lực lượng sản xuất bao gồm:","o":["Tư liệu sản xuất và người lao động","Người lao động và công cụ lao động","Người lai động và trình độ lao động của họ","Tư liệu sản xuất và các nguồn lực tự nhiên"],"a":[0],"e":"Giáo trình nêu lực lượng sản xuất là sự kết hợp người lao động (với kỹ năng, tri thức) và tư liệu sản xuất (tư liệu lao động, trước hết là công cụ lao động, và đối tượng lao động). Vì vậy lực lượng sản xuất gồm tư liệu sản xuất và người lao động. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Thiếu đối tượng lao động; công cụ lao động chỉ là một phần của tư liệu sản xuất.","Thiếu tư liệu sản xuất; trình độ lao động chỉ là một mặt của người lao động.","Thiếu người lao động, là yếu tố hàng đầu; nguồn lực tự nhiên chỉ là đối tượng lao động nếu được đưa vào sản xuất."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục II.1.b «Lực lượng sản xuất»","c":3,"v":"khớp"},{"q":"Quan niệm cho rằng \"suy nghĩ của những người sống trong túp lều tranh luôn luôn khác với suy nghĩ của những kẻ sống trong cung điện\" là quan điểm của","o":["Chủ nghĩa duy tâm","Chủ nghĩa duy vật siêu hình","Chủ nghĩa duy vật lịch sử","Chủ nghĩa duy vật"],"a":[1],"e":"Quan niệm cho rằng suy nghĩ của con người hoàn toàn do hoàn cảnh sống quy định thuộc kiểu chủ nghĩa duy vật cũ, siêu hình, mà Mác phê phán: học thuyết duy vật coi con người là sản phẩm của hoàn cảnh quên rằng chính con người làm thay đổi hoàn cảnh. Giáo trình trích luận điểm này của Mác. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.XIV](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Chủ nghĩa duy tâm cho ý thức, tinh thần quyết định hoàn cảnh; câu này lại giải thích tư duy bằng hoàn cảnh vật chất.","","Chủ nghĩa duy vật lịch sử giải thích bằng tồn tại xã hội và còn nhấn mạnh con người tác động trở lại, cải biến hoàn cảnh.","Duy vật nói chung quá rộng; điểm cần nhận ra là tính máy móc, siêu hình khi bỏ qua hoạt động thực tiễn của con người."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.XIV (Mác phê phán học thuyết duy vật coi con người là sản phẩm của hoàn cảnh); chưa tìm được xuất xứ nguyên văn câu «túp lều tranh, cung điện»","c":1,"v":"nghi vấn","k":"nghi vấn: Không tìm được xuất xứ nguyên văn của câu trích; có thể bị hiểu là duy vật lịch sử (tồn tại xã hội quyết định ý thức). Các nguồn tìm được chỉ là ngân hàng câu hỏi, không có giải thích. Học theo đáp án B của đề."},{"q":"Bản chất của con người được quyết định bởi","o":["Các quan hệ xã hội","Giáo dục gia đình","Sự nỗ lực của cá nhân","Giáo dục nhà trường"],"a":[0],"e":"Mác khẳng định trong «Luận cương về Phoiơbắc»: trong tính hiện thực của nó, bản chất con người là tổng hòa những quan hệ xã hội. Giáo trình giải thích bản chất xã hội của con người bộc lộ qua toàn bộ các quan hệ xã hội (giai cấp, dân tộc, chính trị, kinh tế, gia đình...). ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.XIV](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Giáo dục gia đình chỉ là một quan hệ xã hội trong tổng hòa các quan hệ, không quyết định bản chất con người.","Nỗ lực cá nhân là nhân tố chủ quan, không phải cái quyết định bản chất, vì bản chất không phải cái trừu tượng cố hữu của cá nhân riêng biệt.","Giáo dục nhà trường cũng chỉ là một yếu tố trong các quan hệ xã hội."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.XIV, mục về bản chất con người; C. Mác, «Luận cương về Phoiơbắc» (Luận cương VI)","c":3,"v":"khớp","k":"Trong file gốc, câu này bị dính với đề của một câu khác (bài thuyết trình theo quy luật lượng - chất) mà phần đáp án bị mất; câu dính đã được cắt bỏ."},{"q":"Đặc trưng chủ yếu của cách mạng xã hội là gì?","o":["Sự thay đổi về hệ tư tưởng nói riêng và toàn bộ đời sống tinh thần của xã hội nói chung","Sự thay đổi về cơ cấu, tổ chức hoạt động sản xuất ra của cải vật chất trong xã hội","Sự thay đổi chính quyền nhà nước từ tay giai cấp thống trị đã lỗi thời sang tay giai cấp cách mạng.","Sự thay đổi về thế lực cầm quyền trong cùng một giai cấp"],"a":[2],"e":"Giáo trình nêu vấn đề giành chính quyền là vấn đề cơ bản của mọi cuộc cách mạng xã hội, vì giai cấp cách mạng phải giành lấy chính quyền nhà nước từ tay giai cấp thống trị lỗi thời để xác lập chuyên chính của mình. Vì vậy đặc trưng chủ yếu là sự thay đổi chính quyền nhà nước từ giai cấp thống trị đã lỗi thời sang giai cấp cách mạng. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.XII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Thay đổi hệ tư tưởng và đời sống tinh thần là hệ quả sau khi giành chính quyền, không phải đặc trưng chủ yếu.","Thay đổi cơ cấu sản xuất là nội dung kinh tế - xã hội của cách mạng, được thực hiện sau khi có chính quyền.","","Thay đổi thế lực trong cùng một giai cấp là đảo chính, khác hoàn toàn với cách mạng xã hội."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.XII, mục II.1.a-b","c":3,"v":"khớp"},{"q":"Theo quan điểm của phép biện chứng duy vật thì quy luật nào vạch ra khuynh hướng cơ bản phổ biến của sự vận động và phát triển","o":["Quy luật thống nhất và đấu tranh của các mặt đối lập","Quy luật về chuyển hóa sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại","Quy luật phủ định của phủ định","Quy luật về sự phù hợp của QHSX và trình độ LLSX"],"a":[2],"e":"Giáo trình nêu quy luật phủ định của phủ định khái quát xu hướng tất yếu tiến lên của sự vật, tức xu hướng phát triển, theo đường «xoáy ốc» với tính kế thừa, lặp lại và tiến lên. Vì vậy quy luật này vạch ra khuynh hướng cơ bản, phổ biến của sự vận động, phát triển. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.VIII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Quy luật mâu thuẫn chỉ ra nguồn gốc, động lực của sự vận động và phát triển.","Quy luật lượng - chất chỉ ra cách thức của sự vận động và phát triển.","","Quy luật quan hệ sản xuất phù hợp với lực lượng sản xuất là quy luật xã hội, không thuộc ba quy luật cơ bản của phép biện chứng duy vật."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.VIII, mục IV «Quy luật phủ định của phủ định»","c":2,"v":"khớp"},{"q":"Khái niệm nào chỉ sự quy định, sự tác động qua lại, sự chuyển hoá lẫn nhau giữa các sự vật, hiện tượng hay giữa các mặt, các yếu tố trong một sự vật, hiện tượng?","o":["Mối liên hệ","Sự phát triển","Sự thay đổi","Sự biến đổi"],"a":[0],"e":"Giáo trình định nghĩa: liên hệ là phạm trù triết học dùng để chỉ sự quy định, sự tác động qua lại, sự chuyển hóa lẫn nhau giữa các sự vật, hiện tượng hay giữa các mặt của một sự vật, một hiện tượng trong thế giới. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.VI](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Sự phát triển là khái niệm chỉ quá trình vận động theo chiều hướng tiến lên từ thấp đến cao, không phải sự quy định, tác động qua lại.","Sự thay đổi là khái niệm chung, không nêu quan hệ quy định lẫn nhau giữa các sự vật.","Sự biến đổi cũng là khái niệm chung chung, không chỉ quan hệ giữa các sự vật, hiện tượng."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.VI «Hai nguyên lý của phép biện chứng duy vật», mục về nguyên lý mối liên hệ phổ biến","c":2,"v":"khớp"},{"q":"Khái niệm quan hệ sản xuất được hiểu là","o":["Mối quan hệ giữa người với người trong quá trình sản xuất","Mối quan hệ giữa người với người trong quá trình tiêu dùng","Mối quan hệ giữa người với người trong quá trình phân phối","Mối quan hệ giữa người với người trong quá trình hoạch định"],"a":[0],"e":"Quan hệ sản xuất là quan hệ giữa người với người trong quá trình sản xuất, bao gồm quan hệ sở hữu, tổ chức - quản lý và phân phối. Đề chọn A vì các phương án khác thay «sản xuất» bằng tiêu dùng, phân phối hay hoạch định. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Quá trình tiêu dùng không phải phạm vi định nghĩa quan hệ sản xuất.","Phân phối chỉ là một trong ba mặt của quan hệ sản xuất, không phải toàn bộ khái niệm.","Hoạch định không phải mặt cấu thành quan hệ sản xuất (mặt tổ chức - quản lý mới thuộc quan hệ sản xuất)."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục II.1.c","c":3,"v":"khớp"},{"q":"Khái niệm lực lượng sản xuất được hiểu là","o":["Toàn bộ những năng lực thực tiễn dùng trong sản xuất của xã hội","Toàn bộ những năng lực thực tiễn dùng trong tiêu dùng của xã hội","Toàn bộ những năng lực thực tiễn dùng trong phân phối của xã hội","Toàn bộ những năng lực thực tiễn dùng trong hoạch định của xã hội"],"a":[0],"e":"Giáo trình định nghĩa lực lượng sản xuất là năng lực thực tiễn cải biến giới tự nhiên của con người nhằm đáp ứng nhu cầu đời sống; nó biểu hiện quan hệ giữa con người với tự nhiên trong quá trình sản xuất. Vì vậy chọn phương án nói về năng lực thực tiễn dùng trong sản xuất của xã hội. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Tiêu dùng không thuộc khái niệm lực lượng sản xuất.","Phân phối thuộc quan hệ sản xuất, không phải năng lực cải biến tự nhiên.","Hoạch định không thuộc khái niệm lực lượng sản xuất."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục II.1.b","c":3,"v":"khớp"},{"q":"Mối quan hệ giữa cơ sở hạ tầng và kiến trúc thượng tầng là mối quan hệ:","o":["Luôn luôn thống nhất với nhau","Luôn luôn đối lập nhau","Thống nhất và đấu tranh giữa hai mặt đối lập","Thống nhất là căn bản, còn đấu tranh giữa chúng chỉ là tạm thời"],"a":[2],"e":"Giáo trình viết cơ sở hạ tầng và kiến trúc thượng tầng thống nhất biện chứng với nhau, trong đó cơ sở hạ tầng quyết định kiến trúc thượng tầng, còn kiến trúc thượng tầng có tính độc lập tương đối và tác động mạnh mẽ trở lại cơ sở hạ tầng. Đề diễn đạt quan hệ này là thống nhất và đấu tranh giữa hai mặt đối lập. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["«Luôn luôn thống nhất» bỏ qua mâu thuẫn, sự tác động hai chiều (thúc đẩy hoặc kìm hãm).","«Luôn luôn đối lập» bỏ qua sự thống nhất biện chứng và sự phù hợp giữa hai mặt.","","Theo phép biện chứng, đấu tranh của các mặt đối lập là tuyệt đối còn thống nhất là tương đối, nên không thể nói đấu tranh chỉ là tạm thời."],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.X, mục III.2 (quan hệ biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng) và Ch.VIII (quy luật mâu thuẫn)","c":3,"v":"khớp","k":"Giáo trình dùng chữ «thống nhất biện chứng»; cụm «thống nhất và đấu tranh giữa hai mặt đối lập» là cách diễn đạt của đề, suy ra từ quan hệ biện chứng này."},{"q":"V.I. Lênin cho rằng: Tính....không thể tách rời tính phổ biến.","o":["Nhân quả","Tất nhiên","Đơn nhất","Hiện thực"],"a":[1],"e":"Theo đáp án của đề, Lênin cho rằng tính tất nhiên không thể tách rời tính phổ biến: cái tất nhiên xuất phát từ bản chất bên trong của sự vật và mang tính chung, ổn định. Giáo trình nói cái tất nhiên gắn với bản chất nội tại, và cái chung gắn với bản chất là hình thức thể hiện của cái tất nhiên. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.VII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Nhân quả là quan hệ sản sinh giữa nguyên nhân và kết quả, không phải đặc tính đi cặp với tính phổ biến trong câu nói.","","Đơn nhất đối lập với phổ biến; không thể nói đơn nhất «không tách rời» phổ biến theo ý câu.","Hiện thực là phạm trù chỉ cái đang tồn tại, không phải tính chất đi cặp với phổ biến trong câu nói."],"s":"V.I. Lênin (câu trích, chưa xác định tác phẩm); GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.VII, mục IV (tất nhiên - ngẫu nhiên)","c":2,"v":"chưa kiểm chứng","k":"chưa kiểm chứng được nguồn cho câu này. Chỉ thấy câu hỏi này trong các ngân hàng câu hỏi (cùng đáp án B); chưa tìm được xuất xứ nguyên văn trong tác phẩm của Lênin nên chưa gắn được tên tác phẩm (bản nháp ghi «Bút ký triết học» chưa được kiểm chứng)."},{"q":"Thế giới quan là gì?","o":["Quan điểm, cách nhìn về XH","Quan điểm, cách nhìn về thế giới tự nhiên","Quan điểm, niềm tin, nhìn nhận về các sự vật cụ thể","Toàn bộ quan điểm và niềm tin định hướng hoạt động con người trong cuộc sống"],"a":[3],"e":"Giáo trình định nghĩa thế giới quan là toàn bộ những quan niệm của con người về thế giới, về bản thân con người, về cuộc sống và vị trí của con người trong thế giới; trong đó có sự hòa nhập giữa tri thức và niềm tin, và tri thức chỉ gia nhập thế giới quan khi trở thành niềm tin định hướng hoạt động. Vì vậy chọn D. ([GT Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3, Ch.I](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Quá hẹp: thế giới quan không chỉ là quan điểm về xã hội.","Quá hẹp: không chỉ là quan điểm về giới tự nhiên.","Quá hẹp: thế giới quan không chỉ nói về các sự vật cụ thể, mà là quan niệm chung về thế giới và vị trí con người trong đó.",""],"s":"GT Triết học Mác-Lênin (bản tái bản lần 3), Ch.I, mục II.1 «Triết học - hạt nhân lý luận của thế giới quan»","c":1,"v":"khớp"},{"q":"Ý thức tôn giáo là niềm tin của một bộ phận nhân dân, thường là yếu tố bền vững nhất trong đời sống tinh thần của mỗi con người, của xã hội là nguyên nhân gì (?) của sự tồn tại tôn giáo?","o":["Nhận thức.","Văn hóa.","Trình độ.","Tâm lý."],"a":[3],"e":"Theo chủ nghĩa Mác - Lênin, tôn giáo có ba nguồn gốc: nguồn gốc kinh tế - xã hội, nguồn gốc nhận thức và nguồn gốc tâm lý (sợ hãi, lo âu trước thiên nhiên và xã hội); niềm tin tôn giáo gắn với tình cảm, tâm lý nên tồn tại bền vững, nên đề chọn tâm lý. Giáo trình CNXH khoa học xem tôn giáo còn tồn tại trong thời kỳ quá độ vì các điều kiện tồn tại của nó vẫn còn. ([Tư liệu Văn kiện - Quan điểm của CN Mác-Lênin về tôn giáo](https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/c-mac/nghien-cuu-hoc-tap-tu-tuong/quan-diem-cua-chu-nghia-mac-lenin-ve-ton-giao-va-su-van-dung-de-giai-quyet-van-de-ton-giao-trong-thoi-ky-3126); [Giáo trình CNXH khoa học, vấn đề tôn giáo, VOER](https://voer.edu.vn/c/chuong-10-van-de-ton-giao-trong-qua-trinh-xay-dung-chu-nghia-xa-hoi/dc7c6722/2592e79b))","w":["Nguồn gốc nhận thức là sự hạn chế hiểu biết trước thiên nhiên và xã hội, khác với yếu tố niềm tin, tình cảm mà đề nhấn mạnh.","Văn hóa không phải một trong ba nguồn gốc của tôn giáo trong cách phân loại của giáo trình.","Trình độ không được giáo trình nêu là nguồn gốc riêng; nhận thức và kinh tế - xã hội là các nguồn gốc khác.",""],"s":"Giáo trình Chủ nghĩa xã hội khoa học, chương về vấn đề tôn giáo (nguồn gốc tôn giáo); câu hỏi không thuộc phần Triết học nên chưa đối chiếu số chương giáo trình Triết","c":3,"v":"dễ nhầm","k":"Đề là câu cụt, diễn đạt không rõ («nguyên nhân gì (?)»); chưa mở được trang VOER (lỗi kết nối), phần ba nguồn gốc dựa trên kết quả tìm kiếm; trang Tư liệu Văn kiện không dùng cụm «yếu tố bền vững». Học theo đáp án D của đề."},{"q":"Nguồn gốc vận động và phát triển của các hình thái kinh tế - xã hội là gì?Chọn một câu trả lời đúng:","o":["Sự tăng lên không ngừng của năng xuất lao động.","Mâu thuẫn giai - tầng trong xã hội, sự thay đổi của quan hệ sản xuất.","Do việc giải quyết mâu thuẫn giữa lực lượng sản xuất với quan hệ sản xuất, mâu thuẫn giữa cơ sở hạ tầng với kiến trúc thượng tầng.","Quần chúng nhân dân không ngừng nổi dậy đấu tranh chống các thế lực phản động trong xã hội."],"a":[2],"e":"Giáo trình nêu rằng chính sự tác động của các quy luật khách quan (quan hệ sản xuất phải phù hợp với trình độ phát triển của lực lượng sản xuất; cơ sở hạ tầng quyết định kiến trúc thượng tầng) làm cho các hình thái kinh tế - xã hội vận động, phát triển từ thấp đến cao. Vì vậy nguồn gốc vận động, phát triển nằm ở việc giải quyết mâu thuẫn LLSX - QHSX và CSHT - KTTT; nguồn gốc sâu xa là sự phát triển của lực lượng sản xuất. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Gần với «nguồn gốc sâu xa» (phát triển lực lượng sản xuất) nhưng chỉ nêu một yếu tố, chưa nói cơ chế mâu thuẫn LLSX - QHSX, CSHT - KTTT; năng suất lao động tăng là biểu hiện của sự phát triển LLSX.","Mâu thuẫn giai cấp và sự thay đổi QHSX là hệ quả, biểu hiện bên ngoài; giáo trình chỉ coi đấu tranh giai cấp là một trong những động lực của xã hội có giai cấp, không phải nguồn gốc chung.","","Quần chúng nổi dậy là hình thức biểu hiện cụ thể của đấu tranh xã hội, không phải nguồn gốc vận động của hình thái kinh tế - xã hội."],"s":"GT Triết học Mác-Lênin (bản 14 chương, tái bản lần 3), Chương X, mục IV.2.a (phát triển các hình thái KT-XH là quá trình lịch sử - tự nhiên)","c":3,"v":"dễ nhầm","k":"Phương án A dễ nhầm vì giáo trình gọi nguồn gốc sâu xa là phát triển lực lượng sản xuất; đề chọn C (cơ chế mâu thuẫn) nên cần đọc kỹ chữ «giải quyết mâu thuẫn»."},{"q":"Câu trả lời sau đây, câu nào diễn đạt chưa chuẩn xác:","o":["Chủ nghĩa Mác là học thuyết do C.Mác sáng lập.","Chủ nghĩa Mác là học thuyết về sự nghiệp giải phóng giai cấp vô sản và nhân dân lao động.","Chủ nghĩa Mác là thế giới quan và phương pháp luận chung của mọi nhận thức và thực tiễn.","Chủ nghĩa mác là học thuyết được xây dựng trên cơ sở kế thừa những tinh hoa của lịch sử tư tưởng nhân loại và thực tiễn cách mạng"],"a":[2],"e":"Nhận định chưa chuẩn xác là C vì nó tuyệt đối hóa: giáo trình mô tả triết học Mác - Lênin là thế giới quan và phương pháp luận (ở cấp «phương pháp luận chung nhất») khoa học và cách mạng, chứ không phải thế giới quan, phương pháp luận «của mọi nhận thức và thực tiễn» thay cho các khoa học cụ thể. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Diễn đạt chấp nhận được: chủ nghĩa Mác là học thuyết do C. Mác sáng lập (cùng Ph. Ăngghen), về sau Lênin phát triển.","Đúng: chủ nghĩa Mác là học thuyết về sự nghiệp giải phóng giai cấp vô sản và nhân dân lao động.","","Đúng: học thuyết được xây dựng trên cơ sở kế thừa tinh hoa tư tưởng nhân loại và thực tiễn cách mạng."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương I, mục III.3 (chức năng phương pháp luận: ba cấp độ, phương pháp luận chung nhất); chưa tìm thấy câu gốc nguyên văn của đề","c":1,"v":"dễ nhầm","k":"Giáo trình không có câu nguyên văn này; việc C là «chưa chuẩn xác» suy ra từ sự tuyệt đối hóa chữ «mọi». Một số ngân hàng trắc nghiệm trên mạng cũng cho đáp án tương tự nhưng chưa tìm được nguồn chính thức xác nhận."},{"q":"Trong chỉ đạo thực tiễn cần căn cứ vào đâu để đề ra chủ trương, phương hướng hành động?","o":["Cái tất nhiên, bản chất, nội dung.","Cái ngẫu nhiên, hình thức, hiện tượng","Các phương án trả lời đều sai"],"a":[0],"e":"Giáo trình rút ra kết luận phương pháp luận: cái tất nhiên gắn với bản chất của sự vật, cái nhất định xảy ra theo quy luật nội tại, còn cái ngẫu nhiên có thể xảy ra, có thể không; do đó trong hoạt động thực tiễn phải dựa vào cái tất nhiên, không thể dựa vào cái ngẫu nhiên (nhưng cũng không bỏ qua hoàn toàn cái ngẫu nhiên). ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Cái ngẫu nhiên, hình thức, hiện tượng không ổn định, không phản ánh quy luật nội tại nên không thể làm căn cứ chính để đề ra chủ trương; chỉ cần lưu ý để có phương án dự phòng.","Vì phương án A đúng nên «các phương án đều sai» là sai."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VII, mục IV.3 (kết luận phương pháp luận về tất nhiên và ngẫu nhiên); vế «bản chất, nội dung» suy rộng từ các cặp phạm trù liên quan","c":2,"v":"khớp","f":1},{"q":"Trong tác phẩm kinh điển nào sau đây, tác phẩm nào thể hiện tập trung việc V.I. Lênin đã kế thừa và phát triển quan niệm của chủ nghĩa Mác về vật chất, về mối quan hệ giữa vật chất và ý thức, tồn tại xã hội và ý thức xã hội:","o":["Làm gì.","Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán.","Ba nguồn gốc và ba bộ phận cấu thành chủ nghĩa Mác.","Bút ký triết học."],"a":[1],"e":"Trong «Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán» (1909), Lênin phê phán chủ nghĩa Makhơ đồng thời bổ sung, phát triển chủ nghĩa duy vật biện chứng và duy vật lịch sử, trong đó có định nghĩa vật chất và nhiều vấn đề căn bản của nhận thức luận mácxít. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["«Làm gì?» (1902) bàn về xây dựng đảng, không phải tác phẩm tập trung phát triển quan niệm về vật chất.","","«Ba nguồn gốc và ba bộ phận cấu thành chủ nghĩa Mác» khái quát chủ nghĩa Mác, không phải nơi tập trung phát triển quan niệm về vật chất và quan hệ vật chất - ý thức.","«Bút ký triết học» là các ghi chép, nhận xét của Lênin chủ yếu về phép biện chứng, không phải tác phẩm tập trung bàn về vật chất."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương III, phần về V.I. Lênin (chưa đối chiếu số mục); bản 2021: Chương I, mục II.1","c":2,"v":"khớp"},{"q":"Nội dung mặt thứ nhất của vấn đề cơ bản của triết học là:","o":["Quan hệ giữa vật chất với ý thức.","Quan hệ giữa ý thức với vật chất.","Khả năng nhận thức thế giới của con người.","Bản chất của thế giới là vật chất hay ý thức."],"a":[3],"e":"Mặt thứ nhất của vấn đề cơ bản của triết học (mặt bản thể luận) trả lời câu hỏi giữa ý thức và vật chất thì cái nào có trước, cái nào có sau, cái nào quyết định cái nào; tức là bản chất của thế giới là vật chất hay ý thức. Cách giải quyết mặt này chia các nhà triết học thành hai trường phái lớn: duy vật và duy tâm. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Chỉ nêu tên quan hệ vật chất - ý thức nói chung, chưa nêu nội dung mặt thứ nhất (cái nào có trước, quyết định cái nào).","Tương tự A, đảo thứ tự chữ nhưng vẫn chưa nêu nội dung của mặt thứ nhất.","Khả năng nhận thức thế giới của con người là mặt thứ hai (nhận thức luận).",""],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương I, mục I.2 (vấn đề cơ bản của triết học)","c":1,"v":"khớp","k":"A, B và D cùng gần nghĩa; đề chọn D vì đó là cách diễn đạt «bản chất của thế giới là vật chất hay ý thức»."},{"q":"Theo Ph. Ăngghen, chia vận động thành:","o":["Bốn hình thức vận động cơ bản","Năm hình thức vận động cơ bản","Sáu hình thức vận động cơ bản","Ba hình thức vận động cơ bản"],"a":[1],"e":"Ph. Ăngghen chia vận động của vật chất thành năm hình thức cơ bản: vận động cơ học, vật lý, hóa học, sinh học và xã hội. Các hình thức cao xuất hiện trên cơ sở các hình thức thấp và bao hàm chúng; mọi sự quy giản hình thức vận động thấp đều sai lầm. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Bốn là thiếu một hình thức (giáo trình nêu đủ 5, có cả vận động xã hội).","","Sáu là thừa một hình thức so với phân loại của Ăngghen.","Ba là thiếu hai hình thức."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương V, mục I.3.a (vận động)","c":2,"v":"khớp"},{"q":"Phương thức sản xuất bao gồm:","o":["Lực lượng sản xuất và quan hệ sản xuất.","Lực lượng sản xuất, quan hệ sản xuất, cơ sở hạ tầng.","Lực lượng sản xuất, quan hệ sản xuất, cơ sở hạ tầng, kiến trúc thượng tầng"],"a":[0],"e":"Giáo trình: phương thức sản xuất chính là sự thống nhất giữa lực lượng sản xuất ở một trình độ nhất định và quan hệ sản xuất tương ứng. Cơ sở hạ tầng và kiến trúc thượng tầng là cặp phạm trù khác, thuộc cấu trúc của hình thái kinh tế - xã hội. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Cơ sở hạ tầng là tổng hợp các quan hệ sản xuất hợp thành cơ cấu kinh tế, không phải một thành phần ngang hàng của phương thức sản xuất.","Thêm cả cơ sở hạ tầng và kiến trúc thượng tầng là nhầm phương thức sản xuất với toàn bộ hình thái kinh tế - xã hội."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương X, mục II.1.a (khái niệm phương thức sản xuất)","c":3,"v":"khớp"},{"q":"Ý nghĩa định nghĩa vật chất của Lênin được thể hiện:","o":["Khẳng định tính thứ nhất của vật chất.","Cho phép xác định cái gì là vật chất trong lĩnh vực xã hội.","Các phương án trả lời đều đúng."],"a":[2],"e":"Giáo trình nêu các ý nghĩa của định nghĩa vật chất của Lênin: khẳng định vật chất là tính thứ nhất, bác bỏ chủ nghĩa duy tâm và thuyết không thể biết, khắc phục hạn chế của chủ nghĩa duy vật trước Mác, định hướng cho khoa học cụ thể, và cho phép xác định cái gì là vật chất trong lĩnh vực xã hội. Vì vậy cả hai ý A và B đều đúng. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đúng nhưng chưa đầy đủ: còn ý nghĩa xác định vật chất trong xã hội (B); chọn C là bao quát nhất.","Đúng nhưng chưa đầy đủ: còn ý nghĩa khẳng định tính thứ nhất của vật chất (A); chọn C là bao quát nhất.",""],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương V, mục I.2.c (quan điểm của chủ nghĩa duy vật biện chứng về vật chất)","c":2,"v":"khớp","f":1},{"q":"Chân lý có những tính chất gì?","o":["Tính khách quan, tính tuyệt đối, tính tương đối, tính hoàn chỉnh","Tính khách quan, tính tuyệt đối, tính tương đối, tính cụ thể","Tính khách quan, tính tuyệt đối, tính tương đối, tính phổ biến"],"a":[1],"e":"Giáo trình viết: chân lý có tính khách quan, tính tương đối, tính tuyệt đối và tính cụ thể; thiếu một trong các tính chất đó thì tri thức không có giá trị đối với đời sống con người. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["«Hoàn chỉnh» không phải tính chất của chân lý; chân lý còn phát triển nên không nói là hoàn chỉnh.","","«Phổ biến» không nằm trong bốn tính chất giáo trình nêu (thay vào đó là tính cụ thể)."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương IX, mục «Vấn đề chân lý» - Các tính chất của chân lý (đánh số mục III.2 trong bản PDF)","c":2,"v":"khớp"},{"q":"Tư tưởng nôn nóng, đốt cháy giai đoạn phản ánh trực tiếp việc:","o":["Không vận dụng quy luật phủ định của phủ định","Không vận dụng đúng quy luật thống nhất và đấu tranh của các mặt đối lập","Không vận dụng đúng quy luật từ những thay đổi về lượng dẫn đến những thay đổi về chất và ngược lại"],"a":[2],"e":"Giáo trình rút ra từ quy luật lượng - chất: phải biết từng bước tích lũy về lượng để làm biến đổi về chất, nhờ đó tránh tư tưởng chủ quan, duy ý chí, nôn nóng, «đốt cháy giai đoạn» muốn thực hiện những bước nhảy liên tục. Do đó nó phản ánh việc không vận dụng đúng quy luật lượng - chất. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Quy luật phủ định của phủ định nói về khuynh hướng phát triển (xoáy ốc, kế thừa), không phải việc bỏ qua tích lũy lượng.","Quy luật thống nhất và đấu tranh của các mặt đối lập nói về nguồn gốc, động lực của vận động, phát triển.",""],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VIII, mục II.3 (ý nghĩa phương pháp luận quy luật lượng - chất)","c":2,"v":"khớp"},{"q":"Thực tiễn là:","o":["Hoạt động vật chất có mục đích mang tính lịch sử-xã hội của con người","Hoạt động tinh thần nhằm tạo ra các giá trị thẩm mỹ","Một số hoạt động vật chất và một số hoạt động tinh thần"],"a":[0],"e":"Thực tiễn là toàn bộ những hoạt động vật chất có mục đích, mang tính lịch sử - xã hội của con người nhằm cải biến tự nhiên và xã hội; có ba hình thức cơ bản: sản xuất vật chất, chính trị - xã hội và thực nghiệm khoa học. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Hoạt động tinh thần không phải thực tiễn; giáo trình phê phán chủ nghĩa duy tâm chỉ hiểu thực tiễn là hoạt động tinh thần sáng tạo.","Thực tiễn là hoạt động vật chất, không bao gồm «một số hoạt động tinh thần»."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương IX, mục I.2.a (phạm trù thực tiễn)","c":2,"v":"khớp"},{"q":"Những hình thức nhận thức: Khái niệm, phán đoán, suy luận thuộc giai đoạn nhận thức nào?","o":["Nhận thức cảm tính","Nhận thức lý tính","Nhận thức thông thường","Nhận thức khoa học"],"a":[1],"e":"Giáo trình: nhận thức lý tính là giai đoạn phản ánh gián tiếp, trừu tượng và khái quát những thuộc tính bản chất; nó có ba hình thức là khái niệm, phán đoán và suy luận. Còn nhận thức cảm tính (trực quan sinh động) gồm cảm giác, tri giác, biểu tượng. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Nhận thức cảm tính (trực quan sinh động) gồm cảm giác, tri giác, biểu tượng.","","Nhận thức thông thường là cấp độ nhận thức khác (thông thường - khoa học), phân loại theo tiêu chí khác.","Nhận thức khoa học cũng là cấp độ khác, không phải tên giai đoạn gồm khái niệm, phán đoán, suy luận."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương IX, mục «Quá trình nhận thức», phần b) Tư duy trừu tượng (chưa chắc số mục vì PDF đánh số lệch)","c":2,"v":"khớp"},{"q":"Theo quan điểm của triết học Mác-Lênin, tiêu chuẩn của chân lý là gì?","o":["Tri thức do các thế hệ trước để lại","Tri thức được nhiều người công nhận","Thực tiễn","Lời nói của các vĩ nhân"],"a":[2],"e":"Giáo trình khẳng định thực tiễn không chỉ là cơ sở, động lực, mục đích của nhận thức mà còn đóng vai trò là tiêu chuẩn để kiểm tra chân lý, là thước đo giá trị của những tri thức đã đạt được; C. Mác cũng coi việc tư duy đạt chân lý khách quan hay không là vấn đề thực tiễn. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Tri thức của thế hệ trước cũng phải được thực tiễn kiểm nghiệm lại, không tự nó là tiêu chuẩn.","Số đông công nhận không bảo đảm đúng; tiêu chuẩn là thực tiễn.","","Lời của vĩ nhân cũng cần được thực tiễn kiểm nghiệm."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương IX, mục I.2.b (vai trò của thực tiễn đối với nhận thức)","c":2,"v":"khớp"},{"q":"V.l. Lenin khẳng định: Chủ nghĩa Mác dựa vào... chứ không phải dựa vào... để vạch ra đương lối chính trị của mình.","o":["Khả năng/ Hiện thực.","Hiện thực/ Ngẫu nhiên.","Hiện thực/ Khả năng.","Tất yếu/ Ngẫu nhiên."],"a":[2],"e":"Giáo trình rút ra: hiện thực là cái tồn tại thực sự, còn khả năng là cái hiện chưa có, nên trong thực tiễn cần dựa vào hiện thực để định ra chủ trương, phương hướng hành động; chỉ dựa vào khả năng sẽ dễ rơi vào ảo tưởng. Theo Lênin, người mácxít chỉ có thể dùng làm căn cứ cho chính sách của mình những sự thật được chứng minh rõ rệt, không thể chối cãi. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đảo ngược vị trí: chủ nghĩa Mác không dựa vào khả năng (cái chưa có) làm căn cứ.","Ngẫu nhiên không phải là cặp đối lập với hiện thực trong luận điểm này.","","«Tất yếu/ngẫu nhiên» là cặp phạm trù khác, không phải cặp trong câu của Lênin."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VII, mục VII.3 (khả năng và hiện thực)","c":2,"v":"khớp","k":"Chưa đối chiếu được nguyên văn câu trích của Lênin trong Toàn tập; chỉ đối chiếu ý với giáo trình."},{"q":"V.I.Lênin cho rằng: nhận thức đi từ...đến..., từ bản chất ít sâu sắc đến bản chất sâu sắc hơn.","o":["Hình thức/ nội dung","Nội dung/ hình thức","Bản chất/ hiện tượng","Hiện tượng/ bản chất"],"a":[3],"e":"Giáo trình nêu nhận thức bản chất của sự vật là quá trình phức tạp đi từ hiện tượng đến bản chất, từ bản chất ít sâu sắc đến bản chất sâu sắc hơn (theo ý Lênin); bản chất sâu sắc hơn hiện tượng, hiện tượng phong phú hơn bản chất. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Hình thức/nội dung là cặp phạm trù khác, không phải chiều đi của nhận thức trong luận điểm này.","Tương tự A, sai cặp phạm trù.","Đảo chiều: nhận thức không đi từ bản chất đến hiện tượng mà từ hiện tượng đến bản chất.",""],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VII, mục VI.2 (bản chất và hiện tượng)","c":2,"v":"khớp"},{"q":"\"Bản chất chỉ là tên gọi trống rỗng mà con người tưởng tượng ra, nó không tồn tại trên thực tế\". Đây là quan niệm của trường phái triết học nào?","o":["Duy tâm khách quan","Bất khả vi","Duy vật biện chứng","Duy tâm chủ quan"],"a":[3],"e":"Theo giáo trình, trong lịch sử triết học phái duy danh coi phạm trù chỉ là những từ trống rỗng do con người tưởng tượng ra, không biểu hiện cái gì của hiện thực; còn chủ nghĩa duy vật biện chứng cho rằng nội dung của phạm trù mang tính khách quan. Ngân hàng trắc nghiệm trên mạng chọn đáp án D (duy tâm chủ quan) cho câu này. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf); [doctailieu.com](https://doctailieu.com/trac-nghiem/ban-chat-chi-la-ten-goi-trong-rong-ma-con-nguoi-tuong-tuong-ra-no-khong-ton-tai-28370))","w":["Duy tâm khách quan thừa nhận có ý niệm tồn tại khách quan, không nói bản chất chỉ là tên gọi con người tưởng tượng.","«Bất khả vi» không phải tên trường phái triết học; có thể là lỗi chép của đề.","Duy vật biện chứng thừa nhận bản chất tồn tại khách quan.",""],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VII, mục I.2 (bản chất của phạm trù: phái duy danh) và mục VI","c":2,"v":"nghi vấn","k":"nghi vấn: Nội dung câu nói khớp với mô tả phái duy danh trong giáo trình hơn là duy tâm chủ quan; phương án B của đề («Bất khả vi») có vẻ là lỗi chép của một phương án khác. Bộ trắc nghiệm đang lưu hành vẫn chọn D nên cứ nhớ D theo đề nhưng cần biết đây là chỗ đáng ngờ."},{"q":"Trong quá trình vận động, phát triển của sự vật,... giữ vai trò quyết định...","o":["Hình thức/Nội dung","Nội dung/Hình thức","Hiện tượng/Bản chất","Ngẫu nhiên/Tất nhiên"],"a":[1],"e":"Giáo trình: nội dung giữ vai trò quyết định đối với hình thức trong quá trình vận động, phát triển của sự vật, vì khuynh hướng chủ đạo của nội dung là biến đổi, còn hình thức tương đối bền vững, biến đổi chậm hơn; hình thức lạc hậu sẽ kìm hãm nội dung rồi phải thay đổi cho phù hợp. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đảo vai trò: hình thức không quyết định nội dung, nhưng có tác động trở lại (thúc đẩy hoặc kìm hãm).","","Hiện tượng/bản chất là cặp phạm trù khác, không phải quan hệ quyết định trong cặp nội dung - hình thức.","Ngẫu nhiên/tất nhiên là cặp khác; ngẫu nhiên không quyết định xu hướng phát triển."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VII, mục V.2.b (nội dung quyết định hình thức)","c":2,"v":"khớp"},{"q":"Trong các cụm từ dưới đây, cụm từ nào được xem là \"hình thức\" trong cặp phạm trù \"nội dung - hình thức\" mà phép biện chứng duy vật nghiên cứu: \" truyện kiều là...\"","o":["Tác phẩm của Nguyễn Du","Tác phẩm thơ lục bát","Tác phẩm có bìa màu xanh","Tác phẩm ra đời vào thế kỷ XVIII"],"a":[1],"e":"Giáo trình chỉ rõ phép biện chứng duy vật chủ yếu nói đến hình thức bên trong gắn liền với nội dung (cơ cấu của nội dung), chẳng hạn hình thức của tác phẩm văn học là thể loại, phương pháp kết cấu, nghệ thuật xây dựng hình tượng. Vì vậy «tác phẩm thơ lục bát» là hình thức của Truyện Kiều. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Tác giả là thông tin về nguồn gốc, không phải cơ cấu bên trong của tác phẩm.","","Màu bìa là hình thức bề ngoài (khổ sách, kiểu chữ...), phép biện chứng duy vật không chủ yếu nói đến loại hình thức này.","Thời điểm ra đời là thông tin lịch sử, không phải hình thức bên trong của nội dung."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VII, mục V.1 (khái niệm nội dung và hình thức)","c":2,"v":"dễ nhầm","k":"Dễ chọn C vì «bìa màu xanh» cũng là hình thức, nhưng là hình thức bề ngoài; giáo trình nhấn mạnh hình thức bên trong."},{"q":"C.Mác và Ph.Ăngghen cho rằng: Cái mà người ta quả quyết cho là...thì lại hoàn toàn do những cái...cấu thành và cái được coi là...lại là hình thức trong đó ẩn nấp...","o":["Tất yếu/ Ngẫu nhiên; Ngẫu nhiên/ Tất yếu.","Ngẫu nhiên/ Tất yếu; Tất yếu/ Ngẫu nhiên","Tất yếu/ Ngẫu nhiên; Tất yếu/ Ngẫu nhiên.","Ngẫu nhiên/ Tất yếu; Ngẫu nhiên/ Tất yếu"],"a":[0],"e":"Ăngghen (trích trong các tuyển tập của Mác - Ăngghen) viết: cái người ta quả quyết là tất yếu thì lại hoàn toàn do những cái ngẫu nhiên cấu thành, và cái được coi là ngẫu nhiên lại là hình thức trong đó ẩn nấp cái tất yếu. Phù hợp giáo trình: cái tất nhiên bao giờ cũng bộc lộ qua vô số cái ngẫu nhiên, cái ngẫu nhiên là hình thức biểu hiện của cái tất nhiên. ([Wikipedia: Quan hệ giữa tất nhiên và ngẫu nhiên](https://vi.wikipedia.org/wiki/Quan_h%E1%BB%87_gi%E1%BB%AFa_t%E1%BA%A5t_nhi%C3%AAn_v%C3%A0_ng%E1%BA%ABu_nhi%C3%AAn); [GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Đảo cặp: không phải cái ngẫu nhiên do cái tất yếu cấu thành; ý trích là ngược lại.","Lặp một cặp ở cả hai vế (tất yếu/ngẫu nhiên) làm mất tính tương phản của câu.","Lặp một cặp ở cả hai vế (ngẫu nhiên/tất yếu) làm mất tính tương phản của câu."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VII, mục IV.2.b; trích dẫn theo Mác - Ăngghen Tuyển tập, t.II (bản của NXB Sự thật 1971, tr.473, theo trang Wikipedia nói trên)","c":2,"v":"khớp","k":"Chưa xác định được tên tác phẩm gốc của câu trích, chỉ có nguồn trích từ tuyển tập."},{"q":"\"Đói nghèo\" và \"dốt nát\", hiện tượng nào là nguyên nhân, hiện tượng nào là kết quả?","o":["Đói nghèo là nguyên nhân, dốt nát là kết quả.","Dốt nát là nguyên nhân, đói nghèo là kết quả.","Cả hai đều là nguyên nhân.","Hiện tượng này vừa là nguyên nhân vừa là kết quả của hiện tượng kia."],"a":[3],"e":"Giáo trình lấy đúng ví dụ này: trình độ dân trí thấp do kinh tế kém phát triển, ít đầu tư cho giáo dục; nhưng dân trí thấp lại kìm hãm áp dụng khoa học kỹ thuật, làm kinh tế kém phát triển. Nguyên nhân và kết quả có thể thay đổi vị trí cho nhau, tác động qua lại. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Chỉ đúng một chiều; dốt nát cũng quay lại làm đói nghèo thêm.","Chỉ đúng một chiều; nghèo cũng làm thiếu điều kiện học hành gây dốt nát.","Bỏ qua việc mỗi hiện tượng cũng là kết quả của hiện tượng kia.",""],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VII, mục III.2.b (nguyên nhân và kết quả đổi vị trí cho nhau)","c":2,"v":"khớp"},{"q":"Trong các cặp khái niệm dưới đây, cặp nào có quan hệ nhân quả?","o":["Đông - Tây","Nghèo - Dốt","Xuân - Hạ","Ngày - Đêm"],"a":[1],"e":"Giáo trình phân biệt quan hệ nhân quả với quan hệ kế tiếp về thời gian: nguyên nhân và kết quả phải có quan hệ sản sinh ra nhau, còn ngày kế tiếp đêm hay mùa hè kế tiếp mùa xuân thì không phải nhân quả. Nghèo và dốt là cặp có quan hệ tác động qua lại, sản sinh nhau. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đông - Tây là cặp chỉ phương hướng, không sản sinh nhau.","","Xuân - Hạ chỉ kế tiếp về thời gian; giáo trình nêu rõ mùa xuân không là nguyên nhân của mùa hè.","Ngày - Đêm chỉ kế tiếp nhau; giáo trình nêu ngày đêm do trái đất quay quanh trục, không phải nhân quả."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VII, mục III.2 (quan hệ biện chứng nhân - quả)","c":2,"v":"khớp"},{"q":"Sai lầm của các nhà triết học cổ đại trong quan niệm về vật chất?","o":["Đồng nhất vật chất với một số dạng vật thể cụ thể, cảm tính.","Vật chất là tất cả cái tồn tại khách quan.","Vật chất là có thể nhận thức được.","Vật chất tự thân vận động."],"a":[0],"e":"Giáo trình: thời cổ đại các nhà triết học duy vật đã đồng nhất vật chất nói chung với những dạng cụ thể của nó, tức là những vật thể hữu hình, cảm tính đang tồn tại ở thế giới bên ngoài. Đây là hạn chế so với quan niệm của Lênin về vật chất. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Là quan điểm đúng, thuộc định nghĩa vật chất của Lênin (tồn tại khách quan).","Là nhận định đúng của chủ nghĩa duy vật biện chứng (con người nhận thức được thế giới), không phải sai lầm của triết học cổ đại.","Vật chất tự thân vận động là quan điểm đúng của triết học Mác - Lênin."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương V, mục I.2.a (lược khảo quan điểm trước Mác về vật chất)","c":2,"v":"khớp"},{"q":"Khái niệm trung tâm mà V.I. Lênin sử dụng để định nghĩa về vật chất là?","o":["Phạm trù triết học.","Thực tại khách quan.","Cảm giác.","Phản ánh."],"a":[1],"e":"Lênin định nghĩa: vật chất là một phạm trù triết học dùng để chỉ thực tại khách quan được đem lại cho con người trong cảm giác, được cảm giác chép lại, chụp lại, phản ánh và tồn tại không lệ thuộc vào cảm giác. Khái niệm trung tâm là «thực tại khách quan». ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["«Phạm trù triết học» là loại khái niệm dùng để định nghĩa, không phải khái niệm trung tâm phản ánh nội dung.","","Cảm giác là cái phản ánh vật chất, vật chất tồn tại không lệ thuộc vào cảm giác.","Phản ánh là thuộc tính, cách thức vật chất được ý thức nắm bắt, không phải khái niệm trung tâm."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương V, mục I.2.c; V.I. Lênin, Toàn tập, t.18 (theo giáo trình)","c":2,"v":"khớp"},{"q":"\"Tất cả cái gì đang vận động, đều vận động nhờ một cái khác nào đó\". Nhận định này gắn liền với hệ thống triết học nào? Hãy chọn phương án sai?","o":["Triết học duy vật.","Triết học duy tâm.","Triết học duy tâm khách quan.","Triết học duy tâm chủ quan."],"a":[0],"e":"Quan điểm «mọi cái vận động đều nhờ một cái khác» đặt nguồn gốc vận động ở bên ngoài vật chất, nên gắn với chủ nghĩa duy tâm (cả khách quan lẫn chủ quan); giáo trình cũng nêu chủ nghĩa duy vật siêu hình cận đại từng coi nguồn gốc vận động nằm ngoài vật chất, trong khi triết học Mác - Lênin coi vận động là sự tự thân vận động của vật chất. Đề hỏi phương án sai nên chọn A (triết học duy vật). ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Không sai: nhận định này gắn với triết học duy tâm.","Không sai: duy tâm khách quan viện đến một lực lượng tinh thần bên ngoài làm nguồn gốc vận động.","Không sai: duy tâm chủ quan cũng gắn với nhận định này."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương V, mục I.2.a và I.3.a (tự thân vận động)","c":2,"v":"dễ nhầm","k":"Giáo trình cho thấy duy vật siêu hình cận đại cũng từng coi nguồn gốc vận động ở ngoài vật chất, nên «gắn với duy vật» không sai tuyệt đối; đề chọn A theo nghĩa duy vật biện chứng. Chưa tìm được nguồn gốc câu trích."},{"q":"Phép biện chứng của triết học Hêghen là:","o":["Phép biện chứng duy tâm chủ quan.","Phép biện chứng duy vật hiện đại.","Phép biện chứng ngây thơ, chất phác.","Phép biện chứng duy tâm khách quan."],"a":[3],"e":"Giáo trình: Hêghen là nhà biện chứng đồng thời là nhà triết học duy tâm khách quan; ông cho khởi nguyên của thế giới là «ý niệm tuyệt đối» hay «tinh thần thế giới», nên phép biện chứng của ông là phép biện chứng duy tâm khách quan. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Duy tâm chủ quan gắn với Béccli, không phải Hêghen.","Phép biện chứng duy vật là của Mác - Ăngghen, kế thừa hạt nhân hợp lý của Hêghen.","Phép biện chứng ngây thơ, chất phác là hình thức biện chứng thời cổ đại.",""],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương II (triết học cổ điển Đức - Hêghen; chưa đối chiếu số mục); Chương I, mục III.2 (ba hình thức phép biện chứng)","c":1,"v":"khớp"},{"q":"Chọn luận điểm thể hiện lập trường triết học duy tâm lịch sử:","o":["Quan hệ sản xuất mang tính vật chất.","Yếu tố kinh tế quyết định lịch sử.","Sự vận động và phát triển của xã hội, suy cho cùng là do tư tưởng của con người quyết định.","Kiến trúc thương tầng chỉ đóng vai trò thụ động trong lịch sử."],"a":[2],"e":"Duy tâm lịch sử cho rằng yếu tố tinh thần, tư tưởng quyết định sự vận động, phát triển của xã hội; còn chủ nghĩa duy vật lịch sử khẳng định tồn tại xã hội quyết định ý thức xã hội, trong khi ý thức xã hội có tính độc lập tương đối và tác động trở lại. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Quan hệ sản xuất mang tính vật chất là quan điểm duy vật lịch sử.","Yếu tố kinh tế quyết định lịch sử là quan điểm duy vật lịch sử.","","Kiến trúc thượng tầng có tác động trở lại cơ sở hạ tầng nên không chỉ thụ động; câu D đánh giá thấp vai trò này nhưng vẫn không phải lập trường duy tâm."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương XIII, mục I (tồn tại xã hội quyết định ý thức xã hội) và Chương X, mục III.2","c":3,"v":"khớp"},{"q":"Triết học trong xã hội có giai cấp được hiểu như thế nào?","o":["Cũng có tính giai cấp","Không có tính giai cấp","Chỉ triết học phương Tây mới có tính giai cấp","Chỉ có triết học phương Đông mới có tính giai cấp"],"a":[0],"e":"Giáo trình chỉ ra trong xã hội có giai cấp, các giai cấp thống trị và lực lượng xã hội phản động ủng hộ, sử dụng chủ nghĩa duy tâm làm nền tảng lý luận cho quan điểm chính trị - xã hội của mình, tức triết học gắn với lợi ích giai cấp nhất định. Vì vậy triết học trong xã hội có giai cấp cũng có tính giai cấp. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Phủ nhận hoàn toàn tính giai cấp của triết học là sai.","Không chỉ triết học phương Tây có tính giai cấp; đây là đặc điểm chung của triết học trong xã hội có giai cấp.","Không chỉ triết học phương Đông có tính giai cấp; sai vì giới hạn tính giai cấp vào một khu vực."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương I, mục II.2 (chủ nghĩa duy vật, duy tâm và nguồn gốc xã hội); chưa tìm thấy câu kết luận nguyên văn","c":1,"v":"khớp","id":"h0e0cu"},{"q":"Động lực của cách mạng xã hội là","o":["Giai cấp chân chính","Giai cấp tiến tiến","Giai cấp chiếm số đông"],"a":[1],"e":"Giáo trình: động lực của cách mạng xã hội là những giai cấp có lợi ích gắn bó chặt chẽ và lâu dài với cách mạng; vai trò lãnh đạo thuộc về giai cấp đại biểu cho phương thức sản xuất mới, tiến bộ nhất trong số các giai cấp đang tồn tại. Vì vậy chọn «giai cấp tiên tiến». ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["«Giai cấp chân chính» không phải thuật ngữ của giáo trình.","","Số đông chưa chắc có vai trò lãnh đạo; vai trò đó thuộc giai cấp tiến bộ nhất, đại biểu phương thức sản xuất mới."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương XII, mục II.d (tính chất, lực lượng và động lực của cách mạng xã hội)","c":3,"v":"dễ nhầm","k":"Câu chữ giáo trình về «động lực» là các giai cấp có lợi ích gắn bó lâu dài với cách mạng; «giai cấp tiên tiến» sát với vai trò lãnh đạo. Đề chọn B."},{"q":"Trong thực tế chúng ta phải dựa vào khả năng hay hiện thực","o":["Khả năng","Hiện thực","Các phương án trả lời đều sai"],"a":[1],"e":"Giáo trình: hiện thực là cái tồn tại thực sự, khả năng là cái hiện chưa có, nên trong hoạt động thực tiễn cần dựa vào hiện thực để định ra chủ trương, phương hướng hành động; chỉ dựa vào khả năng dễ rơi vào ảo tưởng, nhưng vẫn phải tính đến khả năng. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Khả năng là cái chưa tồn tại thực sự nên không phải căn cứ chính, tuy cần tính đến khi lập kế hoạch.","","Vì B đúng nên «các phương án đều sai» là sai."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VII, mục VII.3 (khả năng và hiện thực)","c":2,"v":"khớp","f":1},{"q":"Đặc điểm lớn nhất của thời kỳ quá độ lên chủ nghĩa xã hội ở nước ta là","o":["Có nhiều thành phần kinh tế đan xen nhau","Từ một nền sản xuất nhỏ là phổ biến quá độ lên chủ nghĩa xã hội không qua chế độ tư bản chủ nghĩa","Năng suất lao động thấp"],"a":[1],"e":"Đặc điểm lớn nhất của thời kỳ quá độ ở nước ta là tiến lên chủ nghĩa xã hội từ một nước nông nghiệp lạc hậu, nền sản xuất nhỏ là phổ biến, bỏ qua chế độ tư bản chủ nghĩa; do đó thời kỳ này lâu dài và rất khó khăn. Nhiều thành phần kinh tế và năng suất thấp chỉ là biểu hiện của xuất phát điểm đó. ([lyluanchinhtri.vn](https://lyluanchinhtri.vn/nhan-thuc-cua-dang-ta-ve-thoi-ky-qua-do-len-chu-nghia-xa-hoi-o-viet-nam-249.html))","w":["Nhiều thành phần kinh tế đan xen là đặc điểm kinh tế quan trọng nhưng chưa phải đặc điểm lớn nhất; nó là hệ quả của xuất phát điểm.","","Năng suất lao động thấp là hệ quả của nền sản xuất nhỏ, chưa nêu được đặc điểm lớn nhất (quá độ bỏ qua chế độ TBCN)."],"s":"Văn kiện Đảng (Cương lĩnh 1991, bổ sung 2011) và giáo trình Chủ nghĩa xã hội khoa học; chưa đối chiếu số chương, chưa mở trực tiếp văn bản Cương lĩnh","c":4,"v":"khớp","k":"Nguồn trực tuyến xác nhận ý nghĩa nhưng là bài viết lý luận, chưa trích được nguyên văn Cương lĩnh; nên đối chiếu thêm giáo trình CNXH khoa học."},{"q":"Kết cấu của tồn tại xã hội bao gồm?","o":["Phương thức sản xuất, điều kiện dân số, điều kiện tự nhiên địa lý","Phương thức sản xuất, phương thức tiêu dùng, phương thức trao đổi hàng hóa","Phương thức sản xuất, điều kiện dân số, cơ sở hạ tầng xã hội"],"a":[0],"e":"Giáo trình: các yếu tố chính tạo thành tồn tại xã hội là phương thức sản xuất vật chất, điều kiện tự nhiên - hoàn cảnh địa lý, dân số và mật độ dân số, trong đó phương thức sản xuất vật chất là yếu tố cơ bản nhất. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Phương thức tiêu dùng, phương thức trao đổi không phải yếu tố cấu thành tồn tại xã hội theo giáo trình.","Cơ sở hạ tầng xã hội không nằm trong ba yếu tố nêu; cơ sở hạ tầng là phạm trù khác của hình thái kinh tế - xã hội."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương XIII, mục I (tồn tại xã hội và ý thức xã hội); bản 2021: Chương III, mục IV.1","c":3,"v":"khớp"},{"q":"Thêm cụm từ thích hợp vào chỗ trống của câu sau để được luận điểm của chủ nghĩa duy vật biện chứng về tính chất của các phạm trù: Nội dung của phạm trù có tính ..(1) ..., hình thức của phạm trù có tính...(2)...","o":["1- chủ quan, 2- khách quan","1- chủ quan, 2- chủ quan.","1- khách quan, 2- chủ quan.","1- khách quan, 2- khách quan"],"a":[2],"e":"Giáo trình: các phạm trù được hình thành bằng khái quát hóa, trừu tượng hóa những thuộc tính, mối liên hệ vốn có của sự vật nên nội dung của phạm trù mang tính khách quan, bị thế giới khách quan quy định, mặc dù hình thức thể hiện của nó là chủ quan. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Ngược: nội dung chủ quan, hình thức khách quan là sai.","Nội dung phản ánh thế giới khách quan nên không thể chủ quan.","","Hình thức thể hiện của phạm trù là do con người tạo ra nên có tính chủ quan."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VII, mục I.2 (bản chất của phạm trù)","c":2,"v":"khớp"},{"q":"Vật chất với tư cách là phạm trù triết học đã có lịch sử phát triển khoảng bao nhiêu năm","o":["2500 năm","3000 năm","3500 năm","4000 năm"],"a":[0],"e":"Giáo trình ghi: vật chất với tư cách là phạm trù triết học đã có lịch sử khoảng 2.500 năm; ngay từ lúc mới ra đời xung quanh nó đã diễn ra cuộc đấu tranh giữa chủ nghĩa duy vật và chủ nghĩa duy tâm. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","3000 năm không đúng mốc giáo trình nêu.","3500 năm không đúng mốc giáo trình nêu.","4000 năm không đúng mốc giáo trình nêu."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương V, mục I.2.a","c":2,"v":"khớp"},{"q":"Khái niệm \"bước nhảy\"?","o":["Sự đột biến","Chuyển dần về chất","Hoàn thiện chất","Quá trình biến đổi về chất diễn ra tại điểm nút"],"a":[3],"e":"Giáo trình: bước nhảy là phạm trù triết học dùng để chỉ sự chuyển hóa về chất của sự vật do sự thay đổi về lượng trước đó gây nên; sự vật tích lũy đủ về lượng tại điểm nút sẽ tạo ra bước nhảy, chất mới ra đời. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Sự đột biến chỉ là một hình thức của bước nhảy, chưa nêu điều kiện điểm nút.","Chuyển dần về chất là thay đổi dần về lượng/tiến hóa, không phải bước nhảy.","«Hoàn thiện chất» không phải khái niệm của giáo trình.",""],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VIII, mục II.2 (quan hệ giữa thay đổi về lượng và về chất)","c":2,"v":"khớp"},{"q":"Cuộc cách mạng xã hội chủ nghĩa đầu tiên trên thế giới là","o":["Cách mạng tháng Tám","Cách mạng tháng Mười Nga","Cách mạng Tân Hợi"],"a":[1],"e":"Cách mạng Tháng Mười Nga (1917) do giai cấp công nhân lãnh đạo, lật đổ chính phủ tư sản và lập ra Nhà nước xô viết, được coi là cuộc cách mạng xã hội chủ nghĩa đầu tiên trong lịch sử; giáo trình cũng nêu chủ nghĩa xã hội hình thành, phát triển từ sau Cách mạng Tháng Mười Nga. ([UEL: Cách mạng Tháng Mười Nga](https://www.uel.edu.vn/cach-mang-thang-muoi-nga-cuoc-cach-mang-xa-hoi-chu-nghia-dau-tien-trong-lich-su); [GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Cách mạng tháng Tám (1945) là cách mạng giải phóng dân tộc ở Việt Nam, không phải cuộc cách mạng xã hội chủ nghĩa đầu tiên.","","Cách mạng Tân Hợi (1911) là cách mạng dân chủ tư sản ở Trung Quốc."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương X, mục IV.3 (câu nhắc tới CM Tháng Mười); chưa mở trực tiếp sách lịch sử","c":4,"v":"khớp"},{"q":"Lượng giá trị của đơn vị hàng hoá thay đổi","o":["Tỷ lệ nghịch với năng suất lao động, không phụ thuộc vào cường độ lao động.","Tỷ lệ thuận với năng suất lao động","Tỷ lệ nghịch với cường độ lao động"],"a":[0],"e":"Giáo trình Kinh tế chính trị Mác - Lênin: tăng năng suất lao động thì giá trị của một đơn vị hàng hóa giảm, tức tỷ lệ nghịch với năng suất lao động; còn tăng cường độ lao động thì số lượng hàng hóa và hao phí lao động cùng tăng nên giá trị một đơn vị hàng hóa vẫn không đổi. ([GT Kinh tế chính trị Mác-Lênin, Bộ GD&ĐT](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["","Tỷ lệ thuận với năng suất là sai; năng suất tăng thì giá trị một đơn vị hàng hóa giảm.","Cường độ lao động tăng không làm đổi giá trị một đơn vị hàng hóa (tổng giá trị cùng tăng với số sản phẩm)."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), mục «Lượng giá trị của hàng hóa và các yếu tố ảnh hưởng tới nó»; chưa đối chiếu số chương","c":4,"v":"khớp"},{"q":"Giá trị cá biệt của hàng hoá do","o":["Hao phí lao động cá biệt của người sản xuất quyết định","Hao phí lao động cá biệt của người sản xuất nhiều hàng hoá quyết định","Hao phí lao động của ngành quyết định"],"a":[0],"e":"Giáo trình Kinh tế chính trị nêu: những người sản xuất khác nhau có mức hao phí lao động cá biệt khác nhau, tạo giá trị cá biệt của hàng hóa; còn lượng giá trị (giá trị xã hội) do thời gian lao động xã hội cần thiết quyết định. ([GT Kinh tế chính trị Mác-Lênin, Bộ GD&ĐT](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["","Giá trị cá biệt không phụ thuộc số lượng hàng hóa mà người sản xuất làm ra mà do hao phí lao động cá biệt.","Hao phí lao động của ngành (hao phí xã hội cần thiết) quyết định giá trị xã hội chứ không phải giá trị cá biệt."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), mục «Thời gian lao động xã hội cần thiết»; chưa đối chiếu số chương","c":4,"v":"khớp","k":"Giáo trình dùng cụm «mức hao phí lao động cá biệt»; thuật ngữ «giá trị cá biệt» xuất hiện ở phần giá trị thặng dư siêu ngạch."},{"q":"Thuật ngữ giai cấp công nhân và giai cấp vô sản","o":["Đồng nghĩa","Khác nghĩa","Không liên quan về nghĩa"],"a":[0],"e":"Trong chủ nghĩa Mác, giai cấp công nhân (không có tư liệu sản xuất, bán sức lao động, bị bóc lột giá trị thặng dư) trong xã hội tư bản còn được gọi là giai cấp vô sản, nên hai thuật ngữ đồng nghĩa. ([loigiaihay.com](https://loigiaihay.com/giai-cap-cong-nhan-va-su-menh-lich-su-cua-giai-cap-cong-nhan-c126a20301.html))","w":["","Không khác nghĩa: Mác - Ăngghen dùng hai thuật ngữ cho cùng một giai cấp, chỉ nhấn mạnh các mặt khác nhau.","Hai thuật ngữ có liên quan chặt chẽ, cùng chỉ giai cấp đối kháng với giai cấp tư sản."],"s":"GT Chủ nghĩa xã hội khoa học (chưa đối chiếu số chương, chưa mở trực tiếp giáo trình); nguồn trực tuyến: loigiaihay.com","c":4,"v":"khớp","k":"Chỉ đối chiếu được qua trang tổng hợp bài giảng, chưa mở giáo trình CNXH khoa học."},{"q":"Biện chứng là phương pháp","o":["Thấy cái chung mà không thấy cái riêng","Thấy cái riêng mà không thấy cái chung","Vừa thấy cái chung và cái riêng","Vừa thấy cái chung, vừa thấy cái riêng và cái đơn nhất"],"a":[3],"e":"Giáo trình nêu quan hệ giữa cái riêng, cái chung và cái đơn nhất: cái riêng không tách rời cái chung, và bên cạnh những đặc điểm chung, cái riêng còn có cái đơn nhất; cái đơn nhất và cái chung có thể chuyển hóa cho nhau. Do đó phương pháp biện chứng nhìn thấy cả cái chung, cái riêng và cái đơn nhất. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Chỉ thấy cái chung là phiến diện, giống quan điểm phái duy thực.","Chỉ thấy cái riêng là phiến diện, giống phái duy danh.","Thiếu cái đơn nhất so với đề; đề chọn D là đầy đủ nhất.",""],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VII, mục II.2 (quan hệ biện chứng giữa cái riêng và cái chung)","c":2,"v":"dễ nhầm","k":"Giáo trình không có câu định nghĩa nguyên văn «biện chứng là phương pháp...»; C cũng có thể coi là đúng nhưng chưa đầy đủ, nên đề chọn D."},{"q":"Đặc điểm của quy luật triết học mang tính","o":["Chung nhất, khái quát nhất về thế giới","Cụ thể nhất, chi tiết nhất về thế giới","Toàn diện nhất, sâu sắc nhất về thế giới"],"a":[0],"e":"Giáo trình: các quy luật phổ biến tác động trong tất cả các lĩnh vực tự nhiên, xã hội và tư duy, và đó chính là những quy luật mà phép biện chứng duy vật nghiên cứu; trong khi quy luật riêng và quy luật chung có phạm vi hẹp hơn. Vì thế quy luật triết học mang tính chung nhất, khái quát nhất về thế giới. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Quy luật cụ thể, chi tiết thuộc các khoa học cụ thể (quy luật riêng, quy luật chung).","«Toàn diện nhất, sâu sắc nhất» không phải cách giáo trình đặc trưng quy luật triết học; đặc trưng là tính phổ biến."],"s":"GT Triết học Mác-Lênin (tái bản lần 3), Chương VIII, mục I.2 (phân loại quy luật)","c":1,"v":"khớp","k":"Giáo trình dùng chữ «quy luật phổ biến»; cụm «chung nhất, khái quát nhất» là cách diễn đạt của đề."},{"q":"Phân công lao động xã hội","o":["Là một trong những nguyên nhân hình thành chủ nghĩa tư bản độc quyền","Không dẫn đến sự hình thành tư bản độc quyền","Nguyên nhân hình thành chủ nghĩa tư bản","Là một trong những nguyên nhân hình thành chủ nghĩa tư bản độc quyền nhà nước"],"a":[0],"e":"Theo giáo trình Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), nguyên nhân chủ yếu hình thành tư bản độc quyền (Lênin) là: sự phát triển của lực lượng sản xuất dưới tác dụng của tiến bộ khoa học – kỹ thuật, cạnh tranh tự do dẫn tới tập trung sản xuất, khủng hoảng kinh tế và tín dụng. Còn «sự phát triển của phân công lao động xã hội» được giáo trình nêu là một nguyên nhân ra đời của chủ nghĩa tư bản độc quyền NHÀ NƯỚC (vì xuất hiện các ngành tư bản tư nhân không muốn/không thể kinh doanh). Đề cho đáp án A, nhưng theo giáo trình thì D khớp hơn. ([Giáo trình Kinh tế chính trị Mác-Lênin, Chương VII mục I.1 và II.1](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["","Sai: phân công lao động xã hội có liên quan đến sự hình thành các hình thức độc quyền (là nguyên nhân của độc quyền nhà nước), không phải «không dẫn đến».","Sai: chủ nghĩa tư bản hình thành từ tích lũy nguyên thủy tư bản và sản xuất hàng hóa phát triển, không phải do phân công lao động xã hội nói chung.","Theo giáo trình, đây mới là nguyên nhân được nêu rõ («sự phát triển của phân công lao động xã hội» là nguyên nhân thứ hai của CNTB độc quyền nhà nước); nếu phải theo đáp án của đề thì ghi nhớ A."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), Chương VII mục I.1.a và II.1.a (đã đối chiếu)","c":4,"v":"nghi vấn","k":"nghi vấn: Đáp án đề là A nhưng giáo trình KTCT liệt kê phân công lao động xã hội là nguyên nhân của CNTB độc quyền nhà nước (D); nguyên nhân của CNTB độc quyền gồm lực lượng sản xuất, cạnh tranh, khủng hoảng và tín dụng. Có thể đề lấy từ nguồn khác hoặc câu hỏi cụt ngữ cảnh."},{"q":"Triết học bao gồm những quan điểm chung nhất, những sự lý giải có luận chứng cho các câu hỏi chung của con người, nên triết học bao gồm toàn bộ tri thức của nhân loại Kết luận trên ứng với triết học thời kỳ nào? Chọn câu trả lời đúng.","o":["Triết học cổ đại","Triết học phục hưng","Triết học Trung cổ - Tây âu","Triết học Mác - Lênin"],"a":[0],"e":"Giáo trình nêu: ngay từ khi ra đời, triết học được xem là hình thái cao nhất của tri thức, bao hàm tri thức của tất cả các lĩnh vực, mãi về sau (từ thế kỷ XV–XVII) các ngành khoa học riêng mới dần tách ra; ở Hy Lạp cổ đại đó là «nền triết học tự nhiên». Vì vậy quan niệm triết học bao gồm toàn bộ tri thức nhân loại ứng với triết học cổ đại. ([Giáo trình Triết học Mác-Lênin 2021, phần Triết học và vấn đề cơ bản](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Sai: thời Phục hưng – cận đại (thế kỷ XV–XVII) là lúc các khoa học cụ thể bắt đầu tách khỏi triết học.","Sai: triết học Trung cổ Tây Âu là «nữ tì của thần học», thay triết học tự nhiên bằng triết học kinh viện, tập trung vào niềm tin tôn giáo.","Sai: triết học Mác – Lênin chấm dứt tham vọng coi triết học là «khoa học của các khoa học», chỉ nghiên cứu những quy luật chung nhất."],"s":"GT Triết học Mác-Lênin 2021, Chương 1 mục 1.3 (số mục theo bản PDF; chưa đối chiếu số chương chính xác); bản cũ cũng nêu Triết học Mác chấm dứt tham vọng «khoa học của các khoa học»","c":1,"v":"khớp"},{"q":"Thời gian chu chuyển của tư bản được hiểu.","o":["Thời gian sản xuất + thời gian bán hàng.","Thời gian sản xuất + thời gian lưu thông.","Thời gian dự trữ sản xuất + thời gian lưu thông.","Thời gian sản xuất + thời gian tiếp thị."],"a":[1],"e":"Thời gian tư bản thực hiện được một vòng tuần hoàn gọi là thời gian chu chuyển của tư bản, bao gồm thời gian sản xuất và thời gian lưu thông. ([Giáo trình Kinh tế chính trị Mác-Lênin, Chương V mục II.2.a](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["Sai: chỉ có thời gian bán hàng thì thiếu thời gian mua và toàn bộ thời gian sản xuất; thời gian bán chỉ là một phần của thời gian lưu thông.","","Sai: thời gian dự trữ sản xuất chỉ là một bộ phận của thời gian sản xuất, không thay cho toàn bộ thời gian sản xuất.","Sai: «tiếp thị» không phải thành phần trong định nghĩa; thời gian lưu thông gồm thời gian mua và thời gian bán hàng hóa."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), Chương V mục II.2.a (đã đối chiếu; số mục theo cấu trúc bản PDF)","c":4,"v":"khớp"},{"q":"Loại tái sản xuất nào làm tăng sản phẩm chủ yếu do tăng năng suất lao động và hiệu quả sử dụng các nguồn lực?","o":["Tái sản xuất mở rộng theo chiều rộng","Tái sản xuất mở rộng","Tái sản xuất mở rộng theo chiều sâu"],"a":[2],"e":"Tái sản xuất mở rộng theo chiều sâu là sự mở rộng quy mô sản xuất làm cho sản phẩm tăng lên chủ yếu nhờ tăng năng suất lao động và nâng cao hiệu quả sử dụng các yếu tố đầu vào; điều kiện chủ yếu là ứng dụng rộng rãi thành tựu khoa học – công nghệ tiên tiến. ([Giáo trình Kinh tế chính trị Mác-Lênin, Chương II mục I](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["Sai: theo chiều rộng là mở rộng chủ yếu bằng cách tăng thêm yếu tố đầu vào (vốn, tài nguyên, sức lao động), năng suất và hiệu quả không đổi.","Sai: «tái sản xuất mở rộng» là khái niệm chung, bao gồm cả hai hướng chiều rộng và chiều sâu, chưa chỉ rõ cách tăng sản phẩm.",""],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), Chương II mục I.2 (đã đối chiếu)","c":4,"v":"khớp","id":"1eh2bfv"},{"q":"Ph.Ăngghen cho rằng: đối với ai phủ nhận..thì mọi quy luật tự nhiên đều là giả thuyết.","o":["Vấn đề nội dung hình thức","Phạm trù khả năng - hiện thực","Tính nhận quà","Tính biện chứng"],"a":[2],"e":"Ph. Ăngghen coi tính nhân quả là cơ sở của quy luật: ai phủ nhận tính nhân quả thì mọi quy luật tự nhiên đều chỉ là giả thuyết. Giáo trình nhấn mạnh mối liên hệ nhân quả có tính khách quan, phổ biến và tất yếu, và trích Ăngghen: hoạt động của con người là «hòn đá thử vàng của tính nhân quả». Đáp án C («tính nhận quà») là lỗi chép của «tính nhân quả». ([Giáo trình Triết học Mác-Lênin 2021, phần Nguyên nhân và kết quả](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Sai: quan hệ nội dung – hình thức không phải điều kiện để quy luật tự nhiên khỏi là giả thuyết.","Sai: khả năng – hiện thực là cặp phạm trù khác, không phải căn cứ của tính quy luật trong câu trích.","","Sai: tính biện chứng nói chung không phải thứ mà nhân quả – quy luật dựa trên; câu trích nói về tính nhân quả."],"s":"GT Triết học Mác-Lênin 2021, mục Nguyên nhân – kết quả (chưa đối chiếu số chương); câu trích Ăngghen trong «Biện chứng của tự nhiên» chưa tra bản gốc","c":2,"v":"khớp","k":"Đề chép sai chính tả «nhận quà» thay cho «nhân quả»; nguyên văn câu của Ăngghen chưa tra bản gốc nên chỉ dùng ý chung."},{"q":"Khi nghiên cứu phương thức sản xuất TBCN, C.Mác bắt đầu từ","o":["Sản xuất hàng hoá giản đơn và hàng hoá","Lưu thông hàng hoá","Sản xuất giá trị thặng dư"],"a":[0],"e":"Khi nghiên cứu phương thức sản xuất tư bản chủ nghĩa, C. Mác bắt đầu từ hàng hóa, vì sản xuất tư bản chủ nghĩa trước hết là sản xuất hàng hóa đã phát triển cao, trong đó hàng hóa là «tế bào kinh tế của xã hội tư sản»; sản xuất hàng hóa và lưu thông hàng hóa phát triển là tiền đề lịch sử của tư bản. ([Giáo trình Kinh tế chính trị Mác-Lênin, Chương III mục I](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["","Sai: lưu thông hàng hóa chỉ là một tiền đề, không phải điểm xuất phát nghiên cứu «tế bào» của chủ nghĩa tư bản.","Sai: sản xuất giá trị thặng dư là nội dung nghiên cứu sau khi đã phân tích hàng hóa, tiền tệ, sự chuyển hóa tiền thành tư bản."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), Chương III mục I (đã đối chiếu)","c":4,"v":"khớp"},{"q":"Coi vận động của vật chất chỉ là biểu hiện của vận động cơ học, đó là quan điểm về vận động và vật chất của ai","o":["Các nhà triết học thời kỳ cổ đại","Các nhà triết học siêu hình","Các nhà triết học duy vật biện chứng hiện đại","Các nhà triết học duy vật thời kỳ cổ đại"],"a":[1],"e":"Giáo trình nêu: thế kỷ XVII–XVIII, quan điểm siêu hình – máy móc chi phối triết học về vật chất; niềm tin vào cơ học Niutơn khiến các nhà khoa học coi vận động của vật chất chỉ là biểu hiện của vận động cơ học. Đó là quan điểm của các nhà triết học siêu hình. ([Giáo trình Triết học Mác-Lênin (bản cũ), mục về vật chất](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Sai: triết học cổ đại nhìn vận động rộng, trực quan, chưa quy về cơ học Niutơn.","","Sai: chủ nghĩa duy vật biện chứng hiện đại khẳng định nhiều hình thức vận động khác nhau về chất, không quy về cơ học.","Sai: các nhà duy vật cổ đại chưa đồng nhất vận động với vận động cơ học; việc quy giản gắn với duy vật siêu hình thế kỷ XVII–XVIII."],"s":"GT Triết học Mác-Lênin (bản cũ), mục I Vật chất và các phương thức tồn tại của vật chất (chưa đối chiếu số chương)","c":2,"v":"khớp","id":"1r3y11t"},{"q":"Chon quan niệm đúng về con người theo quan điểm toàn diện của chủ nghĩa duy vật lịch sử. Con người là","o":["Thực thể vật chất tự nhiên","Thực thể chính trị và đạo đức","Thực thể chính trị, có tư duy và văn hóa","Thực thể tự nhiên và xã hội"],"a":[3],"e":"Con người là một thực thể tự nhiên – xã hội có ý thức, chủ thể sáng tạo ra lịch sử; quan điểm toàn diện của chủ nghĩa duy vật lịch sử thống nhất mặt tự nhiên (sinh học) và mặt xã hội. ([Giáo trình Triết học Mác-Lênin 2021, phần Con người](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Sai: chỉ nêu mặt tự nhiên, bỏ mặt xã hội nên phiến diện.","Sai: chính trị, đạo đức chỉ là một số khía cạnh xã hội, không bao quát và thiếu mặt tự nhiên.","Sai: thiếu mặt tự nhiên (sinh học) của con người.",""],"s":"GT Triết học Mác-Lênin 2021, phần Con người (chưa đối chiếu số chương)","c":3,"v":"khớp"},{"q":"Khẳng định nào sau đây là sai","o":["Triết học Mác là sự kết hợp phép biện chứng của Hêghen và chủ nghĩa duy tâm của Phoi - ơ - bắc","Triết học Mác có sự thống nhất giữa phương pháp biện chứng và thế giới quan duy vật","Triết học Mác kế thừa và cải tạo phép biện chứng của Hêghen trên cơ sở duy vật"],"a":[0],"e":"Nhận định A sai: giáo trình nói chủ nghĩa duy vật biện chứng không phải là sự «lắp ghép» phép biện chứng của Hêghen với chủ nghĩa duy vật của Phoiơbắc; Mác cải tạo cả chủ nghĩa duy vật cũ lẫn phép biện chứng duy tâm của Hêghen. Phoiơbắc là nhà duy vật, không phải duy tâm. ([Giáo trình Triết học Mác-Lênin (bản cũ), mục về triết học Mác](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Đúng: triết học Mác thống nhất thế giới quan duy vật với phương pháp biện chứng.","Đúng: Mác kế thừa và cải tạo phép biện chứng của Hêghen trên cơ sở duy vật."],"s":"GT Triết học Mác-Lênin (bản cũ), phần sự ra đời và bản chất triết học Mác (chưa đối chiếu số chương)","c":1,"v":"khớp"},{"q":"Chọn quan điểm đúng nhất trong các quan điểm sau đây.","o":["Vận động là phương thức tồn tại của vật chất","Không gian, thời gian là những phương thức tồn tại của vật chất","Vận động phương thức, không gian, thời gian là những hình thức tồn tại của vật chất"],"a":[0],"e":"Giáo trình khẳng định vận động là thuộc tính cố hữu và «là phương thức tồn tại của vật chất»; còn không gian, thời gian là hình thức tồn tại của vật chất (bản 2021 viết «hình thức tồn tại»). Vì vậy A đúng nhất. ([Giáo trình Triết học Mác-Lênin 2021, phần Các hình thức tồn tại của vật chất](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Dễ nhầm: bản giáo trình cũ có viết không gian, thời gian là «phương thức tồn tại», nhưng bản 2021 gọi là «hình thức tồn tại»; phương án này không phải «đúng nhất» vì phương thức tồn tại chủ yếu chỉ vận động.","Sai: câu ghép lẫn thuật ngữ, gọi cả vận động lẫn không gian, thời gian là «hình thức» và lệch cách dùng chuẩn."],"s":"GT Triết học Mác-Lênin 2021, mục d. Các hình thức tồn tại của vật chất (số chương chưa đối chiếu); bản cũ mục I.3 «Những phương thức tồn tại của vật chất»","c":2,"v":"dễ nhầm","k":"Bản giáo trình cũ gọi cả vận động lẫn không gian – thời gian là «phương thức tồn tại», bản 2021 phân biệt phương thức (vận động) và hình thức (không gian, thời gian); phương án B vì vậy dễ gây tranh cãi, cần nhớ theo đáp án đề là A."},{"q":"Nội dung công cuộc đại phân công lao động xã hội lần thứ ba là:","o":["Đại công nghiệp tách khỏi nông nghiệp","Trồng trọt tách khỏi chăn nuôi","Ngành thương nghiệp ra đời","Thủ công nghiệp tách khỏi nông nghiệp"],"a":[2],"e":"Theo Ăngghen có ba lần đại phân công lao động xã hội: chăn nuôi tách khỏi trồng trọt; thủ công nghiệp tách khỏi nông nghiệp; thương nghiệp ra đời (xuất hiện tầng lớp thương nhân không sản xuất chỉ trao đổi). Lần thứ ba là thương nghiệp ra đời.","w":["Sai: đại công nghiệp là sản phẩm của thời kỳ tư bản chủ nghĩa, không nằm trong ba lần phân công cổ đại.","Sai: đây là lần phân công thứ nhất.","","Sai: đây là lần phân công thứ hai."],"s":"Ph. Ăngghen, «Nguồn gốc của gia đình, của chế độ tư hữu và của nhà nước» (chưa tra bản gốc; kết quả tìm kiếm thứ cấp nhất quán)","c":3,"v":"chưa kiểm chứng","k":"chưa kiểm chứng được nguồn cho câu này. Nội dung ba lần phân công khớp các trang tổng hợp, nhưng chưa mở được văn bản gốc hoặc giáo trình để dẫn link chắc chắn."},{"q":"Định nghĩa giai cấp của Lênin dựa vào cơ sở nào sau đây","o":["Xã hội","Kinh tế","Chính trị"],"a":[1],"e":"Lênin định nghĩa trong «Sáng kiến vĩ đại»: giai cấp là những tập đoàn người khác nhau về địa vị trong một hệ thống sản xuất xã hội nhất định, về quan hệ với tư liệu sản xuất, về vai trò trong tổ chức lao động xã hội, về cách thức và phần của cải xã hội được hưởng; tức dựa trên cơ sở kinh tế. ([Giáo trình Triết học Mác-Lênin (bản cũ), mục Giai cấp và đấu tranh giai cấp](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Sai: «xã hội» quá chung, không phải tiêu chí phân biệt giai cấp.","","Sai: chính trị là biểu hiện, hệ quả của địa vị kinh tế chứ không phải cơ sở của định nghĩa."],"s":"GT Triết học Mác-Lênin (bản cũ), mục II.1.a Khái niệm giai cấp (chưa đối chiếu số chương)","c":3,"v":"khớp"},{"q":"Theo quan điểm của chủ nghĩa duy vật biện chứng ở động vật bậc cao có thể đạt đến hình thức phản ánh nào","o":["Phản ánh ý thức","Phản ánh tâm lý động vật","Tính kích thích","Phản ánh sinh học"],"a":[1],"e":"Hình thức phản ánh ở động vật bậc cao có hệ thần kinh trung ương là tâm lý; tâm lý động vật chưa phải là ý thức, đó mới là phản ánh mang tính bản năng do nhu cầu sinh lý trực tiếp. ([Giáo trình Triết học Mác-Lênin 2021, phần Nguồn gốc của ý thức](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Sai: ý thức là hình thức phản ánh cao nhất, chỉ có ở con người.","","Sai: tính kích thích là hình thức phản ánh của cơ thể sống đơn giản nhất (thực vật).","Sai: phản ánh sinh học là nhóm chung của sinh vật; ở động vật bậc cao hình thức cao nhất là tâm lý."],"s":"GT Triết học Mác-Lênin 2021, mục nguồn gốc tự nhiên của ý thức; bản cũ cùng nội dung (chưa đối chiếu số chương)","c":2,"v":"khớp","id":"17z927x"},{"q":"Theo quan điểm của KTCT, trong tư liệu lao động bộ phận nào quyết định đến năng suất lao động?","o":["Công cụ lao động","Nguyên vật liệu cho sản xuất","Các vật chứa đựng, bảo quản","Kết cấu hạ tầng sản xuất"],"a":[0],"e":"Trong tư liệu lao động, công cụ lao động giữ vai trò quyết định đến năng suất lao động và chất lượng sản phẩm; Mác gọi nó là hệ thống xương cốt và bắp thịt của nền sản xuất. ([Giáo trình Kinh tế chính trị Mác-Lênin, Chương I mục II](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["","Sai: nguyên vật liệu thuộc đối tượng lao động, không thuộc tư liệu lao động.","Sai: vật chứa đựng, bảo quản chỉ là bộ phận phục vụ quá trình sản xuất.","Sai: kết cấu hạ tầng sản xuất có vai trò rất quan trọng nhưng giáo trình nhấn mạnh công cụ lao động mới giữ vai trò quyết định năng suất."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), Chương I mục II (đã đối chiếu)","c":4,"v":"khớp"},{"q":"Quan điểm nào sau đây phản ánh đầy đủ nội dung khái niệm tồn tại xã hội","o":["Tồn tại xã hội là phạm trù dùng chỉ toàn bộ điều kiện vật chất của xã hội","Tồn tại xã hội là phạm trù dùng chỉ toàn bộ các giá trị tinh thần của xã hội","Tồn tại xã hội là phạm trù dùng chỉ toàn bộ các điều kiện sinh hoạt của xã hội"],"a":[0],"e":"Tồn tại xã hội là toàn bộ sinh hoạt vật chất và những điều kiện sinh hoạt vật chất của xã hội; các yếu tố chính gồm phương thức sản xuất vật chất, điều kiện tự nhiên – hoàn cảnh địa lý, dân số và mật độ dân số, trong đó phương thức sản xuất vật chất là cơ bản nhất. Phương án A nêu đúng phạm vi vật chất. ([Giáo trình Triết học Mác-Lênin (bản cũ), mục Tồn tại xã hội và ý thức xã hội](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Sai: giá trị tinh thần thuộc ý thức xã hội, không thuộc tồn tại xã hội.","Sai: thiếu chữ «vật chất»; «điều kiện sinh hoạt» chung chung có thể lẫn cả sinh hoạt tinh thần."],"s":"GT Triết học Mác-Lênin (bản cũ), mục I.1.a Khái niệm tồn tại xã hội (chưa đối chiếu số chương)","c":3,"v":"khớp","k":"A và C gần nghĩa; khác ở chỗ giáo trình nhấn mạnh sinh hoạt và điều kiện sinh hoạt vật chất.","id":"16cuqy7"},{"q":"Phương pháp rút ra kết quả riêng từ những kết luận chung, không tính đến sự tồn tại thực tế của sự vật, được gọi là?","o":["Phương pháp quy nạp","Phương pháp diễn dịch","Phương pháp kinh nghiệm","Phương pháp kinh viện"],"a":[3],"e":"Phương án D («kinh viện») là đáp án của đề: giáo trình mô tả triết học kinh viện thời Trung cổ gắn với niềm tin tôn giáo, chú giải tín điều, nặng về tư biện. Khái niệm «rút kết quả riêng từ kết luận chung, không tính đến thực tế» không được giáo trình định nghĩa nguyên văn.","w":["Sai: quy nạp đi từ cái riêng đến cái chung.","Dễ nhầm: diễn dịch cũng đi từ chung đến riêng nhưng là phương pháp lôgic hợp lệ; câu hỏi nhấn mạnh «không tính đến thực tế» nên đề chọn kinh viện.","Sai: phương pháp kinh nghiệm dựa vào quan sát, thực nghiệm.",""],"s":"GT Triết học Mác-Lênin 2021, mục triết học Trung cổ (kinh viện); định nghĩa phương pháp trong câu chưa đối chiếu","c":1,"v":"dễ nhầm","k":"Giáo trình chỉ mô tả triết học kinh viện (đối tượng tôn giáo, tư biện) chứ không định nghĩa «phương pháp kinh viện» như câu hỏi; diễn dịch (B) cũng đi từ chung đến riêng nên dễ lẫn, cần nhớ theo đáp án đề."},{"q":"Cái do nguyên nhân cơ bản bên trong của kết cấu vật chất quyết định và trong những điều kiện nhất định nó phải xảy ra như thể chứ không thể khác được gọi là?","o":["Tất nhiên","Ngẫu nhiên","Hệ quả","Bản chất"],"a":[0],"e":"Tất nhiên là phạm trù chỉ cái do những nguyên nhân cơ bản bên trong của kết cấu vật chất quyết định và trong những điều kiện nhất định nó phải xảy ra như thế chứ không thể khác được. ([Giáo trình Triết học Mác-Lênin (bản cũ), mục Tất nhiên và ngẫu nhiên](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Sai: ngẫu nhiên là cái không do mối liên hệ bản chất bên trong quyết định mà do các nhân tố bên ngoài, có thể xuất hiện hoặc không.","Sai: «hệ quả» không phải phạm trù cho định nghĩa này (kết quả là phạm trù của cặp nguyên nhân – kết quả).","Sai: bản chất thuộc cặp bản chất – hiện tượng, không phải cặp tất nhiên – ngẫu nhiên."],"s":"GT Triết học Mác-Lênin (bản cũ), mục IV.1 Tất nhiên và ngẫu nhiên (chưa đối chiếu số chương)","c":2,"v":"khớp"},{"q":"Trong chủ nghĩa tư bản, ... quan hệ giữa giai cấp tư sản và giai cấp công nhân là quan hệ bóc lột.","o":["Hình thức","Nội dung","Bản chất","Hiện tượng"],"a":[2],"e":"Giáo trình nêu việc nhà tư bản chiếm đoạt giá trị thặng dư do quá trình sản xuất tư bản chủ nghĩa tạo ra gọi là bóc lột giá trị thặng dư; đó là bản chất quan hệ giữa giai cấp tư sản và giai cấp công nhân làm thuê trong chủ nghĩa tư bản. ([Giáo trình Kinh tế chính trị Mác-Lênin, Chương IV mục II](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["Sai: hình thức bề ngoài là quan hệ mua bán, thuê mướn sức lao động.","Sai: nội dung là cái được hình thức chứa đựng, không nhấn mạnh quan hệ bóc lột cốt lõi như «bản chất».","","Sai: hiện tượng là biểu hiện bề ngoài, trong khi bóc lột là cái bên trong, bản chất."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), Chương IV mục II (đã đối chiếu nội dung bóc lột giá trị thặng dư)","c":4,"v":"khớp"},{"q":"Để làm rõ vai trò của các bộ phận tư bản trong việc tạo ra giá trị thặng dư, tư bản được chia thành","o":["Tư bản độc quyền và tư bản nhà nước","Tư bản bất biến và tư bản khả biến","Tư bản cố định và tư bản lưu động"],"a":[1],"e":"Căn cứ vào vai trò khác nhau của các bộ phận tư bản trong quá trình sản xuất giá trị thặng dư, tư bản được chia thành tư bản bất biến (c) và tư bản khả biến (v): bất biến là điều kiện cần thiết, khả biến có vai trò quyết định vì chính nó đã lớn lên. ([Giáo trình Kinh tế chính trị Mác-Lênin, Chương IV mục II](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["Sai: tư bản độc quyền và tư bản nhà nước là cách phân loại theo giai đoạn phát triển của chủ nghĩa tư bản, không liên quan vai trò tạo giá trị thặng dư.","","Sai: tư bản cố định và tư bản lưu động chia theo phương thức chu chuyển giá trị vào sản phẩm, không làm rõ nguồn gốc giá trị thặng dư."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), Chương IV mục II.2 (đã đối chiếu); cố định – lưu động ở Chương V mục I.3","c":4,"v":"khớp"},{"q":"Trong xã hội phân chia giai cấp","o":["Đấu tranh giai cấp là nguồn gốc và động lực vận động và phát triển xã hội","Đấu tranh giai cấp là nguyên nhân chủ yếu của vận động và phát triển xã hội","Đấu tranh giai cấp là động lực chủ yếu dẫn đến sự vận động và phát triển xã hội"],"a":[0],"e":"Giáo trình trình bày đấu tranh giai cấp là «một trong những động lực phát triển của xã hội có giai cấp»: đỉnh cao của đấu tranh giai cấp là cách mạng xã hội, thay thế phương thức sản xuất cũ bằng phương thức mới tiến bộ hơn. Đề cho đáp án A («nguồn gốc và động lực») là cách diễn đạt mạnh hơn giáo trình. ([Giáo trình Triết học Mác-Lênin (bản cũ), mục Giai cấp và đấu tranh giai cấp](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Chưa chuẩn: «nguyên nhân chủ yếu» không phải cách nói của giáo trình, vì nguồn gốc sâu xa là mâu thuẫn giữa lực lượng sản xuất và quan hệ sản xuất.","Chưa chuẩn: «động lực chủ yếu» cũng tuyệt đối hóa, giáo trình chỉ nói «một trong những động lực»."],"s":"GT Triết học Mác-Lênin (bản cũ), mục II.2.b Đấu tranh giai cấp là một trong những động lực phát triển của xã hội có giai cấp (chưa đối chiếu số chương)","c":3,"v":"nghi vấn","k":"nghi vấn: Giáo trình dùng «một trong những động lực», không viết «nguồn gốc và động lực»; đáp án A có thể là cách nói trích từ nguồn khác hoặc lỗi chép, cần nhớ theo đáp án đề."},{"q":"Các tổ chức độc quyền sử dụng giá cả độc quyền để","o":["Củng cố vai trò tổ chức độc quyền","Chiếm đoạt giá trị thặng dư của người khác","Gây thiệt hại cho các đối thủ cạnh tranh"],"a":[1],"e":"Nhờ địa vị thống trị trong sản xuất và lưu thông, các tổ chức độc quyền định giá cả độc quyền (cao hơn giá cả sản xuất khi bán, thấp hơn khi mua) để thu lợi nhuận độc quyền; giáo trình chỉ rõ những gì tổ chức độc quyền thu được cũng là những thứ các nhà tư bản vừa và nhỏ, nhân dân lao động và nhân dân thuộc địa mất đi, tức chiếm đoạt giá trị thặng dư của người khác. ([Giáo trình Kinh tế chính trị Mác-Lênin, Chương VII mục I.2](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["Sai: củng cố vị thế độc quyền có thể là hệ quả nhưng không phải mục đích trực tiếp của giá cả độc quyền theo giáo trình.","","Sai: gây thiệt hại đối thủ chỉ là hệ quả đi kèm; mục tiêu kinh tế là lợi nhuận độc quyền bằng cách chiếm đoạt giá trị của người khác."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), Chương VII mục I.2.a (đã đối chiếu)","c":4,"v":"khớp"},{"q":"Chọn câu trả lời đúng theo quan điểm của chủ nghĩa duy vật lịch sử: Trong mối quan hệ giữa lực lượng sản xuất và quan hệ sản xuất","o":["Lực lượng sản xuất là yếu tố thường xuyên biến đổi, phát triển","Quan hệ sản xuất là yếu tố thường xuyên biến đổi, phát triển","Cả hai đều là những yếu tố thường xuyên biến đổi, phát triển","Không có yếu tố nào thường xuyên biến đổi, phát triển"],"a":[0],"e":"Giáo trình nêu công cụ lao động là yếu tố động nhất, cách mạng nhất trong lực lượng sản xuất, là nguyên nhân sâu xa của mọi biến đổi kinh tế – xã hội; nên lực lượng sản xuất là yếu tố thường xuyên biến đổi, phát triển, còn quan hệ sản xuất tương đối ổn định hơn. ([Giáo trình Triết học Mác-Lênin 2021, phần Lực lượng sản xuất](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Sai: quan hệ sản xuất tương đối ổn định, thay đổi chậm hơn và thường lạc hậu so với lực lượng sản xuất.","Sai: chỉ lực lượng sản xuất là yếu tố động nhất.","Sai: lực lượng sản xuất luôn phát triển."],"s":"GT Triết học Mác-Lênin 2021, phần Lực lượng sản xuất – quan hệ sản xuất (chưa đối chiếu số chương); ý «quan hệ sản xuất tương đối ổn định» là kiến thức chung, chưa thấy nguyên văn trong bản đã đọc","c":3,"v":"khớp"},{"q":"Tư bản cố định và tư bản lưu động thuộc phạm trù tư bản nào?","o":["Tư bản sản xuất.","Tư bản tiền tệ.","Tư bản bất biến."],"a":[0],"e":"Căn cứ vào tính chất chu chuyển khác nhau (cách chuyển giá trị vào sản phẩm), người ta chia tư bản sản xuất thành hai bộ phận: tư bản cố định và tư bản lưu động. ([Giáo trình Kinh tế chính trị Mác-Lênin, Chương V mục I.3](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["","Sai: tư bản tiền tệ là một hình thái của tư bản công nghiệp trong tuần hoàn, không chứa cố định và lưu động.","Sai: tư bản bất biến và khả biến là cách phân loại khác (theo vai trò trong tạo giá trị thặng dư); tư bản cố định chỉ là bộ phận chủ yếu của tư bản bất biến."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), Chương V mục I.3 (đã đối chiếu)","c":4,"v":"khớp"},{"q":"Theo quan điểm Mác-Lênin, chủ nghĩa cộng sản chia làm mấy giai đoạn","o":["2 giai đoạn","3 giai đoạn","4 giai đoạn"],"a":[0],"e":"Theo Mác – Lênin, hình thái kinh tế – xã hội cộng sản chủ nghĩa gồm hai giai đoạn phát triển: giai đoạn thấp (xã hội xã hội chủ nghĩa) và giai đoạn cao (chủ nghĩa cộng sản); trước đó là thời kỳ quá độ. Giáo trình triết học 2021 cũng nêu chủ nghĩa xã hội và chủ nghĩa cộng sản là hai giai đoạn trong sự phát triển của xã hội cộng sản chủ nghĩa. ([Giáo trình Triết học Mác-Lênin 2021, phần Lênin](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Dễ nhầm: nếu tính cả thời kỳ quá độ thì thành ba giai đoạn (quá độ, thấp, cao) nhưng câu hỏi hỏi các giai đoạn của chủ nghĩa cộng sản nên là hai.","Sai: không có cách chia bốn giai đoạn."],"s":"GT Triết học Mác-Lênin 2021, phần Lênin và «Nhà nước và cách mạng» (chưa đối chiếu số chương); văn bản gốc của Lênin chưa tra","c":4,"v":"dễ nhầm","k":"Một số tài liệu chia ba giai đoạn (quá độ, giai đoạn thấp, giai đoạn cao) nên phương án B có thể gây tranh cãi; đề chọn 2 giai đoạn."},{"q":"Cơ chế kinh tế của CNTB độc quyền nhà nước gồm:","o":["Cơ chế thị trường, độc quyền tư nhân và sự can thiệp của nhà nước","Cơ chế thị trường, các nhà tài phiệt và sự điều tiết của nhà nước","Cơ chế thị trường và độc quyền tư nhân"],"a":[0],"e":"Giáo trình nêu hệ thống điều tiết kinh tế của nhà nước trong chủ nghĩa tư bản độc quyền nhà nước dung hợp cả ba cơ chế: thị trường, độc quyền tư nhân và điều tiết của nhà nước, nhằm phát huy mặt tích cực và hạn chế mặt tiêu cực của từng cơ chế. ([Giáo trình Kinh tế chính trị Mác-Lênin, Chương VII mục II.2.c](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["","Sai: «các nhà tài phiệt» không phải một cơ chế; cơ chế gồm thị trường, độc quyền tư nhân và điều tiết của nhà nước.","Sai: thiếu cơ chế điều tiết, can thiệp của nhà nước, là đặc điểm nổi bật của CNTB độc quyền nhà nước."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), Chương VII mục II.2.c (đã đối chiếu)","c":4,"v":"khớp"},{"q":"Đâu là nội dung nguyên lý của phép biện chứng duy vật về mối liên hệ phổ biến của các sự vật và hiện tượng","o":["Các sự vật và hiện tượng trong thế giới tồn tại tách rời nhau, giữa chúng không có sự phụ thuộc, ràng buộc lẫn nhau.","Các sự vật có sự liên hệ tác động nhau nhưng không có sự chuyển hóa lẫn nhau","Sự vật khác nhau ở vẻ bề ngoài, do chủ quan con người quy định, bản chất sự vật không có gì khác nhau","Thế giới là một chính thể thống nhất bao gồm các sự vật, các quá trình vừa tách biệt nhau, vừa có mối liên hệ qua lại với nhau, vừa thâm nhập và chuyển hóa cho nhau"],"a":[3],"e":"Phép biện chứng duy vật thừa nhận có mối liên hệ phổ biến giữa các đối tượng: các sự vật, hiện tượng trong thế giới vừa tách biệt vừa có liên hệ, tác động, thâm nhập và chuyển hóa lẫn nhau, thế giới là một chỉnh thể thống nhất. ([Giáo trình Triết học Mác-Lênin 2021, phần Mối liên hệ phổ biến](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Sai: quan điểm siêu hình coi sự vật tồn tại tách rời, không phụ thuộc nhau.","Sai: phủ nhận sự chuyển hóa lẫn nhau, mâu thuẫn với nguyên lý về mối liên hệ phổ biến.","Sai: quan điểm duy tâm chủ quan coi khác biệt do chủ quan con người quy định.",""],"s":"GT Triết học Mác-Lênin 2021, mục Mối liên hệ phổ biến (chưa đối chiếu số chương); câu «chỉnh thể thống nhất» chưa thấy nguyên văn trong đoạn đã đọc","c":2,"v":"khớp"},{"q":"Giai cấp công nhân hình thành và phát triển mạnh trong xã hội nào.","o":["Xã hội chiếm hữu nô lệ","Xã hội phong kiến","Xã hội tư bản chủ nghĩa","Xã hội xã hội chủ nghĩa"],"a":[2],"e":"Giai cấp công nhân hiện đại là sản phẩm của nền đại công nghiệp, ra đời và phát triển mạnh cùng chủ nghĩa tư bản, là giai cấp bị bóc lột giá trị thặng dư; trong xã hội xã hội chủ nghĩa họ trở thành giai cấp lãnh đạo nhưng không phải là xã hội nơi họ hình thành.","w":["Sai: thời chiếm hữu nô lệ có chủ nô và nô lệ.","Sai: thời phong kiến có địa chủ và nông dân.","","Sai: giai cấp công nhân hình thành từ chủ nghĩa tư bản, xã hội xã hội chủ nghĩa là nơi họ trở thành giai cấp lãnh đạo."],"s":"GT CNXH khoa học (chưa đối chiếu với bản giáo trình; kết quả tìm kiếm thứ cấp nhất quán)","c":4,"v":"chưa kiểm chứng","k":"chưa kiểm chứng được nguồn cho câu này. Chưa mở được giáo trình CNXH khoa học để dẫn link; nội dung khớp các tài liệu thứ cấp."},{"q":"Công cuộc đổi mới xã hội chủ nghĩa diễn ra ở nước nào sau đây","o":["Trung Quốc","Việt Nam","Cu Ba"],"a":[1],"e":"Công cuộc đổi mới xã hội chủ nghĩa do Đảng Cộng sản Việt Nam khởi xướng từ Đại hội đại biểu toàn quốc lần thứ VI (tháng 12-1986) và được lãnh đạo thực hiện từ đó. ([Đại hội đại biểu toàn quốc lần thứ VI của Đảng, Tư liệu văn kiện Đảng](https://tulieuvankien.dangcongsan.vn/ban-chap-hanh-trung-uong-dang/dai-hoi-dang/lan-thu-vi/dai-hoi-dai-bieu-toan-quoc-lan-thu-vi-cua-dang-19))","w":["Sai: Trung Quốc thực hiện cải cách mở cửa từ 1978, thuật ngữ khác.","","Sai: Cu Ba cập nhật mô hình kinh tế, không dùng khái niệm Đổi mới theo Đại hội VI của Việt Nam."],"s":"Văn kiện Đại hội VI của Đảng (1986), tulieuvankien.dangcongsan.vn (đã mở kết quả tìm kiếm; chưa trích văn kiện chi tiết)","c":4,"v":"khớp"},{"q":"Hai khái niệm triết học cùng với thế giới quan...","o":["Là trùng nhau vì đều là hệ thống quan điểm chung về thế giới","Triết học không phải là toàn bộ thế giới quan mà chỉ là hạt nhân lý luận chung nhất của thế giới quan","Không phải mọi triết học đều là hạt nhân lý luận của thế giới quan mà chỉ có triết học Mác - Lênin mới là hạt nhân lý luận của thế giới quan","Là hoàn toàn khác nhau"],"a":[1],"e":"Giáo trình nêu: triết học với phương thức tư duy đặc thù xây dựng hệ thống lý luận gồm những quan niệm chung nhất về thế giới như một chỉnh thể, nên triết học là hạt nhân lý luận của thế giới quan, giữ vai trò định hướng; thế giới quan còn hình thành từ tri thức khoa học cụ thể, kinh nghiệm sống, niềm tin. ([Giáo trình Triết học Mác-Lênin (bản cũ), mục Triết học – hạt nhân lý luận của thế giới quan](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Sai: không trùng nhau; triết học chỉ là hạt nhân lý luận chứ không là toàn bộ thế giới quan.","","Sai: không phải chỉ triết học Mác – Lênin; giáo trình nói triết học nói chung là hạt nhân lý luận của thế giới quan (thế giới quan triết học).","Sai: hai khái niệm có quan hệ chặt chẽ, không hoàn toàn khác nhau."],"s":"GT Triết học Mác-Lênin (bản cũ), mục I.1 Triết học – hạt nhân lý luận của thế giới quan (chưa đối chiếu số chương)","c":1,"v":"khớp"},{"q":"Nhà nước xã hội chủ nghĩa","o":["Tôn trọng quyền tự quyết và bình đẳng giữa các dân tộc","Không tôn trọng quyền tự quyết và bình đẳng giữa các dân tộc","Không can thiệp vào vấn đề dân tộc"],"a":[0],"e":"Nhà nước xã hội chủ nghĩa tôn trọng quyền tự quyết và bình đẳng giữa các dân tộc, phù hợp Cương lĩnh dân tộc của chủ nghĩa Mác – Lênin: các dân tộc hoàn toàn bình đẳng, có quyền tự quyết, công nhân các dân tộc liên hiệp lại.","w":["","Sai: trái bản chất nhà nước xã hội chủ nghĩa và Cương lĩnh dân tộc.","Sai: nhà nước có trách nhiệm hoạch định chính sách, giải quyết vấn đề dân tộc."],"s":"GT CNXH khoa học, phần Cương lĩnh dân tộc (chưa đối chiếu giáo trình; kết quả tìm kiếm thứ cấp nhất quán)","c":4,"v":"chưa kiểm chứng","k":"chưa kiểm chứng được nguồn cho câu này. Chưa mở được giáo trình CNXH khoa học; ý khớp tổng hợp Cương lĩnh dân tộc của Lênin."},{"q":"Cạnh tranh kinh tế được hiểu là","o":["Sự đấu tranh ở giữa các chủ thể kinh tế, để giành chi phí tối đa cho mình.","Sự đấu tranh ở giữa các chủ thể kinh tế, để giành lợi ích tối đa cho mình.","Sự đấu tranh ở giữa các chủ thể kinh tế, để giành thị phần tối đa cho mình.","Sự đấu tranh ở giữa các chủ thể kinh tế."],"a":[1],"e":"Cạnh tranh là sự ganh đua về kinh tế giữa những chủ thể trong nền sản xuất hàng hóa nhằm giành giật những điều kiện thuận lợi trong sản xuất, tiêu thụ hoặc tiêu dùng để từ đó thu được nhiều lợi ích nhất cho mình. ([Giáo trình Kinh tế chính trị Mác-Lênin, Chương III mục IV.2](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["Sai: mục tiêu là lợi ích tối đa, không phải chi phí tối đa.","","Sai: thị phần chỉ là phương tiện hoặc mục tiêu trung gian, không phải mục đích cuối.","Sai: thiếu mục đích «để giành lợi ích tối đa», nên chưa đủ định nghĩa."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), Chương III mục IV.2 Quy luật cạnh tranh (đã đối chiếu)","c":4,"v":"khớp"},{"q":"Trong nền sản xuất lớn hiện đại, yếu tố nào giữ vai trò quyết định của quá trình lao động sản xuất?","o":["Sức lao động","Tư liệu sản xuất hiện đại","Công cụ sản xuất tiên tiến","Đối tượng lao động"],"a":[0],"e":"Giáo trình nêu sức lao động giữ vai trò yếu tố chủ thể của quá trình sản xuất, còn đối tượng lao động và tư liệu lao động là yếu tố khách thể; công cụ sản xuất dù hiện đại, kể cả máy tự động hay người máy thông minh, đều do con người tạo ra và sử dụng, và với công cụ tiên tiến thì yếu tố trí tuệ trong sức lao động càng quan trọng. ([Giáo trình Kinh tế chính trị Mác-Lênin, Chương I mục II](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["","Sai: tư liệu sản xuất hiện đại do con người tạo ra và chỉ phát huy khi có người sử dụng, là yếu tố khách thể.","Dễ nhầm: giáo trình triết học nêu công cụ lao động quyết định năng suất lao động, nhưng trong quá trình lao động sản xuất yếu tố chủ thể là sức lao động.","Sai: đối tượng lao động là yếu tố bị tác động, khách thể của sản xuất."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), Chương I mục II (đã đối chiếu; chữ «quyết định» chưa thấy nguyên văn cho sức lao động)","c":4,"v":"dễ nhầm","k":"Giáo trình gọi sức lao động là yếu tố chủ thể, còn nói công cụ lao động quyết định năng suất; hai ý này khiến phương án C dễ nhầm; đề chọn A."},{"q":"Ngày lao động của công nhân bao gồm?","o":["Thời gian lao động giản đơn, thời gian lao động thặng dư.","Thời gian lao động phức tạp, thời gian lao động thặng dư.","Thời gian lao động cần thiết, thời gian lao động thặng dư.","Tất cả phương án trên"],"a":[2],"e":"Ngày lao động của công nhân gồm thời gian lao động tất yếu (tạo ra giá trị mới vừa đủ bù đắp giá trị sức lao động) và thời gian lao động thặng dư (tạo ra giá trị thặng dư cho nhà tư bản). ([Giáo trình Kinh tế chính trị Mác-Lênin, Chương IV mục II.1](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["Sai: lao động giản đơn là cách phân loại lao động theo trình độ, không phải thành phần của ngày lao động.","Sai: lao động phức tạp cũng là cách phân loại lao động theo trình độ.","","Sai: A và B đều sai nên «tất cả» không đúng."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), Chương IV mục II.1 (đã đối chiếu)","c":4,"v":"khớp","k":"Giáo trình dùng thuật ngữ «thời gian lao động tất yếu»; đề ghi «cần thiết» cùng nghĩa.","f":1},{"q":"Tích lũy tư bản dẫn đến","o":["Hình thành chủ nghĩa tư bản độc quyền","Hình thành chủ nghĩa tư bản độc quyền nhà nước","Hình thành chủ nghĩa tư bản"],"a":[0],"e":"Giáo trình nêu cạnh tranh tự do đẻ ra tập trung sản xuất, và tập trung sản xuất đến mức độ nhất định dẫn tới độc quyền; tích lũy tư bản (tích tụ và tập trung tư bản) làm quy mô tư bản lớn lên, là con đường dẫn tới chủ nghĩa tư bản độc quyền. ([Giáo trình Kinh tế chính trị Mác-Lênin, Chương VII mục I.1](https://kmacle.duytan.edu.vn/uploads/2eae0e86-e7c6-431d-aa08-b8f89ba71921_giaotrinhkinhtechinhtri.pdf))","w":["","Sai: chủ nghĩa tư bản độc quyền nhà nước là nấc thang phát triển tiếp theo của độc quyền, không phải kết quả trực tiếp ở đây.","Sai: chủ nghĩa tư bản hình thành từ trước, phương án này bị cụt chữ và chưa chỉ rõ."],"s":"GT Kinh tế chính trị Mác-Lênin (Bộ GD&ĐT), Chương IV mục IV (tích lũy tư bản) và Chương VII mục I.1 (đã đối chiếu; không có câu nối trực tiếp «tích lũy dẫn đến độc quyền»)","c":4,"v":"dễ nhầm","k":"Giáo trình không có câu nguyên văn «tích lũy tư bản dẫn đến CNTB độc quyền»; quan hệ nối qua tích tụ, tập trung sản xuất, tư bản; phương án C của đề bị cụt chữ."},{"q":"Cái chung chỉ tồn tại trong","o":["Cái riêng","Cái đơn nhất","Cái cụ thể"],"a":[0],"e":"Cái chung không tồn tại độc lập mà chỉ tồn tại trong cái riêng, thông qua cái riêng mà biểu hiện sự tồn tại của mình; cái riêng là cái toàn bộ, cái chung chỉ là bộ phận. ([Giáo trình Triết học Mác-Lênin 2021, phần Cái riêng, cái chung và cái đơn nhất](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Sai: cái đơn nhất là mặt chỉ có ở một sự vật; cái chung và cái đơn nhất đều chỉ tồn tại trong cái riêng.","Sai: «cái cụ thể» không phải phạm trù trong cặp cái riêng – cái chung – cái đơn nhất."],"s":"GT Triết học Mác-Lênin 2021, mục Cái riêng, cái chung và cái đơn nhất (chưa đối chiếu số chương)","c":2,"v":"khớp"},{"q":"Luận điểm \"Mối liên hệ nhân quả là do cảm giác con người quy định\" thuộc lập trường triết học nào?","o":["Chủ nghĩa duy tâm khách quan","Chủ nghĩa duy tâm chủ quan","Chủ nghĩa duy vật biện chứng","Chủ nghĩa duy vật siêu hình"],"a":[1],"e":"Luận điểm cho rằng mối liên hệ nhân quả do cảm giác con người quy định là của chủ nghĩa duy tâm chủ quan; giáo trình nêu Béccơly trên lập trường duy tâm chủ quan cho rằng cảm giác là nền tảng của mối liên hệ giữa các đối tượng, trong khi mối liên hệ nhân quả có tính khách quan, phổ biến và tất yếu. ([Giáo trình Triết học Mác-Lênin 2021, phần Mối liên hệ phổ biến và nguyên nhân – kết quả](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Sai: duy tâm khách quan cho nguồn gốc là ý niệm tuyệt đối (như Hêghen), không phải cảm giác cá nhân.","","Sai: duy vật biện chứng khẳng định nhân quả khách quan, không phụ thuộc cảm giác.","Sai: duy vật siêu hình cũng thừa nhận nhân quả khách quan (thường hiểu cơ học)."],"s":"GT Triết học Mác-Lênin 2021, mục Mối liên hệ phổ biến, Nguyên nhân và kết quả (chưa đối chiếu số chương)","c":2,"v":"khớp"},{"q":"Theo quan điểm chủ nghĩa duy vật biện chứng thì đứng im là một trạng thái đặc biệt của vận động.","o":["Tuyệt đối","Trong cân bằng","Tại chỗ","Tĩnh tại"],"a":[1],"e":"Đứng im, theo triết học Mác – Lênin, là một trạng thái đặc biệt của vận động: vận động trong cân bằng, nghĩa là những tính chất của vật chất chưa có sự biến đổi cơ bản; đứng im chỉ là tương đối và tạm thời. ([Giáo trình Triết học Mác-Lênin (bản cũ), mục Vận động](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Sai: vận động mới là tuyệt đối, đứng im chỉ tương đối.","","Sai: «tại chỗ» không phải thuật ngữ chuẩn của giáo trình.","Sai: «tĩnh tại» không phải thuật ngữ chuẩn và dễ hiểu thành không vận động."],"s":"GT Triết học Mác-Lênin (bản cũ), mục I.3.a Vận động (chưa đối chiếu số chương)","c":2,"v":"khớp","id":"1n60ukq"},{"q":"Theo chủ nghĩa Mác - Lênin, triết học khác với các khoa học khác ở chỗ nào?","o":["Tính đặc thù của hệ thống tri thức khoa học và phương pháp nghiên cứu","Tính đặc thù của hệ thống tri thức và phương pháp nghiên cứu khoa học","Tính đặc thù của khoa học và phương pháp nghiên cứu đặc thù","Tính biện chứng và siêu hình"],"a":[0],"e":"Giáo trình nêu: triết học khác với các khoa học khác ở tính đặc thù của hệ thống tri thức khoa học và phương pháp nghiên cứu; tri thức triết học mang tính khái quát cao dựa trên sự trừu tượng hóa sâu sắc về thế giới. ([Giáo trình Triết học Mác-Lênin 2021, phần Triết học là gì](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Gần giống nhưng đảo vị trí chữ «khoa học» (đặc thù của hệ thống tri thức và phương pháp nghiên cứu khoa học), không khớp nguyên văn.","Sai: nói «đặc thù của khoa học» và «phương pháp đặc thù», lệch khỏi chuẩn.","Sai: biện chứng và siêu hình là hai phương pháp tư duy đối lập, không phải căn cứ phân biệt triết học với khoa học khác."],"s":"GT Triết học Mác-Lênin 2021, Chương 1 mục 1.2 (số mục theo bản PDF; chưa đối chiếu số chương chính xác)","c":1,"v":"khớp","k":"A và B chỉ khác vị trí chữ; A khớp nguyên văn giáo trình 2021."},{"q":"Về cấu trúc, tư liệu sản xuất thuộc mặt nào trong lực lượng sản xuất?","o":["Kinh tế - kỹ thuật","Người lao động","Nhà xưởng, máy móc","Phương tiện thanh toán"],"a":[0],"e":"Về cấu trúc, lực lượng sản xuất được xem xét trên cả hai mặt: mặt kinh tế – kỹ thuật (tư liệu sản xuất) và mặt kinh tế – xã hội (người lao động). ([Giáo trình Triết học Mác-Lênin 2021, phần Lực lượng sản xuất](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Sai: người lao động thuộc mặt kinh tế – xã hội.","Sai: nhà xưởng, máy móc là ví dụ cụ thể của tư liệu sản xuất (tư liệu lao động), không phải tên mặt cấu trúc.","Sai: phương tiện thanh toán không phải mặt cấu trúc của lực lượng sản xuất."],"s":"GT Triết học Mác-Lênin 2021, phần Lực lượng sản xuất (chưa đối chiếu số chương)","c":3,"v":"khớp"},{"q":"Nội dung cơ bản của cuộc đấu tranh giai cấp trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam hiện nay là gì?","o":["Thực hiện thắng lợi mục tiêu độc lập dân tộc","Xây dựng một xã hội phát triển toàn diện","Đảm bảo sự phát triển toàn diện cho mọi người dân","Thực hiện thắng lợi mục tiêu độc lập dân tộc và chủ nghĩa xã hội, xây dựng một xã hội dân giàu, nước mạnh, dân chủ, công bằng, văn minh"],"a":[3],"e":"Nội dung của cuộc đấu tranh giai cấp trong thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam hiện nay là thực hiện thắng lợi mục tiêu độc lập dân tộc và chủ nghĩa xã hội, xây dựng một xã hội dân giàu, nước mạnh, dân chủ, công bằng, văn minh. ([Giáo trình Triết học Mác-Lênin 2021, phần Đấu tranh giai cấp ở Việt Nam](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Sai: chỉ nêu mục tiêu độc lập dân tộc, thiếu chủ nghĩa xã hội và các đặc trưng xã hội.","Sai: chưa nêu mục tiêu độc lập dân tộc và chủ nghĩa xã hội.","Sai: chỉ nêu một khía cạnh, chưa đầy đủ nội dung cơ bản.",""],"s":"GT Triết học Mác-Lênin 2021, phần Đấu tranh giai cấp trong thời kỳ quá độ ở Việt Nam (chưa đối chiếu số chương)","c":4,"v":"khớp"},{"q":"Nếu quá đề cao triết học duy tâm sẽ dẫn đến","o":["Xa rời thực tế","Cực đoan","Thực dụng"],"a":[0],"e":"Giáo trình không có câu nào nêu nguyên văn hệ quả «xa rời thực tế», nhưng chỉ ra nguồn gốc nhận thức luận của chủ nghĩa duy tâm là cách xem xét phiến diện, tuyệt đối hóa, thần thánh hóa một mặt của quá trình nhận thức, và nguồn gốc xã hội là việc coi nhân tố tinh thần giữ vai trò quyết định. Đề cao duy tâm nghĩa là đặt ý thức, tinh thần lên trước vật chất nên dễ tách rời hiện thực khách quan, vì vậy A là phương án hợp lý nhất. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","«Cực đoan» là cách nhận xét chung chung, không phải hệ quả đặc trưng giáo trình nêu ra cho chủ nghĩa duy tâm.","«Thực dụng» là tên một trào lưu triết học khác (chủ nghĩa thực dụng), không phải hệ quả của việc đề cao duy tâm."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương I, mục về chủ nghĩa duy vật và chủ nghĩa duy tâm (nguồn gốc nhận thức luận và xã hội của duy tâm)","c":1,"v":"dễ nhầm","k":"Câu hỏi mang tính suy luận, giáo trình không có câu khẳng định trực tiếp «đề cao duy tâm dẫn đến xa rời thực tế»."},{"q":"Phát triển là quá trình","o":["Tiến lên theo đường vòng khép kín","Tiến lên theo đường quanh co khúc khuỷu, thăng trầm, phức tạp","Quá trình tiến lên theo đường thẳng tắp"],"a":[1],"e":"Theo quan điểm biện chứng, phát triển là quá trình tiến lên theo đường «xoáy ốc», không phải lúc nào cũng theo đường thẳng mà rất quanh co, phức tạp, thậm chí có những bước lùi tạm thời. Hết mỗi chu kỳ sự vật lặp lại dường như sự vật ban đầu nhưng ở cấp độ cao hơn. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VI](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Vòng khép kín là quan điểm siêu hình: thay đổi chỉ lặp lại, không sinh ra cái mới với chất mới; biện chứng nói xoáy ốc, lặp lại ở cấp độ cao hơn.","","Đường thẳng tắp là cách hiểu siêu hình, coi phát triển là tiến lên liên tục, không có bước quanh co; giáo trình khẳng định phát triển không phải lúc nào cũng theo đường thẳng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VI (mục về phát triển); Chương VIII (phủ định của phủ định, đường xoáy ốc)","c":2,"v":"khớp"},{"q":"Khẳng định mối liên hệ giữa các sự vật, hiện tượng do sự quy định của các lực lượng siêu nhiên là quan điểm của","o":["Chủ nghĩa duy tâm chủ quan","Chủ nghĩa duy tâm khách quan","Chủ nghĩa duy vật siêu hình"],"a":[1],"e":"Chủ nghĩa duy tâm khách quan thừa nhận ý thức có trước, nhưng cho đó là thứ tinh thần khách quan tồn tại độc lập với con người, mang các tên như ý niệm, tinh thần tuyệt đối, lý tính thế giới. Vì vậy, quan niệm mối liên hệ của sự vật do lực lượng siêu nhiên quy định thuộc duy tâm khách quan. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. I](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Duy tâm chủ quan cho sự vật chỉ là phức hợp những cảm giác của cá nhân, chủ thể; không dựa vào một lực lượng siêu nhiên tồn tại ngoài con người.","","Duy vật siêu hình vẫn thừa nhận vật chất có trước, nhưng xem xét sự vật cô lập, tách rời; không viện đến lực lượng siêu nhiên."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương I, mục chủ nghĩa duy tâm (duy tâm chủ quan, duy tâm khách quan)","c":2,"v":"khớp"},{"q":"Vấn đề cơ bản của triết học gồm hai mặt đó là","o":["Bản thể luận và nhận thức luận","Lý luận và thực tiễn","Tri thức và chân lý"],"a":[0],"e":"Vấn đề cơ bản của triết học có hai mặt: mặt thứ nhất là giữa ý thức và vật chất cái nào có trước, cái nào quyết định cái nào; mặt thứ hai là con người có khả năng nhận thức được thế giới hay không. Hai mặt này thường được gọi là bản thể luận và nhận thức luận. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. I](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Lý luận và thực tiễn là cặp phạm trù của lý luận nhận thức, không phải hai mặt của vấn đề cơ bản của triết học.","Tri thức và chân lý là các khái niệm của nhận thức luận, không phải hai mặt của vấn đề cơ bản."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương I, mục vấn đề cơ bản của triết học (hai mặt); tên gọi bản thể luận, nhận thức luận là cách gọi quen dùng, chưa thấy ghi nguyên văn trong đoạn này","c":1,"v":"khớp"},{"q":"Phương pháp luận là lý luận chung về","o":["Phương pháp","Giải pháp","Phương châm"],"a":[0],"e":"Phương pháp luận là lý luận về phương pháp, là hệ thống các quan điểm chỉ đạo việc tìm tòi, xây dựng, lựa chọn và vận dụng các phương pháp. Giáo trình chia thành ba cấp độ: phương pháp luận ngành, chung và chung nhất. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. I](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Giải pháp là cách giải quyết một vấn đề cụ thể, không phải đối tượng của phương pháp luận.","Phương châm là tư tưởng chỉ đạo, khẩu hiệu hành động, không phải khái niệm mà phương pháp luận là lý luận chung về nó."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương I, mục chức năng phương pháp luận của triết học","c":1,"v":"khớp"},{"q":"Tác phẩm nào được xem là đánh dấu cho sự chín muồi về tư tưởng xã hội chủ nghĩa của C.Mác và Ăng-ghen","o":["Gia đình thần thánh (1842)","Hệ tư tưởng Đức (1842)","Tuyên ngôn của Đảng cộng sản (1848)"],"a":[2],"e":"Theo giáo trình, «Tuyên ngôn của Đảng Cộng sản» (2-1848) là văn kiện có tính chất cương lĩnh đầu tiên của chủ nghĩa Mác, trình bày chủ nghĩa Mác như một chỉnh thể gồm ba bộ phận hợp thành, nên chọn C. Cần lưu ý giáo trình xem «Hệ tư tưởng Đức» là tác phẩm chín muồi đầu tiên của triết học Mác, còn Lênin lại coi «Sự khốn cùng của triết học» là tác phẩm chín muồi đầu tiên. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. III](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["«Gia đình thần thánh» xuất bản tháng 2-1845 (đề ghi 1842 là sai), phê phán phái Hêghen trẻ và mới đề xuất một số nguyên lý cơ bản, chưa phải mốc chín muồi.","«Hệ tư tưởng Đức» viết cuối 1845 đầu 1846 (đề ghi 1842 là sai), đánh dấu sự hình thành quan niệm duy vật về lịch sử, chín muồi về triết học chứ chưa trình bày chỉnh thể ba bộ phận như Tuyên ngôn.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương III, mục sự hình thành triết học Mác (Hệ tư tưởng Đức, Sự khốn cùng của triết học, Tuyên ngôn)","c":1,"v":"nghi vấn","k":"nghi vấn: Năm của A và B trong đề (1842) đều sai (thực tế 1845 và 1845-46). Giáo trình dùng cụm «chín muồi» cho Hệ tư tưởng Đức (triết học) chứ không cho Tuyên ngôn; đáp án C chỉ hợp nếu hiểu là chín muồi về tư tưởng xã hội chủ nghĩa/cương lĩnh. Giữ đáp án C theo đề."},{"q":"Triết học duy vật biện chứng là sự thống nhất giữa","o":["Thế giới quan duy vật và phương pháp luận biện chứng","Nhân sinh quan duy vật và phương pháp luận biện chứng","Thế giới quan duy vật và phương pháp luận siêu hình"],"a":[0],"e":"Triết học Mác dùng thế giới quan duy vật và phương pháp biện chứng làm cơ sở lý luận chung, nên triết học duy vật biện chứng là sự thống nhất giữa thế giới quan duy vật và phương pháp luận biện chứng. Giáo trình nói rõ cần thấm nhuần thế giới quan duy vật và phương pháp biện chứng khoa học của chủ nghĩa Mác-Lênin. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. III](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Cặp chuẩn là thế giới quan và phương pháp luận; «nhân sinh quan» là một bộ phận của thế giới quan, không phải vế đối ứng với phương pháp luận.","Phương pháp luận siêu hình đối lập với biện chứng nên không thể thống nhất với thế giới quan duy vật trong triết học Mác."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương III (triết học là cơ sở thế giới quan và phương pháp luận); chưa đối chiếu số mục","c":1,"v":"khớp"},{"q":"Biện chứng là phương pháp của khoa học nào sau đây","o":["Triết học","Đạo đức học","Chính trị học"],"a":[0],"e":"Phương pháp biện chứng là một trong hai phương pháp đối lập của triết học (với phương pháp siêu hình) và đã trải qua ba hình thức lịch sử: biện chứng tự phát, biện chứng duy tâm, biện chứng duy vật. Vì vậy biện chứng là phương pháp của triết học. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. I](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Đạo đức học nghiên cứu nguồn gốc, bản chất của đạo đức; biện chứng không phải phương pháp đặc trưng của khoa học này.","Chính trị học nghiên cứu quyền lực và hoạt động chính trị; phương pháp biện chứng được trình bày như phương pháp của triết học."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương I, mục sự đối lập giữa phương pháp siêu hình và phương pháp biện chứng","c":2,"v":"khớp"},{"q":"Giữa phạm trù triết học và phạm trù của các khoa học khác có mối quan hệ biện chứng với nhau. Mối quan hệ đó là","o":["Quan hệ giữa bản chất và hiện tượng","Quan hệ giữa cái chung và cái riêng","Quan hệ giữa nội dung và hình thức"],"a":[1],"e":"Giáo trình khẳng định giữa phạm trù của triết học và phạm trù của các khoa học cụ thể có mối quan hệ biện chứng với nhau, đó là quan hệ giữa cái chung và cái riêng. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Bản chất và hiện tượng là một cặp phạm trù khác của phép biện chứng, không phải quan hệ giữa phạm trù triết học và phạm trù khoa học cụ thể.","","Nội dung và hình thức là một cặp phạm trù khác, không dùng để mô tả quan hệ này."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VII, mục khái niệm phạm trù (đầu chương)","c":1,"v":"khớp"},{"q":"Sự vật mới ra đời bao giờ cũng trên cơ sở những cái đã có của sự vật cũ, qua đó tiến hành chọn lọc những cái tích cực, tiến bộ, phù hợp để tiếp tục phát triển. Điều này thể hiện tính chất gì của sự phát triển","o":["Tính kế thừa","Tính lặp đi lặp lại","Tính tiến lên"],"a":[0],"e":"Phủ định biện chứng có hai đặc trưng cơ bản là tính khách quan và tính kế thừa. Tính kế thừa nghĩa là cái mới chỉ ra đời trên nền tảng của cái cũ, không thủ tiêu hoàn toàn cái cũ mà chọn lọc, giữ lại yếu tố tích cực, phù hợp. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VIII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Tính lặp lại là hiện tượng chu kỳ sau dường như lặp lại chu kỳ đầu nhưng ở cấp độ cao hơn, không nói về việc chọn lọc cái đã có.","Tính tiến lên là xu hướng đi từ thấp đến cao, không phải việc dựa trên cái cũ để giữ lại cái tích cực."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VIII, mục phủ định biện chứng (tính khách quan, tính kế thừa) và đường xoáy ốc (kế thừa, lặp lại, tiến lên)","c":2,"v":"khớp"},{"q":"Mác đã kế thừa \"hạt nhân hợp lý\" trong triết học của ông để xây dựng phép biện chứng duy vật. Ông là ai?","o":["Phoiơbắc","Platon","Hêghen"],"a":[2],"e":"C.Mác và Ph.Ăngghen đã gạt bỏ tính chất thần bí, kế thừa những hạt nhân hợp lý trong phép biện chứng duy tâm để xây dựng phép biện chứng duy vật. Hạt nhân hợp lý ấy là phương pháp biện chứng của Hêghen, chứa đựng tư tưởng thiên tài về sự phát triển. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. II](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Phoiơbắc là người Mác lấy chủ nghĩa duy vật nhân bản; giáo trình nói Phoiơbắc không rút được hạt nhân hợp lý mà vứt bỏ luôn phép biện chứng của Hêghen.","Platôn là nhà duy tâm khách quan thời cổ đại với học thuyết về ý niệm, không phải nguồn «hạt nhân hợp lý» được Mác kế thừa.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương II (triết học Hêghen) và Chương I (hình thức lịch sử của phép biện chứng)","c":1,"v":"khớp","id":"krsmve"},{"q":"Theo sự phát triển của xã hội, thứ tự phát triển của các hình thức cộng đồng trong lịch sử là","o":["Thị tộc - Bộ lạc - Bộ tộc - Dân tộc","Thị tộc - Bộ tộc - Bộ lạc - Dân tộc","Dân tộc - Thị tộc - Bộ lạc - Bộ tộc"],"a":[0],"e":"Trước khi dân tộc ra đời, các hình thức cộng đồng người biến đổi từ thị tộc đến bộ lạc, bộ tộc, rồi đến dân tộc. Thứ tự đúng là thị tộc, bộ lạc, bộ tộc, dân tộc. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. XI](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Đảo bộ tộc lên trước bộ lạc; theo giáo trình bộ lạc xuất hiện trước bộ tộc.","Dân tộc là hình thức cộng đồng ra đời sau cùng, không thể đứng đầu chuỗi."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương XI (Giai cấp và dân tộc), mục dân tộc","c":4,"v":"khớp"},{"q":"Theo quan điểm của Triết học Mác- Lênin, có thể định nghĩa về vật chất như sau:","o":["Vật chất là những chất tạo nên vũ trụ","Vật chất là tồn tại khách quan","Vật chất là thực tại khách quan"],"a":[2],"e":"Lênin định nghĩa: «Vật chất là một phạm trù triết học dùng để chỉ thực tại khách quan được đem lại cho con người trong cảm giác, được cảm giác của chúng ta chép lại, chụp lại, phản ánh». Cụm cốt lõi là «thực tại khách quan». ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. V](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["«Những chất tạo nên vũ trụ» là kiểu quan niệm đồng nhất vật chất với một chất cụ thể của các nhà triết học cổ đại, giáo trình Lênin đã vượt qua.","Chỉ lệch một chữ: «tồn tại khách quan» thay cho «thực tại khách quan»; định nghĩa chuẩn dùng «thực tại khách quan» vì «tồn tại» quá rộng, không nêu được vật chất là cái được cảm giác phản ánh.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương V, mục định nghĩa vật chất của V.I.Lênin","c":2,"v":"dễ nhầm","k":"B và C chỉ khác nhau một từ («tồn tại» và «thực tại»)."},{"q":"Vật chất là tất cả những gì","o":["Tồn tại một cách cụ thể, có thể nhìn thấy","Tồn tại vô hình, thần bí ở bên ngoài thế giới khách quan","Tồn tại ở bên ngoài ý thức, được ý thức con người phản ánh","Tồn tại vô hình, không thể nhìn thấy"],"a":[2],"e":"Theo định nghĩa của Lênin, vật chất là thực tại khách quan, tồn tại bên ngoài ý thức và được ý thức con người phản ánh. Vật chất vì thế không bị giới hạn ở cái nhìn thấy được hay một dạng cụ thể nào. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. V](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Vật chất với tư cách phạm trù triết học là vật chất nói chung, khác với các dạng cụ thể mà khoa học nghiên cứu; không đồng nhất với cái cụ thể nhìn thấy được.","Tồn tại vô hình, thần bí bên ngoài thế giới khách quan là cách hiểu duy tâm, trái với tính khách quan của vật chất.","","Vật chất tồn tại khách quan dù con người có nhìn thấy hay không; «không thể nhìn thấy» không phải dấu hiệu của vật chất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương V, mục định nghĩa vật chất của V.I.Lênin","c":2,"v":"khớp"},{"q":"Vấn đề cơ bản của triết học là","o":["Quan hệ giữa vật chất và ý thức","Quan hệ giữa khách quan và chủ quan","Quan hệ giữa thực tiễn và lí luận"],"a":[0],"e":"Ăngghen chỉ rõ vấn đề cơ bản lớn của mọi triết học là quan hệ giữa tư duy và tồn tại. Giáo trình diễn đạt là quan hệ giữa ý thức và vật chất: cái nào có trước, cái nào quyết định cái nào. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. I](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Khách quan và chủ quan là cặp khái niệm khác, không phải nội dung vấn đề cơ bản của triết học.","Thực tiễn và lý luận là vấn đề của lý luận nhận thức, không phải vấn đề cơ bản của triết học."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương I, mục vấn đề cơ bản của triết học","c":1,"v":"khớp"},{"q":"Kết cấu của ý thức theo chiều dọc thì bao gồm","o":["Tự ý thức, tiềm thức, vô thức","Tự ý thức, tri thức, tiềm thức, vô thức","Các phương án trả lời đều sai"],"a":[0],"e":"Giáo trình gọi là kết cấu ý thức «theo chiều sâu của nội tâm», gồm tự ý thức, tiềm thức, vô thức. Đề dùng cách nói «chiều dọc» tương ứng với cách phân chia này, còn tri thức thuộc cách phân chia khác (các yếu tố cấu thành). ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. V](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Thêm «tri thức» là sai: tri thức là yếu tố trong cách tiếp cận theo các yếu tố cấu thành (tri thức, tình cảm, niềm tin, ý chí...), không thuộc ba tầng theo chiều sâu nội tâm.","Sai vì phương án A đã đúng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương V, mục kết cấu của ý thức (theo chiều sâu của nội tâm)","c":2,"v":"dễ nhầm","k":"Giáo trình dùng cụm «theo chiều sâu của nội tâm», còn «chiều dọc/chiều ngang» là cách gọi của đề, không thấy ghi nguyên văn trong bản này.","f":1},{"q":"Định nghĩa vật chất của Lênin được viết trong tác phẩm:","o":["Bút ký triết học","Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán","Chủ nghĩa đế quốc - giai đoạn tột cùng của chủ nghĩa tư bản","Làm gì?"],"a":[1],"e":"Định nghĩa vật chất của Lênin được nêu trong «Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán», xuất bản năm 1909, nhằm phê phán quan điểm duy tâm, siêu hình của phái Makhơ. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. III](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["«Bút ký triết học» là những ghi chép và nhận xét của Lênin khi đọc sách các nhà triết học, bổ sung phép biện chứng, không phải nơi nêu định nghĩa vật chất.","","«Chủ nghĩa đế quốc, giai đoạn tột cùng của chủ nghĩa tư bản» bàn về chủ nghĩa tư bản độc quyền, không phải nơi nêu định nghĩa vật chất.","«Làm gì?» bàn về tổ chức và xây dựng đảng, không phải tác phẩm triết học nêu định nghĩa vật chất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương III, mục V.I.Lênin phát triển triết học Mác; Chương V (định nghĩa vật chất)","c":2,"v":"khớp"},{"q":"Nền tảng lý luận của chủ nghĩa Mác- Lênin là","o":["Triết học","Kinh tế chính trị học","Chủ nghĩa xã hội khoa học"],"a":[0],"e":"Giáo trình nói triết học đóng vai trò cơ sở lý luận chung của chủ nghĩa Mác, tức cơ sở thế giới quan và phương pháp luận; triết học Mác là thế giới quan khoa học của giai cấp công nhân. Vì vậy nền tảng lý luận của chủ nghĩa Mác-Lênin là triết học. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. III](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Kinh tế chính trị học là một trong ba bộ phận hợp thành, luận giải quy luật kinh tế, không phải bộ phận đóng vai trò cơ sở thế giới quan và phương pháp luận.","Chủ nghĩa xã hội khoa học là bộ phận thứ ba, vận dụng thế giới quan và phương pháp luận triết học vào lý luận về xã hội chủ nghĩa."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương III, mục triết học Mác là cơ sở lý luận chung; chưa đối chiếu số mục","c":1,"v":"khớp"},{"q":"Bản chất của triết học duy tâm như thế nào","o":["Đi ngược lại với khoa học","Không hoàn toàn phản khoa học","Rất khoa học"],"a":[1],"e":"Giáo trình chỉ ra chủ nghĩa duy tâm triết học là sản phẩm của tư duy lý tính dựa trên cơ sở tri thức và lý trí, sai lầm của nó bắt nguồn từ việc tuyệt đối hóa, thần thánh hóa một mặt của quá trình nhận thức; Mác còn kế thừa hạt nhân hợp lý của phép biện chứng duy tâm. Vì vậy không thể nói duy tâm hoàn toàn phản khoa học. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. I](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Phủ nhận hoàn toàn là phiến diện: duy tâm triết học có yếu tố hợp lý (ví dụ phương pháp biện chứng của Hêghen).","","Duy tâm không thể «rất khoa học» vì bản chất đặt ý thức có trước và thừa nhận sự sáng tạo ra thế giới."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương I (chủ nghĩa duy tâm triết học) và Chương II (hạt nhân hợp lý của Hêghen)","c":1,"v":"dễ nhầm","k":"Giáo trình không có câu «không hoàn toàn phản khoa học»; đáp án suy ra từ các nhận định trên."},{"q":"Quan điểm nào sau đây đúng nhất","o":["Phạm trù là những thực thể ý niệm, tồn tại bên ngoài và độc lập với ý thức.","Phạm trù là những từ trống rỗng, do con người tưởng tượng ra, không biểu hiện một cái gì của hiện thực.","Phạm trù là kết quả của quá trình nhận thức, là hình ảnh chủ quan của thế giới khách quan."],"a":[2],"e":"Giáo trình nêu quan điểm của các trường phái về bản chất phạm trù: phái duy thực coi phạm trù là thực thể ý niệm tồn tại độc lập với ý thức, phái duy danh coi là từ trống rỗng. Quan điểm của chủ nghĩa Mác-Lênin là phạm trù là kết quả của quá trình nhận thức, là hình ảnh chủ quan của thế giới khách quan. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đây là quan điểm của phái duy thực: phạm trù là thực thể ý niệm tồn tại bên ngoài và độc lập với ý thức, tức duy tâm.","Đây là quan điểm của phái duy danh: phạm trù chỉ là từ trống rỗng, không biểu hiện gì của hiện thực, phủ nhận cơ sở khách quan.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VII, mục bản chất của phạm trù","c":2,"v":"khớp"},{"q":"Tất nhiên là phạm trù triết học dùng để chỉ","o":["Những gì đang tồn tại và phát triển","Những gì sẽ xuất hiện do nguyên nhân bên trong quyết định","Những gì sẽ xuất hiện trong thực tế"],"a":[1],"e":"Tất nhiên là phạm trù chỉ cái do những nguyên nhân cơ bản bên trong của kết cấu vật chất quyết định và trong những điều kiện nhất định nó phải xảy ra như thế chứ không thể khác. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["«Những gì đang tồn tại và phát triển» quá chung, thuộc phạm trù hiện thực, không nêu nguyên nhân bên trong quyết định.","","«Những gì sẽ xuất hiện trong thực tế» quá chung và không gắn với nguyên nhân cơ bản bên trong, nên chưa phân biệt được tất nhiên với ngẫu nhiên."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VII, mục khái niệm tất nhiên và ngẫu nhiên","c":2,"v":"khớp"},{"q":"Quan điểm nào cho rằng sự phát triển chỉ là sự tăng, giảm đơn thuần về mặt lượng, không có sự thay đổi về chất","o":["Quan điểm duy vật","Quan điểm duy tâm","Quan điểm siêu hình"],"a":[2],"e":"Quan điểm siêu hình xem sự phát triển chỉ là sự tăng hay giảm đơn thuần về lượng, hoặc chỉ thay đổi theo vòng khép kín, không có sự thay đổi về chất và không sinh ra cái mới. Quan điểm biện chứng thì coi phát triển là sự thay đổi về lượng dẫn đến thay đổi về chất. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VI](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Duy vật là lập trường về vấn đề cơ bản (vật chất có trước); duy vật biện chứng còn coi phát triển gồm cả thay đổi về chất.","Duy tâm là lập trường về vấn đề cơ bản (ý thức có trước), không phải cách nhìn nhận phát triển thuần túy về lượng.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VI (mục quan điểm siêu hình và biện chứng về phát triển)","c":2,"v":"khớp"},{"q":"Thuộc tính cơ bản được Lênin rút ra trong định nghĩa phạm trù vật chất là","o":["Thực tại khách quan","Thực tế khách quan","Tồn tại khách quan"],"a":[0],"e":"Trong định nghĩa của Lênin, thuộc tính cơ bản của vật chất là tính «thực tại khách quan», tức tồn tại độc lập với ý thức và được ý thức phản ánh. Giáo trình trích: «Vật chất là một phạm trù triết học dùng để chỉ thực tại khách quan...». ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. V](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","«Thực tế» khác «thực tại»; định nghĩa của Lênin dùng «thực tại khách quan», không phải «thực tế khách quan».","«Tồn tại khách quan» là cách diễn đạt gần nghĩa nhưng không đúng cụm trong định nghĩa; lệch một chữ so với «thực tại khách quan»."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương V, mục định nghĩa vật chất của V.I.Lênin","c":2,"v":"dễ nhầm","k":"Ba phương án chỉ khác nhau một từ gần nghĩa; đáp án A đúng cụm từ trong định nghĩa."},{"q":"Chủ nghĩa Mác-Lênin ra đời vào khoảng thời gian nào","o":["Giữa thế kỷ XIX","Đầu thế kỷ XIX","Đầu thế kỷ XX","Cuối thế kỷ XIX"],"a":[0],"e":"Giáo trình viết triết học Mác ra đời vào những năm 40 của thế kỷ XIX, tức giữa thế kỷ XIX (đỉnh cao là «Tuyên ngôn của Đảng Cộng sản» tháng 2-1848). Lênin phát triển chủ nghĩa Mác từ cuối thế kỷ XIX đầu thế kỷ XX. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. III](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Đầu thế kỷ XIX là thời kỳ trước khi chủ nghĩa Mác ra đời, thời của các nhà xã hội chủ nghĩa không tưởng và triết học cổ điển Đức.","Đầu thế kỷ XX là giai đoạn Lênin vận dụng và phát triển chủ nghĩa Mác, không phải lúc ra đời.","Cuối thế kỷ XIX là thời kỳ chủ nghĩa Mác đã ra đời và đang lan rộng; chủ nghĩa Mác hình thành vào những năm 40, tức giữa thế kỷ."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương III, mục điều kiện ra đời triết học Mác (những năm 40 của thế kỷ XIX); Chương I","c":1,"v":"dễ nhầm","k":"Đề hỏi «chủ nghĩa Mác-Lênin» nhưng đáp án tính theo thời điểm ra đời của chủ nghĩa Mác (những năm 40 thế kỷ XIX)."},{"q":"Cặp phạm trù nguyên nhân, kết quả chỉ ra","o":["Một kết quả có thể được tạo ra bởi nhiều nguyên nhân khác nhau","Một kết quả chỉ được tạo ra bởi một nguyên nhân cơ bản","Các phương án trả lời đều sai"],"a":[0],"e":"Theo giáo trình, nguyên nhân sinh ra kết quả rất phức tạp vì còn phụ thuộc nhiều điều kiện, hoàn cảnh: một kết quả có thể do nhiều nguyên nhân sinh ra (ví dụ mất mùa do hạn hán, lũ lụt, sâu bệnh), và một nguyên nhân có thể gây ra nhiều kết quả. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Một kết quả chỉ do một nguyên nhân là cách hiểu giản đơn; giáo trình nêu một kết quả có thể do nhiều nguyên nhân.","Sai vì phương án A đã đúng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VII, mục nguyên nhân và kết quả","c":2,"v":"khớp","f":1},{"q":"Theo Ăng-ghen, có thể chia vận động thành:","o":["Bốn hình thức vận động cơ bản","Năm hình thức vận động cơ bản","Sáu hình thức vận động cơ bản"],"a":[1],"e":"Dựa trên thành tựu khoa học của thời mình, Ph.Ăngghen phân chia vận động thành 5 hình thức cơ bản: vận động cơ học, vật lý, hóa học, sinh học và xã hội. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. V](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Bốn hình thức là thiếu một hình thức; Ăngghen có đủ cơ học, vật lý, hóa học, sinh học, xã hội.","","Sáu hình thức là thừa một hình thức; Ăngghen chỉ chia thành năm."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương V, mục vận động và các hình thức cơ bản của vận động","c":2,"v":"khớp"},{"q":"Mối liên hệ nhân quả có các tính chất cơ bản nào sau đây","o":["Tính khách quan, tính phổ biến, tính đa dạng.","Tính khách quan, tính phổ biến, kế thừa.","Tính khách quan, tính phổ biến, tính tất yếu."],"a":[2],"e":"Phép biện chứng duy vật khẳng định mối liên hệ nhân quả có tính khách quan, tính phổ biến và tính tất yếu. Mỗi tính chất được giáo trình giải thích: nhân quả vốn có của sự vật, không sự vật nào không có nguyên nhân, và cùng điều kiện thì nguyên nhân gây ra kết quả như nhau. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["«Tính đa dạng» là tính chất của mối liên hệ nói chung, không nằm trong ba tính chất của nhân quả (khách quan, phổ biến, tất yếu).","«Kế thừa» là đặc trưng của phủ định biện chứng, không phải tính chất của mối liên hệ nhân quả.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VII, mục nguyên nhân và kết quả (tính chất của mối liên hệ nhân quả)","c":2,"v":"khớp"},{"q":"Phạm trù triết học nào dùng để chỉ tính quy định khách quan vốn có của sự vật và hiện tượng, sự thống nhất hữu cơ của các thuộc tính làm cho nó là nó mà không phải là cái khác","o":["Bước nhảy","Lượng","Chất"],"a":[2],"e":"Chất là phạm trù triết học dùng để chỉ tính quy định khách quan vốn có của sự vật, là sự thống nhất hữu cơ của những thuộc tính làm cho sự vật là nó chứ không phải là cái khác. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VIII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Bước nhảy chỉ sự chuyển hóa về chất, là giai đoạn chuyển hóa căn bản của sự vật, không phải tính quy định làm sự vật là nó.","Lượng chỉ tính quy định về số lượng, quy mô, trình độ, nhịp điệu; lượng chưa làm cho sự vật là nó.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VIII, mục khái niệm chất, lượng trong quy luật lượng-chất","c":2,"v":"khớp"},{"q":"Khẳng định nào sau đây là đúng?","o":["Mỗi sự vật cụ thể được đặc trưng bằng nhiều hình thức vận động","Hình thức vận động cao luôn bao hàm các hình thức vận động thấp, nhưng không có chiều ngược lại","Có sự vật không vận động","Có thể quy hình thức vận động cao về hình thức vận động thấp và ngược lại"],"a":[1],"e":"Giáo trình nêu: các hình thức vận động cao xuất hiện trên cơ sở các hình thức thấp, bao hàm trong nó tất cả các hình thức thấp hơn, còn hình thức thấp không bao hàm được hình thức cao, nên mọi sự quy giản hình thức cao về thấp đều sai lầm. Vì vậy B đúng. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. V](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Gần đúng nhưng chưa chuẩn: giáo trình viết mỗi sự vật có thể gắn liền với nhiều hình thức vận động, song sự tồn tại của nó bao giờ cũng đặc trưng bằng một hình thức vận động cơ bản.","","Vận động là phương thức tồn tại của vật chất, không có sự vật nào không vận động.","Quy hình thức cao về thấp và ngược lại là khuynh hướng sai lầm trong nhận thức, vì các hình thức vận động khác nhau về chất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương V, mục vận động và quan hệ giữa các hình thức vận động","c":2,"v":"dễ nhầm","k":"Phương án A có thể bị coi là đúng một phần (mỗi sự vật gắn với nhiều hình thức vận động), nhưng giáo trình nhấn mạnh sự vật đặc trưng bằng một hình thức cơ bản; B là phương án đúng nhất."},{"q":"Chọn phương án phản ánh quan điểm Mác-Lênin","o":["Trong giới hạn của độ, lượng của sự vật thay đổi nhưng chất của sự vật chưa thay đổi cơ bản","Trong giới hạn của độ, sự thay đổi về lượng hoàn toàn không làm ảnh hưởng tới sự thay đổi chất của sự vật","Bước nhảy là sự thay đổi về lượng của sự vật","Sự thay đổi về lượng sẽ làm thay đổi ngay lập tức chất của sự vật"],"a":[0],"e":"Độ là khoảng giới hạn trong đó sự thay đổi về lượng của sự vật chưa làm thay đổi căn bản chất của sự vật ấy. Chất chỉ đổi khi lượng đạt đến điểm nút và xảy ra bước nhảy. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VIII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Tuyệt đối hóa: trong độ lượng và chất vẫn có quan hệ thống nhất, lượng đổi dần tích lũy cho bước nhảy; không phải «hoàn toàn không ảnh hưởng».","Bước nhảy là sự chuyển hóa về chất, không phải sự thay đổi về lượng.","Chất chỉ thay đổi khi lượng vượt quá độ, đến điểm nút; không đổi ngay lập tức theo mỗi thay đổi về lượng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VIII, mục quy luật chuyển hóa từ những thay đổi về lượng thành những thay đổi về chất (độ, điểm nút, bước nhảy)","c":2,"v":"khớp"},{"q":"Quan điểm toàn diện yêu cầu","o":["Phải xem xét tất cả các mối liên hệ, đồng thời phân loại được vị trí, vai trò của các mối liên hệ.","Xem xét tất cả các mối liên hệ, lấy mối liên hệ thứ yếu làm mối liên hệ chủ yếu, không cơ bản làm cơ bản.","Xem xét tất cả các mối liên hệ và coi vị trí, vai trò của các mối liên hệ đó là như nhau.","Chỉ xem xét những mối liên hệ đóng vai trò quyết định sự tồn tại và phát triển của sự vật."],"a":[0],"e":"Quan điểm toàn diện đòi hỏi nhận thức sự vật trong mối liên hệ qua lại giữa các bộ phận, yếu tố, mặt của sự vật và với các sự vật khác. Đồng thời phải biết phân biệt từng mối liên hệ, chú ý mối liên hệ bên trong, bản chất, chủ yếu, tất nhiên. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VI](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Lấy mối liên hệ thứ yếu làm chủ yếu là sai phương pháp, trái với yêu cầu phân biệt vị trí, vai trò các mối liên hệ.","Coi mọi mối liên hệ vai trò như nhau là cách nhìn dàn đều, không phân biệt chủ yếu, thứ yếu.","Chỉ xét mối liên hệ quyết định là phiến diện, trái với yêu cầu xem xét tất cả các mối liên hệ."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VI, mục ý nghĩa phương pháp luận (quan điểm toàn diện)","c":2,"v":"khớp"},{"q":"Vật chất là tất cả những gì","o":["Chỉ có một thế giới duy nhất là thế giới vật chất","Mọi bộ phận của thế giới vật chất đều liên hệ chuyển hóa lẫn nhau","Thế giới vật chất tồn tại vĩnh viễn, khách quan, vô hạn, vô tận, không do ai sinh ra và không mất đi","Thế giới vật chất bao gồm những bộ phận riêng biệt nhau"],"a":[2],"e":"Nội dung này là một ý của nguyên lý về sự thống nhất vật chất của thế giới: thế giới vật chất tồn tại vĩnh viễn, vô hạn và vô tận, không được sinh ra và không bị mất đi. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. V](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Chỉ có một thế giới duy nhất là thế giới vật chất là ý khác của nguyên lý thống nhất, không phải ý nói về sự tồn tại vĩnh viễn, vô hạn.","Mọi bộ phận của thế giới vật chất liên hệ, chuyển hóa lẫn nhau là ý về mối liên hệ phổ biến, không phải về tính vĩnh viễn, vô tận.","","Cho thế giới gồm những bộ phận riêng biệt nhau là quan điểm siêu hình, trái với tính thống nhất của thế giới."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương V, mục tính thống nhất vật chất của thế giới","c":2,"v":"dễ nhầm","k":"Đề cụt/mất dẫn nhập (lặp lại «Vật chất là tất cả những gì» nhưng các phương án là nội dung của nguyên lý thống nhất thế giới); đáp án C khớp ý «vĩnh viễn, vô hạn, vô tận, không sinh ra và không mất đi» của giáo trình."},{"q":"Chọn phương án đúng theo quan điểm của triết học Mác Lênin","o":["Mâu thuẫn biện chứng là sự liên hệ, tác động qua lại giữa các mặt đối lập","Trong tư duy không có mâu thuẫn biện chứng","Cứ hai mặt đối lập là tạo thành một mâu thuẫn biện chứng","Mâu thuẫn biện chứng trong tư duy độc lập với mâu thuẫn trong hiện thực"],"a":[0],"e":"Các mặt đối lập nằm trong sự liên hệ, tác động qua lại lẫn nhau tạo thành mâu thuẫn biện chứng. Mâu thuẫn biện chứng tồn tại khách quan, phổ biến trong tự nhiên, xã hội và tư duy; mâu thuẫn trong tư duy phản ánh mâu thuẫn trong hiện thực. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VIII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Mâu thuẫn biện chứng tồn tại cả trong tự nhiên, xã hội và tư duy.","Hai mặt đối lập chỉ tạo thành mâu thuẫn khi nằm trong sự liên hệ, tác động qua lại; không phải cứ hai mặt đối lập là mâu thuẫn.","Mâu thuẫn trong tư duy là phản ánh mâu thuẫn trong hiện thực, không độc lập với hiện thực."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VIII, mục quy luật thống nhất và đấu tranh của các mặt đối lập (khái niệm mâu thuẫn biện chứng)","c":2,"v":"khớp"},{"q":"Chọn phương án đúng theo quan điểm triết học Mác- Lênin","o":["Lượng của sự vật luôn được diễn tả bằng những con số chính xác","Có những lượng không biểu thị yếu tố nào của sự vật","Mỗi sự vật chỉ có một lượng","Có những lượng biểu thị yếu tố quy định kết cấu bên trong sự vật"],"a":[3],"e":"Giáo trình nêu lượng có thể xác định bằng đơn vị đo cụ thể hoặc chỉ biểu thị dưới dạng trừu tượng, khái quát; có những lượng biểu thị yếu tố quy định kết cấu bên trong của sự vật (số lượng nguyên tử hợp thành nguyên tố hóa học, số lĩnh vực cơ bản của đời sống xã hội). ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VIII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Tuyệt đối hóa «luôn»: có lượng chỉ biểu thị dạng trừu tượng, khái quát, như trình độ tri thức hay ý thức trách nhiệm.","Lượng là cái vốn có của sự vật và khách quan, biểu thị các yếu tố như kích thước, quy mô, trình độ, nhịp điệu.","Mỗi sự vật có nhiều lượng (kích thước, số lượng, quy mô, trình độ, nhịp điệu...), không chỉ một lượng.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VIII, mục khái niệm lượng","c":2,"v":"khớp"},{"q":"Quy luật bao giờ cũng mang tính:","o":["Khách quan","Chủ quan","Cả khách quan và chủ quan","Phụ thuộc vào ý thức con người"],"a":[0],"e":"Quy luật là mối liên hệ khách quan, bản chất, tất nhiên, phổ biến và lặp lại giữa các sự vật, hiện tượng; giáo trình nhấn mạnh quy luật khách quan tồn tại không phụ thuộc ý thức con người, con người chỉ nhận thức và vận dụng quy luật. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VIII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Quy luật mang tính chủ quan là quan điểm duy tâm, tách quy luật khỏi hiện thực khách quan.","Không có thành phần chủ quan trong bản thân quy luật; chủ quan chỉ ở khâu con người nhận thức, vận dụng.","Quy luật không phụ thuộc vào ý thức con người; con người chỉ có thể tác động làm quy luật phát huy nhanh hay chậm."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VIII, mục khái niệm quy luật; chưa đối chiếu câu chữ chính xác của định nghĩa","c":2,"v":"khớp"},{"q":"Luận điểm nào sau đây là đúng?","o":["Chất mới của sự vật ra đời không tác động trở lại lượng của sự vật","Chất mới ra đời chỉ làm thay đổi kết cấu nhưng không làm thay đổi quy mô, trình độ, nhịp điệu của sự vận động và phát triển của sự vật","Chất mới ra đời có thể làm thay đổi kết cấu, quy mô, trình độ, nhịp điệu của sự vận động và phát triển của sự vật","Chất mới ra đời chỉ làm thay đổi quy mô, trình độ, nhịp điệu của sự vận động và phát triển của sự vật nhưng không làm thay đổi kết cấu của sự vật"],"a":[2],"e":"Chất mới của sự vật ra đời sẽ tác động trở lại lượng của sự vật: chất mới có thể làm thay đổi kết cấu, quy mô, trình độ, nhịp điệu của sự vận động và phát triển của sự vật. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VIII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Sai vì chất mới ra đời tác động trở lại lượng của sự vật.","Sai vì chất mới làm thay đổi cả quy mô, trình độ, nhịp điệu chứ không chỉ kết cấu (tuyệt đối hóa «chỉ»).","","Sai vì chất mới cũng làm thay đổi kết cấu, không chỉ quy mô, trình độ, nhịp điệu."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VIII, mục quy luật chuyển hóa từ lượng thành chất (tác động trở lại của chất mới)","c":2,"v":"khớp"},{"q":"Tính quy định nói lên quy mô, trình độ phát triển của sự vật gọi là gì?","o":["Bước nhảy","Độ","Lượng","Chất"],"a":[2],"e":"Lượng là phạm trù triết học dùng để chỉ tính quy định vốn có của sự vật về mặt số lượng, quy mô, trình độ, nhịp điệu của sự vận động và phát triển cũng như các thuộc tính của sự vật. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VIII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Bước nhảy là sự chuyển hóa về chất, không phải tính quy định về quy mô, trình độ.","Độ là khoảng giới hạn trong đó lượng đổi mà chất chưa đổi căn bản.","","Chất là tính quy định làm sự vật là nó, khác cái khác; lượng mới nói quy mô, trình độ."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VIII, mục khái niệm lượng","c":2,"v":"khớp"},{"q":"Yếu tố cách mạng nhất trong lực lượng sản xuất là:","o":["Phương tiện lao động","Người lao động","Đối tượng lao động","Công cụ lao động"],"a":[3],"e":"Công cụ lao động là yếu tố động nhất của lực lượng sản xuất; sự cải tiến, hoàn thiện không ngừng công cụ lao động làm biến đổi toàn bộ tư liệu sản xuất và xét đến cùng là nguyên nhân sâu xa của mọi biến đổi xã hội. Giáo trình xếp công cụ lao động là yếu tố đóng vai trò quyết định trong tư liệu sản xuất. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Phương tiện lao động là khái niệm rộng, nằm cạnh công cụ trong tư liệu lao động; yếu tố động nhất là công cụ lao động.","Người lao động là chủ thể của quá trình sản xuất và là yếu tố quyết định hàng đầu, nhưng giáo trình gọi công cụ lao động là yếu tố động nhất, cách mạng nhất.","Đối tượng lao động chịu tác động của công cụ và ít là yếu tố thúc đẩy biến đổi.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương X, mục lực lượng sản xuất (người lao động, công cụ lao động)","c":3,"v":"khớp","k":"Giáo trình viết «yếu tố động nhất»; cụm «cách mạng nhất» trong đề là cách nói quen dùng, không thấy nguyên văn."},{"q":"Cách thức của sự phát triển là","o":["Đấu tranh của các mặt đối lập để giải quyết mâu thuẫn","Sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại","Hai lần phủ định"],"a":[1],"e":"Quy luật chuyển hóa từ những thay đổi về lượng thành những thay đổi về chất và ngược lại chỉ ra cách thức của sự vận động, phát triển: lượng đổi dần tích lũy, đến điểm nút thì xảy ra bước nhảy làm chất đổi, và chất mới lại tác động trở lại lượng. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. VIII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đấu tranh của các mặt đối lập để giải quyết mâu thuẫn là nguồn gốc, động lực của sự phát triển, không phải cách thức.","","Hai lần phủ định (phủ định của phủ định) chỉ khuynh hướng, hình thức xoáy ốc của phát triển, không phải cách thức."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương VIII, mục quy luật lượng-chất; cụm «cách thức của phát triển» chưa thấy nguyên văn trong bản này","c":2,"v":"dễ nhầm","k":"Cách gọi «cách thức / nguồn gốc, động lực / khuynh hướng» cho ba quy luật là cách tóm tắt phổ biến, không thấy nguyên văn trong bản giáo trình cũ này."},{"q":"Quy luật xã hội nào giữ vai trò quyết định nhất đối với sự vận động, phát triển của xã hội?","o":["Quy luật tồn tại xã hội quyết định ý thức xã hội","Quy luật về sự phù hợp của quan hệ sản xuất với trình độ phát triển của lực lượng sản xuất","Quy luật đấu tranh giai cấp","Quy luật cơ sở hạ tầng quyết định kiến trúc thượng tầng"],"a":[1],"e":"Giáo trình khẳng định quy luật về sự phù hợp của quan hệ sản xuất với trình độ phát triển của lực lượng sản xuất là quy luật cơ bản nhất của sự vận động, phát triển xã hội, vì nhờ đó giải thích sự thay thế các hình thái kinh tế-xã hội. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Ch. X](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Quy luật tồn tại xã hội quyết định ý thức xã hội là quy luật quan trọng nhưng giáo trình không xếp là quy luật cơ bản nhất.","","Đấu tranh giai cấp là động lực quan trọng trong xã hội có giai cấp, nhưng bản thân nó bị quy định bởi mâu thuẫn lực lượng sản xuất-quan hệ sản xuất.","Quy luật cơ sở hạ tầng quyết định kiến trúc thượng tầng là quy luật quan trọng, nhưng cơ sở hạ tầng bản thân do quan hệ sản xuất hợp thành và chịu sự chi phối của quy luật cơ bản nhất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản cũ tái bản lần 3), Chương X, mục các quy luật cơ bản của sự vận động, phát triển xã hội","c":3,"v":"khớp"},{"q":"Nguồn gốc lý luận trực tiếp của triết học Mác là","o":["Triết học Hy Lạp cổ đại","Triết học cổ điển Đức","Triết học tây Âu trung cổ"],"a":[1],"e":"Nguồn gốc lý luận trực tiếp của triết học Mác là triết học cổ điển Đức, đặc biệt những «hạt nhân hợp lý» trong triết học của Hêghen (phép biện chứng) và Phoiơbắc (chủ nghĩa duy vật); Mác cải tạo cả hai để xây dựng chủ nghĩa duy vật biện chứng. ([Giáo trình Triết học Mác-Lênin 2019, tr.26-27](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Triết học Hy Lạp cổ đại là một nguồn tư tưởng của lịch sử triết học nhưng giáo trình không xem là nguồn gốc lý luận trực tiếp; nguồn trực tiếp là triết học cổ điển Đức.","","Triết học Tây Âu thời Trung cổ chịu chi phối của thần học, không phải nguồn gốc lý luận trực tiếp của triết học Mác."],"s":"GT Triết học Mác-Lênin (2019), Ch.1, mục II (Sự ra đời và phát triển của triết học Mác-Lênin), phần «Nguồn gốc lý luận», tr.26-27; bản cũ tái bản lần 3 cũng viết như vậy ở Chương III","c":1,"v":"khớp"},{"q":"Theo triết học Mác-Lênin, khẳng định nào sau đây là đúng?","o":["Ý thức là sự phản ánh hiện thực khách quan theo nhu cầu nhận thức của con người","Ý thức là hình ảnh chủ quan của thế giới khách quan, là tinh thần so với thế giới vật chất.","Ý thức con người mang tính năng động sáng tạo lại hiện thực theo nhu cầu của nhận thức.","Ý thức là quá trình phản ánh hiện thực khách quan vào trong bộ óc con người một cách đơn giản, nguyên xi"],"a":[1],"e":"Giáo trình viết: bản chất ý thức là hình ảnh chủ quan của thế giới khách quan, là quá trình phản ánh tích cực, sáng tạo hiện thực khách quan của óc người; về nội dung ý thức là khách quan, về hình thức là chủ quan. Phương án B nêu đúng định nghĩa này: ý thức là tinh thần so với thế giới vật chất. ([Giáo trình Triết học Mác-Lênin 2019, tr.83-84](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Ý thức phản ánh hiện thực khách quan chứ không phản ánh «theo nhu cầu nhận thức»; cách nói này đưa yếu tố chủ quan vào làm tiêu chí của phản ánh và không nêu được bản chất của ý thức.","","Tính năng động, sáng tạo đúng là một đặc điểm của phản ánh ý thức, nhưng «sáng tạo lại hiện thực theo nhu cầu» chỉ nêu một mặt và không phải định nghĩa bản chất; đáp án chuẩn là B.","Phản ánh «đơn giản, nguyên xi» là quan niệm của chủ nghĩa duy vật siêu hình; chủ nghĩa duy vật biện chứng coi phản ánh là tích cực, sáng tạo."],"s":"GT Triết học Mác-Lênin (2019), Ch.2, mục I.2 (Nguồn gốc, bản chất và kết cấu của ý thức), tr.83-84","c":2,"v":"dễ nhầm","k":"Phương án A và C có phần đúng về tinh thần (phản ánh năng động, sáng tạo); chỉ B bám sát nguyên văn định nghĩa trong giáo trình nên là đáp án."},{"q":"Luận điểm nào sau đây là đúng?","o":["Nguyên nhân giống nhau tác động trong những điều kiện giống nhau cũng có thể đưa đến kết quả khác nhau","Nguyên nhân khác nhau tác động trong những điều kiện như nhau luôn đưa đến kết quả như nhau","Nguyên nhân tác động trong những điều kiện và hoàn cảnh càng ít khác nhau bao nhiêu thì kết quả do chúng gây ra càng giống nhau bấy nhiêu","Nguyên nhân giống nhau tác động trong những điều kiện khác nhau có thể đưa đến kết quả như nhau"],"a":[2],"e":"Do kết quả phụ thuộc cả vào điều kiện, hoàn cảnh nên một nguyên nhân nhất định trong hoàn cảnh nhất định chỉ gây ra một kết quả nhất định; vì vậy nguyên nhân tác động trong điều kiện, hoàn cảnh càng ít khác nhau bao nhiêu thì kết quả càng giống nhau bấy nhiêu. ([Giáo trình Triết học Mác-Lênin 2019, tr.109](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf); [bản cũ tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Sai: nguyên nhân giống nhau trong điều kiện (hoàn toàn) giống nhau thì gây ra kết quả như nhau; không thể có kết quả khác nhau.","Sai: nguyên nhân khác nhau thì kết quả nói chung khác nhau; không thể khẳng định «luôn như nhau».","","Sai: điều kiện khác nhau thì cùng một nguyên nhân sẽ cho kết quả khác nhau; kết quả như nhau chỉ khi điều kiện, hoàn cảnh ít khác nhau."],"s":"GT Triết học Mác-Lênin (2019), Ch.2, mục II.2 (quan hệ nhân quả), tr.109; bản cũ tái bản lần 3, Chương VII (phạm trù nguyên nhân - kết quả)","c":2,"v":"khớp"},{"q":"Chọn phương án phản ánh quan điểm của chủ nghĩa duy tâm","o":["Ý thức là thực thể độc lập, sáng tạo ra vật chất","Ý thức là sự phản ánh nguyên xi hiện thực khách quan vào bộ óc con người.","Ý thức là sự phản ánh năng động, sáng tạo hiện thực khách quan vào bộ óc con người","Ýthức là sự phản ánh thụ động hiện thực khách quan vào bộ óc con người."],"a":[0],"e":"Chủ nghĩa duy tâm coi ý thức, tinh thần có trước và quyết định vật chất, nên phương án A (ý thức là thực thể độc lập, sáng tạo ra vật chất) phản ánh quan điểm duy tâm. Ba phương án còn lại bàn về ý thức như sự phản ánh hiện thực khách quan vào óc người, tức là lập trường duy vật. ([Giáo trình Triết học Mác-Lênin 2019, tr.17-18, 83-84](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Coi ý thức là sự phản ánh nguyên xi hiện thực khách quan là quan niệm duy vật (siêu hình), không phải duy tâm.","Phản ánh năng động, sáng tạo hiện thực khách quan vào óc người là quan điểm duy vật biện chứng.","Phản ánh thụ động hiện thực khách quan là quan điểm duy vật siêu hình, vẫn thừa nhận vật chất có trước."],"s":"GT Triết học Mác-Lênin (2019), Ch.1, mục I.2 (chủ nghĩa duy vật và chủ nghĩa duy tâm), tr.17-18; Ch.2, mục I.2, tr.83-84","c":2,"v":"khớp"},{"q":"Khẳng định nào sau đây là đúng?","o":["Có sự vật không vận động","Hình thức vận động cao luôn bao hàm các hình thức vận động thấp, nhưng không có chiều ngược lại","Mỗi sự vật cụ thể được đặc trưng bằng nhiều hình thức vận động","Có thể quy hình thức vận động cao về hình thức vận động thấp và ngược lại"],"a":[1],"e":"Theo giáo trình, các hình thức vận động có mối liên hệ phát sinh: hình thức vận động cao nảy sinh trên cơ sở và bao hàm các hình thức vận động thấp, còn hình thức thấp không bao hàm được hình thức cao; hình thức cao khác về chất nên không thể quy về hình thức thấp. ([Giáo trình Triết học Mác-Lênin 2019, tr.71](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf); [bản cũ tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Sai: vận động là thuộc tính cố hữu của vật chất, «không ở đâu có vật chất không vận động».","","Sai ở chữ «nhiều»: mỗi sự vật có thể gắn với nhiều hình thức vận động nhưng được đặc trưng bằng một hình thức vận động cơ bản (bản cũ, Chương V).","Sai: không thể quy hình thức vận động cao về hình thức thấp; quy giản như vậy là sai lầm (siêu hình)."],"s":"GT Triết học Mác-Lênin (2019), Ch.2, mục I.1 (hình thức tồn tại của vật chất - vận động), tr.70-71; bản cũ tái bản lần 3, Chương V","c":2,"v":"khớp"},{"q":"Luận điểm nào không phải là câu trả lời của chủ nghĩa Mác-lênin về tính thống nhất vật chất của thế giới?","o":["Mọi bộ phận của thế giới vật chất đều liên hệ chuyển hóa lẫn nhau","Chỉ có một thế giới duy nhất là thế giới vật chất","Thế giới vật chất tồn tại vĩnh viễn, khách quan, vô hạn, vô tận, không do ai sinh ra và không mất đi","Thế giới vật chất bao gồm những bộ phận riêng biệt nhau"],"a":[3],"e":"Đây là câu hỏi «không phải». Chủ nghĩa Mác - Lênin khẳng định chỉ có một thế giới duy nhất là thế giới vật chất, mọi bộ phận của nó có mối quan hệ vật chất thống nhất, vận động, chuyển hoá lẫn nhau, và nó tồn tại vĩnh viễn, vô hạn, vô tận, không do ai sinh ra. Luận điểm «gồm những bộ phận riêng biệt nhau» đi ngược lại tính thống nhất, nên không phải câu trả lời của Mác - Lênin. ([Giáo trình Triết học Mác-Lênin 2019, tr.76-77](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Đây là luận điểm của Mác - Lênin: mọi bộ phận của thế giới có liên hệ, chuyển hoá lẫn nhau.","Đây là luận điểm của Mác - Lênin: chỉ một thế giới duy nhất và thống nhất là thế giới vật chất.","Đây là luận điểm của Mác - Lênin: thế giới vật chất không do ai sinh ra, không tự mất đi, tồn tại vĩnh viễn, vô hạn, vô tận.",""],"s":"GT Triết học Mác-Lênin (2019), Ch.2, mục I.1, phần «Tính thống nhất vật chất của thế giới», tr.76-77","c":2,"v":"khớp"},{"q":"\"Cái cối xay quay bằng tay đưa lại xã hội có lãnh chúa phong kiến, cái cối xay chạy bằng máy hơi nước đưa xã hội có nhà tư bản công nghiệp\". Thí dụ có hình ảnh trên nhằm nêu bật vai trò quyết định, xét đến cùng, trị sự phát triển là yếu tố nào?","o":["Đối tượng lao động","Lực lượng sản xuất","Tư liệu sản xuất","Công cụ lao động"],"a":[3],"e":"Câu của C. Mác (trong «Sự khốn cùng của triết học») lấy cái cối xay làm ví dụ cho công cụ lao động: thay đổi công cụ thì phương thức sản xuất và các quan hệ xã hội đổi theo; công cụ lao động là yếu tố động nhất của lực lượng sản xuất. Đề chọn công cụ lao động. ([Giáo trình Triết học Mác-Lênin 2019, tr.151](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf); [câu hỏi tương tự, đáp án công cụ lao động](https://doctailieu.com/trac-nghiem/c-mac-viet-cai-coi-xay-quay-bang-tay-dua-lai-cho-xa-hoi-phong-kien-cai-coi-17808))","w":["Đối tượng lao động (đất, nước, nguyên liệu...) không phải yếu tố mà ví dụ cái cối xay nhấn mạnh.","Giáo trình dùng chính đoạn trích này để minh họa lực lượng sản xuất quyết định quan hệ sản xuất, nên B có lý về mặt giáo trình; nhưng ví dụ cái cối xay cụ thể chỉ công cụ lao động, là thành tố động nhất của lực lượng sản xuất.","Tư liệu sản xuất gồm cả công cụ và đối tượng lao động, là khái niệm rộng; ví dụ cái cối xay chỉ đích danh công cụ lao động.",""],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục I.2 (biện chứng giữa lực lượng sản xuất và quan hệ sản xuất), tr.151; C. Mác, «Sự khốn cùng của triết học» (chưa đọc tác phẩm gốc, chỉ theo giáo trình)","c":3,"v":"dễ nhầm","k":"Giáo trình 2019 trích câu này để chứng minh «lực lượng sản xuất quyết định quan hệ sản xuất» (đáp án B cũng có thể được chấp nhận); đáp án D của đề theo cách hiểu «cối xay = công cụ lao động», trùng với đáp án các ngân hàng câu hỏi khác. Đề cũng cụt chữ («trị sự phát triển»)."},{"q":"Mỗi sự vật trong điều kiện xác định.","o":["Chỉ có một thuộc tính xác định","Có một số thuộc tính xác định","Có vô văn thuộc tính xác định","Có một hoặc một số thuộc tính xác định"],"a":[3],"e":"Giáo trình không nêu nguyên văn mệnh đề này. Giáo trình chỉ nói chất của sự vật biểu hiện qua các thuộc tính, mỗi sự vật có nhiều thuộc tính (cơ bản và không cơ bản), và khái niệm phản ánh «một hoặc một số thuộc tính». Vì đề chép cụt/lỗi chính tả nên đáp án D («một hoặc một số thuộc tính xác định») chỉ là cách hiểu theo ngân hàng đề, chưa kiểm chứng được. ([Giáo trình Triết học Mác-Lênin 2019, tr.118-119](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Chỉ có một thuộc tính» trái với giáo trình: mỗi sự vật có nhiều thuộc tính, gồm thuộc tính cơ bản và không cơ bản.","«Có một số thuộc tính» thiếu trường hợp chỉ có một thuộc tính, nên bị coi là chưa bao quát theo đáp án của đề.","«Vô vàn thuộc tính» là cách nói tuyệt đối hoá; giáo trình không khẳng định vô số thuộc tính xác định trong điều kiện xác định.",""],"s":"GT Triết học Mác-Lênin (2019), Ch.2, mục II.2 (quy luật lượng - chất, khái niệm chất và thuộc tính), tr.118-119; chưa tìm được câu nguyên văn tương ứng","c":2,"v":"nghi vấn","k":"nghi vấn: Đề cụt và lỗi chính tả («thuộc tỉnh», «vô văn»); ngữ cảnh gốc không rõ. Không tìm thấy nguồn xác nhận trực tiếp đáp án D; cần xem lại đề gốc.","id":"1vm2yra"},{"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử, ý kiến sau đây đúng hay sai? Vì sao? \"Điều kiện sinh hoạt vật chất của xã hội biến đổi đến đâu thì ngay lập tức tâm lý xã hội và hệ tư tưởng xã hội cũng lập tức biến đổi đến đó\"","o":["Đúng. Vì tồn tại xã hội nào thì ý thức xã hội đó","Đúng. Vì ý thức xã hội chỉ là sự phản ánh tồn tại xã hội","Sai. Vì ý thức xã hội phụ thuộc vào tồn tại xã hội nhưng nó có tính độc lập tương đối của nó","Sai. Vì thực tế lịch sử cho thấy không phải như vậy"],"a":[2],"e":"Ý kiến đó sai: tồn tại xã hội quyết định ý thức xã hội, nhưng ý thức xã hội có tính độc lập tương đối, trong đó ý thức xã hội thường lạc hậu hơn tồn tại xã hội (nhất là tâm lý xã hội: truyền thống, thói quen, tập quán) và cũng có thể vượt trước. Vì vậy tâm lý và hệ tư tưởng không biến đổi «ngay lập tức» theo điều kiện sinh hoạt vật chất. ([Giáo trình Triết học Mác-Lênin 2019, tr.219, 227](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Sai: «tồn tại xã hội nào thì ý thức xã hội ấy» là đúng, nhưng không có nghĩa ý thức biến đổi lập tức; đáp án sai vì kết luận «đúng».","Sai: ý thức xã hội phản ánh tồn tại xã hội nhưng còn có tính độc lập tương đối và tác động trở lại; không chỉ là sự phản ánh đồng thời.","","Kết luận «sai» đúng nhưng lý do chỉ viện «thực tế lịch sử» chung chung, không nêu căn cứ triết học là tính độc lập tương đối của ý thức xã hội."],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục IV.2 (ý thức xã hội), tr.219 và tr.227","c":3,"v":"khớp"},{"q":"\"Phải giải thích ý thức xã hội bằng những mâu thuẫn, những sự xung đột hiện có giữa các lực lượng sản xuất những quan hệ sản xuất của xã hội\". Luận điểm này nhấn mạnh điểm nào trong quan niệm của chủ nghĩa di vật lịch sử?","o":["Vai trò chi phối của phương thức sản xuất đối với ý thức xã hội","Vai trò của cơ sở hạ tầng đối với kiến trúc thượng tầng","Vai trò quyết định của ý thức xã hội đối với tồn tại xã hội","Vai trò quyết định của tồn tại xã hội đối với ý thức xã hội"],"a":[3],"e":"Luận điểm này lấy ý từ Lời tựa «Góp phần phê phán khoa kinh tế chính trị» của C. Mác: không thể căn cứ vào ý thức của một thời đại để đánh giá thời đại ấy, mà phải giải thích ý thức bằng những mâu thuẫn của đời sống vật chất, bằng sự xung đột giữa lực lượng sản xuất và quan hệ sản xuất. Đó là biểu hiện của nguyên lý tồn tại xã hội quyết định ý thức xã hội. ([C. Mác, Lời tựa 1859](https://vnmarxist.com/post-140.html); [Giáo trình Triết học Mác-Lênin 2019, tr.215-216](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Phương thức sản xuất là một phần của tồn tại xã hội; luận điểm có liên quan nhưng tổng quát hơn là tồn tại xã hội quyết định ý thức xã hội, nên A chưa phải ý nhấn mạnh chính.","Cặp cơ sở hạ tầng - kiến trúc thượng tầng là quan hệ khác; luận điểm nói về giải thích ý thức xã hội chứ không bàn về kiến trúc thượng tầng.","Đảo ngược quan hệ: không phải ý thức xã hội quyết định tồn tại xã hội.",""],"s":"C. Mác, Lời tựa «Góp phần phê phán khoa kinh tế chính trị» (1859); GT Triết học Mác-Lênin (2019), Ch.3, mục IV.1-2, tr.215-216","c":3,"v":"dễ nhầm","k":"Phương án A (phương thức sản xuất) cũng gần nghĩa vì mâu thuẫn lực lượng sản xuất - quan hệ sản xuất là nội dung của phương thức sản xuất; đáp án D chọn vì luận điểm quy về nguyên lý tồn tại xã hội quyết định ý thức xã hội."},{"q":"Triết học trở thành \"nữ tì\" của thần học khi nào?","o":["Khi quyền lực của Nhà thờ, kinh viện bao trùm mọi lĩnh vực đời sống xã hội","Khi quyền lực của Thánh chủ bao trùm mọi lĩnh vực đời sống xã hội","Khi quyền lực của Giáo hội bao trùm mọi lĩnh vực đời sống xã hội","Khi quyền lực của nhà vua kém quyền lực giáo phái"],"a":[2],"e":"Giáo trình nêu: ở Tây Âu thời Trung cổ, khi quyền lực của Giáo hội bao trùm mọi lĩnh vực đời sống xã hội thì triết học trở thành «nữ tì» của thần học, và nền triết học tự nhiên bị thay bằng triết học kinh viện. ([Giáo trình Triết học Mác-Lênin 2019, tr.11](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Sai chủ thể: kinh viện là nền triết học thời kỳ đó, không phải thế lực bao trùm xã hội; giáo trình nêu chủ thể là quyền lực của Giáo hội.","«Thánh chủ» không phải thuật ngữ trong giáo trình; chủ thể là Giáo hội.","","Giáo trình không nói nguyên nhân là nhà vua kém quyền lực hơn giáo phái; điều kiện là quyền lực Giáo hội bao trùm xã hội."],"s":"GT Triết học Mác-Lênin (2019), Ch.1, mục I.1 (khái lược về triết học, triết học Tây Âu Trung cổ), tr.11","c":1,"v":"khớp"},{"q":"Theo quan niệm của chủ nghĩa duy vật lịch sử, yếu tố nào giữ vai trò đặc trưng cho chế độ kinh tế của một xã hội nhất định?","o":["Quan hệ sản xuất mới","Quan hệ sản xuất thống trị","Quan hệ sản xuất mạnh nhất","Quan hệ sản xuất đương thời"],"a":[1],"e":"Giáo trình nêu cơ sở hạ tầng (cơ cấu kinh tế) gồm quan hệ sản xuất thống trị, tàn dư và mầm mống; trong đó quan hệ sản xuất thống trị đặc trưng cho cơ sở hạ tầng, tức cho chế độ kinh tế của xã hội đó. ([Giáo trình Triết học Mác-Lênin 2019, tr.154](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quan hệ sản xuất mới (mầm mống) chưa giữ vị trí chủ đạo nên chưa đặc trưng cho chế độ kinh tế.","","«Mạnh nhất» không phải thuật ngữ trong cấu trúc cơ sở hạ tầng của giáo trình.","«Đương thời» không phải thuật ngữ; giáo trình dùng ba loại: thống trị, tàn dư, mầm mống."],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục I.3 (biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng), tr.154","c":3,"v":"khớp"},{"q":"Vận dụng Triết học vào thực tế phải dựa trên quan điểm:","o":["Lịch sử cụ thể","Phát triển","Kế thừa","Tất cả các đáp án đều đúng"],"a":[0],"e":"Giáo trình yêu cầu khi vận dụng nguyên lý chung phải xem xét theo quan điểm lịch sử, gắn với những nguyên lý khác và gắn với «kinh nghiệm cụ thể của lịch sử», tức quán triệt nguyên tắc lịch sử - cụ thể; thiếu điều đó thì vận dụng nguyên lý có thể dẫn đến sai lầm nghiêm trọng. ([Giáo trình Triết học Mác-Lênin 2019, tr.57](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Quan điểm phát triển cũng là nguyên tắc phương pháp luận nhưng đề hỏi cách vận dụng vào thực tế cụ thể, nhấn mạnh quan điểm lịch sử - cụ thể.","Kế thừa không phải yêu cầu được giáo trình nêu cho việc vận dụng triết học vào thực tế.","«Tất cả đều đúng» là cách nói bao trùm; theo đáp án của đề chỉ chọn quan điểm lịch sử - cụ thể."],"s":"GT Triết học Mác-Lênin (2019), Ch.1, mục II (đối tượng và chức năng; vai trò của triết học), tr.57; nguyên tắc lịch sử - cụ thể: Ch.2, tr.105, 142","c":2,"v":"dễ nhầm","k":"Về nội dung, quan điểm phát triển và kế thừa cũng là yêu cầu phương pháp luận của phép biện chứng nên phương án D khó loại trừ hoàn toàn; đáp án A theo đề căn cứ ý «kinh nghiệm cụ thể của lịch sử».","f":1},{"q":"Từ định nghĩa con người của Ph.Ăngghen, đặc điểm nào sau đây cho thấy con người khác với động vật?","o":["Biết tư duy","Biết ứng xử theo các quy phạm đạo đức","Chính trị","Biết chế tạo và sử dụng công cụ lao động"],"a":[3],"e":"Con người khác động vật ở chỗ biết chế tạo và sử dụng công cụ lao động: nhờ chế tạo công cụ lao động mà con người tách khỏi loài vật, tách khỏi tự nhiên và trở thành chủ thể hoạt động thực tiễn xã hội; lao động là điều kiện quyết định hình thành con người. ([Giáo trình Triết học Mác-Lênin 2019, tr.232-233](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Biết tư duy là kết quả của quá trình lao động, ngôn ngữ; không phải tiêu chí khởi nguồn phân biệt người với vật theo định nghĩa của Ăngghen.","Ứng xử theo quy phạm đạo đức là sản phẩm của đời sống xã hội phát sinh sau lao động.","Chính trị là hiện tượng xã hội xuất hiện muộn, không phải đặc điểm phân biệt người với động vật.",""],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục V.1 (khái niệm con người), tr.232-233 (dẫn Ph. Ăngghen); chưa đối chiếu tác phẩm gốc của Ăngghen","c":2,"v":"khớp"},{"q":"Triết học coi vật chất và tinh thần cùng quyết định nguồn gốc và sự tồn tại của thế giới như nhau gọi là","o":["Triết học duy vật","Triết học duy tâm","Triết học nhị nguyên"],"a":[2],"e":"Giáo trình nêu: có những nhà triết học giải thích thế giới bằng cả hai bản nguyên vật chất và tinh thần, coi hai bản nguyên cùng quyết định nguồn gốc và sự vận động của thế giới; học thuyết ấy gọi là nhị nguyên luận (điển hình Đềcáctơ), xét đến cùng thuộc chủ nghĩa duy tâm. ([Giáo trình Triết học Mác-Lênin 2019, tr.19](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Triết học duy vật (nhất nguyên) coi vật chất là cái có trước, quyết định ý thức.","Triết học duy tâm coi ý thức, tinh thần có trước; không coi vật chất và tinh thần quyết định ngang nhau.",""],"s":"GT Triết học Mác-Lênin (2019), Ch.1, mục I.2 (nhị nguyên luận), tr.19","c":1,"v":"khớp"},{"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử thì","o":["Con người là chủ thể tùy ý sáng tạo ra lịch sử","Lịch sử sáng tạo ra con người, con người không thể sáng tạo ra lịch sử","Con người không thể sáng tạo ra lịch sử mà chỉ có thể thích ứng với những điều kiện có sẵn","Con người sáng tạo ra lịch sử trong phạm vi những điều kiện khách quan mà chính lịch sử trước đó đã tạo nên cho nó"],"a":[3],"e":"Con người là chủ thể sáng tạo lịch sử nhưng không sáng tạo theo ý muốn tùy tiện mà phải dựa vào những điều kiện do quá khứ, do thế hệ trước để lại; đồng thời con người tiến hành hoạt động mới để cải biến những điều kiện cũ. ([Giáo trình Triết học Mác-Lênin 2019, tr.233](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Sai: con người không thể sáng tạo lịch sử «tùy ý»; bị chế ước bởi điều kiện khách quan có sẵn.","Sai: giáo trình khẳng định «sáng tạo ra lịch sử» là bản chất của con người; lịch sử và con người sáng tạo lẫn nhau.","Sai: con người không chỉ thích ứng với điều kiện có sẵn mà còn chủ động cải biến những điều kiện cũ.",""],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục V.1, tr.233; ý tưởng gốc của C. Mác trong «Ngày mười tám tháng Sương mù của Lui Bônapáctơ» (chưa đối chiếu tác phẩm gốc)","c":3,"v":"khớp"},{"q":"Vai trò của cách mạng xã hội đối với tiến hóa xã hội gì?","o":["Cách mạng xã hội làm gián đoạn quá trình tiến hóa xã hội","Cách mạng xã hội phủ định tiến hóa xã hội","Cách mạng xã hội không có quan hệ với tiến hóa xã hội","Cách mạng xã hội mở đường cho quá trình tiến hoá xã hội lên giai đoạn cao hơn."],"a":[3],"e":"Giáo trình nêu giữa cách mạng xã hội và tiến hóa xã hội có mối liên hệ hữu cơ: tiến hóa xã hội tạo tiền đề cho cách mạng xã hội, và cách mạng xã hội là cơ sở để tiếp tục có những tiến hóa xã hội ở giai đoạn phát triển sau; cách mạng xã hội cũng mở đường cho lực lượng sản xuất phát triển. ([Giáo trình Triết học Mác-Lênin 2019, tr.208-209](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Cách mạng là bước nhảy đột biến về chất, không làm gián đoạn mà chuyển tiến hóa lên giai đoạn mới.","Cách mạng xã hội không phủ định tiến hóa xã hội; hai quá trình có liên hệ hữu cơ.","Sai: giữa chúng có mối liên hệ hữu cơ.",""],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục III.2 (cách mạng xã hội), tr.208-209; cụm «mở đường cho lực lượng sản xuất phát triển» ở tr.175","c":3,"v":"khớp","k":"Giáo trình không dùng nguyên văn «mở đường ... lên giai đoạn cao hơn»; ý tương đương (tiến hóa tạo tiền đề cho cách mạng, cách mạng là cơ sở của tiến hóa tiếp theo)."},{"q":"Khái niệm \"những nguyên lý cơ bản của chủ nghĩa Mác - Lênin\" là chỉ","o":["Những quan điểm cơ bản của chủ nghĩa Mác - Lênin","Những quan điểm cơ bản, nền tảng của chủ nghĩa Mác - Lênin","Những quan điểm mang tính chất chân lý bền vững của chủ nghĩa Mác - Lênin","Những quan điểm cơ bản, nền tảng và có tính chất chân lý bền vững của chủ nghĩa Mác - Lênin"],"a":[3],"e":"Theo cách định nghĩa thường dùng trong giáo trình «Những nguyên lý cơ bản của chủ nghĩa Mác - Lênin», nguyên lý cơ bản là những quan điểm cơ bản, nền tảng và có tính chất chân lý bền vững của chủ nghĩa Mác - Lênin; phương án D đủ cả ba đặc điểm. Chưa đọc được văn bản gốc để dẫn nguyên văn.","w":["Thiếu hai đặc điểm «nền tảng» và «tính chất chân lý bền vững».","Thiếu đặc điểm «có tính chất chân lý bền vững».","Thiếu đặc điểm «cơ bản, nền tảng»; chỉ có «chân lý bền vững».",""],"s":"Chưa đối chiếu số chương; định nghĩa thuộc chương mở đầu của Giáo trình Những nguyên lý cơ bản của chủ nghĩa Mác - Lênin (không có trong Giáo trình Triết học Mác-Lênin 2019); chưa mở được văn bản PDF để xác nhận","c":1,"v":"chưa kiểm chứng","k":"chưa kiểm chứng được nguồn cho câu này. Không tìm thấy câu nguyên văn trong giáo trình Triết học; PDF giáo trình Nguyên lý cơ bản (kllct.dlu.edu.vn) không trích xuất được chữ nên chưa xác nhận."},{"q":"Về cấu trúc, người lao động thuộc mặt nào trong một phương thức sản xuất?","o":["Kinh tế - giai cấp","Lực lượng sản xuất","Tư liệu sản xuất","Kiến trúc thượng tầng"],"a":[1],"e":"Lực lượng sản xuất là sự kết hợp giữa người lao động với tư liệu sản xuất; về cấu trúc có mặt kinh tế - kỹ thuật (tư liệu sản xuất) và mặt kinh tế - xã hội (người lao động). Vậy người lao động thuộc lực lượng sản xuất. ([Giáo trình Triết học Mác-Lênin 2019, tr.146-147](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Kinh tế - giai cấp» không phải cách phân chia cấu trúc phương thức sản xuất của giáo trình (lực lượng sản xuất và quan hệ sản xuất).","","Tư liệu sản xuất là yếu tố vật chất (tư liệu lao động và đối tượng lao động), không bao gồm người lao động.","Kiến trúc thượng tầng là yếu tố ngoài phương thức sản xuất (quan điểm, tư tưởng và thiết chế xã hội); người lao động không thuộc đó."],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục I.2 (lực lượng sản xuất), tr.146-147","c":3,"v":"khớp"},{"q":"Theo C. Mác, vấn đề tìm hiểu xem tư duy của con người có thể đạt được chân lý khách quan toàn không phải là vấn đề lý luận mà là vấn đề gì?","o":["Thực tế","Hiện thực","Thực tiễn","Khoa học"],"a":[2],"e":"C. Mác viết: vấn đề tìm hiểu xem tư duy của con người có thể đạt tới tính chân lý khách quan không, hoàn toàn không phải là vấn đề lý luận mà là một vấn đề thực tiễn. ([Giáo trình Triết học Mác-Lênin 2019, tr.136](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Thực tế» không phải thuật ngữ trong luận đề của Mác; từ đúng là «thực tiễn».","«Hiện thực» không phải từ trong luận đề; Mác nhấn mạnh thực tiễn.","","«Khoa học» không phải từ trong luận đề; chân lý được kiểm nghiệm qua thực tiễn."],"s":"GT Triết học Mác-Lênin (2019), Ch.2, mục III (lý luận nhận thức - thực tiễn, chân lý), tr.136 (Luận cương về Phoiơbắc)","c":2,"v":"khớp"},{"q":"Nguồn gốc kinh tế của sự vận động và phát triển của hình thái kinh tế- xã hội là gì?","o":["Mâu thuẫn giai cấp gay gắt trong xã hội có giai cấp","Sự tăng lên không ngừng của năng suất lao động","Mâu thuẫn giữa lực lượng sản xuất với quan hệ sản xuất","Sự phát triển mạnh mẽ, đột phá của khoa học kỹ thuật công nghệ"],"a":[2],"e":"Lực lượng sản xuất là yếu tố xét đến cùng quyết định sự vận động, phát triển của hình thái kinh tế - xã hội; mâu thuẫn giữa lực lượng sản xuất tiến bộ với quan hệ sản xuất đã lỗi thời là nguồn gốc sâu xa của cách mạng xã hội, tức của bước chuyển sang hình thái kinh tế - xã hội cao hơn. ([Giáo trình Triết học Mác-Lênin 2019, tr.160, 207](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Mâu thuẫn giai cấp là biểu hiện của mâu thuẫn lực lượng sản xuất - quan hệ sản xuất trong xã hội có giai cấp, không phải nguồn gốc kinh tế.","Năng suất lao động tăng là biểu hiện của sự phát triển lực lượng sản xuất, không phải nguồn gốc của nó.","","Khoa học, kỹ thuật là yếu tố thúc đẩy lực lượng sản xuất, không phải nguồn gốc kinh tế của sự vận động hình thái kinh tế - xã hội."],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục I.4 (sự phát triển các hình thái kinh tế - xã hội), tr.160; mục III.2, tr.207","c":3,"v":"khớp"},{"q":"Nguồn gốc trực tiếp của sự ra đời giai cấp trong xã hội?","o":["Do sự phát triển lực lượng sản xuất làm xuất hiện \"của dư\" tương đối","Do sự chênh lệch về khả năng giữa các tập đoàn người","Do sự phân hóa giữa giàu và nghèo trong xã hội","Do sự xuất hiện chế độ tư hữu về tư liệu sản xuất"],"a":[3],"e":"Giáo trình nêu: nguyên nhân trực tiếp đưa tới sự ra đời của giai cấp là xã hội xuất hiện chế độ tư hữu về tư liệu sản xuất, là cơ sở trực tiếp hình thành các giai cấp; giai cấp chỉ mất đi khi chế độ tư hữu bị xóa bỏ hoàn toàn. Lực lượng sản xuất phát triển, có của dư, là tiền đề (nguyên nhân sâu xa). ([Giáo trình Triết học Mác-Lênin 2019, mục II.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Là tiền đề, nguyên nhân sâu xa chứ không phải nguyên nhân trực tiếp; đề hỏi nguồn gốc trực tiếp.","Chênh lệch khả năng giữa các tập đoàn người không phải nguồn gốc của giai cấp theo giáo trình.","Phân hóa giàu nghèo là hệ quả của chế độ tư hữu, không phải nguồn gốc trực tiếp.",""],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục II.1 (vấn đề giai cấp và đấu tranh giai cấp); chưa ghi số trang","c":3,"v":"khớp"},{"q":"Sai lầm của các nhà duy vật chất phác thời cổ đại là gì?","o":["Đồng nhất vật chất với vật thể","Đồng nhất vật thể với bản thân nó","Đồng nhất vật chất duy vật và thế giới duy tâm","Không có đáp án nào đúng"],"a":[0],"e":"Chủ nghĩa duy vật chất phác cổ đại đồng nhất vật chất với một hay một số chất cụ thể (nước, lửa, không khí...); giáo trình cũng nêu tuyệt đối hóa tính hiện thực cụ thể của phạm trù vật chất là đồng nhất vật chất với vật thể, thực chất quan điểm của chủ nghĩa duy vật trước Mác. ([Giáo trình Triết học Mác-Lênin 2019, tr.17](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","«Đồng nhất vật thể với bản thân nó» là cách nói vô nghĩa, không phải sai lầm được nêu trong giáo trình.","Chủ nghĩa duy vật chất phác không đồng nhất duy vật với duy tâm; nó vẫn thừa nhận tính thứ nhất của vật chất.","Sai vì phương án A đúng."],"s":"GT Triết học Mác-Lênin (2019), Ch.2, mục I.1 (vật chất); Ch.1, mục I.2, tr.17","c":2,"v":"khớp","f":1},{"q":"Ý thức xã hội là phạm trù triết học dùng để chỉ","o":["Toàn bộ đời sống tinh thần của xã hội","Toàn bộ điều kiện vật chất của xã hội","Toàn bộ điều kiện tinh thần của xã hội","Toàn bộ đời sống nói chung của xã hội"],"a":[0],"e":"Ý thức xã hội là mặt tinh thần của đời sống xã hội, là bộ phận hợp thành của văn hóa tinh thần của xã hội; kết cấu gồm tâm lý xã hội và hệ tư tưởng xã hội. ([Giáo trình Triết học Mác-Lênin 2019, tr.216](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Điều kiện vật chất của xã hội thuộc tồn tại xã hội, không phải ý thức xã hội.","«Điều kiện tinh thần» không phải thuật ngữ; ý thức xã hội là mặt tinh thần của đời sống xã hội.","«Đời sống nói chung» bao gồm cả đời sống vật chất (tồn tại xã hội), rộng hơn ý thức xã hội."],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục IV.2 (ý thức xã hội), tr.216","c":3,"v":"khớp","k":"Giáo trình dùng cụm «mặt tinh thần của đời sống xã hội»; phương án A «toàn bộ đời sống tinh thần của xã hội» là cách diễn đạt tương đương."},{"q":"Theo quan điểm của chủ nghĩa Mác - Lênin, \"Bộ tộc\" được định nghĩa là gì?","o":["Bộ tộc là hình thức cộng đồng người hình thành khi xã hội có sự phân chia thành giai cấp. Các bộ tộc được hình thành từ sự liên kết của nhiều bộ lạc sống trên một lãnh thổ nhất định","Những tộc người sống lưu vong","Nhiều bộ lạc hợp lại","Những người có chung lãnh thổ, ngôn ngữ, văn hóa, kinh tế"],"a":[0],"e":"Giáo trình định nghĩa: bộ tộc là hình thức cộng đồng người hình thành khi xã hội có sự phân chia thành giai cấp; các bộ tộc được hình thành từ sự liên kết của nhiều bộ lạc sống trên một lãnh thổ nhất định. ([Giáo trình Triết học Mác-Lênin 2019, tr.186](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Không phải định nghĩa; bộ tộc không phải «những tộc người sống lưu vong».","Chưa đủ: thiếu điều kiện hình thành khi xã hội có giai cấp và sống trên một lãnh thổ nhất định.","Đó là các đặc trưng của dân tộc (hình thức cộng đồng cao hơn bộ tộc), không phải của bộ tộc."],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục II.2 (Dân tộc - bộ tộc), tr.186","c":3,"v":"khớp","k":"Bản nháp ghi nguồn «GT CNXH khoa học, Ch.5» là sai; nội dung này nằm trong Giáo trình Triết học, Ch.3 mục II.2."},{"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử, nhà nước là yếu tố cơ bản trong kiến trúc thượng tầng của xã hội, nó:","o":["Luôn luôn có tác động tích cực đối với cơ sở hạ tầng","Luôn luôn có tác động tiêu cực đối với cơ sở hạ tầng","Có thể tác động tích cực hoặc tiêu cực, tùy theo từng điều kiện nhất định","Không có tác dụng gì tới cơ sở hạ tầng kinh tế mà chỉ có tác dụng tới các yếu tố khác trong bản thân hệ thống kiến trúc thượng tầng"],"a":[2],"e":"Nhà nước tác động trở lại cơ sở hạ tầng theo hai chiều hướng: tác động cùng hướng với sự phát triển kinh tế thì thúc đẩy, ngược hướng thì kìm hãm (Ph. Ăngghen); nên tác động có thể tích cực hoặc tiêu cực tùy điều kiện cụ thể. ([Giáo trình Triết học Mác-Lênin 2019, tr.157-158](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Luôn luôn tích cực» là tuyệt đối hóa; nhà nước có thể kìm hãm kinh tế khi đi ngược chiều phát triển.","«Luôn luôn tiêu cực» cũng là tuyệt đối hóa; sai.","","Sai: nhà nước, qua quyền lực (bạo lực), tác động mạnh vào cơ sở hạ tầng, được Ăngghen gọi là một sức mạnh kinh tế."],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục I.3 (cơ sở hạ tầng và kiến trúc thượng tầng), tr.157-158","c":3,"v":"khớp","id":"zlbw0o"},{"q":"Phạm trù triết học phản ánh thời kỳ hình thành đối tượng, khi nó mới chỉ tồn tại dưới dạng tiền đề hay với tư cách là xu hướng gọi là gì?","o":["Nguyên nhân","Kết quả","Khả năng","Hiện thực"],"a":[2],"e":"Giáo trình nêu: phạm trù khả năng phản ánh thời kỳ hình thành đối tượng, khi nó mới chỉ tồn tại dưới dạng tiền đề hay với tư cách là xu hướng; khả năng là phạm trù chỉ cái chưa có, nhưng sẽ có khi có điều kiện tương ứng. ([Giáo trình Triết học Mác-Lênin 2019, tr.114](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Nguyên nhân là sự tác động lẫn nhau giữa các mặt, các sự vật gây ra biến đổi nhất định, không phản ánh thời kỳ hình thành đối tượng.","Kết quả là những biến đổi do nguyên nhân gây ra.","","Hiện thực là cái đang tồn tại thực sự (đối lập với khả năng), không phải giai đoạn mới chỉ là tiền đề, xu hướng."],"s":"GT Triết học Mác-Lênin (2019), Ch.2, mục II.2 (khả năng và hiện thực), tr.114","c":2,"v":"khớp","id":"cg5ayd"},{"q":"Đâu là một trong những tác phẩm của Lênin?","o":["Chủ nghĩa xã hội không tưởng Pháp","Chủ nghĩa Duy vật và chủ nghĩa kinh viện phê phán","Chủ nghĩa Duy vật và chủ nghĩa kinh nghiệm phê phán","Đường Kách Mệnh"],"a":[2],"e":"«Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán» là tác phẩm của V.I. Lênin, viết để chống chủ nghĩa Makhơ, bảo vệ chủ nghĩa duy vật và phát triển lý luận duy vật biện chứng về nhận thức. ([Giáo trình Triết học Mác-Lênin 2019, tr.44](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Chủ nghĩa xã hội không tưởng Pháp» là một trào lưu tư tưởng (nguồn gốc lý luận của chủ nghĩa xã hội khoa học), không phải tác phẩm của Lênin.","Sai tên: tác phẩm của Lênin là «... chủ nghĩa kinh nghiệm phê phán», không phải «chủ nghĩa kinh viện phê phán».","","«Đường Kách mệnh» là tác phẩm của Hồ Chí Minh."],"s":"GT Triết học Mác-Lênin (2019), Ch.1, mục II (giai đoạn Lênin), tr.44 (giáo trình ghi năm 1908); Đường Kách mệnh của Hồ Chí Minh là kiến thức chung, không từ giáo trình","c":2,"v":"khớp"},{"q":"Theo triết học Mác, con người là gì?","o":["Thực thể sinh học - xã hội","Thực thể tự nhiên - sinh học","Kết hợp con vật và con người","Là thực thể do thánh thần tạo ra"],"a":[0],"e":"Giáo trình đặt tiêu đề: con người là thực thể sinh học - xã hội; về phương diện sinh học con người là thực thể sinh vật, sản phẩm của giới tự nhiên, nhưng không được tuyệt đối hóa mặt sinh học vì bản chất con người là tổng hòa các quan hệ xã hội. ([Giáo trình Triết học Mác-Lênin 2019, tr.231-232](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Chỉ nêu mặt tự nhiên - sinh học, bỏ qua mặt xã hội là mặt quyết định bản chất con người.","«Kết hợp con vật và con người» không phải quan điểm khoa học của triết học Mác.","Thực thể do thánh thần tạo ra là quan điểm thần học, không phải triết học Mác."],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục V.1 (khái niệm con người và bản chất con người), tr.231-232","c":3,"v":"khớp"},{"q":"Khi xem xét, đánh giá con người trong mối quan hệ với gia đình, bạn bè, đồng nghiệp và các mối quan hệ xã hội được gọi là cách nhìn nhận gì?","o":["Biện chứng","Toàn diện","Lịch sử, cụ thể","Phiến diện"],"a":[1],"e":"Giáo trình nêu: khi xem xét con người phải đặt trong tổng thể các quan hệ xã hội, gắn liền với nguyên tắc toàn diện (và lịch sử - cụ thể); chỉ nhìn một mặt, một phương diện của con người để đánh giá là sai lầm. Xem xét con người trong quan hệ gia đình, bạn bè, đồng nghiệp, xã hội là cách nhìn toàn diện. ([Giáo trình Triết học Mác-Lênin 2019, tr.242](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Biện chứng là khái niệm quá chung, bao hàm cả toàn diện lẫn lịch sử - cụ thể; không phải tên gọi cụ thể của cách nhìn này.","","Lịch sử - cụ thể nhấn mạnh đặt trong không gian, thời gian xác định; đề nhấn mạnh nhiều mối quan hệ cùng lúc nên là toàn diện.","Phiến diện là chỉ nhìn một mặt, trái với việc xem xét đa quan hệ."],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục V.3 (quan hệ cá nhân và xã hội), tr.242; nguyên tắc toàn diện: Ch.2, mục II.2, tr.101","c":2,"v":"dễ nhầm","k":"Giáo trình nói xem xét con người trong tổng thể quan hệ xã hội gắn với cả nguyên tắc lịch sử - cụ thể lẫn toàn diện; đáp án B (toàn diện) chọn vì đề nhấn mạnh nhiều mối quan hệ."},{"q":"Yếu tố nào không thuộc lực lượng sản xuất?","o":["Người lao động","Nhà xưởng, công trường","Đối tượng lao động","Kinh tế thượng tầng"],"a":[3],"e":"Đây là câu hỏi «không thuộc». Lực lượng sản xuất gồm người lao động và tư liệu sản xuất (tư liệu lao động như nhà xưởng, công trường và đối tượng lao động). «Kinh tế thượng tầng» không phải khái niệm thuộc lực lượng sản xuất (kiến trúc thượng tầng thuộc phạm vi khác). ([Giáo trình Triết học Mác-Lênin 2019, tr.146-147](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Người lao động thuộc lực lượng sản xuất.","Nhà xưởng, công trường là phương tiện lao động, thuộc tư liệu lao động nên thuộc lực lượng sản xuất.","Đối tượng lao động thuộc tư liệu sản xuất, tức thuộc lực lượng sản xuất.",""],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục I.2 (lực lượng sản xuất), tr.146-147","c":3,"v":"khớp","k":"Cụm «kinh tế thượng tầng» ở đáp án D có vẻ lỗi chép (đúng là «kiến trúc thượng tầng»); không ảnh hưởng đáp án."},{"q":"Giải quyết mặt thứ nhất trong trong vấn đề cơ bản của triết học đã chia nó thành hai trường phái triết học lớn trong lịch sử, đó là các chủ nghĩa","o":["Duy vật và duy tâm","Duy vật và siêu hình","Duy vật biện chứng và duy tâm","Duy vật máy móc và duy tâm"],"a":[0],"e":"Giáo trình viết: việc giải quyết mặt thứ nhất của vấn đề cơ bản của triết học đã chia các nhà triết học thành hai trường phái lớn: chủ nghĩa duy vật (vật chất, giới tự nhiên có trước, quyết định ý thức) và chủ nghĩa duy tâm. ([Giáo trình Triết học Mác-Lênin 2019, tr.16-17](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Duy vật - siêu hình là cách chia theo phương pháp tư duy (biện chứng - siêu hình), không phải theo mặt thứ nhất của vấn đề cơ bản.","Duy vật biện chứng là một hình thức của chủ nghĩa duy vật, không phải một trong hai trường phái lớn ở cấp độ này.","Duy vật máy móc chỉ là một hình thức (siêu hình) của chủ nghĩa duy vật."],"s":"GT Triết học Mác-Lênin (2019), Ch.1, mục I.2 (vấn đề cơ bản của triết học), tr.16-17","c":1,"v":"khớp","id":"niza9c"},{"q":"Nguồn gốc xã hội dẫn đến sự ra đời của Triết học là?","o":["Do sự phát triển của lực lượng sản xuất","Cách mạng nổ ra, những tộc người tan rã","Lao động trí óc đã tách khỏi lao động chân tay","Phân tích đúng tình hình trên toàn thế giới, sản xuất phát triển"],"a":[2],"e":"Giáo trình nêu: gắn liền với sự hình thành xã hội có giai cấp và nhà nước là việc lao động trí óc đã tách khỏi lao động chân tay, trí thức xuất hiện thành một tầng lớp xã hội, nên đây là điều kiện xã hội dẫn đến sự ra đời của triết học. ([Giáo trình Triết học Mác-Lênin 2019, tr.6](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Phát triển lực lượng sản xuất là điều kiện kinh tế chung, chưa phải mệnh đề đặc thù mà giáo trình gọi là nguồn gốc xã hội của triết học.","Cách mạng nổ ra, các tộc người tan rã không phải nguồn gốc xã hội của triết học theo giáo trình.","","Nội dung chung chung («phân tích đúng tình hình trên toàn thế giới»), không phải nguồn gốc xã hội của triết học."],"s":"GT Triết học Mác-Lênin (2019), Ch.1, mục I.1 (khái lược về triết học), tr.6; cùng ý ở tr.18 (nói về nguồn gốc xã hội của chủ nghĩa duy tâm)","c":1,"v":"khớp"},{"q":"Theo quan điểm của chủ nghĩa Mác - Lênin, \"Bộ lạc\" được định nghĩa là gì?","o":["Là cộng đồng bao gồm những bộ lạc có quan hệ cùng huyết thống hoặc các thị tộc có quan hệ hôn nhân liên kết với nhau","Là cộng đồng bao gồm những thị tộc có quan hệ hôn nhân liên kết với nhau","Là cộng đồng bao gồm những thị tộc có quan hệ cùng huyết thống hoặc các thị tộc có quan hệ hôn nhân liên kết với nhau","Là cộng đồng bao gồm những thị tộc có quan hệ cùng huyết thống"],"a":[2],"e":"Giáo trình định nghĩa: bộ lạc là cộng đồng bao gồm những thị tộc có quan hệ cùng huyết thống hoặc các thị tộc có quan hệ hôn nhân liên kết với nhau; bộ lạc phát triển từ thị tộc. ([Giáo trình Triết học Mác-Lênin 2019, tr.185-186](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Lỗi định nghĩa vòng tròn: dùng «bộ lạc» để định nghĩa bộ lạc; phải là «thị tộc».","Thiếu quan hệ cùng huyết thống; định nghĩa có cả huyết thống hoặc hôn nhân.","","Thiếu quan hệ hôn nhân liên kết các thị tộc."],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục II.2 (Dân tộc - bộ lạc), tr.185-186","c":3,"v":"khớp","k":"Bản nháp ghi nguồn «GT CNXH khoa học, Ch.5» là sai; nội dung nằm trong Giáo trình Triết học, Ch.3 mục II.2."},{"q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, sự vật khi mới ra đời chúng tồn tại dưới dạng.","o":["Cái đơn nhất","Cái cụ thể","Cái chung"],"a":[0],"e":"Cái mới không bao giờ xuất hiện đầy đủ ngay mà lúc đầu xuất hiện dưới dạng cái đơn nhất; về sau, theo quy luật, cái mới hoàn thiện dần, thay thế cái cũ và trở thành cái chung, cái phổ biến. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Chương VII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf); [bản 2019, tr.106-107](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","«Cái cụ thể» không phải phạm trù trong cặp cái riêng - cái chung - cái đơn nhất.","Cái chung xuất hiện sau, khi cái đơn nhất được nhân rộng, hoàn thiện và trở nên phổ biến."],"s":"GT Triết học Mác-Lênin, bản cũ tái bản lần 3, Chương VII (cái riêng - cái chung - cái đơn nhất); bản 2019, Ch.2, mục II.2, tr.106-107 (chuyển hóa giữa cái đơn nhất và cái chung)","c":2,"v":"khớp"},{"q":"Hoạt động sản xuất vật chất cơ sở hình thành nên quan hệ gì?","o":["Quan hệ kinh tế giữa người với người","Quan hệ vật chất giữa người với người","Quan hệ kinh tế - vật chất giữa người với vật","Quan hệ kinh tế - vật chất giữa người với người"],"a":[3],"e":"Giáo trình viết: hoạt động sản xuất vật chất là cơ sở hình thành nên quan hệ kinh tế - vật chất giữa người với người, từ đó hình thành các quan hệ xã hội khác (chính trị, pháp luật, đạo đức, tôn giáo...). ([Giáo trình Triết học Mác-Lênin 2019, tr.145](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Thiếu tính chất «vật chất»; giáo trình nêu quan hệ kinh tế - vật chất.","Thiếu tính chất «kinh tế»; giáo trình nêu quan hệ kinh tế - vật chất.","Sai đối tượng: đó là quan hệ giữa người với người, không phải giữa người với vật.",""],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục I.1 (sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội), tr.145","c":3,"v":"khớp"},{"q":"Đâu là một trong những hình thức cộng đồng người trước khi hình thành dân tộc?","o":["Thị tộc","Chủng tộc","Sắc tộc","Dân tộc"],"a":[0],"e":"Giáo trình nêu lịch sử phát triển các hình thức cộng đồng người từ thấp đến cao là thị tộc, bộ lạc, bộ tộc và dân tộc; dân tộc là hình thức cao nhất và phổ biến nhất hiện nay. Vậy thị tộc là hình thức trước dân tộc. ([Giáo trình Triết học Mác-Lênin 2019, tr.185](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Chủng tộc là khái niệm phân loại theo đặc điểm sinh học, không phải hình thức cộng đồng người theo trình độ phát triển xã hội.","Sắc tộc không nằm trong chuỗi thị tộc - bộ lạc - bộ tộc - dân tộc của giáo trình.","Dân tộc là hình thức cộng đồng người cao nhất, hình thành sau, không phải trước dân tộc."],"s":"GT Triết học Mác-Lênin (2019), Ch.3, mục II.2 (Dân tộc), tr.185","c":3,"v":"khớp","k":"Bản nháp ghi nguồn «GT CNXH khoa học, Ch.5» là sai; nội dung nằm trong Giáo trình Triết học, Ch.3 mục II.2."},{"q":"Khi một sự vật, một hiện tượng mới được nảy sinh thì yếu tố nào sẽ xuất hiện đầu tiên?","o":["Cái chung","Cái riêng","Cái đơn nhất","Cái phổ biến"],"a":[2],"e":"Cái mới không xuất hiện đầy đủ ngay mà lúc đầu xuất hiện dưới dạng cái đơn nhất; về sau cái đơn nhất được nhân rộng, hoàn thiện và thành cái chung, cái phổ biến. ([Giáo trình Triết học Mác-Lênin, bản cũ tái bản lần 3, Chương VII](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Cái chung hình thành sau, khi cái đơn nhất phát triển và trở nên phổ biến.","Cái riêng là sự vật, hiện tượng cụ thể (có cả cái chung và cái đơn nhất), không phải yếu tố xuất hiện đầu tiên khi cái mới nảy sinh.","","«Cái phổ biến» chỉ là cách nói khác của cái chung (hình thành sau), không phải yếu tố đầu tiên."],"s":"GT Triết học Mác-Lênin, bản cũ tái bản lần 3, Chương VII (cái riêng - cái chung - cái đơn nhất); bản 2019, Ch.2, mục II.2, tr.106-107","c":2,"v":"khớp"},{"q":"Một trong ba hình thức cơ bản của chủ nghĩa duy vật là gì?","o":["Chủ nghĩa duy vật chất phác thời cổ đại","Chủ nghĩa duy vật trung đại","Chủ nghĩa duy vật Mác thời cận đại","Chủ nghĩa Sôphanh thời hiện đại"],"a":[0],"e":"Giáo trình nêu chủ nghĩa duy vật thể hiện dưới ba hình thức cơ bản: chủ nghĩa duy vật chất phác (thời Cổ đại), chủ nghĩa duy vật siêu hình (thế kỷ XV-XVIII) và chủ nghĩa duy vật biện chứng. ([Giáo trình Triết học Mác-Lênin 2019, tr.17](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","«Duy vật trung đại» không phải một trong ba hình thức cơ bản của giáo trình.","Hình thức thứ ba là chủ nghĩa duy vật biện chứng (do Mác, Ăngghen sáng lập, Lênin phát triển), không gọi là «duy vật Mác thời cận đại».","Sôphanh là cách gọi không thuộc ba hình thức duy vật; «thời hiện đại» cũng không phải hình thức cơ bản."],"s":"GT Triết học Mác-Lênin (2019), Ch.1, mục I.2 (chủ nghĩa duy vật), tr.17","c":1,"v":"khớp"},{"q":"Khẳng định nào sau đây về thế giới vật chất là đúng?","o":["Chỉ có một thế giới duy nhất là thế giới vật chất","Chỉ có một thế giới duy nhất là thế giới tinh thần","Có nhiều thế giới vật chất","Có nhiều thế giới tinh thần"],"a":[0],"e":"Giáo trình khẳng định chỉ một thế giới duy nhất và thống nhất là thế giới vật chất; tinh thần (cảm giác, tư duy, ý thức) có nguồn gốc từ vật chất. ([Giáo trình Triết học Mác-Lênin 2019, tr.68, 76-77](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Chỉ có thế giới tinh thần là quan điểm duy tâm.","Có nhiều thế giới vật chất không có cơ sở trong giáo trình; thế giới vật chất là duy nhất.","Có nhiều thế giới tinh thần là quan điểm duy tâm/tôn giáo; giáo trình không thừa nhận."],"s":"GT Triết học Mác-Lênin (2019), Ch.2, mục I.1, phần «Tính thống nhất vật chất của thế giới», tr.68, 76-77","c":2,"v":"khớp"},{"q":"Cái ...là cái toàn bộ, phong phú hơn cái...","o":["Chung/Riêng.","Riêng/Chung.","Chung/Đơn nhất.","Đơn nhất/Riêng."],"a":[1],"e":"Giáo trình nêu: cái riêng là cái toàn bộ, phong phú hơn cái chung; cái chung là cái bộ phận nhưng sâu sắc hơn cái riêng. Cái riêng phong phú hơn vì ngoài đặc điểm chung còn có cái đơn nhất. Vậy chỗ trống đầu là «Riêng», chỗ trống sau là «Chung». ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đảo ngược: cái chung mới là bộ phận, sâu sắc hơn, không phải toàn bộ.","","Cái đơn nhất không phải vế đối sánh trong nhận định này; cái toàn bộ là cái riêng.","Sai cả hai vế: cái đơn nhất là nét chỉ có ở một sự vật, không phải cái toàn bộ."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương VII (cặp phạm trù cái riêng - cái chung)","c":2,"v":"khớp"},{"q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây là đúng?","o":["Có tất nhiên thuần tuý tồn tại khách quan","Có ngẫu nhiên thuần tuý tồn tại khách quan","Không có cái tất nhiên và ngẫu nhiên thuần tuý tồn tại bên ngoài nhau","Tất nhiên và ngẫu nhiên cùng tồn tại song song với nhau trong tư duy"],"a":[2],"e":"Giáo trình khẳng định tất nhiên và ngẫu nhiên đều tồn tại, nhưng không tồn tại biệt lập dưới dạng thuần túy, cũng không có cái ngẫu nhiên thuần túy; chúng thống nhất hữu cơ với nhau. Vì vậy chỉ phương án C đúng. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Phủ định ý giáo trình: không có cái tất nhiên thuần túy tồn tại tách rời.","Cũng sai tương tự: không có cái ngẫu nhiên thuần túy.","","Tất nhiên và ngẫu nhiên tồn tại khách quan trong thực tế, không chỉ «song song trong tư duy»."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương VII, mục IV (Tất nhiên và ngẫu nhiên)","c":2,"v":"khớp"},{"q":"Điền vào chỗ trống: Chủ nghĩa duy vật biện chứng đã định nghĩa nhận thức là một quá trình phản ánh ... thế giới khách quan vào bộ óc của con người. (Chọn 3 đáp án)","o":["Tự giác","Tích cực","Sáng tạo","Chủ quan"],"a":[0,1,2],"e":"Giáo trình viết: về bản chất, nhận thức là quá trình phản ánh tích cực, tự giác và sáng tạo thế giới khách quan vào bộ óc người trên cơ sở thực tiễn. Do đó ba từ cần điền là tự giác, tích cực, sáng tạo. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","","","Phản ánh của nhận thức không phải «chủ quan»; nội dung do thế giới khách quan quyết định, chủ quan chỉ là hình thức phản ánh trong óc người."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương IX (Lý luận nhận thức), mục bản chất của nhận thức","c":2,"v":"khớp"},{"q":"Toàn bộ những quan hệ sản xuất của một xã hội trong sự vận động hiện thực của chúng hợp thành cơ cấu kinh tế của xã hội đó được là gì?","o":["Cơ sở hạ tầng","Cơ sở thượng tầng","Quan hệ sản xuất","Quan hệ phân phối"],"a":[0],"e":"C. Mác viết: toàn bộ những quan hệ sản xuất ấy hợp thành cơ cấu kinh tế của xã hội; giáo trình định nghĩa cơ sở hạ tầng là toàn bộ những quan hệ sản xuất hợp thành cơ cấu kinh tế của một xã hội nhất định. Câu đề chép hơi cụt («được là gì») nhưng ý rõ. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Kiến trúc thượng tầng (không phải «cơ sở thượng tầng») là quan điểm chính trị, pháp quyền... cùng thiết chế tương ứng.","Quan hệ sản xuất là các bộ phận hợp thành cơ cấu kinh tế, không phải toàn bộ cơ cấu đó.","Quan hệ phân phối chỉ là một mặt của quan hệ sản xuất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương X (Hình thái kinh tế - xã hội), mục cơ sở hạ tầng và kiến trúc thượng tầng","c":3,"v":"khớp","k":"Đề chép cụt: «được là gì»."},{"q":"Trong hoạt động thực tiễn, sai lầm của sự trì trệ bảo thủ là do không tôn trọng quy luật nào?","o":["Quy luật mâu thuẫn","Quy luật lượng chất","Quy luật tự nhiên","Quy luật xã hội"],"a":[1],"e":"Giáo trình chỉ ra tư tưởng bảo thủ, trì trệ, «hữu khuynh» thường biểu hiện ở chỗ coi sự phát triển chỉ là thay đổi đơn thuần về lượng, không dám thực hiện bước nhảy. Đó là vi phạm quy luật chuyển hóa từ những thay đổi về lượng thành những thay đổi về chất. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Quy luật mâu thuẫn nói về nguồn gốc, động lực phát triển, không phải căn nguyên sai lầm này.","","«Quy luật tự nhiên» không phải một quy luật cơ bản của phép biện chứng.","«Quy luật xã hội» là cách gọi chung, không chỉ ra sai lầm cụ thể."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương VIII, mục ý nghĩa phương pháp luận của quy luật lượng - chất","c":2,"v":"khớp"},{"q":"Bản thân cây Sầu riêng luôn tồn tại hai quá trình quang hợp và hô hấp. Quá trình quang hợp giúp cây Sầu riêng hấp thụ nước và khí Cacbonic cùng với ánh sáng mặt trời để tạo ra các hợp chất hữu cơ và thải ra Oxi. Còn quá trình hô hấp là quá trình hấp thụ Oxi, chuyển đổi các chất hữu cơ, và giải phóng năng lượng, thải ra khí Cacbonic. Với kiến thức về Triết học đã được học, Anh/Chị hãy cho biết quá trình quang hợp và hô hấp của cây Sâu riêng nằm trong quy luật nào trong các quy luật sau đây ?","o":["Quy luật từ những sự thay đổi về lượng dẫn đến sự thay đổi về chất và ngược lại","Quy luật thống nhất và đấu tranh giữa các mặt đối lập","Quy luật phủ định của phủ định","Quy luật phát triển"],"a":[1],"e":"Quang hợp và hô hấp là hai quá trình đối lập (một bên tổng hợp chất hữu cơ, một bên phân giải) nhưng cùng tồn tại, gắn bó trong một cây; đây là ví dụ cho quy luật thống nhất và đấu tranh của các mặt đối lập. Ví dụ này là suy luận từ nội dung quy luật, giáo trình không nêu trực tiếp. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Không nói đến sự tích lũy về lượng dẫn tới đổi chất.","","Không có yếu tố phủ định cái cũ để ra cái mới theo chu kỳ.","«Quy luật phát triển» không phải tên một quy luật cơ bản trong giáo trình."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương VIII (quy luật thống nhất và đấu tranh của các mặt đối lập); ví dụ là suy luận, chưa đối chiếu số mục","c":2,"v":"khớp"},{"q":"Cách mạng xã hội được khái quát bởi","o":["Thay đổi thể chế chính trị xã hội này bằng thể chế chính trị khác","Thay đổi thể chế kinh tế này bằng một thể chế kinh tế khác cao hơn","Thay đổi căn bản, toàn diện và triệt để một hình thái kinh tế - xã hội này bằng một hình thái kinh tế - xã hội khác cao hơn","Thay đổi hệ tư tưởng quản lý này bằng hệ tư tưởng quản lý khác"],"a":[2],"e":"Giáo trình: theo nghĩa rộng, cách mạng xã hội là sự biến đổi có tính bước ngoặt và căn bản về chất trong mọi lĩnh vực đời sống xã hội, là phương thức thay thế hình thái kinh tế - xã hội lỗi thời bằng hình thái cao hơn. Phương án C khái quát đúng nghĩa rộng này. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đó chỉ là nghĩa hẹp (lật đổ chế độ chính trị lỗi thời).","Chỉ nói đến thể chế kinh tế, thiếu tính toàn diện của mọi lĩnh vực.","","Hệ tư tưởng chỉ là một yếu tố của kiến trúc thượng tầng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương XII (Nhà nước và cách mạng xã hội), mục bản chất và vai trò của cách mạng xã hội","c":3,"v":"khớp"},{"q":"Định nghĩa đúng triết học Mác - Lênin là","o":["Hệ thống quan điểm duy vật biện chứng về tự nhiên, xã hội và tư duy","Khoa học làm cầu nối giữa các khoa học","Chính trị","Một thứ tôn giáo"],"a":[0],"e":"Giáo trình định nghĩa: Triết học Mác - Lênin là hệ thống quan điểm duy vật biện chứng về tự nhiên, xã hội và tư duy; là thế giới quan và phương pháp luận khoa học, cách mạng của giai cấp công nhân, nhân dân lao động. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Triết học Mác - Lênin không phải «khoa học cầu nối» mà là thế giới quan và phương pháp luận chung.","Triết học không đồng nhất với chính trị.","Triết học dựa trên lý luận khoa học, không phải tôn giáo."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, bản 2021), mục Khái niệm triết học Mác - Lênin; chưa đối chiếu số chương","c":1,"v":"khớp"},{"q":"Theo Triết học Mác, vật chất tồn tại thế nào?","o":["Chủ quan","Phụ thuộc và con người","Khách quan","Theo ý muốn của thần linh"],"a":[2],"e":"Giáo trình: thế giới vật chất tồn tại khách quan, có trước và độc lập với ý thức con người. Vì vậy vật chất tồn tại khách quan. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Chủ quan là lập trường duy tâm chủ quan.","Vật chất không phụ thuộc vào con người.","","Vật chất không tồn tại theo ý muốn của thần linh; đó là quan điểm duy tâm tôn giáo."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương V (Vật chất và ý thức), mục tính thống nhất vật chất của thế giới","c":2,"v":"khớp"},{"q":"Theo Triết học Mác - Lênin cái bàn, cái ghế có phải vật chất không?","o":["Có. Vì nó là dạng của vật chất trong không gian.","Không. Vì nó không có vật chất trong không gian.","Có. Vì nó có tồn tại cụ thể, có kích thước và tồn tại cùng thời gian.","Không. Vì nó chỉ là một dạng cụ thể của vật chất."],"a":[0],"e":"Theo giáo trình, mọi bộ phận của thế giới vật chất đều là những dạng cụ thể của vật chất, là kết cấu vật chất. Cái bàn, cái ghế là vật thể thuộc thế giới vật chất nên là dạng cụ thể của vật chất tồn tại trong không gian. Theo đề, chọn A. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Sai: vật thể cụ thể chính là dạng tồn tại của vật chất.","Kết luận «có» đúng nhưng lập luận «có kích thước và tồn tại cùng thời gian» là chưa chuẩn bằng A.","Tự mâu thuẫn: dạng cụ thể của vật chất vẫn là vật chất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương V, mục tính thống nhất vật chất của thế giới","c":2,"v":"dễ nhầm","k":"A và C đều có thể xem là đúng về kết luận; chỉ khác lập luận, nên học theo đáp án của đề."},{"q":"Những sự vật, hiện tượng nếu có cùng nguyên nhân, trong những điều kiện giống nhau thì sẽ tạo nên kết quả như nhau. Điều này thể hiện tính chất gì trong mối liên hệ nhân quả?","o":["Tính khách quan","Tính phổ biến","Tính tất yếu","Tính biện chứng"],"a":[2],"e":"Giáo trình: tính tất yếu của mối liên hệ nhân quả thể hiện ở chỗ cùng một nguyên nhân nhất định, trong những điều kiện giống nhau sẽ gây ra kết quả như nhau. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Tính khách quan là mối liên hệ nhân quả vốn có, không phụ thuộc ý thức.","Tính phổ biến: mọi sự vật, hiện tượng đều có nguyên nhân.","","«Tính biện chứng» không phải một trong ba tính chất của nhân quả (khách quan, phổ biến, tất yếu)."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương VII, mục nhân quả","c":2,"v":"khớp","id":"1lhis6m"},{"q":"Ai đã tìm ra tia phóng xạ?","o":["Rơnghen","Nicolaus Copernicus","Béccơren","Giordano Bruno"],"a":[2],"e":"Theo giáo trình, năm 1896 Béccơren phát hiện ra hiện tượng phóng xạ (còn Rơnghen phát hiện tia X năm 1895). Đề hỏi «tia phóng xạ» nên đáp án là Béccơren. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Rơnghen phát hiện tia X năm 1895, không phải phóng xạ.","Nicôlai Côpécních là nhà thiên văn thời Phục hưng.","","Brunô là nhà triết học thời Phục hưng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương V, mục phát triển khoa học tự nhiên cuối thế kỷ XIX - đầu XX","c":2,"v":"khớp","id":"ft7ibh"},{"q":"Chọn cụm từ thích hợp điền vào chỗ trống sau để hình thành khái niệm về \"Cơ sở hạ tầng\" theo quan điểm của triết học Mác - Lênin: Cơ sở hạ tầng là tổng hợp các quan hệ sản xuất hợp thành..... của xã hội.","o":["Cơ sở vật chất - kỹ thuật","Hệ thống điện, đường, trường, trạm","Cơ cấu kinh tế","Đời sống vật chất"],"a":[2],"e":"Giáo trình: cơ sở hạ tầng là toàn bộ những quan hệ sản xuất hợp thành cơ cấu kinh tế của một xã hội nhất định. Chỗ trống là cơ cấu kinh tế. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Cơ sở vật chất - kỹ thuật là khái niệm khác (thuộc lực lượng sản xuất, kinh tế chính trị).","Đó là nghĩa thông thường của «hạ tầng», không phải thuật ngữ triết học.","","Quá chung, không phải cụm trong định nghĩa."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương X, mục cơ sở hạ tầng và kiến trúc thượng tầng","c":3,"v":"khớp"},{"q":"Triết học duy vật biện chứng cho rằng:","o":["Vật chất quyết định ý thức, ý thức tác động trở lại vật chất","Ý thức quyết định vật chất, vật chất tác động trở lại ý thức","Vật chất quyết định ý thức, ý thức không thể tác động đến vật chất","Vật chất và ý thức đều có vai trò quyết định"],"a":[0],"e":"Giáo trình: vật chất có trước, ý thức có sau, vật chất quyết định ý thức, song ý thức có thể tác động trở lại vật chất thông qua hoạt động thực tiễn của con người. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Đảo ngược quan hệ, là quan điểm duy tâm.","Phủ nhận vai trò tác động trở lại của ý thức, là duy vật siêu hình.","Cả hai cùng quyết định là nhị nguyên luận."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương V, mục III (ý nghĩa phương pháp luận của mối quan hệ vật chất - ý thức)","c":2,"v":"khớp"},{"q":"Anh A có tri thức, năng lực, trình độ, kinh nghiệm và kỹ năng lao động. Vậy có thể gọi A là?","o":["Trí thức","Người lao động","Lao động trí thức","Năng lực lao động"],"a":[2],"e":"Người có tri thức, năng lực, trình độ, kinh nghiệm và kỹ năng lao động được gọi là lao động trí thức theo cách dùng trong kinh tế tri thức. Cụm này không thấy trong giáo trình triết học đã tra nên chưa kiểm chứng được nguồn.","w":["Trí thức chỉ một tầng lớp xã hội.","Người lao động nói chung, chưa nhấn mạnh yếu tố tri thức.","","Năng lực lao động chỉ là một thuộc tính, không phải chỉ con người."],"s":"chưa đối chiếu được nguồn; câu thuộc nội dung kinh tế tri thức, không có trong giáo trình triết học đã tra","c":3,"v":"chưa kiểm chứng","k":"chưa kiểm chứng được nguồn cho câu này. Không tìm thấy định nghĩa tương ứng trong giáo trình Triết học; giữ giải thích bản nháp."},{"q":"Sự thống nhất giữa lực lượng sản xuất ở một trình độ nhất định và quan hệ sản xuất tương ứng tạo thành :","o":["hình thái kinh tế - xã hội","phương thức sản xuất","cơ sở hạ tầng","kiến trúc thượng tầng"],"a":[1],"e":"Giáo trình: phương thức sản xuất chính là sự thống nhất giữa lực lượng sản xuất ở một trình độ nhất định và quan hệ sản xuất tương ứng. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Hình thái kinh tế - xã hội rộng hơn, gồm cả cơ sở hạ tầng và kiến trúc thượng tầng.","","Cơ sở hạ tầng là toàn bộ quan hệ sản xuất hợp thành cơ cấu kinh tế.","Kiến trúc thượng tầng là các quan điểm và thiết chế chính trị - pháp lý - tư tưởng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương X, mục phương thức sản xuất","c":3,"v":"khớp"},{"q":"Chọn câu trả lời đúng theo quan điểm duy vật lịch sử: Lực lượng cơ bản nhất trong quần chúng nhân dân là:","o":["Giai cấp thống trị xã hội.","Tầng lớp trí thức.","Người lao động.","Công nhân và nông dân."],"a":[2],"e":"Giáo trình nêu quần chúng nhân dân trước hết là những người lao động sản xuất ra của cải vật chất và là lực lượng cơ bản của cách mạng, có vai trò quyết định thắng lợi của mọi cuộc cách mạng. Đáp án của đề là người lao động. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Giai cấp thống trị không phải lực lượng cơ bản của quần chúng.","Tầng lớp trí thức chỉ là bộ phận.","","Công nhân và nông dân là bộ phận của người lao động, hẹp hơn đáp án."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương XIV (con người), mục quần chúng nhân dân","c":3,"v":"khớp"},{"q":"Chỉ có một thế giới duy nhất là thế giới vật chất là thể hiện tính chất gì của thế giới vật chất?","o":["Đồng nhất","Thống nhất","Thuần nhất","Duy nhất"],"a":[1],"e":"Giáo trình: chỉ có một thế giới duy nhất và thống nhất là thế giới vật chất; tính thống nhất của thế giới ở tính vật chất của nó. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["«Đồng nhất» không phải thuật ngữ trong giáo trình.","","«Thuần nhất» cũng không phải thuật ngữ.","«Duy nhất» chỉ là một nội dung trong luận điểm, tên tính chất là tính thống nhất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương V, mục tính thống nhất vật chất của thế giới","c":2,"v":"khớp"},{"q":"Theo C. Mác và Ph. Ăngghen, để tồn tại và phát triển, con người cần phải thực hiện hoạt động gì?","o":["Vận động","Sản xuất","Làm giàu","Kinh doanh"],"a":[1],"e":"Theo C. Mác và Ph. Ăngghen, để tồn tại và phát triển con người phải sản xuất ra tư liệu sinh hoạt, tức tiến hành sản xuất vật chất; sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Vận động là phương thức tồn tại của vật chất, không phải hoạt động đặc trưng này.","","Làm giàu không phải điều kiện tồn tại của con người.","Kinh doanh chỉ là một hình thức kinh tế cụ thể."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương X, mục sản xuất vật chất - cơ sở của sự tồn tại và phát triển xã hội","c":3,"v":"khớp"},{"q":"Các nhà triết học duy tâm được chia thành mấy trường phái?","o":["2","3","4","5"],"a":[0],"e":"Giáo trình: chủ nghĩa duy tâm chia thành hai phái là chủ nghĩa duy tâm chủ quan và chủ nghĩa duy tâm khách quan. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Giáo trình không chia thành ba.","Không có cách chia thành bốn.","Không có cách chia thành năm."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương I, mục vấn đề cơ bản của triết học","c":1,"v":"khớp"},{"q":"Chọn câu trả lời đúng theo quan điểm duy vật lịch sử: Sản xuất ra của cải vật chất giữ vai trò là:","o":["Nền tảng của xã hội","Nền tảng vật chất của xã hội","Nền tảng tinh thần của xã hội","Nền tảng kỹ thuật, công nghệ của xã hội"],"a":[1],"e":"Giáo trình: sản xuất vật chất là cơ sở của sự tồn tại và phát triển của xã hội, quyết định các mặt khác của đời sống xã hội. Đáp án của đề diễn đạt thành «nền tảng vật chất của xã hội»; cụm này không thấy nguyên văn trong giáo trình. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Chưa chỉ rõ tính chất vật chất của nền tảng này.","","Nền tảng tinh thần là sản phẩm phái sinh từ sản xuất vật chất.","Kỹ thuật, công nghệ chỉ là một yếu tố của lực lượng sản xuất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương X, mục sản xuất vật chất","c":3,"v":"dễ nhầm","k":"A và B gần nghĩa; nên học theo đáp án B của đề."},{"q":"Cơ sở của sự tồn tại và phát triển của xã hội là sản xuất:","o":["Hàng hóa, dịch vụ","Tư liệu sản xuất","Tư liệu tiêu dùng","Sản xuất vật chất"],"a":[3],"e":"Giáo trình: trong ba quá trình sản xuất của xã hội (vật chất, tinh thần, sản xuất ra bản thân con người), sản xuất vật chất là cơ sở của sự tồn tại và phát triển của xã hội. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Hàng hóa, dịch vụ chỉ là sản phẩm cụ thể.","Tư liệu sản xuất chỉ là một bộ phận của sản xuất vật chất.","Tư liệu tiêu dùng cũng chỉ là một bộ phận.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương X, mục sản xuất vật chất - cơ sở của sự tồn tại và phát triển xã hội","c":3,"v":"khớp"},{"q":"Trong xã hội có giai cấp, nội dung và hình thức phát triển của ý thức xã hội khác nhau do đâu?","o":["Những điều kiện sinh hoạt vật chất, lợi ích và địa vị của các giai cấp khác nhau","Thói quen khác nhau","Sở thích khác nhau","Những điều kiện sinh hoạt tinh thần, địa vị, thói quen của các giai cấp khác nhau"],"a":[0],"e":"Giáo trình: trong xã hội có giai cấp, các giai cấp có điều kiện sinh hoạt vật chất khác nhau, lợi ích khác nhau do địa vị xã hội của mỗi giai cấp quy định, nên ý thức xã hội của các giai cấp có nội dung và hình thức phát triển khác nhau hoặc đối lập nhau. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Thói quen chỉ là biểu hiện, không phải nguyên nhân gốc.","Sở thích không phải nguyên nhân gốc.","Điều kiện sinh hoạt tinh thần không phải cơ sở quyết định, cơ sở là điều kiện vật chất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương XIII (Ý thức xã hội), mục tính giai cấp của ý thức xã hội","c":3,"v":"khớp","id":"zuhb6u"},{"q":"Vấn đề cơ bản của triết học có hai mặt. Mặt thứ hai phải trà lời câu hỏi con người có khả năng hay không trong:","o":["Nhận thức được bản thân","Hòa hợp với tự nhiên","Chinh phục được thế giới","Nhận thức được thế giới"],"a":[3],"e":"Giáo trình: mặt thứ hai của vấn đề cơ bản của triết học (nhận thức luận) trả lời câu hỏi con người có thể nhận thức được thế giới hay không. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đối tượng nhận thức là thế giới, không phải riêng bản thân.","Hòa hợp với tự nhiên không phải nội dung của vấn đề cơ bản.","Chinh phục thế giới là mục tiêu thực tiễn, không phải mặt thứ hai.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương I, mục vấn đề cơ bản của triết học","c":1,"v":"khớp"},{"q":"Theo C.Mắc, các nên kinh tế căn bản phân biệt với nhau bởi:","o":["Phương thức sản xuất ra của cải vật chất","Mục đích của quá trình sản xuất ra của cải vật chất","Mục đích tự nhiên của quá trình sản xuất ra của cải vật chất","Mục đích xã hội của quá trình sản xuất ra của cải vật chất"],"a":[0],"e":"Câu nói quen thuộc của C. Mác: các thời đại kinh tế khác nhau không phải ở chỗ chúng sản xuất ra cái gì mà ở chỗ chúng sản xuất bằng cách nào, với những tư liệu lao động nào; nghĩa là phân biệt bằng phương thức sản xuất. Giáo trình cũng nói công cụ lao động là tiêu chuẩn phân biệt các thời đại kinh tế. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Mục đích sản xuất không phải tiêu chí phân biệt theo Mác.","«Mục đích tự nhiên» không phải tiêu chí.","Mục đích xã hội cũng không phải tiêu chí."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương X (mục lực lượng sản xuất / phương thức sản xuất); trích dẫn Mác trong «Tư bản» chưa đối chiếu trực tiếp với bản gốc","c":3,"v":"dễ nhầm","k":"Câu Mác nhấn mạnh «bằng cách nào, với tư liệu lao động nào»; đáp án phương thức sản xuất là cách hiểu rút gọn.","id":"6g8frw"},{"q":"Luận điểm sau đây thuộc lập trường triết học nào: \"Cái mới ra đời trên cơ sở phá hủy hoàn toàn cái cũ\"?","o":["Quan điểm siêu hình","Quan điểm duy tâm","Quan điểm phát triển","Quan điểm biện chứng duy vật"],"a":[0],"e":"Giáo trình nhấn mạnh trong hoạt động con người phải biết kế thừa tinh hoa của cái cũ, tránh thái độ phủ định sạch trơn. Luận điểm «cái mới ra đời trên cơ sở phá hủy hoàn toàn cái cũ» thuộc quan điểm siêu hình (phủ định sạch trơn). ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Không phải đặc trưng của quan điểm duy tâm.","Quan điểm phát triển biện chứng thừa nhận sự kế thừa.","Duy vật biện chứng đề cao phủ định biện chứng có kế thừa."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương VIII, mục quy luật phủ định của phủ định","c":2,"v":"khớp","id":"1mwc5mq"},{"q":"Những ý thức lạc hậu tiêu cực không mất đi một cách dễ dàng, là do:","o":["Thói quen tập quán lâu đời","Ý thức xã hội không phản ánh kịp tôi tại xã hội","Thói quen tập quán lâu đời và ý thức xã hội không phần ánh kịp tồn tại xã hội","Ý thức xã hội phản ánh tồn tại xã hội và thói quen tập quán"],"a":[2],"e":"Giáo trình: ý thức xã hội thường lạc hậu so với tồn tại xã hội, biểu hiện rõ trong tâm lý xã hội như truyền thống, tập quán, thói quen; nguyên nhân gồm sự biến đổi nhanh của tồn tại xã hội mà ý thức không phản ánh kịp và sức mạnh của thói quen, tập quán. Đáp án C gộp cả hai. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Chỉ nêu một nguyên nhân.","Cũng chỉ một nguyên nhân.","","Diễn đạt sai: ý thức xã hội phản ánh tồn tại xã hội nhưng không chỉ rõ nguyên nhân lạc hậu."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương XIII, mục tính độc lập tương đối của ý thức xã hội","c":3,"v":"khớp","id":"1k155oc"},{"q":"Thời gian phát hiện ra tia Rơnghen là khi nào?","o":["Năm 1895","Năm 1896","Năm 1897","Năm 1898"],"a":[0],"e":"Theo giáo trình, năm 1895 Rơnghen phát hiện ra tia X; năm 1896 Béccơren phát hiện hiện tượng phóng xạ; năm 1897 Tômxơn phát hiện ra điện tử. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","1896 là năm Béccơren phát hiện phóng xạ.","1897 là năm Tômxơn phát hiện điện tử.","1898 không phải mốc phát hiện tia Rơnghen."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương V, mục phát triển khoa học tự nhiên cuối thế kỷ XIX - đầu XX","c":2,"v":"khớp"},{"q":"Trong xã hội Ấn Độ cổ đại, triết học được hiểu là:","o":["Con đường suy ngẫm để dẫn dắt con người tới lẽ phải","Con đường tu tập","Con đường giải thoát","Con đường giác ngộ"],"a":[0],"e":"Giáo trình: ở Ấn Độ, từ darshana (triết học) có nghĩa là chiêm ngưỡng, nhưng hàm ý là tri thức dựa trên lý trí, là con đường suy ngẫm để dẫn dắt con người đến với lẽ phải. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Tu tập không phải cách giáo trình định nghĩa triết học.","Giải thoát chỉ là mục đích của một số trường phái.","Giác ngộ cũng là mục đích của Phật giáo, không phải nghĩa của darshana."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương I, mục Triết học là gì (khái niệm triết học)","c":1,"v":"khớp","id":"eaf7ob"},{"q":"Theo triết học Mác, hình thái kinh tế - xã hội cuối cùng là?","o":["Phong kiến","Tư bản chủ nghĩa","Xã hội chủ nghĩa","Cộng sản chủ nghĩa"],"a":[3],"e":"Theo học thuyết Mác, hình thái kinh tế - xã hội cao hơn, kế tiếp tư bản chủ nghĩa là cộng sản chủ nghĩa (giai đoạn đầu là xã hội chủ nghĩa). Đáp án cuối cùng là cộng sản chủ nghĩa. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Phong kiến là hình thái đứng trước tư bản chủ nghĩa.","Tư bản chủ nghĩa sẽ bị phủ định bởi hình thái cộng sản chủ nghĩa.","Xã hội chủ nghĩa là giai đoạn đầu của hình thái cộng sản chủ nghĩa.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương XII, mục cách mạng xã hội (nhắc hình thái cộng sản chủ nghĩa là hình thái cao hơn tư bản chủ nghĩa); chưa đối chiếu mục lịch sử các hình thái","c":3,"v":"khớp"},{"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử, trong kiến trúc thượng tầng của xã hội có giai cấp, yếu tố cơ bản nhất, có tác động trực tiếp và mạnh mẽ nhất tới cơ sở hạ tầng là yếu tố:","o":["Tổ chức chính đảng","Tổ chức nhà nước","Tổ chức tôn giáo","Các tổ chức văn hóa - xã hội"],"a":[1],"e":"Giáo trình nêu trong kiến trúc thượng tầng, chính trị và pháp luật có quan hệ trực tiếp với cơ sở hạ tầng, còn triết học, tôn giáo, nghệ thuật quan hệ gián tiếp; trong xã hội có giai cấp, nhà nước có vai trò đặc biệt quan trọng, nhờ nó giai cấp thống trị thực hiện thống trị trên mọi mặt. Cụm «yếu tố cơ bản nhất, tác động trực tiếp và mạnh nhất» không thấy nguyên văn, nhưng đáp án nhà nước phù hợp. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đảng chính trị là thiết chế quan trọng nhưng không được giáo trình nêu là yếu tố mạnh nhất.","","Tôn giáo quan hệ gián tiếp với cơ sở hạ tầng.","Tổ chức văn hóa - xã hội tác động yếu hơn, gián tiếp hơn."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương X, mục kiến trúc thượng tầng","c":3,"v":"dễ nhầm","k":"Cụm «cơ bản nhất, mạnh mẽ nhất» là cách diễn đạt của đề, giáo trình nói «vai trò đặc biệt quan trọng».","id":"tuwr09"},{"q":"Theo quan điểm của chủ nghĩa duy vật biện chứng khẳng định nào sau đây là đúng?","o":["Cái ngẫu nhiên không có nguyên nhân","Chỉ có cái tất yếu mới có nguyên nhân","Không phải cái gì con người chưa nhận thức được nguyên nhân là cái ngẫu nhiên","Cái ngẫu nhiên luôn trở thành cái tất nhiên"],"a":[2],"e":"Giáo trình: không phải chỉ cái tất nhiên mới có nguyên nhân mà cả ngẫu nhiên và tất nhiên đều có nguyên nhân; cũng không nên coi hiện tượng con người chưa nhận thức được nguyên nhân là ngẫu nhiên, vì như vậy rơi vào duy tâm chủ quan. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Ngẫu nhiên vẫn có nguyên nhân (do nhân tố bên ngoài).","Cả tất nhiên lẫn ngẫu nhiên đều có nguyên nhân.","","Ngẫu nhiên không luôn trở thành tất nhiên; hai cái tồn tại thống nhất."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương VII, mục IV (Tất nhiên và ngẫu nhiên)","c":2,"v":"khớp","id":"1b2pzyr"},{"q":"\"Góp gió thành bão\" giúp anh/chị liên hệ tới quy luật nào trong triết học?","o":["Lượng - chất","Mâu thuẫn","Phủ định của phủ định","Không có phương án nào đúng"],"a":[0],"e":"Giáo trình dẫn các câu tích tiểu thành đại, năng nhặt chặt bị, góp gió thành bão khi nói về quy luật lượng - chất: những việc vĩ đại là tổng hợp việc bình thường, tích lũy dần về lượng tới điểm nút thì chuyển thành chất. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Không nói đến mâu thuẫn giữa các mặt đối lập.","Không có yếu tố phủ định cái cũ.","Sai vì A đúng."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương VIII, mục ý nghĩa phương pháp luận của quy luật lượng - chất","c":2,"v":"khớp","id":"470vsu","f":1},{"q":"Theo quan điểm của triết học Mác - Lênin thì sự thay đổi quan hệ sản xuất phụ thuộc vào:","o":["Trình độ của công cụ sản xuất","Trình độ kỹ thuật sản xuất","Trình độ phân công lao động xã hội","Trình độ phát triển của lực lượng sản xuất"],"a":[3],"e":"Giáo trình: lực lượng sản xuất quyết định quan hệ sản xuất; khi lực lượng sản xuất phát triển thì quan hệ sản xuất cũ lạc hậu, phải thay đổi bằng quan hệ sản xuất mới phù hợp. Vì vậy sự thay đổi quan hệ sản xuất phụ thuộc trình độ phát triển của lực lượng sản xuất. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Công cụ chỉ là một yếu tố của lực lượng sản xuất.","Kỹ thuật cũng chỉ là một yếu tố.","Phân công lao động là một biểu hiện, không phải căn cứ tổng quát.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương X, mục quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất","c":3,"v":"khớp"},{"q":"Bản chất của nhà nước là gì?","o":["Mang bản chất của giai cấp thống trị","Mang bản chất của giai cấp bị trị","Mang bản chất của tất cả các giai cấp","Mang bản chất của xã hội"],"a":[0],"e":"Giáo trình: trong xã hội có giai cấp, bản chất của nhà nước là công cụ thống trị giai cấp, bảo vệ lợi ích của giai cấp thống trị. Vì vậy nhà nước mang bản chất của giai cấp thống trị. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Giai cấp bị trị không nắm bộ máy nhà nước.","Nhà nước không đại diện đồng đều cho mọi giai cấp.","Nhà nước trong xã hội có giai cấp mang bản chất giai cấp, không phải bản chất «của xã hội» chung chung."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương XII, mục nhà nước (bản chất giai cấp)","c":3,"v":"khớp","id":"1f1e5iy"},{"q":"Khi sự vật không trực tiếp tác động vào giác quan của con người, là hình thức nhận thức nào sau đây?","o":["Cảm giác","Tri giác","Biểu tượng","Khái niệm"],"a":[3],"e":"Giáo trình: cảm giác phản ánh thuộc tính riêng lẻ khi sự vật đang tác động trực tiếp vào giác quan; tri giác cũng ở giai đoạn trực quan sinh động; còn khái niệm là hình thức cơ bản của tư duy trừu tượng, phản ánh đặc tính bản chất của sự vật. Đề chọn khái niệm, nhưng biểu tượng cũng là hình ảnh còn lưu lại khi sự vật không còn trực tiếp tác động. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Cảm giác chỉ có khi sự vật tác động trực tiếp lên giác quan.","Tri giác cũng cần sự vật tác động trực tiếp.","Theo giáo trình, biểu tượng là hình ảnh còn lưu lại khi sự vật không còn trực tiếp tác động, nên có thể bị xem là đúng; đề không chọn.",""],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương IX, mục trực quan sinh động và tư duy trừu tượng","c":2,"v":"nghi vấn","k":"nghi vấn: Giáo trình định nghĩa biểu tượng đúng là hình ảnh khi sự vật không còn trực tiếp tác động, nên C cũng hợp lý. Đề chọn D; câu có thể thiếu ý (ví dụ thiếu «cảm tính/lý tính»). Nên học theo đáp án của đề."},{"q":"Galilê là nhà triết học thuộc trường phái triết học nào?","o":["Chủ nghĩa duy vật biện chứng","Chủ nghĩa duy vật siêu hình","Chủ nghĩa duy tâm siêu hình","Chủ nghĩa duy tâm máy móc"],"a":[1],"e":"Đề xếp Galilê vào chủ nghĩa duy vật siêu hình. Tuy nhiên giáo trình liệt kê Galilê cùng Côpécních, Brunô, Kuzan, Tômát Morơ trong nhóm nhà khoa học và triết học thời kỳ Phục hưng, không xếp trực tiếp vào duy vật siêu hình; cách xếp của đề là theo cách phân loại thông dụng ở thế kỷ XVI - XVII. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Duy vật biện chứng do Mác - Ăngghen sáng lập sau Galilê.","","Galilê không phải nhà duy tâm.","Không có trường phái này."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương II, mục triết học Tây Âu thời Phục hưng - cận đại","c":1,"v":"nghi vấn","k":"nghi vấn: Giáo trình xếp Galilê vào thời Phục hưng, không nêu nhãn «duy vật siêu hình» trực tiếp; đáp án B của đề dựa vào cách phân loại ngoài giáo trình."},{"q":"Xác định mệnh đề sai:","o":["Vật thể là dạng cụ thể của vật chất","Vật chất tồn tại thông qua những dạng cụ thể của nó","Vật chất là một dạng tồn tại của vật thể","Vật thể không đồng nghĩa với vật chất"],"a":[2],"e":"Giáo trình: mọi bộ phận của thế giới vật chất đều là những dạng cụ thể của vật chất; như vậy vật thể là dạng cụ thể của vật chất chứ vật chất không phải một dạng tồn tại của vật thể. Do đó mệnh đề C sai. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đúng: vật thể là dạng cụ thể của vật chất.","Đúng: vật chất tồn tại thông qua các dạng cụ thể.","","Đúng: vật thể không đồng nghĩa với vật chất, vật chất rộng hơn."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương V, mục tính thống nhất vật chất của thế giới","c":2,"v":"khớp","id":"7yc6u2"},{"q":"Theo C. Mác, trong tính hiện thực của nó, bản chất con người là tổng hòa:","o":["Các phẩm chất xã hội","Quan hệ lợi ích","Các quan hệ xã hội","Quan hệ hiện thực"],"a":[2],"e":"C. Mác viết: trong tính hiện thực của nó, bản chất con người là tổng hòa những quan hệ xã hội. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Phẩm chất xã hội chỉ là một mặt.","Quan hệ lợi ích chỉ là một mặt của quan hệ xã hội.","","«Quan hệ hiện thực» không phải thuật ngữ trong câu của Mác."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương XIV (Quan điểm triết học Mác - Lênin về con người), mục bản chất con người","c":3,"v":"khớp"},{"q":"Ý thức xã hội có tính chất nào sau đây?","o":["Tính độc lập tương đối","Tính độc lập tuyệt đối","Tính sáng tạo","Tính bất biến"],"a":[0],"e":"Giáo trình nêu ý thức xã hội có tính độc lập tương đối, biểu hiện ở chỗ thường lạc hậu so với tồn tại xã hội, có thể vượt trước, có sự kế thừa và tác động qua lại; nhưng suy đến cùng vẫn do tồn tại xã hội quyết định. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Độc lập tuyệt đối là sai, vì ý thức xã hội phụ thuộc vào tồn tại xã hội.","Tính sáng tạo không phải tính chất đặc trưng nêu trong mục này.","Ý thức xã hội thay đổi theo tồn tại xã hội, không bất biến."],"s":"Giáo trình Triết học Mác-Lênin (Bộ GD&ĐT, tái bản lần 3), Chương XIII, mục tính độc lập tương đối của ý thức xã hội","c":3,"v":"khớp"},{"q":"Ở Trung Quốc thời cổ đại có Triết học không?","o":["Có","Không","Chỉ có hệ tư tưởng chứ không có triết học","Không có hệ tư tưởng và triết học"],"a":[0],"e":"Giáo trình nêu triết học ra đời ở cả phương Đông và phương Tây gần như cùng một thời gian (khoảng thế kỷ VIII đến VI trước CN), trong đó Trung Quốc, Ấn Độ cổ đại đã có các học thuyết triết học (chẳng hạn quan niệm Ngũ hành của Trung Quốc). Vì vậy Trung Quốc thời cổ đại có triết học. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Phủ nhận sự tồn tại của triết học Trung Quốc cổ đại, trái với giáo trình (triết học xuất hiện ở các trung tâm văn minh lớn phương Đông).","Triết học là hệ thống quan niệm lý luận chung về thế giới, không thể tách khỏi hệ tư tưởng nên không thể nói «chỉ có hệ tư tưởng mà không có triết học».","Phủ nhận cả hệ tư tưởng lẫn triết học, sai hoàn toàn."],"s":"GT Triết học Mác-Lênin 2019 (3 chương), Ch.1 mục I.1 (khái lược về triết học, nguồn gốc triết học)","c":1,"v":"khớp","id":"3arnxp"},{"q":"Mối quan hệ giữa lĩnh vực kinh tế và lĩnh vực chính trị của xã hội được khái quát trong quy luật nào?","o":["Quy luật về mối quan hệ biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng","Quy luật đấu tranh giai cấp","Quy luật tôn tại xã hội quyết định ý thức xã hội","Tất cả đều sai"],"a":[0],"e":"Giáo trình trình bày mối quan hệ biện chứng giữa cơ sở hạ tầng (kinh tế) và kiến trúc thượng tầng (trong đó có chính trị, nhà nước) của xã hội; đây là sự khái quát quan hệ giữa lĩnh vực kinh tế và lĩnh vực chính trị. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Đấu tranh giai cấp là động lực phát triển của xã hội có giai cấp, không phải quy luật khái quát quan hệ kinh tế - chính trị.","Quy luật tồn tại xã hội quyết định ý thức xã hội nói về quan hệ giữa đời sống vật chất và đời sống tinh thần.","Sai vì A đúng."],"s":"GT Triết học Mác-Lênin 2019, Ch.3 mục I.3 (biện chứng giữa cơ sở hạ tầng và kiến trúc thượng tầng)","c":3,"v":"khớp","id":"15thh3z","f":1},{"q":"Lơxíp và Đêmôcrít có điểm chung là gì?","o":["Cà hai ông đều cho rằng, vật chất là nước","Cả hai ông đều cho rằng, vật chất là lửa","Cả hai ông đều cho rằng, vật chất là không khí","Cá hai ông đều cho rằng, vật chất là nguyên tử"],"a":[3],"e":"Giáo trình viết rõ: định nghĩa vật chất của Lơxíp và Đêmôcrít, cả hai ông đều cho rằng vật chất là nguyên tử, những hạt nhỏ nhất không thể phân chia. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Nước là quan điểm của Talét, không phải của Lơxíp và Đêmôcrít.","Lửa là quan điểm của Hêraclít.","Không khí là quan điểm của Anaximen.",""],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục I (vật chất và ý thức; quan niệm về vật chất trước Mác)","c":1,"v":"khớp","id":"1cdb5gs"},{"q":"Hiện tượng là:","o":["Một bộ phận của bản chất","Luôn đông nhất với bản chất","Biểu hiện bên ngoài của bản chất","Kết quà của bản chất"],"a":[2],"e":"Theo giáo trình, hiện tượng là phạm trù chỉ những biểu hiện của các mặt, mối liên hệ tất nhiên tương đối ổn định ở bên ngoài, là hình thức thể hiện của bản chất; tức là biểu hiện bên ngoài của bản chất. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Hiện tượng là sự biểu hiện của bản chất ra bên ngoài chứ không phải một bộ phận của bản chất.","Hiện tượng và bản chất thống nhất biện chứng nhưng không luôn đồng nhất; hiện tượng dễ biến đổi hơn bản chất.","","Bản chất mới là cái quy định, hiện tượng là hình thức thể hiện chứ không phải kết quả của bản chất."],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục II.2.b (cặp phạm trù bản chất - hiện tượng)","c":2,"v":"khớp"},{"q":"Về cơ bản, nhà nước có mấy chức năng?","o":["2","3","4","5"],"a":[0],"e":"Giáo trình chia chức năng của nhà nước theo hai góc độ: theo tính chất quyền lực chính trị là chức năng thống trị chính trị của giai cấp và chức năng xã hội (hai chức năng), theo phạm vi tác động là chức năng đối nội và đối ngoại (cũng hai). Đáp án 2 phù hợp với cách chia này. ([GT Triết học Mác-Lênin, bản 9 chương](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Giáo trình không chia nhà nước thành ba chức năng cơ bản.","Không có cách chia bốn chức năng cơ bản trong giáo trình.","Không có cách chia năm chức năng cơ bản trong giáo trình."],"s":"GT Triết học Mác-Lênin (bản 9 chương), mục «Chức năng cơ bản của nhà nước» (chương về nhà nước); bản 2019 3 chương: Ch.3 mục III.1.d","c":3,"v":"dễ nhầm","k":"Có hai cặp chức năng (thống trị chính trị - xã hội; đối nội - đối ngoại) nên dễ nhầm thành 4; đáp án 2 theo đề."},{"q":"Thời đại kinh tế ngày nay được gọi là gì?","o":["Nền kinh tế 4.0","Nền kinh tế tri thức","Nền kinh tế thị trường","Nền kinh tế hàng hóa nhiều thành phần"],"a":[1],"e":"Giáo trình nêu trong thời đại cách mạng công nghiệp lần thứ 4, nền kinh tế của nhiều quốc gia phát triển đang trở thành nền kinh tế tri thức, trong đó sự sản sinh, phổ cập và sử dụng tri thức đóng vai trò quyết định. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Kinh tế 4.0 không phải tên gọi chuẩn của một loại hình nền kinh tế; 4.0 gắn với cuộc cách mạng công nghiệp lần thứ 4.","","Kinh tế thị trường là cơ chế vận hành kinh tế, không đặc trưng cho thời đại ngày nay.","Kinh tế hàng hóa nhiều thành phần là mô hình của Việt Nam trong thời kỳ quá độ, không phải tên gọi thời đại."],"s":"GT Triết học Mác-Lênin 2019, Ch.3 mục I.2 (lực lượng sản xuất); chưa đối chiếu số mục chính xác","c":4,"v":"khớp"},{"q":"Trước khi chủ nghĩa duy vật biện chứng ra đời, nhìn chung các nhà triết học duy vật quan niệm vật chất là gì?","o":["Một hay một số chất tự có, đầu tiên","Toàn bộ vật chất","Vũ trụ quan","Giới tự nhiên","Ý thức"],"a":[0],"e":"Giáo trình nêu chủ nghĩa duy vật chất phác cổ đại đồng nhất vật chất với một hay một số chất cụ thể của vật chất (nước, lửa, không khí, nguyên tử...), mang tính trực quan, ngây thơ. Đó là quan niệm chung trước chủ nghĩa duy vật biện chứng. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Toàn bộ vật chất là cách hiểu phạm trù vật chất khái quát, không phải quan niệm của duy vật trước Mác.","Vũ trụ quan là cách nhìn thế giới, không phải định nghĩa vật chất.","Giới tự nhiên là đối tượng nghiên cứu, không phải quan niệm về vật chất.","Ý thức là cái đối lập với vật chất, quan niệm duy tâm."],"s":"GT Triết học Mác-Lênin 2019, Ch.1 mục I.2 (chủ nghĩa duy vật chất phác) và Ch.2 mục I","c":2,"v":"khớp","id":"ogerbk"},{"q":"\"Cái đơn nhất\" là phạm trù triết học dùng để chỉ:","o":["Thuộc tính tồn tại duy nhất ở một sự vật","Thuộc tính tồn tại trong nhiều sự vật hiện tượng","Những sự vật hiện tượng khách quan"],"a":[0],"e":"Cái đơn nhất là phạm trù triết học dùng để chỉ các mặt, các đặc điểm chỉ vốn có ở một sự vật, hiện tượng (một cái riêng) nào đó mà không lặp lại ở sự vật, hiện tượng nào khác. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Thuộc tính tồn tại ở nhiều sự vật là định nghĩa của cái chung.","Sự vật, hiện tượng khách quan nói chung gần với cái riêng và không nêu đặc điểm duy nhất."],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục II.2.b (cái riêng, cái chung, cái đơn nhất)","c":2,"v":"khớp"},{"q":"Khi đánh giá một con người, quan điểm toàn diện đòi hỏi điều gì?","o":["Phải đặc biệt nhấn mạnh một mặt nào đó, bỏ qua những mặt còn lại","Phải đặt họ vào những điều kiện, thời đại của minh mà đánh giá","Phải đặt họ trong những mối quan hệ với những người khác, với những việc khác có thể ảnh hưởng đến sự phát triển của họ mà đánh giá","Phải xuất phát từ mục đích và lợi ích của họ mà đánh giá"],"a":[2],"e":"Quan điểm toàn diện đòi hỏi xem xét sự vật trong mối liên hệ với các sự vật khác, các yếu tố có thể tác động. Khi đánh giá một con người, phải đặt họ trong các mối quan hệ với người khác, với việc khác có thể ảnh hưởng đến sự phát triển của họ. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Nhấn mạnh một mặt, bỏ qua mặt khác là quan điểm phiến diện, trái với toàn diện.","Đặt trong điều kiện, thời đại của mình là yêu cầu của quan điểm lịch sử - cụ thể.","","Chỉ xuất phát từ mục đích, lợi ích của họ là phiến diện, chủ quan."],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục II.2.a (nguyên lý về mối liên hệ phổ biến, quan điểm toàn diện)","c":2,"v":"khớp","id":"3kdmlz"},{"q":"Trong các yếu tố cầu thành cơ sở hạ tầng của xã hội, yếu tố nào đóng vai trò quyết định?","o":["Quan hệ sản xuất tàn dư của xã hội cũ","Quan hệ sản xuất mầm mống của xã hội tương lai","Quan hệ sản xuất thống trị","Quan hệ sản xuất chủ đạo"],"a":[2],"e":"Giáo trình nêu cơ sở hạ tầng gồm nhiều loại quan hệ sản xuất (tàn dư, thống trị, mầm mống), trong đó quan hệ sản xuất thống trị đặc trưng cho cơ sở hạ tầng của xã hội và giữ vai trò quyết định, chi phối các quan hệ sản xuất khác. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quan hệ sản xuất tàn dư là của xã hội cũ, không giữ vai trò quyết định.","Quan hệ sản xuất mầm mống là của xã hội tương lai, chưa chiếm vị trí chi phối.","","«Chủ đạo» không phải thuật ngữ giáo trình dùng cho cơ sở hạ tầng; giáo trình dùng «thống trị»."],"s":"GT Triết học Mác-Lênin 2019, Ch.3 mục I.3.a (khái niệm cơ sở hạ tầng và kiến trúc thượng tầng)","c":3,"v":"khớp","id":"spsrch"},{"q":"Theo quan điểm của triết học Mác - Lênin, thuộc tính phản ánh là thuộc tính:","o":["Riêng có ở con người","Chỉ có ở các cơ thể sống","Chỉ có ở các chất vô cơ","Phổ biến ở mọi tố chức vật chất"],"a":[3],"e":"Theo triết học Mác - Lênin, phản ánh là thuộc tính phổ biến của mọi dạng vật chất, từ giới vô sinh đến hữu sinh; ý thức chỉ là thuộc tính phản ánh của một dạng vật chất có tổ chức cao là bộ óc người. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Ý thức mới là hình thức phản ánh riêng có của con người; thuộc tính phản ánh nói chung thì phổ biến.","Phản ánh có cả ở giới vô sinh, không chỉ ở cơ thể sống.","Phản ánh không chỉ có ở chất vô cơ mà phát triển lên các hình thức cao hơn.",""],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục I.2.a (nguồn gốc của ý thức)","c":2,"v":"khớp","id":"qxf166"},{"q":"Định nghĩa vật chất của Lênin bao gồm mấy nội dung cơ bản?","o":["2","3","4","5"],"a":[1],"e":"Giáo trình nêu định nghĩa của Lênin: vật chất là phạm trù triết học chỉ thực tại khách quan, được đem lại cho con người trong cảm giác, được cảm giác chép lại, chụp lại, phản ánh và tồn tại không lệ thuộc vào cảm giác; đáp án của đề đếm thành ba nội dung cơ bản. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Hai nội dung là thiếu so với cách phân tích thông dụng.","","Bốn nội dung là thừa so với cách phân tích thông dụng.","Năm nội dung là thừa so với cách phân tích thông dụng."],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục I.1.c (quan niệm của triết học Mác - Lênin về vật chất)","c":2,"v":"dễ nhầm","k":"Giáo trình chỉ nói «các nội dung cơ bản sau đây» và phân tích theo từng ý; số 3 là cách đếm phổ biến trong đề cương, nên đáp án phụ thuộc cách đếm."},{"q":"Hiện tượng, quá trình khác nhau đều có những mối liên hệ cụ thể khác nhau, là biểu hiện của tính chất nào trong mối liên hệ?","o":["Đa dạng, phong phú","Khách quan","Phổ biến","Chung nhất"],"a":[0],"e":"Giáo trình nêu mối liên hệ phổ biến có tính đa dạng, phong phú: có mối liên hệ chung, riêng, bên trong, bên ngoài...; các hiện tượng, quá trình khác nhau có mối liên hệ cụ thể khác nhau là biểu hiện của tính đa dạng, phong phú. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Tính khách quan là mối liên hệ vốn có, không phụ thuộc ý thức con người.","Tính phổ biến là mối liên hệ có ở mọi sự vật, hiện tượng, mọi lĩnh vực.","«Chung nhất» không phải tên một tính chất của mối liên hệ trong giáo trình."],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục II.2.a (nguyên lý về mối liên hệ phổ biến)","c":2,"v":"khớp","id":"q4u2sd"},{"q":"Hiện thực là phạm trù triết học dùng để chỉ những gì:","o":["Sẽ tồn tại khi có đủ điều kiện","Đang tồn tại trong thực tế","Sẽ xuất hiện khi hội đủ mọi điều kiện"],"a":[1],"e":"Hiện thực là phạm trù chỉ cái đang có, đang tồn tại gồm tất cả các sự vật, hiện tượng đang tồn tại khách quan trong thực tế. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Cái sẽ tồn tại khi đủ điều kiện là khả năng, không phải hiện thực.","","Cái sẽ xuất hiện khi hội đủ điều kiện cũng là khả năng."],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục II.2.b (cặp phạm trù khả năng - hiện thực)","c":2,"v":"khớp"},{"q":"Toàn bộ những chính sách, quan điểm, tư tưởng, đường lối chỉ đạo của nhà nước được gọi là gì?","o":["Cơ sở hạ tầng","Cơ sở thượng tầng","Quan hệ sản xuất","Kiến trúc thượng tầng"],"a":[3],"e":"Kiến trúc thượng tầng là toàn bộ những quan điểm chính trị, pháp quyền, đạo đức, tôn giáo, nghệ thuật, triết học... cùng các thiết chế tương ứng như nhà nước, đảng phái, giáo hội, đoàn thể, được xây dựng trên một cơ sở hạ tầng nhất định. Những chính sách, tư tưởng, đường lối chỉ đạo của nhà nước thuộc kiến trúc thượng tầng. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Cơ sở hạ tầng là tổng hợp các quan hệ sản xuất hợp thành cơ cấu kinh tế.","«Cơ sở thượng tầng» không phải thuật ngữ; thuật ngữ đúng là kiến trúc thượng tầng.","Quan hệ sản xuất là một mặt của phương thức sản xuất, không gồm các quan điểm chính sách.",""],"s":"GT Triết học Mác-Lênin 2019, Ch.3 mục I.3.a (khái niệm cơ sở hạ tầng và kiến trúc thượng tầng)","c":3,"v":"khớp","id":"qcgs3x"},{"q":"Đâu là hình thức thế giới quan tôn tại trước thế giới quan triết học?","o":["Thế giới quan tiền tệ","Thế giới quan tôn giáo","Thế giới quan nhân sinh","Thế giới quan pháp luật"],"a":[1],"e":"Giáo trình nêu tư duy huyền thoại và tín ngưỡng nguyên thủy là loại hình triết lý đầu tiên để con người giải thích thế giới; triết học ra đời khi các loại hình tư duy huyền thoại và tôn giáo thu hẹp. Thế giới quan tôn giáo (cùng huyền thoại) tồn tại trước thế giới quan triết học. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Không có hình thức thế giới quan nào gọi là «tiền tệ» trong giáo trình.","","«Nhân sinh» không phải một hình thức thế giới quan trong giáo trình (ba hình thức chủ yếu: tôn giáo, khoa học, triết học).","Pháp luật là hiện tượng thuộc kiến trúc thượng tầng, không phải hình thức thế giới quan trước triết học."],"s":"GT Triết học Mác-Lênin 2019, Ch.1 mục I.1 (khái lược về triết học; thế giới quan)","c":1,"v":"khớp"},{"q":"Trong tư liệu sản xuất thì cái gì phản ánh rõ nhất trình độ phát triển của lực lượng sản xuất?","o":["Công cụ lao động","Máy móc","Đối tượng lao động","Công cụ tin học"],"a":[0],"e":"Giáo trình nêu trình độ của lực lượng sản xuất được thể hiện trước hết ở trình độ của công cụ lao động; công cụ lao động là yếu tố động nhất, phản ánh rõ nhất trình độ phát triển của lực lượng sản xuất. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Máy móc chỉ là một dạng công cụ lao động, phạm vi hẹp hơn.","Đối tượng lao động ít phản ánh trình độ phát triển lực lượng sản xuất.","Công cụ tin học chỉ là một loại công cụ lao động hiện đại, phạm vi hẹp hơn."],"s":"GT Triết học Mác-Lênin 2019, Ch.3 mục I.2.a (phương thức sản xuất, lực lượng sản xuất)","c":3,"v":"khớp"},{"q":"Đâu là tác phẩm của Ph. Ăngghen?","o":["\"Biện chứng của thiên nhiên\"","\"Biện chứng của tự nhiên\"","\"Biện chứng của tự do\"","\"Tự nhiên của biện chứng\""],"a":[1],"e":"Biện chứng của tự nhiên là tác phẩm của Ph. Ăngghen, được giáo trình nêu trong các tác phẩm của ông (cùng Chống Đuyrinh...). ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Sai tên: không phải «Biện chứng của thiên nhiên».","","Không có tác phẩm «Biện chứng của tự do» của Ăngghen.","Không có tác phẩm «Tự nhiên của biện chứng»."],"s":"GT Triết học Mác-Lênin 2019, Ch.1 mục II (sự ra đời và phát triển triết học Mác)","c":2,"v":"khớp","id":"u6ckhn"},{"q":"Vị trí, vai trò của Triết học Mác - Lênin trong đời sống xã hội và trong sự nghiệp đổi mới ở Việt Nam hiện nay?","o":["Thúc đấy","Đối lập","Mâu thuẫn","Quan trọng, là nên tảng tư tưởng, kim chỉ nam cho hành động"],"a":[3],"e":"Triết học Mác - Lênin là nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng và nhân dân ta trong sự nghiệp đổi mới; vị trí, vai trò đó là quan trọng. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Thúc đẩy» chưa nêu đúng vị trí nền tảng tư tưởng, kim chỉ nam.","Không đối lập với sự nghiệp đổi mới mà dẫn đường cho nó.","Không mâu thuẫn với đổi mới mà là cơ sở thế giới quan, phương pháp luận cho nó.",""],"s":"GT Triết học Mác-Lênin 2019, các mục về vai trò của triết học Mác - Lênin; chưa đối chiếu số mục chính xác","c":1,"v":"khớp","id":"o9cwor"},{"q":"Theo triết học Mác, sự chuyển dịch từ hình thái kinh tế chiếm hữu nô lệ, sang phong kiến rồi đến xã hội chủ nghĩa thuộc loại vận động nào?","o":["Vận động vật lý","Vận động hóa học","Vận động sinh học","Vận động xã hội"],"a":[3],"e":"Ph. Ăngghen chia vận động của vật chất thành năm hình thức cơ bản: cơ học, vật lý, hóa học, sinh học và xã hội. Sự chuyển từ hình thái kinh tế - xã hội này sang hình thái khác là vận động xã hội. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Vận động vật lý là vận động của các hạt, trường, năng lượng.","Vận động hóa học là hóa hợp, phân giải các chất.","Vận động sinh học là quá trình trao đổi chất của cơ thể sống.",""],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục I.1.d (các hình thức tồn tại của vật chất, hình thức vận động cơ bản)","c":2,"v":"khớp"},{"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử, lực lượng chủ thể sáng tạo ra lịch sử là:","o":["Quần chúng nhân dân","Vĩ nhân, lãnh tụ","Tầng lớp trí thức","Trí thức, vĩ nhân"],"a":[0],"e":"Chủ nghĩa duy vật lịch sử khẳng định quần chúng nhân dân là chủ thể sáng tạo chân chính ra lịch sử; vĩ nhân, lãnh tụ có vai trò quan trọng nhưng không thay thế được quần chúng. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Vĩ nhân, lãnh tụ dẫn dắt, thúc đẩy nhưng không phải chủ thể sáng tạo chính.","Tầng lớp trí thức chỉ là một bộ phận của quần chúng nhân dân.","Trí thức, vĩ nhân đều chỉ là bộ phận, không phải chủ thể chung."],"s":"GT Triết học Mác-Lênin 2019, Ch.3 (vai trò quần chúng nhân dân); chưa đối chiếu số mục chính xác","c":3,"v":"khớp"},{"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử, nhà nước là gì?","o":["Tổ chức phi chính phủ","Tổ chức quyền lực phi giai cấp","Tổ chức quyền lực mang bản chất của giai cấp sở hữu tư liệu sản xuất chủ yếu của xã hội","Tổ chức quyền lực mang bàn chất của mọi giai cấp trong xã hội"],"a":[2],"e":"Nhà nước là tổ chức đặc biệt của quyền lực chính trị, mang bản chất giai cấp của giai cấp thống trị (giai cấp sở hữu tư liệu sản xuất chủ yếu của xã hội), là công cụ thống trị giai cấp. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Nhà nước là tổ chức quyền lực, không phải tổ chức phi chính phủ.","Nhà nước có tính giai cấp, không phải tổ chức phi giai cấp.","","Nhà nước mang bản chất của giai cấp thống trị, không phải của mọi giai cấp."],"s":"GT Triết học Mác-Lênin 2019, Ch.3 mục III.1.b (bản chất của nhà nước)","c":3,"v":"khớp","id":"1irus1g"},{"q":"Theo quan niệm duy vật biện chứng về lịch sử thì những quan hệ sản xuất cũ được thay thế bằng quan hệ sản xuất mới, phù hợp trình độ phát triển của lực lượng sản xuất đã phát triển nhờ điều gì?","o":["Cải cách triệt để","Cách mạng vô sản","Cách mạng xã hội","Đảo chính"],"a":[2],"e":"Theo quan điểm duy vật lịch sử, khi quan hệ sản xuất cũ trở nên lỗi thời, kìm hãm lực lượng sản xuất thì thông qua cách mạng xã hội, quan hệ sản xuất cũ được thay bằng quan hệ sản xuất mới phù hợp. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Cải cách chỉ thay đổi bộ phận, không thay đổi căn bản quan hệ sản xuất.","Cách mạng vô sản là một loại cách mạng xã hội cụ thể; câu hỏi nêu khái niệm chung là cách mạng xã hội.","","Đảo chính chỉ thay đổi nhân sự quyền lực, không thay đổi chế độ."],"s":"GT Triết học Mác-Lênin 2019, Ch.3 mục I.2 và III.2 (cách mạng xã hội); chưa đối chiếu số mục chính xác","c":3,"v":"khớp"},{"q":"Triết học do C.Mác và Ph.Ăng-ghen thực hiện là bước ngoặt cách mạng trong sự phát triển của triết học. Biểu hiện vĩ đại nhất của bước ngoặt cách mạng đó là:","o":["Thay đổi căn bản tính chất của triết học, thay đổi căn bản đối tượng của nó và mối quan hệ đối với các khoa học khác","Gắn bó chặt chẽ giữa triết học với phong trào cách mạng của giai cấp vô sản và quần chúng lao động","Sáng tạo ra chủ nghĩa duy vật lịch sử làm thay đổi quan niệm của con người về xã hội","Làm cho triết học trở nên phổ biến trong cuộc sống"],"a":[2],"e":"Giáo trình nêu Mác và Ăngghen sáng tạo ra chủ nghĩa duy vật lịch sử, thành tựu vĩ đại nhất của tư tưởng khoa học, là cuộc cách mạng thực sự trong triết học về xã hội và nội dung chủ yếu của bước ngoặt cách mạng trong triết học. Đáp án C bám sát ý này. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Cũng là nội dung của bước ngoặt cách mạng nhưng đề hỏi biểu hiện vĩ đại nhất, nên chọn C.","Gắn bó với phong trào cách mạng là một đặc trưng, không phải biểu hiện vĩ đại nhất.","","Làm triết học phổ biến chỉ là hệ quả, không phải nội dung của bước ngoặt."],"s":"GT Triết học Mác-Lênin 2019, Ch.1 mục II.1 (sự ra đời triết học Mác, bước ngoặt cách mạng)","c":1,"v":"dễ nhầm","k":"Giáo trình dùng cụm «nội dung chủ yếu của bước ngoặt cách mạng», phương án A cũng nằm trong bước ngoặt; đáp án C theo đề.","id":"1tchzzx"},{"q":"Các hình thức cơ bản của chủ nghĩa duy tâm:","o":["Duy tâm chủ quan và duy tâm khách quan","Duy tâm biện chứng và duy tâm siêu hình","Duy tâm trung cổ cận đại và duy tâm cổ điển Đức","Duy tâm khách quan và duy tâm cổ đại"],"a":[0],"e":"Giáo trình nêu chủ nghĩa duy tâm có hai phái chủ yếu: chủ nghĩa duy tâm chủ quan và chủ nghĩa duy tâm khách quan. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Biện chứng và siêu hình là hai phương pháp tư duy, không phải hình thức của duy tâm.","Cách chia theo thời kỳ lịch sử, không phải hình thức cơ bản của duy tâm.","Duy tâm cổ đại không phải một hình thức cơ bản đối ứng với duy tâm khách quan."],"s":"GT Triết học Mác-Lênin 2019, Ch.1 mục I.2 (nội dung vấn đề cơ bản; chủ nghĩa duy tâm)","c":1,"v":"khớp"},{"q":"Sự sinh ra, lớn lên, già đi thuộc hình thức vận động nào trong triết học?","o":["Vận động cơ học","Vận động sinh học","Vận động vật lý","Vận động hóa học"],"a":[1],"e":"Ph. Ăngghen chia vận động thành năm hình thức; sự sinh ra, lớn lên, già đi của cơ thể sống (trao đổi chất) thuộc vận động sinh học. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Vận động cơ học là sự dịch chuyển vị trí trong không gian.","","Vận động vật lý là vận động của các hạt, trường, năng lượng.","Vận động hóa học là hóa hợp và phân giải các chất."],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục I.1.d (hình thức vận động cơ bản của vật chất)","c":2,"v":"khớp"},{"q":"Cấu trúc của phương thức sản xuất gồm những yếu tố nào sau đây?","o":["Công cụ lao động, đối tượng lao động","Trình độ lao động, quan hệ sản xuất","Lực lượng sản xuất, quan hệ sản xuất","Tư liệu sản xuất và con người"],"a":[2],"e":"Phương thức sản xuất là cách thức con người thực hiện sản xuất vật chất ở những giai đoạn lịch sử nhất định, gồm hai mặt là lực lượng sản xuất và quan hệ sản xuất. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Công cụ lao động và đối tượng lao động là yếu tố của tư liệu sản xuất.","Trình độ lao động không phải một cấu trúc của phương thức sản xuất và thiếu lực lượng sản xuất.","","Tư liệu sản xuất và con người là các yếu tố của lực lượng sản xuất."],"s":"GT Triết học Mác-Lênin 2019, Ch.3 mục I.2.a (phương thức sản xuất)","c":3,"v":"khớp","id":"w4kakz"},{"q":"Chỉ tính quy định, mối liên hệ thống nhất giữa chất và lượng, là khoảng giới hạn mà trong đó sự thay đổi về lượng của sự vật chưa làm thay đổi căn bản chất của nó gọi là:","o":["Độ","Giối hạn","Điểm nút","Tích về lượng"],"a":[0],"e":"Độ là khái niệm chỉ mối liên hệ thống nhất giữa chất và lượng, là giới hạn tồn tại của sự vật mà trong đó thay đổi về lượng chưa dẫn đến thay đổi về chất. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","«Giới hạn» là từ chung, không phải khái niệm chuẩn; điểm giới hạn mới là điểm nút.","Điểm nút là điểm giới hạn mà tại đó thay đổi về lượng làm chất đổi.","Tích về lượng không phải tên khái niệm của quy luật chuyển hóa lượng - chất."],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục II.2.c (quy luật lượng - chất)","c":2,"v":"khớp","id":"o9pbct"},{"q":"Các hình thức tồn tại của các dạng cụ thể của vật chất ở một vị trí nhất định, có một quảng tinh nhất định và tồn tại trong mối tương quan nhất định với các dạng cụ thể khác của vật chất được goi là","o":["Tồn tại của vật chất","Thời gian","Không gian","Sự tồn tại"],"a":[2],"e":"Không gian là hình thức tồn tại của vật chất xét về mặt quảng tính, sự cùng tồn tại, trật tự phân bố và tương quan với các dạng khác. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Tồn tại của vật chất» quá chung chung, không chỉ riêng quảng tính.","Thời gian là hình thức tồn tại xét về mặt độ dài diễn biến, sự kế tiếp.","","«Sự tồn tại» không phải khái niệm xác định ở đây."],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục I.1.d (không gian, thời gian)","c":2,"v":"khớp","id":"50eexa"},{"q":"Chủ nghĩa duy tâm có nguồn gốc nhận thức và nguồn gốc xã hội là trong quá trình nhân thức nó xem xét phiến diện, tuyệt đổi hóa, thần thánh hóa cái gì của quá trình nhận thức?","o":["Một đối tượng","Những đặc tính nào đó","Một số mặt nào đó","Một mặt, một đặc tính nào đó"],"a":[3],"e":"Giáo trình nêu chủ nghĩa duy tâm có nguồn gốc nhận thức từ cách xem xét phiến diện, tuyệt đối hóa, thần thánh hóa một mặt, một đặc tính nào đó của quá trình nhận thức; ngoài ra còn có nguồn gốc xã hội. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Một đối tượng» không phải cụm giáo trình dùng.","«Những đặc tính» là số nhiều, giáo trình nói một mặt, một đặc tính.","«Một số mặt» là số nhiều, lệch so với «một mặt, một đặc tính».",""],"s":"GT Triết học Mác-Lênin 2019, Ch.1 mục I.2 (nguồn gốc nhận thức của chủ nghĩa duy tâm)","c":1,"v":"khớp","id":"1f48ae6"},{"q":"Giả sử khái niệm Việt Nam là một \"cái riêng\" thì yếu tố nào sau đây là cái đơn nhất?","o":["Con người","Quốc gia","Văn hóa","Hà Nội"],"a":[3],"e":"Cái đơn nhất chỉ có ở một cái riêng. Giáo trình bản cũ lấy ví dụ: những đặc điểm chỉ ở Hà Nội mới có là cái đơn nhất, còn con người, quốc gia, văn hóa là những mặt, thuộc tính lặp lại ở nhiều cái riêng nên là cái chung. ([GT Triết học Mác-Lênin, bản 9 chương](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Con người có ở nhiều quốc gia, thuộc cái chung.","Quốc gia cũng là phạm trù chung cho nhiều nước.","Văn hóa là thuộc tính chung của nhiều cộng đồng.",""],"s":"GT Triết học Mác-Lênin (bản 9 chương), mục cái riêng, cái chung, cái đơn nhất (Ch.VII); bản 2019: Ch.2 mục II.2.b","c":2,"v":"khớp","id":"3zram0"},{"q":"Nhận thức lý tính được thực hiện dưới hình thức nào?","o":["Cảm giác, tri giác và phán đoán","Khái niệm, phán đoán và suy lý","Cảm giác, khái niệm, suy lý","Cảm giác, tri giác, biểu tượng"],"a":[1],"e":"Nhận thức lý tính, bắt nguồn từ trực quan sinh động, thông qua tư duy trừu tượng, phản ánh sự vật gián tiếp, khái quát hơn dưới các hình thức khái niệm, phán đoán và suy lý. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Cảm giác, tri giác thuộc nhận thức cảm tính; chỉ phán đoán thuộc lý tính.","","Cảm giác thuộc nhận thức cảm tính, trộn lẫn hai giai đoạn.","Cảm giác, tri giác, biểu tượng là ba hình thức của nhận thức cảm tính."],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục III.4 (các giai đoạn cơ bản của quá trình nhận thức)","c":2,"v":"khớp"},{"q":"Ý thức xã hội phản ánh tồn tại xã hội với hai trình độ khác nhau đó là hai trình độ nào?","o":["Tâm lý xã hội và hệ tư tưởng xã hội","Tâm lý con người và hệ tư tưởng","Tinh thần xã hội và hệ tư tưởng","Nên tảng vật chất và giá trị tinh thần"],"a":[0],"e":"Giáo trình nêu kết cấu của ý thức xã hội gồm tâm lý xã hội và hệ tư tưởng xã hội, là hai trình độ phản ánh tồn tại xã hội. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","«Tâm lý con người» không phải thuật ngữ; giáo trình dùng tâm lý xã hội.","«Tinh thần xã hội» không phải thuật ngữ chuẩn trong giáo trình.","Nền tảng vật chất, giá trị tinh thần không phải hai trình độ của ý thức xã hội."],"s":"GT Triết học Mác-Lênin 2019, Ch.3 mục IV.2 (khái niệm ý thức xã hội, kết cấu)","c":3,"v":"khớp","id":"10m4wlp"},{"q":"Cái tất nhiên là cái do:","o":["Những nguyên nhân cơ bản bên trong sự vật quy định","Những nguyên nhân bên ngoài sự vật qui định","Cả nguyên nhân bên trong và nguyên nhân bên ngoài sự vật qui định","Những nguyên nhân bản chất bên trong qui định"],"a":[0],"e":"Tất nhiên là phạm trù chỉ mối liên hệ bản chất, do nguyên nhân cơ bản bên trong sự vật, hiện tượng quy định và trong điều kiện nhất định phải xảy ra đúng như thế chứ không thể khác. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Nguyên nhân bên ngoài quy định là đặc điểm của cái ngẫu nhiên.","Kết hợp bên trong và bên ngoài không phải định nghĩa cái tất nhiên.","Gần nghĩa với A nhưng đổi cụm giáo trình «nguyên nhân cơ bản» thành «nguyên nhân bản chất»; đề chọn A theo nguyên văn."],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục II.2.b (tất nhiên và ngẫu nhiên)","c":2,"v":"dễ nhầm","k":"A và D rất gần nghĩa; A khớp nguyên văn giáo trình («nguyên nhân cơ bản bên trong»)."},{"q":"Cơ sở khách quan của xây dựng liên minh giữa giai cấp công nhân với giai cấp nông dân và các tầng lớp lao động khác trong cách mạng xã hội chủ nghĩa là công nghiệp và nông nghiệp là hai ngành có vai trò như thế nào?","o":["Sản xuất","Đảm bảo các nhu cầu xã hội","Đảm bảo cân đối cung-cầu","Sản xuất chính"],"a":[0],"e":"Về cơ sở khách quan của liên minh công - nông, nguồn tham khảo viết: liên minh công nông do sự gắn bó thống nhất giữa sản xuất công nghiệp với sản xuất nông nghiệp, hai ngành sản xuất chính trong xã hội. ([Ôn thi sinh viên - CNXHKH](https://onthisinhvien.com/tinh-tat-yeu-va-co-so-khach-quan-cua-lien-minh-giua-giai-cap-cong-nhan-voi-giai-cap-nong-dan-chu-nghia-xa-hoi-khoa-hoc))","w":["","Đảm bảo nhu cầu xã hội là kết quả, không phải cách mô tả vai trò hai ngành trong nguồn.","Đảm bảo cân đối cung - cầu không phải ý nêu cơ sở khách quan.","«Sản xuất chính» lại là cụm sát nguyên văn nguồn (hai ngành sản xuất chính), nên đáng nghi so với đáp án A."],"s":"GT Chủ nghĩa xã hội khoa học (liên minh giai cấp công nhân với nông dân); chưa đối chiếu số chương","c":4,"v":"nghi vấn","k":"nghi vấn: Đáp án của đề là A (Sản xuất) nhưng nguồn nói hai ngành sản xuất chính, sát với D; đề hỏi cụt, giữ đáp án theo đề, cần đối chiếu giáo trình CNXHKH.","id":"c5tbkx"},{"q":"Một nhóm sinh viên tranh luận về chân lý, hãy xác định ý kiến nào đúng nhất, chân lý là gì?","o":["Quan điểm được mọi người trong cuộc bỏ phiếu tán thành","Quan điểm được đa số ủng hộ","Một phán đoán đúng quy tắc logic","Một quan điểm được chứng minh trong thực tiễn là đúng"],"a":[3],"e":"Chân lý là tri thức phù hợp với hiện thực khách quan và được thực tiễn kiểm nghiệm; thực tiễn là tiêu chuẩn của chân lý. Vì vậy quan điểm được chứng minh đúng trong thực tiễn mới là chân lý. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Biểu quyết, tán thành không quyết định chân lý.","Số đông ủng hộ chưa chắc là đúng.","Hợp logic là điều kiện cần, chưa đủ; phải kiểm nghiệm bằng thực tiễn.",""],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục III.5 (tính chất của chân lý)","c":2,"v":"khớp","id":"9ehtnx"},{"q":"Theo quan điểm duy vật lịch sử, sản xuất ra của cải vật chất giữ vai trò là:","o":["Nền tảng của xã hội","Nền tảng vật chất của xã hội","Nền tảng tinh thần của xã hội","Nền tảng kỹ thuật, công nghệ của xã hội"],"a":[1],"e":"Giáo trình nêu sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội; sản xuất ra của cải vật chất giữ vai trò nền tảng vật chất của xã hội. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Nói «nền tảng của xã hội» chưa nêu tính chất vật chất; đề chọn phương án B cụ thể hơn.","","Nền tảng tinh thần là phái sinh từ đời sống vật chất.","Kỹ thuật, công nghệ chỉ là yếu tố của lực lượng sản xuất."],"s":"GT Triết học Mác-Lênin 2019, Ch.3 mục I.1 (sản xuất vật chất là cơ sở của tồn tại và phát triển xã hội)","c":3,"v":"dễ nhầm","k":"Trùng nội dung với câu 361; A và B gần nghĩa, đáp án B theo đề.","id":"ii5jbp"},{"q":"Phép biện chứng chất phác thời cổ đại là","o":["Một hình thức của chủ nghĩa duy tâm","Một phần của chủ nghĩa duy vật","Tất cà đều đúng","Một hình thức của phép biện chứng"],"a":[3],"e":"Giáo trình nêu có ba hình thức cơ bản của phép biện chứng, trong đó phép biện chứng chất phác thời cổ đại là hình thức đầu tiên; do đó nó là một hình thức của phép biện chứng. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Biện chứng chất phác không phải một hình thức của duy tâm.","Đúng là gắn với duy vật chất phác, nhưng phương án này nêu «một phần của chủ nghĩa duy vật» sai về loại khái niệm: biện chứng là phương pháp, không phải thế giới quan.","A và B đều sai nên «tất cả đều đúng» sai.",""],"s":"GT Triết học Mác-Lênin 2019, Ch.1 mục I.3 (biện chứng và siêu hình)","c":2,"v":"khớp","id":"k0f922"},{"q":"Tổng hợp tất cả những mặt, những mối liên hệ tất nhiên, tương đối ổn định bên trong sự vật, quy định sự vận động và phát triển của sự vật gọi là gì?","o":["Bản chất","Hiện tượng","Nội dung","Hình thức"],"a":[0],"e":"Bản chất là phạm trù chỉ tổng thể các mối liên hệ khách quan, tất nhiên, tương đối ổn định bên trong, quy định sự vận động, phát triển của đối tượng và thể hiện mình qua các hiện tượng tương ứng. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Hiện tượng là biểu hiện bên ngoài của bản chất.","Nội dung thuộc cặp phạm trù nội dung - hình thức.","Hình thức thuộc cặp nội dung - hình thức."],"s":"GT Triết học Mác-Lênin 2019, Ch.2 mục II.2.b (bản chất - hiện tượng)","c":2,"v":"khớp"},{"q":"Vấn đề cơ bản của Triết học là gì?","o":["Mối quan hệ giữa tự nhiên và bản thể","Mối quan hệ giữa tư duy và tồn tại","Mối quan hệ giữa cái chung và cái riêng","Con người và bản thể"],"a":[1],"e":"Vấn đề cơ bản của triết học là vấn đề về mối quan hệ giữa vật chất với ý thức (tư duy với tồn tại); đây là vấn đề có ý nghĩa nền tảng và là điểm xuất phát để giải quyết các vấn đề còn lại của triết học. ([GT Triết học Mác-Lênin 2019](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quan hệ tự nhiên - bản thể không phải vấn đề cơ bản.","","Cái chung - cái riêng là một cặp phạm trù của phép biện chứng.","Con người và bản thể không phải vấn đề cơ bản của triết học."],"s":"GT Triết học Mác-Lênin 2019, Ch.1 mục I.2.1 (nội dung vấn đề cơ bản của triết học)","c":1,"v":"khớp"},{"q":"Chủ nghĩa duy vật biện chứng khẳng định rằng, nguyên nhân sinh ra kết quả phải có thêm yếu tố nào","o":["Tác động","Điều kiện","Nguyên cớ","Ý chí"],"a":[1],"e":"Giáo trình nêu rõ kết quả do nguyên nhân sinh ra còn phụ thuộc vào những điều kiện, hoàn cảnh nhất định; một nguyên nhân nhất định trong hoàn cảnh nhất định chỉ có thể gây ra một kết quả nhất định. Vì vậy nguyên nhân muốn sinh ra kết quả phải có thêm yếu tố điều kiện. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Tác động» là bản thân sự tương tác giữa các mặt, các sự vật; giáo trình định nghĩa chính sự tác động này là nguyên nhân, nên không phải yếu tố bổ sung.","","«Nguyên cũ» không phải thuật ngữ triết học, lỗi chép đề, vô nghĩa.","«Y chí» (ý chí) là yếu tố chủ quan của con người; mối quan hệ nhân quả có tính khách quan, không cần ý chí mới sinh ra kết quả."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.2, mục II.2 (Nội dung của phép biện chứng duy vật: cặp phạm trù nguyên nhân - kết quả)","c":2,"v":"khớp","k":"Phương án C và D bị lỗi chính tả trong đề (Nguyên cũ, Y chí).","id":"zolxn1"},{"q":"Theo quan điểm của chủ nghĩa duy vật thì những mối liên hệ tồn tại ở mọi sự vật, hiện tượng của thế giới là mối liên hệ","o":["Chung","Quan trọng","Khá phổ biến","Phổ biến"],"a":[3],"e":"Phép biện chứng duy vật khẳng định tính phổ biến của mối liên hệ: mọi sự vật, hiện tượng trong tự nhiên, xã hội và tư duy đều nằm trong các mối liên hệ; đây là nội dung của nguyên lý về mối liên hệ phổ biến. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Chung» không phải thuật ngữ dùng để gọi tính chất này; cái chung là phạm trù khác (cái chung - cái riêng).","«Quan trọng» chỉ mức độ ý nghĩa, không phải tính chất mà giáo trình dùng cho mối liên hệ tồn tại ở mọi sự vật.","«Khá phổ biến» làm yếu đi tính tuyệt đối; nguyên lý khẳng định mọi sự vật, hiện tượng đều có liên hệ.",""],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.2, mục II.2 (Nguyên lý về mối liên hệ phổ biến); chưa đối chiếu nguyên văn câu hỏi","c":2,"v":"khớp","id":"808qca"},{"q":"Nguyên nhân và kết quả cái nào có trước?","o":["Nguyên nhân","Kết quả","Cả hai cùng xuất hiện trước","Không cái nào xuất hiện trước"],"a":[0],"e":"Giáo trình nêu rằng xét về mặt thời gian, nguyên nhân có trước kết quả, nên khi tìm nguyên nhân của một sự vật cần tìm ở những sự kiện đã xảy ra trước đó. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Kết quả là biến đổi do nguyên nhân gây ra nên xuất hiện sau, không thể có trước.","Hai cái không xuất hiện đồng thời; nguyên nhân có trước (không nên nhầm với việc chúng có thể đổi chỗ cho nhau ở các mối quan hệ khác nhau).","Có trình tự thời gian rõ ràng: nguyên nhân có trước kết quả."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.2, mục II.2 (cặp phạm trù nguyên nhân - kết quả, ý nghĩa phương pháp luận)","c":2,"v":"khớp"},{"q":"Mối liên hệ thống nhất và đầu tranh, chuyển hoá giữa các mặt đối lập của mỗi sự vật, hiện tượng hoặc giữa các sự vật, hiện tượng với nhau gọi là khái niệm gì?","o":["Chuyển hoá chất, lượng","Sự thống nhất","Quan hệ hài hòa.","Mâu thuẫn"],"a":[3],"e":"Trong phép biện chứng duy vật, mâu thuẫn biện chứng là khái niệm chỉ sự liên hệ, tác động theo cách vừa thống nhất, vừa đấu tranh, vừa chuyển hóa lẫn nhau giữa các mặt đối lập. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Chuyển hóa chất - lượng là nội dung quy luật lượng - chất, không phải khái niệm mô tả quan hệ giữa các mặt đối lập.","Sự thống nhất chỉ là một mặt của mâu thuẫn, chưa bao gồm đấu tranh và chuyển hóa.","«Quan hệ hài hòa» không phải thuật ngữ của giáo trình và đi ngược với đấu tranh giữa các mặt đối lập.",""],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.2, mục II.2 (Quy luật thống nhất và đấu tranh của các mặt đối lập)","c":2,"v":"khớp"},{"q":"Ai là người khẳng định: \"lao động đã sáng tạo ra bản thân con người?","o":["Ph.Ăngghen","L.Phoiơbắc","Immanuel Kant","Béccơren"],"a":[0],"e":"Ph. Ăngghen khẳng định rằng, theo một ý nghĩa cao nhất, lao động đã sáng tạo ra bản thân con người; giáo trình trích câu này khi nói vai trò của sản xuất vật chất đối với sự hình thành con người. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","L. Phoiơbắc là nhà duy vật nhân bản, không phải tác giả của luận điểm này.","I. Cantơ là người sáng lập triết học cổ điển Đức, không phải tác giả.","Béccdren (đề chép sai tên) không phải tác giả luận điểm này."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.3, mục I.1; gốc: Ph. Ăngghen, Vai trò của lao động trong quá trình chuyển biến từ vượn thành người","c":2,"v":"khớp","id":"jvhk41"},{"q":"Theo quan niệm duy vật biện chứng về lịch sử thì đề giải thích đúng đắn các vấn đề của đời sống xã hội thì phải tìm nguyên nhân cuối cùng từ thực trạng phát triển của năm sản xuất vật chất của xã hội đô, mà căn bản là từ trình độ phát triển của","o":["Phương thức sản xuất của nó","Quan hệ sản xuất của nó","Tư liệu sản xuất của nó","Cơ sở vật chất"],"a":[1],"e":"Đề hỏi nguyên nhân cuối cùng của các vấn đề đời sống xã hội phải tìm từ trình độ phát triển của yếu tố nào trong nền sản xuất vật chất. Theo giáo trình, lực lượng sản xuất là yếu tố xét đến cùng quyết định sự vận động, phát triển của hình thái kinh tế - xã hội; đáp án đề cho là B (quan hệ sản xuất) nên chỉ học theo đề, còn cần đối chiếu với giáo trình. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Phương thức sản xuất là sự thống nhất của lực lượng sản xuất và quan hệ sản xuất; nó là khái niệm rộng, không phải yếu tố mà trình độ của nó được xét ở đây.","","Tư liệu sản xuất chỉ là một bộ phận (cùng với người lao động) của lực lượng sản xuất.","Cơ sở vật chất không phải phạm trù chuẩn của học thuyết hình thái kinh tế - xã hội ở đây."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.3, mục I.4 (lực lượng sản xuất là yếu tố xét đến cùng quyết định) và Ch.3, mục I.2; chưa tìm được nguyên văn câu hỏi trong giáo trình","c":3,"v":"nghi vấn","k":"nghi vấn: Đáp án đề là B (quan hệ sản xuất) nhưng chưa tìm được nguyên văn câu này trong giáo trình. Giáo trình bản 2021 viết lực lượng sản xuất là yếu tố xét đến cùng quyết định sự vận động của hình thái kinh tế - xã hội, và Ph. Ăngghen (Chống Đuyrinh) tìm nguyên nhân cuối cùng ở biến đổi của phương thức sản xuất; Lênin có công thức quy quan hệ sản xuất vào trình độ lực lượng sản xuất. Vì vậy B đáng nghi: có thể đề chép nhầm hoặc đáp án đúng là lực lượng sản xuất (không có trong các lựa chọn). Cần kiểm tra lại với giảng viên. Tham khảo: [Ph. Ăngghen, Chống Đuyrinh, marxists.org](https://www.marxists.org/vietnamese/marx-engels/1870s/chongduhring/phan_27.htm).","id":"1xdyeqg"},{"q":"Tinh thiên - Trời hửng Sự vật vần xoay đà định sẵn, Hết mưa là nắng hừng lên thôi, Đất trời một thoáng thu màn ướt, Sông núi muôn trùng trải gấm phơi, Trời ẩm, hoa cười chào gió nhẹ, Cây cao, chim hót rộn cành tươi, Người cùng vạn vật đều phơi phới, Hết khổ là vui vốn lẽ đời. Trong bài thơ trên của Chủ tịch Hồ Chí Minh, cặp phạm trù nào được nhắc đến?","o":["Cái chung, cái riêng","Bản chất, hiện tượng","Tất nhiên, ngẫu nhiên","Nguyên nhân, kết quả"],"a":[2],"e":"Các câu «sự vật vần xoay đã định sẵn», «hết mưa là nắng», «hết khổ là vui vốn lẽ đời» diễn tả cái xảy ra theo quy luật, trong điều kiện nhất định phải xảy ra như thế, tức cái tất nhiên; còn cảnh cụ thể (hoa cười, chim hót) là biểu hiện ngẫu nhiên. Giáo trình định nghĩa tất nhiên là mối liên hệ bản chất, do nguyên nhân bên trong quy định, trong điều kiện nhất định phải xảy ra đúng như thế. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Bài thơ không nói tới quan hệ giữa cái chung và cái riêng.","Bài thơ không đối lập bản chất với hiện tượng.","","Quan hệ nhân quả mờ hơn: hiện tượng nối tiếp (mưa rồi nắng) được diễn đạt như tính tất yếu của quy luật, nên cặp phạm trù thích hợp hơn là tất nhiên - ngẫu nhiên."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.2, mục II.2 (cặp phạm trù tất nhiên - ngẫu nhiên); chưa kiểm chứng nguồn bài thơ","c":2,"v":"dễ nhầm","k":"Câu phân tích văn học nên mang tính gợi mở, dễ nhầm với nguyên nhân - kết quả (hết mưa là nắng). Chưa tìm được nguồn xác nhận bài thơ và đáp án trong tài liệu học thuật; chỉ đối chiếu được định nghĩa tất nhiên - ngẫu nhiên."},{"q":"Lơxíp (khoảng 500 - 440 trước CN) được xem là?","o":["Nhà triết học Giáo hội Cổ đại","Nhà toán học Hi Lạp Cổ đại","Nhà triết học Hi Lạp Cổ đại","Nhà thần học Hi Lạp Cổ đại"],"a":[2],"e":"Giáo trình gọi Lơxíp (khoảng 500 - 440 trước CN) cùng Đêmôcrít là hai nhà triết học Hy Lạp cổ đại; hai ông cho rằng vật chất là nguyên tử. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Không có khái niệm «nhà triết học Giáo hội Cổ đại» trong giáo trình; Lơxíp thuộc triết học Hy Lạp cổ đại.","Giáo trình xếp ông vào nhà triết học, không phải nhà toán học.","","Ông là nhà duy vật, không phải nhà thần học."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.2, mục I.1 (Vật chất và các hình thức tồn tại của vật chất)","c":1,"v":"khớp","id":"2gzc5g"},{"q":"Ai được xem là nhà triết học thiên tài vào thế kỷ XVIII - XIX?","o":["Heraclitus","Immanuel Kant","Socrates","Bruno Fesnades"],"a":[1],"e":"Giáo trình nêu I. Kant (Cantơ) là nhà triết học sáng lập ra triết học cổ điển Đức ở thế kỷ XVIII; cùng Hêghen ông là đỉnh cao của triết học cổ điển Đức, nên đáp án là Kant. Cụm «thiên tài» là cách nói của đề, không phải thuật ngữ của giáo trình. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Hêraclít là nhà triết học Hy Lạp cổ đại, không thuộc thế kỷ XVIII - XIX.","","Xôcrát là nhà triết học Hy Lạp cổ đại.","Brunô (đề chép sai tên) là nhà triết học thời Phục hưng, không phải thế kỷ XVIII - XIX."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.1, mục I.1 (Khái lược về triết học)","c":1,"v":"khớp","id":"6s0c81"},{"q":"Chủ nghĩa duy vật hình thành và phát triển với mấy hình thức cơ bản?","o":["1","2","3","4"],"a":[2],"e":"Giáo trình viết: cho đến nay chủ nghĩa duy vật đã được thể hiện dưới ba hình thức cơ bản là chủ nghĩa duy vật chất phác, chủ nghĩa duy vật siêu hình và chủ nghĩa duy vật biện chứng. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Một hình thức là thiếu; giáo trình nêu ba.","Hai hình thức là thiếu; giáo trình nêu ba (chất phác, siêu hình, biện chứng).","","Bốn hình thức là thừa; giáo trình chỉ liệt kê ba."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.1, mục I.2 (Vấn đề cơ bản của triết học: chủ nghĩa duy vật)","c":1,"v":"khớp"},{"q":"Đâu là nhận định đúng về Triết học?","o":["Triết học là hạt nhân của tôn giáo","Triết học là hạt nhân của thế giới quan","Triết học là trung tâm của phương pháp luận","Triết học là hạt nhân của phương pháp luận"],"a":[1],"e":"Giáo trình nêu «Triết học là hạt nhân của thế giới quan» và có mục «Triết học - hạt nhân lý luận của thế giới quan». ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Triết học không phải hạt nhân của tôn giáo; thế giới quan tôn giáo chỉ chịu ảnh hưởng của triết học.","","Giáo trình dùng cụm «hạt nhân», không dùng «trung tâm của phương pháp luận».","Hạt nhân là của thế giới quan, không phải của phương pháp luận; phương pháp luận là nội dung khác của triết học."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.1, mục I.1 (mục 1.4 Triết học - hạt nhân lý luận của thế giới quan)","c":1,"v":"khớp"},{"q":"Ai là người tạo ra cơ sở tri thức cho sự phát triển của triết học trong thời kỳ Phục hưng?","o":["Adam Smith","Martin Luther","Xanh-ximông","Copernicus"],"a":[3],"e":"Giáo trình viết rằng phải đến sau cuộc cách mạng Copernicus (Cô-péc-ních), các khoa học Tây Âu thế kỷ XV, XVI mới dần phục hưng, tạo cơ sở tri thức cho sự phát triển mới của triết học. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["A. Smith là nhà kinh tế học cổ điển Anh, không phải người tạo cơ sở tri thức này.","Math Lurer (có thể là chép sai tên M. Luther) là nhân vật cải cách tôn giáo, giáo trình không nêu ông ở vai trò này.","Xanhximông là nhà xã hội chủ nghĩa không tưởng, thế kỷ XIX.",""],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.1, mục I.1 (Khái lược về triết học)","c":1,"v":"khớp","k":"Phương án B bị lỗi chép tên trong đề.","id":"v3r6vj"},{"q":"Thời kỳ Phục hưng bắt đầu ở quốc gia nào?","o":["Pháp","Ý","Anh","Bồ Đào Nha"],"a":[1],"e":"Phục hưng là phong trào văn hóa bắt đầu từ Italia (Ý) vào khoảng thế kỷ XIV, rồi lan sang các nước Tây Âu khác. ([Wikipedia tiếng Việt: Phục Hưng](https://vi.wikipedia.org/wiki/Ph%E1%BB%A5c_H%C6%B0ng))","w":["Pháp tiếp nhận phong trào sau, không phải nơi bắt đầu.","","Anh tiếp nhận sau khi phong trào đã phát triển ở Italia.","Bồ Đào Nha không phải cái nôi của Phục hưng."],"s":"Wikipedia tiếng Việt (Phục Hưng); giáo trình chỉ nhắc Phục hưng thế kỷ XV (Ch.2, mục I.1), chưa nêu nơi bắt đầu","c":1,"v":"khớp"},{"q":"Chủ nghĩa duy vật siêu hình ra đời gắn liền với thời kỳ nào?","o":["Thời kỳ Phục hưng","Thời kỳ Trung cổ","Thời kỳ Khải huyền","Thời kỳ cận đại"],"a":[3],"e":"Giáo trình viết chủ nghĩa duy vật siêu hình thể hiện rõ ở các nhà triết học thế kỷ XV đến XVIII, điển hình ở thế kỷ XVII, XVIII, khi cơ học cổ điển đạt thành tựu rực rỡ; thời kỳ Phục hưng - cận đại (XV - XVIII). Vì vậy đáp án là thời kỳ cận đại. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Phục hưng chỉ là giai đoạn mở đầu của thế kỷ XV - XVIII; hình thức này điển hình ở thế kỷ XVII - XVIII (cận đại).","Thời Trung cổ gắn với triết học kinh viện, thần học, không phải duy vật siêu hình.","«Thời kỳ Khải huyền» không phải thời kỳ lịch sử triết học.",""],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.1, mục I.2 và Ch.2, mục I.1","c":1,"v":"khớp"},{"q":"Ngũ hành gồm những yếu tố nào?","o":["Nhân, lễ, nghĩa, trí, tín","Kim, mộc, thổ, thủy, không khí","Kim, mộc, thủy, hỏa, thổ","Kim, mộc, thủy, hỏa, lễ"],"a":[2],"e":"Giáo trình nêu ngũ hành của Trung Quốc gồm kim, mộc, thủy, hỏa, thổ, khi quy vật chất về các vật thể hữu hình, cảm tính. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Nhân, lễ, nghĩa, trí, tín là ngũ thường của Nho giáo, không phải ngũ hành.","Không khí không thuộc ngũ hành (không khí thuộc quan niệm khác, như Anaximen).","","«Lễ» thuộc ngũ thường, không phải một hành."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.2, mục I.1 (quan niệm về vật chất trước Mác)","c":1,"v":"khớp"},{"q":"Theo triết học Mác - Lênin, yếu tố nào đóng vai trò quyết định đối với tất cả các mặt của đời sống xã hội?","o":["Khoa học","Phương thức sản xuất","Chính trị","Văn hóa nghệ thuật"],"a":[1],"e":"Theo C. Mác (Lời tựa Góp phần phê phán khoa kinh tế chính trị), phương thức sản xuất đời sống vật chất quyết định các quá trình sinh hoạt xã hội, chính trị và tinh thần nói chung; giáo trình coi phương thức sản xuất vật chất là yếu tố cơ bản nhất của tồn tại xã hội. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Khoa học (tri thức) là lực lượng sản xuất trực tiếp trong điều kiện hiện đại nhưng không phải yếu tố quyết định tất cả các mặt.","","Chính trị thuộc kiến trúc thượng tầng, bị quyết định bởi cơ sở hạ tầng và phương thức sản xuất.","Văn hóa nghệ thuật là một bộ phận của ý thức xã hội, do tồn tại xã hội quyết định."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.3, mục IV.1 (Tồn tại xã hội và các yếu tố cơ bản của tồn tại xã hội)","c":3,"v":"khớp"},{"q":"Sự ra đời của quan điểm duy vật về lịch sử do C. Mác sáng lập ra đã khắc phục được những sai lầm căn bản trong việc lý giải xã hội theo:","o":["Quan điểm tôn giáo và duy tâm","Quan điểm duy vật siêu hình và tôn giáo","Quan điểm duy tâm và siêu hình","Quan điểm duy vật tự nhiên và tầm thường"],"a":[2],"e":"Giáo trình nêu chủ nghĩa duy vật cũ bị «cầm tù» trong cách nhìn phiến diện của phép siêu hình và duy tâm về xã hội; quan điểm duy vật về lịch sử của Mác khắc phục sai lầm đó. Vì vậy đáp án là quan điểm duy tâm và siêu hình. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Thiếu yếu tố siêu hình; sai lầm được nêu gồm cả duy tâm lẫn siêu hình.","«Duy vật siêu hình và tôn giáo» lệch: đối tượng phê phán là duy tâm và siêu hình.","","«Duy vật tự nhiên và tầm thường» không phải cặp quan điểm giáo trình nêu ở đây."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.1, mục II.1 (Sự ra đời và phát triển của triết học Mác-Lênin); chưa đối chiếu số mục chính xác","c":3,"v":"khớp"},{"q":"Phạm trù nhằm chỉ những biến đổi xuất hiện do tác động lẫn nhau giữa các mặt trong một sự vật hoặc giữa các sự vật với nhau gây ra, gọi là gì?","o":["Nguyên nhân","Kết quả","Hiện thực","Khả năng"],"a":[1],"e":"Giáo trình định nghĩa kết quả là phạm trù chỉ những biến đổi xuất hiện do tác động lẫn nhau giữa các mặt trong một sự vật hoặc giữa các sự vật với nhau gây ra. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Nguyên nhân là sự tác động lẫn nhau gây ra biến đổi, còn đề hỏi chính biến đổi đó.","","Hiện thực là phạm trù khác (cặp khả năng - hiện thực).","Khả năng là cái chưa xuất hiện, không phải biến đổi đã xảy ra."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.2, mục II.2 (cặp phạm trù nguyên nhân - kết quả)","c":2,"v":"khớp"},{"q":"Theo quan điểm của triết học Mác - Lênin, con người là thực thể thống nhất của các mặt nào?","o":["Sinh học và tâm lý","Sinh học và xã hội","Phẩm chất đạo đức và nhân cách","Tâm lý và năng lực nhận thức"],"a":[1],"e":"Giáo trình nêu con người là thực thể sinh học - xã hội; theo quan điểm của chủ nghĩa Mác - Lênin không thể tách rời hai phương diện sinh học và xã hội thành những phương diện biệt lập. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Thiếu mặt xã hội; mặt tâm lý không phải mặt cơ bản trong định nghĩa.","","Phẩm chất đạo đức và nhân cách là biểu hiện của mặt xã hội, không phải hai mặt thống nhất của con người.","Tâm lý và năng lực nhận thức chỉ là một số thuộc tính, không bao quát bản chất con người."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.3, mục V.1 (Khái niệm con người và bản chất con người)","c":3,"v":"khớp"},{"q":"Chủ nghĩa duy vật là trường phái triết học cho rằng:","o":["Bản chất thế giới là vật thể","Bản chất thế giới là vật chất","Vật chất là tính thứ hai","Vật chất tác động đến ý thức","Bản chất thế giới là vật chất và ý thức"],"a":[1],"e":"Theo giáo trình, chủ nghĩa duy vật thừa nhận vật chất là tính thứ nhất, ý thức là tính thứ hai, và bản chất của thế giới là vật chất. Trong các phương án, B nêu đúng bản chất thế giới. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Vật thể chỉ là dạng cụ thể của vật chất; bản chất thế giới là vật chất, không phải vật thể.","","Câu này mới nói vật chất là tính thứ hai, sai thứ tự: vật chất là tính thứ nhất.","Mới nêu quan hệ tác động, chưa nêu bản chất thế giới; không phải luận điểm xác định chủ nghĩa duy vật.","Bản chất thế giới gồm cả vật chất và ý thức là quan điểm nhị nguyên, không phải duy vật."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.1, mục I.2 (Vấn đề cơ bản của triết học: chủ nghĩa duy vật)","c":1,"v":"khớp","k":"Phương án E có thêm trong đề (5 phương án)."},{"q":"Theo chủ nghĩa duy vật biện chứng, mối quan hệ giữa lực lượng sản xuất và quan hệ sản xuất?","o":["Biện chứng","Tương hỗ","Phụ thuộc","Quan điểm toàn diện và cụ thể"],"a":[0],"e":"Giáo trình nêu lực lượng sản xuất và quan hệ sản xuất là hai mặt của một phương thức sản xuất, có tác động biện chứng: lực lượng sản xuất quyết định quan hệ sản xuất, còn quan hệ sản xuất tác động trở lại to lớn đối với lực lượng sản xuất. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","«Tương hỗ» chỉ nói tác động hai chiều, bỏ qua vai trò quyết định của lực lượng sản xuất.","«Phụ thuộc» chỉ đúng một chiều (quan hệ sản xuất phụ thuộc lực lượng sản xuất), chưa phản ánh tác động trở lại.","«Quan điểm toàn diện và cụ thể» là nguyên tắc phương pháp luận, không phải tên của mối quan hệ."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.3, mục I.2 (Biện chứng giữa lực lượng sản xuất và quan hệ sản xuất)","c":3,"v":"khớp"},{"q":"Ngày nay, trong nền sản xuất xã hội, tỷ trọng lao động trí tuệ có xu hướng như thế nào?","o":["Tăng dần","Giảm dần","Điều hòa","Ổn định"],"a":[0],"e":"Giáo trình viết: ngày nay, trong nền sản xuất xã hội, tỷ trọng lao động cơ bắp đang có xu thế giảm, trong đó lao động có trí tuệ và lao động trí tuệ ngày càng tăng lên. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Ngược với xu thế: tỷ trọng lao động trí tuệ tăng, còn lao động cơ bắp giảm.","«Điều hòa» không phải xu hướng được nêu.","Không ổn định: giáo trình nêu xu hướng tăng rõ rệt của lao động trí tuệ."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.3, mục I.2 (lực lượng sản xuất: người lao động)","c":4,"v":"khớp"},{"q":"Sản xuất vật chất là hoạt động có tính chất gì?","o":["Tính khách quan, tính tất yếu, tính xã hội, tính văn hóa và tính mục đích","Tính tất yếu, tính tư duy, tính cộng đồng, tính văn hóa và tính mục đích","Tính khách quan, tính mục đích, tính xã hội, tính lịch sử và tính sáng tạo","Tính xã hội, tính lịch sử, tính sáng tạo, tính văn hóa và tính mục đích tự thân"],"a":[2],"e":"Đề liệt kê các tính chất của sản xuất vật chất; trong các phương án chỉ C gồm khách quan, mục đích, xã hội, lịch sử và sáng tạo. Giáo trình nhấn mạnh sản xuất là hoạt động sáng tạo, mang tính xã hội và là hoạt động đặc trưng của con người, nhưng không liệt kê chính xác năm tính chất này. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Có «tính văn hóa» và «tính tất yếu», không nằm trong bộ tính chất thường được nêu.","Có «tính tư duy», «tính cộng đồng», «tính văn hóa», không đúng bộ tính chất.","","Có «tính văn hóa» và «mục đích tự thân», không đúng bộ tính chất."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.3, mục I.1; chưa tìm được nguồn nêu đủ năm tính chất","c":3,"v":"chưa kiểm chứng","k":"chưa kiểm chứng được nguồn cho câu này. Giáo trình bản 2021 không liệt kê đủ năm tính chất; các trang web đề cương chỉ nêu lại bộ tính chất khá khác nhau. Chưa tìm được nguồn chính thống xác nhận; cần nhớ theo đáp án của đề."},{"q":"Đâu là một trong những hình thức tồn tại của vật chất?","o":["Không gian, thời gian","Vật thể","Cái bàn, cái quạt","Không có phương án đúng"],"a":[0],"e":"Giáo trình nêu không gian và thời gian là hình thức tồn tại của vật chất vận động; không có không gian và thời gian thuần túy tách rời vật chất vận động. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Vật thể là dạng tồn tại cụ thể của vật chất, không phải hình thức tồn tại.","Cái bàn, cái quạt là các vật thể cụ thể, không phải hình thức tồn tại của vật chất.","Sai vì phương án A là phương án đúng."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.2, mục I.1 (Vật chất và các hình thức tồn tại của vật chất: không gian và thời gian)","c":2,"v":"khớp","id":"8z3ado","f":1},{"q":"Theo chủ nghĩa duy vật lịch sử, lực lượng sản xuất có quan hệ thế nào với quan hệ sản xuất?","o":["Quyết định","Tác động trở lại","Phụ thuộc","Không phụ thuộc"],"a":[0],"e":"Giáo trình nêu lực lượng sản xuất quyết định quan hệ sản xuất, quan hệ sản xuất phải phù hợp với trình độ phát triển của lực lượng sản xuất và tác động trở lại. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","«Tác động trở lại» là vai trò của quan hệ sản xuất đối với lực lượng sản xuất, đảo chiều.","«Phụ thuộc» là sai chiều: quan hệ sản xuất phụ thuộc lực lượng sản xuất, chứ không phải ngược lại.","«Không phụ thuộc» sai: lực lượng sản xuất quyết định quan hệ sản xuất."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.3, mục I.2 (Vai trò quyết định của lực lượng sản xuất đối với quan hệ sản xuất)","c":3,"v":"khớp"},{"q":"Chủ nghĩa duy vật cho rằng đầu là bản nguyên của thế giới?","o":["Bản chất thế giới là vật chất","Bản nguyên thế giới là ý thức","Bản nguyên thế giới là lực lượng siêu nhiên","Bản nguyên thế giới là Thượng đế"],"a":[0],"e":"Chủ nghĩa duy vật cho rằng giải thích thế giới phải dựa vào bản thân giới tự nhiên, không viện đến thần linh, Thượng đế hay lực lượng siêu nhiên; bản nguyên (bản chất) thế giới là vật chất. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Bản nguyên là ý thức là quan điểm duy tâm.","Lực lượng siêu nhiên là quan điểm thần học và duy tâm, bị chủ nghĩa duy vật bác bỏ.","Thượng đế là quan điểm thần học và duy tâm."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.1, mục I.2 (chủ nghĩa duy vật)","c":1,"v":"khớp","id":"1udo43o"},{"q":"Thừa nhận sự tồn tại của vật chất và tinh thần là bản nguyên có thể cùng quyết định nguồn gốc và sự vận động của thế giới là trường phái nào?","o":["Nhị nguyên luận","Biện chững","Biện chúng luận","Chủ nghĩa Mác - Lênin"],"a":[0],"e":"Giáo trình viết: những nhà triết học giải thích thế giới bằng cả hai bản nguyên vật chất và tinh thần, xem chúng có thể cùng quyết định nguồn gốc và sự vận động của thế giới, được gọi là nhị nguyên luận, điển hình là Descartes. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","«Biện chững» (chép sai) là phương pháp, không phải trường phái trả lời vấn đề bản nguyên.","«Biện chứng luận» là phương pháp tư duy, không phải học thuyết về bản nguyên.","Chủ nghĩa Mác - Lênin là chủ nghĩa duy vật biện chứng, coi vật chất có trước, không thừa nhận hai bản nguyên."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.1, mục I.2 (Vấn đề cơ bản của triết học: nhị nguyên luận)","c":1,"v":"khớp","k":"Phương án B, C bị lỗi chính tả trong đề."},{"q":"Tại sao khi nhìn lên trời, mỗi người đều nhìn thấy đám mây với những hình thù khác nhau?","o":["Sự phản ánh năng động, sáng tạo của ý thức","Do ý muốn chủ quan của mỗi người","Thế giới khách quan đa dạng phong phú","Do đám mây hôm đó có hình thù như vật cụ thể nên mỗi người nhìn khác nhau"],"a":[0],"e":"Giáo trình nêu ý thức là sự phản ánh sáng tạo hiện thực khách quan, sáng tạo là thuộc tính đặc trưng bản chất nhất của ý thức; do đó cùng một đám mây, mỗi người phản ánh ra hình khác nhau. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Không chỉ do ý muốn chủ quan: phản ánh vẫn dựa trên đối tượng khách quan.","Thế giới khách quan là nội dung được phản ánh, nhưng cùng một đám mây mà mỗi người thấy khác nhau là do năng lực phản ánh của ý thức.","Cùng một đám mây nhưng phản ánh khác nhau: nguyên nhân không nằm ở hình dạng đám mây."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.2, mục I.2 (Nguồn gốc, bản chất và kết cấu của ý thức: ý thức là sự phản ánh sáng tạo)","c":2,"v":"khớp"},{"q":"Theo triết học Mác-xít thì siêu hình và biện chứng là hai phương pháp như thế nào?","o":["Đối lập nhau","Tương tác lần nhau","Bổ sung cho nhau","Có mối liên hệ với nhau"],"a":[0],"e":"Giáo trình nêu trong triết học mácxít, biện chứng và siêu hình là hai phương pháp tư duy chung nhất đối lập nhau; bảng so sánh nêu rõ sự đối lập giữa hai phương pháp. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Không phải tương tác lẫn nhau: giáo trình nhấn mạnh đối lập.","Không bổ sung cho nhau: hai phương pháp xem xét đối tượng theo cách ngược nhau (tĩnh - động, cô lập - liên hệ).","Có liên hệ nhưng đáp án đúng nhất là đối lập; «có mối liên hệ» không nêu bản chất của quan hệ."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.1, mục I.3 (Biện chứng và siêu hình)","c":1,"v":"khớp"},{"q":"Cơ sở của sự tồn tại và phát triển xã hội có nguồn gốc trực tiếp từ đâu?","o":["Nên tảng xã hội","Sản xuất vật chất","Thế giới vật chất","Thế giới khách quan"],"a":[1],"e":"Giáo trình khẳng định sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội loài người, là tiền đề trực tiếp tạo ra tư liệu sinh hoạt. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Nền tảng xã hội» là cách nói chung chung, không nêu nguồn gốc trực tiếp.","","Thế giới vật chất quá chung; nguồn gốc trực tiếp của xã hội là hoạt động sản xuất vật chất.","Thế giới khách quan quá chung, không chỉ ra hoạt động trực tiếp tạo cơ sở cho xã hội."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.3, mục I.1 (Sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội)","c":3,"v":"khớp"},{"q":"Vấn đề cơ bản của triết học có hai mặt. Mặt thứ nhất phải trả lời cho hỏi cái nào có trước, cái nào có sau, cái nào quyết định cái nào. Đó là quan hệ giữa cái gì với cái gì?","o":["Tư duy với thực tế","Tư duy với xã hội","Ý thức vật chất","Ý thức và bộ não"],"a":[2],"e":"Giáo trình nêu mặt thứ nhất của vấn đề cơ bản của triết học: giữa ý thức và vật chất thì cái nào có trước, cái nào có sau, cái nào quyết định cái nào. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Tư duy với thực tế» không phải cặp chuẩn của vấn đề cơ bản (cặp chuẩn là ý thức - vật chất).","«Tư duy với xã hội» không phải cặp chuẩn của vấn đề cơ bản của triết học.","","Ý thức và bộ não là quan hệ sinh lý - nguồn gốc ý thức, không phải vấn đề cơ bản."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.1, mục I.2 (Vấn đề cơ bản của triết học)","c":1,"v":"khớp"},{"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử, mỗi hình thái kinh tế - xã hội được cấu thành từ những nhân tố nào?","o":["Lực lượng sản xuất, kiến trúc thượng tầng","Quan hệ kinh tế, lực lượng sản xuất và kiến trúc thượng tầng","Quan hệ sản xuất và kiến trúc thượng tầng","Lực lượng sản xuất, quan hệ sản xuất hợp thành cơ cấu kinh tế của xã hội và kiến trúc thượng tầng"],"a":[3],"e":"Giáo trình nêu hình thái kinh tế - xã hội gồm ba yếu tố cơ bản, phổ biến: lực lượng sản xuất, quan hệ sản xuất (cơ sở hạ tầng) và kiến trúc thượng tầng. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Thiếu quan hệ sản xuất (cơ sở hạ tầng).","«Quan hệ kinh tế» không phải thuật ngữ chuẩn; giáo trình dùng quan hệ sản xuất.","Thiếu lực lượng sản xuất.",""],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.3, mục I.4 (Sự phát triển các hình thái kinh tế - xã hội)","c":3,"v":"khớp","k":"Cụm «cơ cấu kinh tế của xã hội» ở phương án D là cách diễn đạt của đề; giáo trình bản 2021 dùng quan hệ sản xuất (cơ sở hạ tầng)."},{"q":"Theo quan điểm của chủ nghĩa duy tâm khách quan, mối quan hệ giữa các sự vật do cái gì quyết định?","o":["Lực lượng siêu nhiên (thượng đế, ý niệm tuyệt đối)","Cảm giác, thói quen của con người","Bản chất của thế giới tự nhiên","Phức hợp của cảm giác"],"a":[0],"e":"Giáo trình nêu chủ nghĩa duy tâm khách quan thừa nhận tính thứ nhất của ý thức nhưng coi đó là thứ tinh thần khách quan có trước, tồn tại độc lập với con người, như ý niệm, tinh thần tuyệt đối, lý tính thế giới. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Cảm giác, thói quen của con người là quan điểm duy tâm chủ quan hoặc kinh nghiệm luận.","Bản chất của thế giới tự nhiên là quan điểm duy vật.","Phức hợp của cảm giác là quan điểm của duy tâm chủ quan."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.1, mục I.2 (Chủ nghĩa duy tâm)","c":2,"v":"khớp"},{"q":"Nguồn gốc tự nhiên của ý thức bao gồm yếu tố nào?","o":["Thế giới vật chất của con người","Thế giới khách quan","Não người","B và C"],"a":[3],"e":"Giáo trình nêu nguồn gốc tự nhiên của ý thức là sự xuất hiện con người cùng bộ óc có năng lực phản ánh hiện thực khách quan; ý thức là chức năng của bộ óc người, và thế giới khách quan tác động lên bộ óc là điều kiện để phản ánh. Vậy cả B và C. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Thế giới vật chất của con người» là cách nói không chuẩn, thu hẹp phạm vi của thế giới khách quan.","Thế giới khách quan đúng nhưng chưa đủ, còn thiếu bộ óc người; đáp án đầy đủ là B và C.","Bộ óc người đúng nhưng chưa đủ, còn thiếu thế giới khách quan (đối tượng phản ánh).",""],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.2, mục I.2 (Nguồn gốc của ý thức: nguồn gốc tự nhiên)","c":2,"v":"khớp","k":"Giáo trình nhấn mạnh bộ óc là khí quan vật chất của ý thức; yếu tố «thế giới khách quan» là đối tượng phản ánh, nên cần nhớ đáp án D (B và C).","f":1},{"q":"Chọn phương án trả lời phù hợp nhất. \"Sự ra đời của Triết học Mác là một quá trình...\". Từ còn thiếu trong chỗ trống là gì?","o":["Tất yếu khách quan","Thiết yếu","\"nhiều hơn và đồ sộ hơn\"... \"thế hệ trước\"","Đấu tranh của giai cấp"],"a":[0],"e":"Giáo trình viết triết học Mác ra đời như một tất yếu lịch sử, vì đời sống và thực tiễn cách mạng của giai cấp công nhân đòi hỏi lý luận mới và vì những tiền đề cho sự ra đời đã được nhân loại tạo ra. Đáp án là tất yếu khách quan. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","«Thiết yếu» không phải thuật ngữ giáo trình dùng cho sự ra đời của triết học Mác.","Phương án này không là một từ điền khuyết, đề bị lỗi (chép dở).","«Đấu tranh của giai cấp» chỉ là một nhân tố, chưa nêu tính chất tất yếu của quá trình."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.1, mục II.1 (Sự ra đời và phát triển của triết học Mác-Lênin)","c":1,"v":"khớp","k":"Phương án C bị lỗi chép đề."},{"q":"Quan điểm nào thuộc chủ nghĩa duy tâm?","o":["Vật chất quyết định ý thức","Vật chất là tính thứ nhất, ý thức là tính thứ hai","Vật chất và ý thức song song tồn tại, không cái nào phụ thuộc cái nào","Ý thức có trước, vật chất có sau; ý thức quyết định vật chất"],"a":[3],"e":"Giáo trình nêu chủ nghĩa duy tâm cho rằng ý thức, tinh thần là cái có trước và sản sinh ra giới tự nhiên; vì vậy quan điểm «ý thức có trước, vật chất có sau, ý thức quyết định vật chất» là duy tâm. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Vật chất quyết định ý thức là quan điểm duy vật.","Vật chất là tính thứ nhất, ý thức là tính thứ hai là quan điểm duy vật.","Vật chất và ý thức song song, không cái nào phụ thuộc cái nào là quan điểm nhị nguyên.",""],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.1, mục I.2 (Chủ nghĩa duy tâm)","c":1,"v":"khớp"},{"q":"Bộ phận nào của tư liệu lao động được coi là tiêu chí phản ánh đặc trưng phát triển của một thời đại kinh tế?","o":["Công cụ lao động","Kết cấu hạ tầng sản xuất","Nhà cửa, kho bãi để chứa đựng, bảo quản","Quan hệ sản xuất"],"a":[0],"e":"Giáo trình viết công cụ lao động là yếu tố động nhất, cách mạng nhất trong lực lượng sản xuất, là thước đo trình độ cải biến tự nhiên của con người và tiêu chuẩn để phân biệt các thời đại kinh tế khác nhau. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Kết cấu hạ tầng sản xuất là phương tiện lao động, nhưng giáo trình không coi nó là tiêu chuẩn phân biệt thời đại kinh tế.","Nhà cửa, kho bãi chỉ là phương tiện lao động hỗ trợ.","Quan hệ sản xuất không phải bộ phận của tư liệu lao động."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.3, mục I.2 (lực lượng sản xuất: công cụ lao động)","c":4,"v":"khớp"},{"q":"Theo quan điểm của phép biện chứng duy vật thì quy luật nào là quy luật về khuynh hướng cơ bản, phổ biến của mọi sự vận động và phát triển diễn ra trong lĩnh vực tự nhiên, xã hội và tư duy?","o":["Vận động","Lượng đổi, chất đổi","Mâu thuẫn","Phủ định của phủ định"],"a":[3],"e":"Giáo trình nêu quy luật phủ định của phủ định chỉ ra khuynh hướng (đi lên), hình thức (xoáy ốc), kết quả của sự phát triển thông qua sự thống nhất giữa tính thay đổi với tính kế thừa. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Vận động không phải quy luật của phép biện chứng duy vật.","Quy luật lượng - chất chỉ ra cách thức của sự phát triển.","Quy luật mâu thuẫn chỉ ra nguồn gốc, động lực của sự phát triển.",""],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.2, mục II.2 (Quy luật phủ định của phủ định)","c":2,"v":"khớp"},{"q":"Đâu không phải là quan điểm của Chủ nghĩa Mác-Lênin về lãnh tụ?","o":["Những cá nhân kiệt xuất trong nhiều lĩnh vực","Những cá nhân kiệt xuất có sự gắn bó với quần chúng nhân dân","Những cá nhân kiệt xuất được quần chúng tín nhiệm","Những cá nhân kiệt xuất tự nguyện hy sinh bản thân mình vì lợi ích của quần chúng nhân dân"],"a":[0],"e":"Giáo trình nêu lãnh tụ là cá nhân kiệt xuất nhận thức đúng yêu cầu, quy luật của một lĩnh vực nhất định của đời sống xã hội, dám quên mình vì lợi ích quần chúng, được quần chúng tín nhiệm và gắn bó mật thiết với quần chúng. Vì vậy không phải quan điểm là «kiệt xuất trong nhiều lĩnh vực». ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Đúng quan điểm: lãnh tụ gắn bó mật thiết với quần chúng.","Đúng quan điểm: lãnh tụ được quần chúng tín nhiệm.","Đúng quan điểm: lãnh tụ dám quên mình vì lợi ích của quần chúng nhân dân."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.3, mục V.3 (vai trò của quần chúng nhân dân và lãnh tụ trong lịch sử)","c":3,"v":"khớp","k":"Câu hỏi dạng phủ định («đâu không phải»), dễ chọn nhầm."},{"q":"Trong các yếu tố của lực lượng sản xuất, yếu tố nào là quan trọng nhất?","o":["Tư liệu sản xuất","Người lao động","Đối tượng lao động","Máy móc và công nghệ hiện đại"],"a":[1],"e":"Giáo trình viết trong lực lượng sản xuất, người lao động là nhân tố hàng đầu giữ vai trò quyết định, vì là chủ thể sáng tạo và sử dụng công cụ lao động; các tư liệu sản xuất suy đến cùng chỉ là sản phẩm lao động của con người. ([Giáo trình Triết học Mác-Lênin, bản 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Tư liệu sản xuất do con người tạo ra, giá trị của chúng phụ thuộc trình độ sử dụng của người lao động.","","Đối tượng lao động là yếu tố bị tác động, thụ động hơn người lao động.","Máy móc và công nghệ do con người làm ra; công cụ lao động là yếu tố động nhất nhưng người lao động mới là nhân tố hàng đầu."],"s":"GT Triết học Mác-Lênin (bản 2021), Ch.3, mục I.2 (Lực lượng sản xuất)","c":3,"v":"khớp","k":"Dễ nhầm với công cụ lao động (là yếu tố động nhất, cách mạng nhất), nhưng nhân tố hàng đầu là người lao động."},{"q":"Tiền đề xuất phát chủ nghĩa duy vật lịch sử là gì?","o":["Con người hiện thực","Con người trừu tượng","Con người hành động","Con người tư duy"],"a":[0],"e":"Giáo trình trích Mác – Ăngghen trong «Hệ tư tưởng Đức»: tiền đề đầu tiên của toàn bộ lịch sử nhân loại là sự tồn tại của những cá nhân con người sống, tức con người hiện thực mà sản xuất vật chất là hành vi lịch sử đầu tiên của họ. Vì vậy chủ nghĩa duy vật lịch sử xuất phát từ con người hiện thực chứ không từ con người trừu tượng. ([GT Triết học Mác-Lênin 2021, Bộ GD&ĐT](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf); [GT bản tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Con người trừu tượng là cách nhìn của chủ nghĩa duy tâm, bị Mác – Ăngghen phê phán, không phải tiền đề của duy vật lịch sử.","Hoạt động là hệ quả của sự tồn tại của con người hiện thực chứ không phải tiền đề xuất phát gọi tên trong giáo trình.","Tư duy chỉ là một mặt hoạt động của con người; xuất phát từ tư duy là lập trường duy tâm."],"s":"GT Triết học Mác-Lênin (bản 2021: Chương 1 mục về sự ra đời triết học Mác; bản tái bản lần 3: Chương III), trích «Hệ tư tưởng Đức»; chưa đối chiếu số mục chính xác.","c":3,"v":"khớp"},{"q":"Quan điểm lịch sử cụ thể được rút ra từ nghiên cứu nguyên lý triết học nào sau đây?","o":["Nguyên lý duy vật lịch sử","Nguyên lý về mối liên hệ phổ biến","Nguyên lý phát triển","Nguyên lý triết học thực hành"],"a":[1],"e":"Giáo trình nêu: do các mối liên hệ rất đa dạng, phong phú nên trong nhận thức và thực tiễn phải tôn trọng quan điểm lịch sử – cụ thể, tức chú ý điều kiện, hoàn cảnh lịch sử – cụ thể nơi sự vật sinh ra, tồn tại và phát triển; quan điểm này được rút ra từ nguyên lý về mối liên hệ phổ biến. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Nguyên lý duy vật lịch sử không phải một trong hai nguyên lý của phép biện chứng duy vật mà từ đó giáo trình rút ra các quan điểm phương pháp luận.","","Nguyên lý phát triển dẫn tới quan điểm phát triển; giáo trình bản 2021 còn nói lịch sử – cụ thể xuất phát đồng thời từ hai nguyên lý nên C không hẳn sai, nhưng đề chọn B.","Triết học thực hành không phải một nguyên lý của phép biện chứng duy vật."],"s":"GT bản tái bản lần 3: Chương VI mục I (Nguyên lý về mối liên hệ phổ biến); GT bản 2021: Chương 2 mục II.2.","c":2,"v":"dễ nhầm","k":"Bản tái bản lần 3 đặt quan điểm lịch sử – cụ thể ở nguyên lý mối liên hệ phổ biến (khớp đáp án B), nhưng bản 2021 viết cơ sở lý luận của nguyên tắc này là đồng thời cả nguyên lý liên hệ phổ biến và nguyên lý phát triển ([GT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf)). Nên học theo đáp án đề là B."},{"q":"Theo quan điểm của triết học Mác - Lênin mối quan hệ giữa \"sự thống nhất và đấu tranh của các mặt đối lập\" là như thế nào?","o":["Sự thống nhất và đấu tranh của các mặt đối lập là thống nhất. Không có thống nhất của các mặt đối lập thì cũng không có đấu tranh của các mặt đối lập","Sự đấu tranh của các mặt đối lập vừa tương đối, vừa tuyệt đối","Không có sự thống nhất của các mặt đối lập\" thì vẫn có sự đấu tranh của các mặt đối lập\"","Không có sự đấu tranh của các mặt đối lập\" thì có thể trong một vài trường hợp sẽ có \"sự thống nhất của các mặt đối lập\""],"a":[0],"e":"Giáo trình viết: thống nhất của các mặt đối lập là có điều kiện, tạm thời, tương đối; đấu tranh của các mặt đối lập bài trừ lẫn nhau là tuyệt đối, và hai mặt luôn gắn bó trong mâu thuẫn: các mặt đối lập vừa thống nhất vừa đấu tranh, nên không có thống nhất thì không có đấu tranh. Đáp án A nêu đúng sự gắn bó ấy. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Sai vì tuyệt đối hóa lẫn lộn: giáo trình nói đấu tranh là tuyệt đối còn thống nhất mới là tương đối, không nói đấu tranh «vừa tương đối vừa tuyệt đối».","Sai vì thiếu thống nhất thì không thể có hai mặt đối lập cùng tồn tại trong một mâu thuẫn để đấu tranh với nhau.","Sai vì ngược lại: đấu tranh là tuyệt đối, luôn có mặt, không thể có thống nhất mà thiếu đấu tranh."],"s":"GT bản tái bản lần 3: Chương VIII mục III (Quy luật thống nhất và đấu tranh của các mặt đối lập).","c":2,"v":"dễ nhầm","k":"Phương án A diễn đạt hơi lạ so với giáo trình (giáo trình nhấn thống nhất tương đối, đấu tranh tuyệt đối); B chứa một mệnh đề sai nên loại."},{"q":"Ai là người định nghĩa: \"Vật chất là cái phi vật chất đang vận động\"?","o":["E.Makhơ","Anhxtanh","Béc cơren","Henri Berson (Piecson)"],"a":[3],"e":"Theo ngân hàng câu hỏi triết học Mác – Lênin lưu hành, quan điểm «vật chất là cái phi vật chất đang vận động» được gắn với Piếc-sơn (Henri Bergson, phiên âm trong đề là Piecson), và bị coi là phản ánh cuộc khủng hoảng thế giới quan trong vật lý học đầu thế kỷ XX vì lẫn lộn vật chất với phi vật chất. ([Studocu, câu hỏi về ý kiến của Piếc sơn](https://www.studocu.vn/vn/document/truong-dai-hoc-kinh-te-quoc-dan/de-an-luat-thuong-mai/triet-triet/100447511))","w":["E. Makhơ là đại biểu của chủ nghĩa kinh nghiệm phê phán, không phải tác giả định nghĩa này.","Anhxtanh là nhà vật lý học, không đưa ra định nghĩa triết học này.","Béccơren là nhà vật lý phát hiện hiện tượng phóng xạ, không phải tác giả định nghĩa này.",""],"s":"Chỉ tìm được nguồn thứ cấp (Studocu); chưa tìm thấy trong giáo trình Bộ GD&ĐT bản đã tải; chưa đối chiếu số chương.","c":2,"v":"chưa kiểm chứng","k":"chưa kiểm chứng được nguồn cho câu này. Chỉ có nguồn thứ cấp xác nhận tên Piếc-sơn, không tra được văn bản gốc của Lênin. Bản nháp trước ghi Bécxông (Bergson) và đề ghi Henri Berson (Piecson); cách phiên âm không thống nhất, nên học theo đáp án D của đề.","id":"zz3vy2"},{"q":"Theo chủ nghĩa duy vật lịch sử thì những biến đổi từ đầu tạo ra nhu cầu khách quan phải có sự biến đổi tượng ứng trong kiến trúc thượng tầng?","o":["Cơ sở hạ tầng","Lực lượng sản xuất","Quan hệ sản xuất"],"a":[0],"e":"Giáo trình nêu: cơ sở hạ tầng thay đổi thì sớm hay muộn kiến trúc thượng tầng cũng thay đổi theo; lực lượng sản xuất không trực tiếp làm thay đổi kiến trúc thượng tầng mà phải thông qua quan hệ sản xuất, tức cơ sở hạ tầng. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Giáo trình nói rõ lực lượng sản xuất không trực tiếp làm thay đổi kiến trúc thượng tầng, chỉ tác động thông qua quan hệ sản xuất.","Quan hệ sản xuất hợp thành cơ sở hạ tầng; nói riêng quan hệ sản xuất chưa đủ khái quát bằng cơ sở hạ tầng như giáo trình dùng."],"s":"GT bản tái bản lần 3: Chương X mục III (Biện chứng của cơ sở hạ tầng và kiến trúc thượng tầng).","c":3,"v":"khớp"},{"q":"Trong sự tác động trở lại của kiến trúc thượng tầng đến cơ sở hạ tầng, yếu tố nào có tác động lớn nhất?","o":["Nhà nước","Tôn giáo","Ý thức chính trị","Văn hóa"],"a":[0],"e":"Giáo trình viết: trong xã hội có giai cấp, nhà nước là yếu tố có tác động mạnh nhất đối với cơ sở hạ tầng vì đó là bộ máy bạo lực tập trung của giai cấp thống trị về kinh tế; các yếu tố khác như triết học, đạo đức, tôn giáo, nghệ thuật đều bị nhà nước, pháp luật chi phối. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Tôn giáo cũng tác động đến cơ sở hạ tầng nhưng bị nhà nước, pháp luật chi phối nên không mạnh nhất.","Ý thức chính trị là yếu tố tư tưởng, tác động thông qua nhà nước nên không phải yếu tố mạnh nhất.","Văn hóa (nghệ thuật, đạo đức, v.v.) cũng bị nhà nước, pháp luật chi phối nên không mạnh nhất."],"s":"GT bản tái bản lần 3: Chương X mục III (tác động trở lại của kiến trúc thượng tầng đối với cơ sở hạ tầng).","c":3,"v":"khớp"},{"q":"Chọn câu trả lời đúng nhất theo quan điểm duy vật lịch sử: Khẳng định tính lịch sử - tự nhiên của sự phát triển các hình thái kinh tế - xã hội, tức là khẳng định sự phát triển của xã hội:","o":["Hoàn toàn tuân theo quy luật khách quan của giới tự nhiên","Hoàn toàn tuân theo quy luật khách quan của xã hội","Hoàn toàn tuân theo quy luật khách quan của tự nhiên và xã hội","Tuân theo quy luật khách quan nhưng đồng thời chịu sự tác động của các nhân tố khác"],"a":[3],"e":"Mác coi sự phát triển của các hình thái kinh tế – xã hội là một quá trình lịch sử – tự nhiên: xu hướng chung của lịch sử do quy luật khách quan chi phối, xét đến cùng là sự phát triển của lực lượng sản xuất; đồng thời giáo trình nhấn mạnh con đường phát triển của mỗi dân tộc còn chịu tác động của nhiều nhân tố khác. Vì thế đề chọn D. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf); [GT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quy luật xã hội là quy luật khách quan của xã hội, không đồng nhất với quy luật của giới tự nhiên.","Chữ «hoàn toàn» tuyệt đối hóa, bỏ qua tác động của các nhân tố khác (hoạt động của con người, điều kiện cụ thể) mà giáo trình nêu.","Cũng tuyệt đối hóa («hoàn toàn») và đồng nhất quy luật xã hội với quy luật tự nhiên.",""],"s":"GT bản tái bản lần 3: Chương X mục IV (Sự phát triển các hình thái kinh tế – xã hội là quá trình lịch sử – tự nhiên); GT 2021: Chương 3 mục I.4.","c":3,"v":"dễ nhầm","k":"B chỉ sai ở chữ «hoàn toàn»; câu hỏi kiểu chọn «đúng nhất» nên chọn D.","id":"1blfh81"},{"q":"Trong quan điểm của phép biện chứng duy vật thì với hình thức, nội dung giữ vai trò:","o":["Quyết định","Phụ thuộc","Không phụ thuộc","Ít phụ thuộc"],"a":[0],"e":"Giáo trình viết: nội dung và hình thức tồn tại thống nhất, phụ thuộc lẫn nhau, nhưng nội dung giữ vai trò quyết định; hình thức do nội dung quyết định, sau khi xuất hiện có tính độc lập tương đối và tác động trở lại nội dung. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Sai: nội dung quyết định chứ không phụ thuộc hình thức; hình thức mới là mặt phụ thuộc vào nội dung.","Sai: hai mặt thống nhất và phụ thuộc lẫn nhau, hình thức có tác động trở lại nội dung.","Sai: không phải nội dung «ít phụ thuộc»; nội dung giữ vai trò quyết định."],"s":"GT 2021: Chương 2 mục II (phép biện chứng duy vật, cặp phạm trù nội dung – hình thức); GT tái bản lần 3: Chương VII mục V.","c":2,"v":"khớp","id":"16ew64k"},{"q":"Cơ sở chủ yếu nhất để hình thành nên khái niệm là gì?","o":["Thế giới tự nhiên","Thực tiễn","Cảm giác","Tri giác và biểu tượng"],"a":[1],"e":"Giáo trình coi thực tiễn là cơ sở chủ yếu và trực tiếp nhất của nhận thức, đồng thời là động lực, mục đích và tiêu chuẩn kiểm tra chân lý; khái niệm là hình thức tư duy trừu tượng hình thành trong quá trình nhận thức dựa trên thực tiễn. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Thế giới tự nhiên là đối tượng được phản ánh, không phải cơ sở chủ yếu nhất như thực tiễn.","","Cảm giác chỉ là hình thức nhận thức cảm tính, bản thân chưa tạo nên khái niệm.","Tri giác và biểu tượng là các hình thức của nhận thức cảm tính, chỉ là chất liệu, không phải cơ sở chủ yếu nhất."],"s":"GT bản tái bản lần 3: Chương IX mục I (Bản chất của nhận thức và vai trò của thực tiễn); giáo trình nói «cơ sở của nhận thức», chưa thấy câu «cơ sở của khái niệm».","c":2,"v":"khớp","id":"16vbzby"},{"q":"Theo quan điểm của chủ nghĩa duy vật thì bất kỳ một sự vật, hiện tượng nào, ở bất kỳ không gian nào và ở bất kỳ thời gian nào cũng có mối liên hệ với những sự vật, hiện tượng khác là biểu hiện tính chất nào của mối liên hệ?","o":["Tính đa dạng","Tính khách quan","Tính phổ biến","Tính chung nhất"],"a":[2],"e":"Giáo trình định nghĩa: tính phổ biến của mối liên hệ biểu hiện ở chỗ bất kỳ sự vật, hiện tượng nào, ở bất kỳ không gian nào và bất kỳ thời gian nào cũng có mối liên hệ với những sự vật, hiện tượng khác. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Tính đa dạng, phong phú nói về nhiều loại liên hệ khác nhau, không phải việc sự vật nào cũng có liên hệ.","Tính khách quan là liên hệ vốn có, không phụ thuộc ý thức con người.","","«Tính chung nhất» không phải một trong ba tính chất (khách quan, phổ biến, đa dạng) mà giáo trình nêu."],"s":"GT bản tái bản lần 3: Chương VI mục I (Nguyên lý về mối liên hệ phổ biến).","c":2,"v":"khớp","id":"n8nmob"},{"q":"\"Phương pháp biện chứng của tôi không những khác phương pháp của Hêghen về cơ bản mà còn đối lập hẳn với phương pháp ấy nữa\" là luận điểm của ai?","o":["Phoiơbắc","Ph. Ăngghen","V.I. Lênin","C.Mác"],"a":[3],"e":"Đây là câu của C. Mác trong lời bạt cho lần xuất bản thứ hai bộ «Tư bản»: phương pháp biện chứng của Mác không những khác phương pháp của Hêghen về cơ bản mà còn đối lập hẳn với phương pháp ấy; giáo trình dẫn câu này khi nói Mác cải tạo cả chủ nghĩa duy vật cũ lẫn phép biện chứng của Hêghen. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Phoiơbắc là nhà duy vật siêu hình, không phải tác giả luận điểm này.","Ph. Ăngghen không phải tác giả câu này; câu thuộc lời bạt «Tư bản» của Mác.","V.I. Lênin không phải tác giả; Lênin về sau chỉ dẫn lại và phát triển.",""],"s":"GT bản tái bản lần 3: Chương III (sự ra đời và phát triển của triết học Mác), phần Mác cải tạo phép biện chứng Hêghen.","c":2,"v":"khớp"},{"q":"Yếu tố biện chứng trong triết học Phật giáo được thể hiện qua quan điểm về điều gì?","o":["Vô thường, nhân duyên","Bắt chính đạo","Bát khô","Vô thường, vô ngã, vô tạo giả"],"a":[3],"e":"Giáo trình nêu triết học Phật giáo phủ định đấng sáng tạo tối cao, phủ định cái «tôi» (vô ngã) và nêu quan điểm vô thường (vạn vật biến đổi theo chu trình sinh – trụ – dị – diệt); đó là những yếu tố biện chứng, nên đề chọn D gồm vô thường, vô ngã, vô tạo giả. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Nhân duyên cũng là tư tưởng Phật giáo nhưng phương án này thiếu vô ngã, không đầy đủ như đáp án D.","Bát chính đạo (đề chép «Bắt chính đạo») là tám con đường tu tập diệt khổ, thuộc nhân sinh quan, không phải yếu tố biện chứng.","Bát khổ là tám nỗi khổ trong Khổ đế, thuộc nhân sinh quan chứ không phải quan điểm biện chứng.",""],"s":"GT bản tái bản lần 3: Chương II mục I (Triết học Ấn Độ cổ, trung đại – Phật giáo).","c":1,"v":"dễ nhầm","k":"Giáo trình đoạn Phật giáo ghi vô ngã, vô thường, thập nhị nhân duyên; cụm «vô tạo giả» chỉ tìm thấy ở ý phủ định đấng sáng tạo, không gặp đúng thuật ngữ. A khá gần D nên dễ nhầm."},{"q":"Đấu tranh của hai mặt đối lập là:","o":["Sự tác động qua lại theo xu hướng bài trừ và phủ định lẫn nhau","Sự tác động lẫn nhau giữa hai mặt đối lập theo khuynh hướng biện chứng","Các phương án trả lời đều sai"],"a":[0],"e":"Giáo trình định nghĩa: đấu tranh của các mặt đối lập là sự tác động qua lại theo xu hướng bài trừ và phủ định lẫn nhau. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Giáo trình không định nghĩa đấu tranh là tác động «theo khuynh hướng biện chứng»; điểm then chốt là xu hướng bài trừ, phủ định lẫn nhau.","Sai vì phương án A trùng khớp định nghĩa của giáo trình."],"s":"GT bản tái bản lần 3: Chương VIII mục III (Quy luật thống nhất và đấu tranh của các mặt đối lập).","c":2,"v":"khớp","f":1},{"q":"Theo quan điểm triết học Mác - Lênin, nhà nước có mấy đặc trưng?","o":["Hai đặc trưng","Ba đặc trưng","Bốn đặc trưng","Năm đặc trưng"],"a":[3],"e":"Cả hai bản giáo trình Triết học Mác-Lênin (tái bản lần 3 và 2021) đều viết bất kỳ nhà nước nào cũng có ba đặc trưng cơ bản: quản lý dân cư theo lãnh thổ; có hệ thống bộ máy quyền lực chuyên nghiệp mang tính cưỡng chế; có hệ thống thuế khóa. Đáp án D (năm đặc trưng) phù hợp cách trình bày khác trong lý luận nhà nước và pháp luật: quyền lực công cộng đặc biệt, quản lý theo lãnh thổ, chủ quyền quốc gia, ban hành pháp luật, thu thuế. ([GT tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf); [luatvietnam.vn](https://luatvietnam.vn/linh-vuc-khac/nha-nuoc-la-gi-883-95006-article.html))","w":["Hai đặc trưng thiếu so với cả cách nêu ba lẫn năm đặc trưng.","Ba đặc trưng là cách nêu của giáo trình Triết học Mác-Lênin, nên theo giáo trình này B mới đúng, nhưng đề chọn D.","Bốn đặc trưng không phải cách chia chuẩn của các tài liệu tra được.",""],"s":"GT bản tái bản lần 3: Chương XII mục I.2 (Đặc trưng cơ bản của nhà nước: ba đặc trưng); GT 2021: Chương 3 mục III.","c":3,"v":"nghi vấn","k":"nghi vấn: Đáp án D (năm) mâu thuẫn với giáo trình Triết học Mác-Lênin của Bộ GD&ĐT (cả hai bản đều ghi ba đặc trưng); chỉ khớp cách nêu năm đặc trưng trong lý luận nhà nước và pháp luật. Cần cân nhắc khi học: đề thi dùng nguồn nào thì theo nguồn đó."},{"q":"Thông thường, trong kiến trúc thượng tầng các nhà nước tư bản hiện nay:","o":["Đều thực hiện chế độ nhất nguyên chính trị","Không thực hiện chế độ đa nguyên chính trị","Tùy từng nước mà có thể thực hiện chế độ đa nguyên chính trị hay không","Thực hiện chế độ đa đảng nhưng nhất nguyên chính trị"],"a":[3],"e":"Các nguồn lý luận chính trị nêu: ở các nước tư bản có nhiều đảng chính trị nhưng thực chất chỉ một hoặc hai đảng thay nhau cầm quyền và đều đại diện cho các bộ phận của giai cấp tư sản, nên đa đảng nhưng nhất nguyên chính trị (quyền lực thuộc giai cấp tư sản). ([Tạp chí Lý luận chính trị](https://lyluanchinhtri.vn/nhan-dien-chieu-bai-doi-da-nguyen-chinh-tri-da-dang-doi-lap-cua-cac-the-luc-thu-dich-6474.html))","w":["Quá tuyệt đối: nhiều nhà nước tư bản có chế độ đa đảng chứ không chỉ một đảng, dù vẫn nhất nguyên về giai cấp.","Nhận định không chặt chẽ: các nguồn đều nói đa đảng là hình thức tổ chức chính trị phổ biến của nhà nước tư sản.","Cách nói «tùy từng nước» không phải kết luận của tài liệu; bản chất chung là đa đảng nhưng nhất nguyên chính trị.",""],"s":"Không có trong giáo trình Triết học Mác-Lênin; thuộc chương nhà nước và chính trị (CNXH khoa học); chưa đối chiếu số chương.","c":4,"v":"dễ nhầm","k":"Chỉ đối chiếu được với bài lý luận chính trị thứ cấp; giáo trình triết không bàn đến thuật ngữ «nhất nguyên chính trị»."},{"q":"Theo quan điểm của phép biện chứng duy vật thì những thay đổi về chất của sự vật lại tạo ra những thay đổi gì của sự vật trên các phương diện khác nhau?","o":["Biến đổi mới về lượng","Biến đổi của chất","Chất mới","Cái mới"],"a":[0],"e":"Giáo trình viết: quy luật lượng đổi – chất đổi còn nói chiều ngược lại, khi chất mới đã ra đời thì nó tạo ra lượng mới phù hợp để có sự thống nhất mới giữa chất và lượng; chất mới cũng thúc đẩy sự thay đổi tương ứng của lượng. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Câu hỏi nói chất đổi làm thay đổi gì ở các phương diện khác nhau; «biến đổi của chất» lặp lại vế đã cho và không phải kết luận của quy luật.","Chất mới là kết quả của bước nhảy, chứ không phải điều do thay đổi chất tạo ra.","«Cái mới» là khái niệm chung, không phải khái niệm giáo trình dùng ở chỗ này."],"s":"GT 2021: Chương 2 mục II (Quy luật chuyển hóa từ những thay đổi về lượng thành những thay đổi về chất và ngược lại); GT tái bản lần 3: Chương VIII mục II.","c":2,"v":"khớp","id":"ebicza"},{"q":"Theo quan điểm của chủ nghĩa Mác- Lênin, Kiến trúc thượng tầng là gì?","o":["Toàn bộ thiết chế chính trị của xã hội","Toàn bộ thiết chế chính trị và pháp luật của xã hội","Toàn bộ thiết chế chính trị - xã hội","Toàn bộ hệ thống kết cấu các hình thái ý thức xã hội cùng với các thiết chế chính trị - xã hội tương ứng"],"a":[3],"e":"Giáo trình định nghĩa: kiến trúc thượng tầng là toàn bộ những quan điểm chính trị, pháp quyền, triết học, đạo đức, tôn giáo, nghệ thuật… cùng với những thiết chế xã hội tương ứng như nhà nước, đảng phái, giáo hội, đoàn thể, hình thành trên một cơ sở hạ tầng nhất định; phương án D nêu ý này bằng cách diễn đạt khác. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Quá hẹp: chỉ nói thiết chế chính trị, bỏ các hình thái ý thức xã hội.","Chỉ có chính trị và pháp luật, thiếu triết học, đạo đức, tôn giáo, nghệ thuật.","Chỉ nói thiết chế, thiếu các quan điểm tư tưởng, tức các hình thái ý thức xã hội.",""],"s":"GT bản tái bản lần 3: Chương X mục III.1 (Cơ sở hạ tầng và kiến trúc thượng tầng); GT 2021: Chương 3 mục I.3.","c":3,"v":"khớp"},{"q":"Cơ sở để phần chia triết học thành các trường phái khác nhau là:","o":["Vấn đề cơ bản của nhận thức luận","Vấn đề cơ bản của phương pháp luận","Vấn đề cơ bản của triết học"],"a":[2],"e":"Vấn đề cơ bản của triết học là quan hệ giữa vật chất và ý thức (tư duy và tồn tại); cách trả lời mặt thứ nhất (cái nào có trước) là cơ sở để chia triết học thành chủ nghĩa duy vật và chủ nghĩa duy tâm. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Nhận thức luận là mặt thứ hai của vấn đề cơ bản, không phải cơ sở phân chia các trường phái.","Phương pháp luận (biện chứng – siêu hình) là cách phân loại theo phương pháp tư duy, không phải cơ sở phân chia các trường phái duy vật – duy tâm.",""],"s":"GT 2021: Chương 1 mục I.2 (Vấn đề cơ bản của triết học); chưa đối chiếu nguyên văn câu «cơ sở phân chia các trường phái».","c":1,"v":"khớp"},{"q":"Thuộc tính cơ bàn nhất, phổ biến nhất của mọi tồn tại vật chất được khái quát trong phạm trù vật chất của chủ nghĩa duy vật biện chứng là:","o":["Không gian và thời gian","Tồn tại khách quan","Tồn tại trong vận động","Vận động và đứng im"],"a":[1],"e":"Theo định nghĩa vật chất của Lênin được giáo trình nêu, thuộc tính cơ bản, phổ biến nhất của mọi dạng vật chất là tồn tại khách quan, tức tồn tại bên ngoài và độc lập với ý thức, được ý thức phản ánh. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Không gian và thời gian là hình thức tồn tại của vật chất, không phải thuộc tính cơ bản nhất.","","Tồn tại trong vận động nói về phương thức tồn tại của vật chất, không phải thuộc tính cơ bản nhất trong định nghĩa.","Vận động và đứng im là các trạng thái, phương thức tồn tại, không phải thuộc tính được khái quát trong phạm trù vật chất."],"s":"GT 2021: Chương 2 mục I (Vật chất, định nghĩa vật chất của Lênin); GT tái bản lần 3: Chương V mục I.","c":2,"v":"khớp","id":"h1umem"},{"q":"Luận điểm \"Bản chất là những thực thể tinh thần tồn tại khách quan, quyết định sự tồn tại của sự vật\" thuộc lập trường triết học nào?","o":["Chủ nghĩa duy tâm chủ quan","Chủ nghĩa duy tâm khách quan","Chủ nghĩa duy vật siêu hình","Tất cà các đáp án đều đúng"],"a":[1],"e":"Quan điểm cho rằng bản chất của sự vật là những thực thể tinh thần tồn tại khách quan (như ý niệm của Platôn, tinh thần thế giới của Hêghen) và quyết định sự tồn tại của sự vật là chủ nghĩa duy tâm khách quan. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Duy tâm chủ quan coi sự vật là phức hợp cảm giác của chủ thể, không có «thực thể tinh thần tồn tại khách quan».","","Duy vật siêu hình thừa nhận vật chất có trước, không coi tinh thần là bản chất sự vật.","Chỉ B đúng; A và C đều trái với nội dung luận điểm."],"s":"GT 2021: Chương 2 mục I (phê phán thế giới quan duy tâm; chủ nghĩa duy tâm khách quan); GT tái bản lần 3: Chương II (triết học Hy Lạp – Platôn); chưa đối chiếu số mục chính xác.","c":2,"v":"khớp","f":1},{"q":"Sự thống nhất giữa lực lượng sản xuất với một trình độ nhất định và quan hệ sản xuất tương ứng tạo thành gì?","o":["Bản chất hàng hóa","Năng lực sáng tạo","Cách thức sản xuất","Phương thức sản xuất"],"a":[3],"e":"Giáo trình gắn việc thay quan hệ sản xuất cũ bằng quan hệ sản xuất mới phù hợp với trình độ mới của lực lượng sản xuất với việc phương thức sản xuất cũ mất đi, phương thức sản xuất mới ra đời; tức phương thức sản xuất là sự thống nhất giữa lực lượng sản xuất ở một trình độ nhất định và quan hệ sản xuất tương ứng. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Bản chất hàng hóa là khái niệm kinh tế chính trị, không liên quan.","Năng lực sáng tạo không phải phạm trù chỉ sự thống nhất lực lượng – quan hệ sản xuất.","«Cách thức sản xuất» không phải thuật ngữ; thuật ngữ chuẩn là phương thức sản xuất.",""],"s":"GT bản tái bản lần 3: Chương X mục II (Biện chứng của lực lượng sản xuất và quan hệ sản xuất); trùng nội dung câu 356.","c":3,"v":"khớp"},{"q":"Quan điểm phát triển đòi hỏi điều gì?","o":["Bảo vệ cái mới, ủng hộ cái mới, đấu tranh cho cái mới nhưng không phủ định sạch trơn cái cũ","Bảo vệ cái cũ, đấu tranh cho cái cũ đồng thời tạo điều kiện để cái mới ra đời và thay thế cái cũ","Phát huy những mặt tích cực của cái cũ, tạo điều kiện cho nó phát triển","Tạo điều kiện tiền đề cho cái mới phát triển"],"a":[0],"e":"Giáo trình nêu sự phát triển có tính kế thừa: cái mới ra đời không phải là phủ định tuyệt đối, phủ định sạch trơn cái cũ mà giữ lại có chọn lọc, cải tạo những yếu tố còn tác dụng; vì thế quan điểm phát triển đòi hỏi ủng hộ, bảo vệ cái mới nhưng không phủ định sạch trơn cái cũ. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Bảo vệ cái cũ, chống cái mới là bảo thủ, trái với quan điểm phát triển.","Chỉ phát huy cái cũ là bảo thủ, không thấy xu hướng của cái mới.","Chỉ tạo điều kiện cho cái mới, thiếu mặt kế thừa có chọn lọc cái cũ mà quan điểm phát triển yêu cầu."],"s":"GT 2021: Chương 2 mục II.2 (Nguyên lý về sự phát triển); GT tái bản lần 3: Chương VI mục II.","c":2,"v":"khớp","id":"10j5d1a"},{"q":"Điều khẳng định nào sau đây là đúng?","o":["Thuyết không thể biết không thừa nhận chân lý khách quan.","Chủ nghĩa duy tâm chủ quan không thừa nhận chân lý khách quan.","Chủ nghĩa duy tâm khách quan thừa nhận chân lý chủ quan.","Chủ nghĩa duy vật biện chứng thừa nhận chân lý khách quan."],"a":[3],"e":"Chủ nghĩa duy vật biện chứng thừa nhận chân lý khách quan, là nội dung của tri thức phản ánh đúng hiện thực khách quan, không phụ thuộc vào ý thức con người, nên D là phương án đúng. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Phương án này cũng khó bác bỏ về logic, vì bất khả tri nói con người không thể nhận thức bản chất sự vật; đề chọn D làm đáp án đúng.","Duy tâm chủ quan coi tri thức là của chủ thể; phương án này cũng có thể hiểu là đúng, nhưng đề chọn D.","Duy tâm khách quan không chủ trương chân lý chủ quan; phương án này không được giáo trình khẳng định.",""],"s":"GT 2021: Chương 2 mục III (Lý luận nhận thức, Tính chất của chân lý); GT tái bản lần 3: Chương IX mục III.","c":2,"v":"dễ nhầm","k":"A và B cũng khá hợp lý về mặt triết học, nên đề dễ gây nhầm; chỉ phương án D là khẳng định trực tiếp có trong giáo trình.","id":"1o7iiyt"},{"q":"Theo chủ nghĩa duy vật lịch sử, cơ sở hạ tầng là toàn bộ những quan hệ sản xuất hợp thành cơ cấu:","o":["Của xã hội","Kỹ thuật xã hội","Kinh tế của xã hội","Vật chất xã hội"],"a":[2],"e":"Giáo trình định nghĩa: cơ sở hạ tầng là toàn bộ những quan hệ sản xuất hợp thành cơ cấu kinh tế của một xã hội nhất định, trích Mác. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["«Cơ cấu của xã hội» quá chung, không nói rõ là cơ cấu kinh tế.","«Kỹ thuật xã hội» không phải thuật ngữ trong giáo trình.","","«Vật chất xã hội» quá chung, không phải thuật ngữ của định nghĩa."],"s":"GT bản tái bản lần 3: Chương X mục III.1.a (Cơ sở hạ tầng).","c":3,"v":"khớp"},{"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử, để giải thích đúng và triệt để các hiện tượng trong đời sống xã hội, cần phải xuất phát trừ:","o":["Nền sản xuất vật chất của xã hội","Quan điểm chính trị của giai cấp nắm quyền lực nhà nước","Truyền thống văn hóa xã hội","Ý trí của mọi thành viên trong cộng đồng xã hội"],"a":[0],"e":"Giáo trình khẳng định sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội, nên muốn giải thích đúng, triệt để các hiện tượng đời sống xã hội phải xuất phát từ nền sản xuất vật chất của xã hội. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Quan điểm chính trị thuộc kiến trúc thượng tầng, do cơ sở kinh tế quyết định.","Truyền thống văn hóa thuộc ý thức xã hội, bị tồn tại xã hội quyết định.","Ý chí của mọi thành viên là yếu tố chủ quan; duy vật lịch sử không xuất phát từ đó."],"s":"GT 2021: Chương 3 mục I.1 (Sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội); GT tái bản lần 3: Chương X mục I.","c":3,"v":"khớp"},{"q":"Vì các mối liên hệ có tính đa dạng, phong phú nên trong hoạt động nhận thức và thực tiễn khi thực hiện quan điểm toàn diện thì con người phải kết hợp với quan điểm:","o":["Lịch sử - cụ thể","Toàn diện","Biện chứng","Khách quan"],"a":[0],"e":"Giáo trình viết: do các mối liên hệ đa dạng, phong phú nên trong nhận thức và hoạt động thực tiễn con người phải tôn trọng quan điểm lịch sử – cụ thể, chú ý điều kiện, hoàn cảnh lịch sử – cụ thể của sự vật; quan điểm toàn diện vì vậy phải kết hợp với quan điểm lịch sử – cụ thể. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Toàn diện là quan điểm đang xét, nói kết hợp với chính nó là lặp lại.","«Biện chứng» quá chung, không phải quan điểm cụ thể mà giáo trình nêu.","Quan điểm khách quan không phải quan điểm giáo trình nêu để kết hợp với quan điểm toàn diện ở chỗ này."],"s":"GT bản tái bản lần 3: Chương VI mục I (ý nghĩa phương pháp luận của nguyên lý mối liên hệ phổ biến).","c":2,"v":"khớp","id":"1yew33t"},{"q":"Luận điểm sau đây thuộc quan điểm triết học nào: \"Phát triển là quá trình chuyển hóa từ những thay đổi về lượng thành sự thay đổi về chất và ngược lại\"?","o":["Quan điểm chiết trung và ngụy biện","Tất cả đều đúng","Quan điểm biện chứng","Quan điểm siêu hình"],"a":[2],"e":"Quan điểm phát triển là quá trình chuyển hóa từ những thay đổi về lượng thành thay đổi về chất và ngược lại là quan điểm biện chứng, nội dung của quy luật lượng đổi – chất đổi; quan điểm siêu hình coi phát triển chỉ là tăng giảm thuần túy về lượng. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Chiết trung và ngụy biện không đưa ra quan niệm có hệ thống về chuyển hóa lượng – chất.","Không phải tất cả đều đúng vì quan điểm siêu hình phủ nhận chuyển hóa lượng – chất.","","Quan điểm siêu hình coi sự vật chỉ tăng giảm về lượng, không thừa nhận bước nhảy về chất."],"s":"GT 2021: Chương 2 mục II (Quy luật chuyển hóa từ những thay đổi về lượng thành thay đổi về chất); GT tái bản lần 3: Chương VIII mục II.","c":2,"v":"khớp","id":"165wfdj","f":1},{"q":"Trình độ phát triển của phương thức sản xuất ra của cải vật chất là nhân tố giữ vai trò quyết định:","o":["Đời sống tinh thần của xã hội","Đời sống văn hóa của xã hội","Đời sống chính trị, đạo đức của xã hội","Trình độ phát triển của nên sản xuất xã hội"],"a":[3],"e":"Giáo trình khẳng định sản xuất vật chất là cơ sở của sự tồn tại, phát triển xã hội; trình độ phát triển của phương thức sản xuất quyết định trình độ phát triển của nền sản xuất xã hội, và từ đó quyết định đời sống tinh thần, văn hóa, chính trị. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Đời sống tinh thần là lĩnh vực chịu sự quyết định của phương thức sản xuất, không phải đối tượng gần nhất bị quyết định như đề chọn.","Cũng là lĩnh vực chịu sự quyết định gián tiếp; đề chọn trình độ nền sản xuất.","Đời sống chính trị, đạo đức thuộc kiến trúc thượng tầng, bị cơ sở kinh tế quyết định.",""],"s":"GT 2021: Chương 3 mục I.1–I.2; GT tái bản lần 3: Chương X mục I; chưa đối chiếu nguyên văn câu hỏi.","c":3,"v":"dễ nhầm","k":"Câu hỏi diễn đạt chưa rõ; A, B, C cũng bị phương thức sản xuất quyết định nhưng ở mức gián tiếp, nên cần học theo đáp án D của đề.","id":"1r14pez"},{"q":"\"Mặt người da thú\" giúp anh/chị liên hệ tới cặp phạm trù nào trong triết học?","o":["Cái chung, cái riêng","Bản chất, hiện tượng","Tất nhiên, ngẫu nhiên","Nguyên nhân, kết quả"],"a":[1],"e":"«Mặt người da thú» nói về mâu thuẫn giữa hiện tượng bên ngoài (mặt người) và bản chất bên trong (da thú); giáo trình viết bản chất và hiện tượng thống nhất nhưng đó là thống nhất của hai mặt đối lập, không phù hợp hoàn toàn mà luôn bao hàm mâu thuẫn. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Cái chung – cái riêng nói về quan hệ giữa cái phổ biến và cái đơn nhất, không phải ngoài – trong.","","Tất nhiên – ngẫu nhiên nói về nguồn gốc của sự xuất hiện sự kiện, không phải vẻ ngoài và bản chất.","Nguyên nhân – kết quả là quan hệ sinh thành, không phải vẻ bề ngoài đối lập với bản chất."],"s":"GT 2021: Chương 2 mục II (cặp phạm trù bản chất – hiện tượng); GT tái bản lần 3: Chương VII. Thành ngữ là ví dụ minh họa của đề, không có trong giáo trình.","c":2,"v":"khớp","id":"1xiwmx8"},{"q":"Cơ sở của sự tồn tại, phát triển là gì?","o":["Lao động của thế giới","Sản xuất vật chất","Chủ nghĩa tư bản và chủ nghĩa xã hội","Tiêu dùng xã hội"],"a":[1],"e":"Giáo trình đặt tiêu đề rõ: sản xuất vật chất là cơ sở của sự tồn tại và phát triển xã hội, vì để tồn tại và phát triển con người phải sản xuất ra của cải vật chất. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Lao động của thế giới» không phải phạm trù trong giáo trình.","","Chủ nghĩa tư bản và chủ nghĩa xã hội là các chế độ xã hội, không phải cơ sở chung của tồn tại, phát triển.","Tiêu dùng phụ thuộc vào sản xuất, không phải cơ sở của sự tồn tại và phát triển xã hội."],"s":"GT 2021: Chương 3 mục I.1; GT tái bản lần 3: Chương X mục I.","c":3,"v":"khớp","id":"t3jr99"},{"q":"Một trong những nội dung chỉ tính thống nhất vật chất của thế giới là gì?","o":["Chỉ có một thế giới duy nhất, thế giới thống nhất với nhau","Chỉ có một thế giới duy nhất, thế giới thống nhất ở tính vật chất","Thế giới này là do vụ nổ vũ trụ gây ra, tạo ra những hành tinh mang tính vật chất","A và B"],"a":[1],"e":"Giáo trình nêu một nội dung của tính thống nhất vật chất của thế giới: chỉ có một thế giới duy nhất và thống nhất là thế giới vật chất, thế giới thống nhất ở tính vật chất; Ăngghen khẳng định tính thống nhất thực sự của thế giới là tính vật chất của nó. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Chỉ nói thế giới thống nhất với nhau, chưa nêu cơ sở thống nhất là tính vật chất; chủ nghĩa duy vật khác duy tâm ở chỗ này.","","Vụ nổ vũ trụ là giả thuyết khoa học, không phải nội dung triết học về tính thống nhất vật chất của thế giới.","Vì A chưa chính xác nên «A và B» không phải đáp án đúng nhất."],"s":"GT 2021: Chương 2 mục I (Thế giới thống nhất ở tính vật chất); GT tái bản lần 3: Chương V mục I.","c":2,"v":"khớp","id":"yub8vf","f":1},{"q":"Phép biện chứng nào được coi là khoa học về những quy luật phổ biến của sự vận động và sự phát triển của tự nhiên, xã hội và tư duy con người:","o":["Phép biện chứng cổ đại","Phép biện chứng cổ điển Đức","Phép biện chứng của chủ nghĩa Mác - Lênin","Phép biện chứng của G. W.Ph.Hêghen"],"a":[2],"e":"Phép biện chứng duy vật của chủ nghĩa Mác – Lênin là khoa học về những quy luật phổ biến của sự vận động và phát triển của tự nhiên, xã hội và tư duy, theo cách Ăngghen và Lênin định nghĩa. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Biện chứng cổ đại mang tính ngây thơ, chất phác, chưa khái quát thành khoa học về quy luật.","Biện chứng cổ điển Đức mang tính duy tâm, mới đạt đến hệ thống ở dạng duy tâm.","","Biện chứng của Hêghen là biện chứng duy tâm khách quan, bị Mác – Ăngghen cải tạo."],"s":"GT 2021: Chương 2 mục II.1 (Hai loại hình biện chứng và phép biện chứng duy vật); GT tái bản lần 3: Chương I mục III.","c":2,"v":"khớp","id":"1dhpxq4"},{"q":"Ai là tác giả của Thuyết tương đối tổng quát?","o":["Albert Einstein (A.Anhxtanh)","Nicolaus Copernicus","Giordano Bruno","Alex. Sancho"],"a":[0],"e":"Albert Einstein là tác giả của thuyết tương đối rộng (tổng quát), công bố năm 1915–1916 (bài trình bày hoàn chỉnh xuất bản năm 1916). Đây là kiến thức khoa học tự nhiên, không nằm trong giáo trình triết học. ([Wikipedia: General relativity](https://en.wikipedia.org/wiki/General_relativity))","w":["","Copernicus (Côpéc-ních) là nhà thiên văn học, tác giả thuyết nhật tâm.","Giordano Bruno là triết gia, nhà tư tưởng bị Giáo hội thiêu sống, không phải tác giả thuyết tương đối.","Không phải tác giả của thuyết tương đối tổng quát."],"s":"Kiến thức vật lý học (Wikipedia); không thuộc giáo trình Triết học Mác-Lênin.","c":2,"v":"khớp","id":"s1xi9h"},{"q":"Theo chủ nghĩa duy vật biện chứng, vận động không chỉ là sự thay đổi vị trí trong không gian, mà còn là mọi sự thay đổi và:","o":["Mọi di chuyển trong thực tế","Mọi quá trinh diễn ra trong vũ trụ","Mọi vận động trong tự nhiên, xã hội","Mọi vận động trong xã hội"],"a":[1],"e":"Giáo trình dẫn Ăngghen: vận động, hiểu theo nghĩa chung nhất, bao gồm tất cả mọi sự thay đổi và mọi quá trình diễn ra trong vũ trụ, kể từ sự thay đổi vị trí đơn giản cho đến tư duy. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Di chuyển chỉ là một hình thức vận động (cơ học), hẹp hơn nghĩa chung nhất.","","Thiếu tư duy, thiếu vũ trụ nói chung; không phải cách Ăngghen khái quát.","Chỉ xã hội là quá hẹp; vận động bao gồm cả tự nhiên, xã hội, tư duy."],"s":"GT 2021: Chương 2 mục I (Vận động – phương thức tồn tại của vật chất); GT tái bản lần 3: Chương V mục I.","c":2,"v":"khớp","id":"1j434ng"},{"q":"Triết học ra đời vào thời gian nào?","o":["Thế kỷ II. TCN","Thế kỷ VIII - VI TCN","Thế kỷ II sau CN","Thế kỷ VII - VI TCN"],"a":[1],"e":"Giáo trình nêu triết học ra đời ở cả phương Đông và phương Tây gần như cùng một thời gian, khoảng từ thế kỷ VIII đến thế kỷ VI trước Công nguyên, tại các trung tâm văn minh lớn như Trung Quốc, Ấn Độ, Hy Lạp. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Thế kỷ II TCN quá muộn so với mốc ra đời của triết học.","","Thế kỷ II sau Công nguyên quá muộn.","Thế kỷ VII – VI TCN hẹp hơn khoảng VIII – VI TCN mà giáo trình nêu."],"s":"GT bản tái bản lần 3: Chương I mục I.1; GT 2021: Chương 1 mục I.1.","c":1,"v":"khớp"},{"q":"Trước khi triết học Mác ra đời, triết học được \"suy tôn\" là gì?","o":["Khoa học nghiên cứu","Khoa học của các khoa học","Khoa học của toán học","Khoa học của tầng lớp quý tộc"],"a":[1],"e":"Giáo trình viết từ buổi đầu lịch sử triết học đến thời Trung cổ, triết học là tri thức bao trùm, được coi là «khoa học của các khoa học»; Hêghen là người cuối cùng mang tham vọng này, rồi triết học Mác đoạn tuyệt với quan niệm đó. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Khoa học nghiên cứu» quá chung, không phải danh xưng suy tôn.","","Triết học không được gọi là khoa học của toán học.","Triết học không được suy tôn là khoa học của riêng tầng lớp quý tộc."],"s":"GT 2021: Chương 1 mục I.1 (Khái lược về triết học); GT tái bản lần 3: Chương I mục I.","c":1,"v":"khớp"},{"q":"Đêmôcrit (khoảng 427 -374 trước CN) được xem là?","o":["Nhà triết học Giáo hội Cổ đại","Nhà toán học Hi Lạp Cổ đại","Nhà triết học Hi Lạp Cổ đại","Nhà thần học Hy Lạp Cổ đại"],"a":[2],"e":"Đêmôcrít là đại biểu xuất sắc nhất của chủ nghĩa duy vật cổ đại Hy Lạp, nổi bật với thuyết nguyên tử; giáo trình bản 2021 ghi khoảng 427 – 374 trước CN (đúng như đề), còn bản tái bản lần 3 ghi khoảng 460 – 370 trước CN. ([GT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf); [GT tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Không có «nhà triết học Giáo hội cổ đại»; Đêmôcrít là nhà duy vật, đối lập với thần học.","Ông nổi tiếng là triết gia (thuyết nguyên tử), không được giáo trình xếp là nhà toán học.","","Ông không phải nhà thần học; triết học duy vật của ông chống thần học."],"s":"GT 2021: Chương 2 mục I (quan niệm vật chất của Lơxíp và Đêmôcrít); GT tái bản lần 3: Chương II mục I (Triết học Hy Lạp cổ đại).","c":1,"v":"khớp","k":"Mốc 427–374 TCN khớp bản giáo trình 2021, còn bản cũ ghi 460–370; không ảnh hưởng đáp án.","id":"z8klb0"},{"q":"Ném một đồng xu có hai mặt đen và trắng lên trời, đồng xu rơi xuống đất và ngửa mắt đen liên trên. Hiện tượng trên gọi là","o":["Ngẫu nhiên","Tất nhiên","Vừa tất nhiên vừa ngẫu nhiên","Không phải tất nhiên và cũng không phải ngẫu nhiên"],"a":[2],"e":"Giáo trình định nghĩa tất nhiên là cái do nguyên nhân bên trong quyết định, nhất định xảy ra như thế; ngẫu nhiên là cái do nhân tố, hoàn cảnh bên ngoài quyết định, có thể xuất hiện hoặc không; cả hai cùng tồn tại khách quan trong sự vật. Việc đồng xu rơi xuống là tất nhiên (trọng lực) còn mặt nào ngửa là ngẫu nhiên, nên đề chọn C. ([GT Triết học Mác-Lênin, tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Chỉ nhìn kết quả (mặt đen ngửa) mà bỏ qua việc rơi xuống là tất nhiên.","Chỉ nhìn việc rơi xuống mà bỏ qua yếu tố ngẫu nhiên là mặt nào ngửa.","","Phủ nhận cả hai là sai vì hiện tượng có cả hai yếu tố."],"s":"GT bản tái bản lần 3: Chương VII mục IV (Tất nhiên và ngẫu nhiên); ví dụ đồng xu là suy diễn của đề.","c":2,"v":"dễ nhầm","k":"Ví dụ do đề đặt ra, không có trong giáo trình; cách lập luận dựa trên đáp án của đề."},{"q":"Triết học trở thành nữ tì của thần học trong giai đoạn nào?","o":["Ở Tây Âu thời trung cố","Ở Tây Âu thời cổ đại","Ở Tây Âu thời cận đại","Ở Châu Âu thời hiện đại"],"a":[0],"e":"Giáo trình nêu ở Tây Âu thời Trung cổ, khi quyền lực của Giáo hội bao trùm mọi lĩnh vực đời sống xã hội thì triết học trở thành «nữ tì của thần học» (bản cũ ghi «nô lệ của thần học»). ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf); [GT tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Ở Tây Âu cổ đại triết học phát triển độc lập, chưa bị thần học chi phối.","Thời cận đại triết học thoát khỏi sự chi phối của thần học nhờ khoa học phát triển.","Hiện đại không còn tình trạng này."],"s":"GT 2021: Chương 1 mục I.1; GT tái bản lần 3: Chương I mục I và Chương II (triết học Tây Âu thời Trung cổ).","c":1,"v":"khớp"},{"q":"Công ty sản xuất thuốc bảo vệ thực vật muốn bổ nhiệm anh Nguyễn Văn A và chị Trần Thị B làm trưởng phòng quản lý nhân sự. Trong quá trình xem xét, công ty đó đã căn cứ vào năng lực tích lũy trong quá trình làm việc, độ nhạy bén khi xử lý công việc, năng lực phán đoán của Anh A và Chị B... Căn cứ vào ví dụ trên, Anh (Chị) hãy cho biết công ty đó đã vận dụng nội dung nào sau đây để bổ nhiệm nhân sự?","o":["Nguyên lý về mối liên hệ phổ biến","Nguyên lý về sự phát triển","Quy luật phủ định của phủ định","Quy luật đấu tranh và thống nhất giữa các mặt đối lập"],"a":[1],"e":"Công ty xét năng lực tích lũy trong quá trình làm việc và khả năng phán đoán, tức nhìn nhân sự trong sự vận động, tích lũy và có triển vọng; đó là vận dụng nguyên lý về sự phát triển, đòi hỏi xem xét sự vật trong quá trình vận động, biến đổi chứ không bất biến. ([GT Triết học Mác-Lênin 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Nguyên lý liên hệ phổ biến đòi hỏi xét nhiều mối liên hệ; ví dụ nhấn vào quá trình tích lũy năng lực nên không chọn A.","","Phủ định của phủ định nói về khuynh hướng phát triển theo đường xoáy ốc, không nằm trong tình huống.","Quy luật mâu thuẫn nói về nguồn gốc động lực phát triển, không phải căn cứ xét nhân sự ở đây."],"s":"GT 2021: Chương 2 mục II.2 (Nguyên lý về sự phát triển); GT tái bản lần 3: Chương VI mục II.","c":2,"v":"dễ nhầm","k":"Tình huống suy diễn từ ví dụ của đề; A cũng có thể bị hiểu là hợp lý, nên cần bám đáp án B."},{"q":"Dân chủ được hiểu là gì?","o":["Một giá trị xã hội phản ánh các quyền cơ bản của con người; là một hình thức tổ chức nhà nước của giai cấp cầm quyền; có quá trình ra đời, phát triển cùng với lịch sử xã hội nhân loại","Một giá trị xã hội phản ánh các quyền cơ bản của con người; là một hình thức tổ chức nhà nước của giai cấp tư sản cầm quyền; có quá trình ra đời, phát triển cùng với lịch sử xã hội nhân loại","Một giá trị xã hội phản ánh các quyền cơ bản của con người; là một hình thức tố chức nhà nước của giai cấp thống trị cầm quyền; có quá trình ra đời, phát triển từ xã hội chiếm hữu nô lệ","Một giá trị xã hội phản ánh các quyền cơ bản của con người; là một hình thức tổ chức nhà nước của giai cấp vô sản cầm quyền; có quá trình ra đời, phát triển cùng với lịch sử xã hội nhân loại"],"a":[0],"e":"Theo quan niệm của chủ nghĩa Mác-Lênin, dân chủ là một giá trị xã hội phản ánh những quyền cơ bản của con người; là hình thức tổ chức nhà nước của giai cấp cầm quyền thành một chế độ chính trị - xã hội trên cơ sở kinh tế - xã hội nhất định; và là phạm trù lịch sử gắn với quá trình phát triển của xã hội loài người. ([Báo Quân khu 7, dẫn khái niệm dân chủ trong giáo trình](https://baoquankhu7.vn/lam-ro-luan-diem-dan-chu-xa-hoi-chu-nghia-la-ban-chat-cua-che-do-ta-vua-la-muc-tieu-vua-la-dong-luc-cua-su-phat-trien-dat-nuoc-1037614184-0033058s34010gs))","w":["","Thu hẹp thành «giai cấp tư sản cầm quyền»; dân chủ gắn với giai cấp cầm quyền nói chung (chủ nô, phong kiến, tư sản, vô sản), không riêng giai cấp tư sản.","Sai ở chỗ cho dân chủ chỉ ra đời từ xã hội chiếm hữu nô lệ; theo giáo trình dân chủ là phạm trù lịch sử, gắn với toàn bộ quá trình phát triển của xã hội (có mầm mống từ dân chủ nguyên thủy).","Thu hẹp thành «giai cấp vô sản cầm quyền»; đó chỉ là dân chủ xã hội chủ nghĩa, một kiểu dân chủ cụ thể, không phải định nghĩa chung về dân chủ."],"s":"Giáo trình Chủ nghĩa xã hội khoa học (Bộ GD&ĐT), chương Dân chủ xã hội chủ nghĩa và Nhà nước xã hội chủ nghĩa; chưa đối chiếu số mục, chỉ thấy nguồn thứ cấp trích lại định nghĩa","c":4,"v":"khớp","k":"Nguồn là bài báo trích lại giáo trình CNXH khoa học, chưa mở được bản giáo trình gốc để đối chiếu nguyên văn.","id":"15oybhd"},{"q":"Toàn bộ những biểu tượng, tình cảm, tâm trạng của quần chúng về tín ngưỡng, tôn giáo tạo thành bộ phận nào sau đây?","o":["Tâm lý tôn giáo","Tổ chức tôn giáo","Hành vi tôn giáo","Hệ tư tưởng tôn giáo."],"a":[0],"e":"Ý thức tôn giáo gồm hai bộ phận là tâm lý tôn giáo và hệ tư tưởng tôn giáo. Tâm lý tôn giáo là toàn bộ những biểu tượng, tình cảm, tâm trạng của quần chúng về tín ngưỡng, tôn giáo; còn hệ tư tưởng tôn giáo là hệ thống giáo lý do các giáo sĩ, nhà thần học tạo ra và truyền bá. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục IV.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Tổ chức tôn giáo (giáo hội, hội đoàn) là thiết chế xã hội, không phải toàn bộ biểu tượng, tình cảm, tâm trạng của quần chúng.","Hành vi tôn giáo là các nghi lễ, hoạt động thực hành, không phải bộ phận ý thức gồm biểu tượng, tình cảm, tâm trạng.","Hệ tư tưởng tôn giáo là hệ thống giáo lý do giáo sĩ, nhà thần học tạo ra, không phải tâm trạng, tình cảm tự phát của quần chúng."],"s":"GT Triết học Mác-Lênin 2021, Ch.3, mục IV.2 (hình thái ý thức tôn giáo); bản tái bản lần 3: Ch.XIII, mục II","c":3,"v":"khớp"},{"q":"Luận điểm cho rằng \"vật hay vật thể là những phức hợp cảm giác\" thuộc trường phái triết học nào?","o":["Chủ nghĩa duy tâm chủ quan.","Chủ nghĩa duy tâm khách quan.","Chủ nghĩa duy vật siêu hình.","Tất cả các đáp án đều đúng."],"a":[0],"e":"Luận điểm «vật thể là những phức hợp cảm giác» là của chủ nghĩa duy tâm chủ quan (Béccli, Makhơ): họ phủ nhận tồn tại khách quan của hiện thực và cho mọi sự vật chỉ là phức hợp những cảm giác của chủ thể. Lênin gọi đó là «một điều vô lý duy tâm rõ rệt». ([Giáo trình Triết học Mác-Lênin 2021, Chương 1 mục I.2 và Chương 2 mục I](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Duy tâm khách quan coi tinh thần khách quan (ý niệm, ý chí thế giới) có trước, không quy sự vật về cảm giác cá nhân.","Duy vật siêu hình thừa nhận vật chất tồn tại khách quan, nên không quy vật thể về phức hợp cảm giác.","Sai vì chỉ có một trường phái (duy tâm chủ quan) mang luận điểm này; các phương án B, C không đúng."],"s":"GT Triết học Mác-Lênin 2021, Ch.1 mục I.2.2 và Ch.2 mục I.1; bản lần 3: Ch.II mục III (Béccli) cho cụm «sự phức hợp của cảm giác»","c":2,"v":"khớp","id":"9mk8iu","f":1},{"q":"Nhận định nào sau đây là sai khi nói về vị trí, vai trò của Triết học Mác - Lênin trong đời sống xã hội và trong sự nghiệp đổi mới ở Việt Nam hiện nay?","o":["Là thế giới quan khoa học cho hoạt động thực tiễn","Là phương pháp luận biện chứng cho nhận thức khoa học","Là chìa khóa vạn năng để giải quyết mọi vấn đề","Là nền tảng tư tưởng, kim chỉ nam cho hành động"],"a":[2],"e":"Giáo trình khẳng định triết học Mác-Lênin là thế giới quan, phương pháp luận khoa học, nền tảng tư tưởng, kim chỉ nam cho hành động, nhưng không phải «đơn thuốc vạn năng» hay chìa khóa vạn năng để giải quyết mọi vấn đề; quan niệm ấy là ảo tưởng, vì không thể thay thế các khoa học cụ thể. ([Giáo trình Triết học Mác-Lênin 2021, Chương 1, mục II.3](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Đúng: triết học Mác-Lênin là thế giới quan khoa học cho hoạt động thực tiễn.","Đúng: nó cung cấp phương pháp luận biện chứng cho nhận thức khoa học.","","Đúng: nó là nền tảng tư tưởng, kim chỉ nam cho hành động."],"s":"GT Triết học Mác-Lênin 2021, Ch.1, mục II.3 (vai trò của triết học Mác-Lênin trong đời sống xã hội và sự nghiệp đổi mới ở Việt Nam)","c":1,"v":"khớp"},{"q":"Trả lời theo quan điểm duy vật lịch sử, ý kiến sau đây đúng hay sai? Vì sao? \"Nhà nước là hiện tượng vĩnh viễn của lịch sử\"","o":["Đúng. Vì bản chất của con người vốn là tham lam, vị kỷ nên xã hội luôn luôn cần đến quyền lực đặc biệt là nhà nước để điều tiết các quan hệ lợi ích","Đúng. Vì đã là một cộng đồng xã hội thì tất yếu phải có sự quản lý và điều tiết chung","Sai. Vì nguồn gốc ra đời của nhà nước là do mâu thuẫn giai cấp không thể điều hòa được mà giai cấp không phải là hiện tượng vĩnh viễn của lịch sử","Sai. Vì thực tế lịch sử thời nguyên thủy không có tổ chức nhà nước trong kiến trúc thượng tầng của xã hội, còn tương lai của xã hội loài người thế nào thì không thể dự báo chính xác được"],"a":[2],"e":"Theo duy vật lịch sử, nhà nước ra đời khi mâu thuẫn giai cấp không thể điều hòa được, là sản phẩm và biểu hiện của mâu thuẫn ấy; giai cấp chỉ gắn với những giai đoạn lịch sử nhất định của sản xuất nên nhà nước cũng không phải hiện tượng vĩnh viễn. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục III.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Kết luận «đúng» sai, và lý do dựa vào bản chất con người tham lam, vị kỷ là quan điểm duy tâm, phi lịch sử, không phải nguồn gốc nhà nước.","Kết luận «đúng» sai: nhu cầu quản lý chung không đồng nghĩa với nhà nước, vì nhà nước là bộ máy quyền lực gắn với xã hội có giai cấp.","","Kết luận «sai» đúng nhưng lý do chưa nêu nguồn gốc (mâu thuẫn giai cấp) và nói không thể dự báo tương lai, trái với quan điểm duy vật lịch sử."],"s":"GT Triết học Mác-Lênin 2021, Ch.3, mục III.1 (dẫn Lênin: nhà nước là sản phẩm của mâu thuẫn giai cấp không thể điều hòa) và mục II.1 (giai cấp gắn với giai đoạn lịch sử nhất định)","c":3,"v":"khớp","k":"Kết luận «nhà nước không vĩnh viễn» suy ra từ luận điểm giai cấp và nhà nước là phạm trù lịch sử; giáo trình không dùng nguyên câu này."},{"q":"Hình thức sản xuất nào sau đây có vai trò quyết định sự tồn tại và phát triển của xã hội?","o":["Sản xuất vật chất","Sản xuất tinh thần","Sản xuất con người","Sản xuất xã hội"],"a":[0],"e":"Sản xuất xã hội gồm sản xuất vật chất, sản xuất tinh thần và sản xuất ra bản thân con người; trong đó sản xuất vật chất là cơ sở của sự tồn tại và phát triển của xã hội, quyết định các mặt khác của đời sống xã hội. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục I.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Sản xuất tinh thần phụ thuộc vào sản xuất vật chất, không giữ vai trò quyết định.","Sản xuất ra bản thân con người là một mặt của sản xuất xã hội, nhưng không quyết định sự tồn tại và phát triển của xã hội.","«Sản xuất xã hội» là khái niệm bao trùm cả ba loại sản xuất, không phải hình thức cụ thể quyết định."],"s":"GT Triết học Mác-Lênin 2021, Ch.3, mục I.1; bản lần 3: Ch.X, mục I.3","c":3,"v":"khớp"},{"q":"Ai là người khẳng định: \"Cần phải có sự phân biệt rõ ràng giữa vật chất với tính cách là một phạm trù của triết học\"?","o":["C.Mác","Ph.Ăngghen","L.Phoiơbắc","Immanuel Kant|"],"a":[1],"e":"Theo Ph. Ăngghen, để có quan niệm đúng đắn về vật chất, cần phân biệt rõ ràng giữa vật chất với tính cách là một phạm trù của triết học, một sáng tạo của tư duy, với bản thân các sự vật, hiện tượng cụ thể của thế giới vật chất. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục I.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Giáo trình gán luận điểm này cho Ph. Ăngghen, không phải C. Mác.","","Phoiơbắc là nhà duy vật nhân bản, không phải tác giả luận điểm phân biệt phạm trù vật chất với các vật thể cụ thể.","Cantơ là nhà triết học cổ điển Đức, không phải tác giả của luận điểm này."],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục I.1 (vật chất và các hình thức tồn tại của vật chất)","c":2,"v":"khớp","k":"Đề chép cụt: câu gốc còn vế sau «với bản thân các sự vật, hiện tượng cụ thể»; phương án D có ký tự thừa «|»."},{"q":"Nhu cầu ăn, mặc, ở, học tập của con người là:","o":["Là cái chung","Là cái tất yếu","Vừa là cái chung vừa là cái tất yếu"],"a":[2],"e":"Giáo trình (bản tái bản lần 3) lấy ví dụ: mọi người sinh ra đều có nhu cầu ăn, mặc, ở, đi lại, học tập; đó là những nhu cầu liên quan đến sự tồn tại của con người nên là cái chung tất yếu. Vì vậy đáp án là vừa là cái chung vừa là cái tất yếu. ([Giáo trình Triết học Mác-Lênin tái bản lần 3, Chương VII, mục IV](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đúng nhưng chưa đủ: nhu cầu này là cái chung của mọi người, song còn là cái tất yếu vì gắn với sự sống còn.","Đúng nhưng chưa đủ: nhu cầu này tất yếu, song còn mang tính phổ biến ở mọi người nên là cái chung.",""],"s":"GT Triết học Mác-Lênin tái bản lần 3, Ch.VII, mục IV (tất nhiên và ngẫu nhiên); ví dụ này không thấy trong bản 2021","c":2,"v":"khớp","k":"Đề chỉ có 3 phương án A, B, C."},{"q":"Triết học Mác - Lênin chỉ ra nguồn gốc của sự hình thành và phân chia giai cấp trong xã hội là do đầu?","o":["Trời định","Tài năng","Kinh tế","Chính quyên"],"a":[2],"e":"Theo triết học Mác-Lênin, sự phân chia giai cấp trước hết do nguyên nhân kinh tế: lực lượng sản xuất phát triển, xuất hiện của cải dư thừa và chế độ tư hữu về tư liệu sản xuất, từ đó phân hóa giàu nghèo và hình thành giai cấp. Chế độ tư hữu là cơ sở trực tiếp của sự hình thành giai cấp. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục II.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Trời định» là quan điểm duy tâm, thần quyền, không có cơ sở khoa học.","Tài năng cá nhân không phải nguyên nhân hình thành giai cấp; giai cấp do vị trí trong hệ thống sản xuất xã hội.","","Chính quyền (nhà nước) ra đời sau, là hệ quả của phân chia giai cấp, không phải nguồn gốc."],"s":"GT Triết học Mác-Lênin 2021, Ch.3, mục II.1; bản lần 3: Ch.XI, mục II","c":3,"v":"khớp","id":"v1xp8o"},{"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử, điều kiện nào sau đây là tiên quyết, cần thiết và chủ yếu quyết định sự hình thành và phát triển của con người cả về phương diện sinh học và xã hội?","o":["Lao động","Ngôn ngũ","Văn hóa","Giao tiếp"],"a":[0],"e":"Ph. Ăngghen chỉ rõ lao động là động lực xã hội đầu tiên thúc đẩy sự hình thành con người: «trước hết là lao động; sau lao động và đồng thời với lao động là ngôn ngữ». Giáo trình cũng khẳng định lao động hình thành bản chất xã hội và nhân cách của con người. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục I.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Ngôn ngữ phát sinh sau và cùng với lao động, là sức kích thích thứ hai, không phải điều kiện tiên quyết.","Văn hóa là sản phẩm của lao động và hoạt động xã hội, không phải điều kiện quyết định ban đầu.","Giao tiếp phát triển trên cơ sở lao động, không phải điều kiện tiên quyết."],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục I.2 (nguồn gốc xã hội của ý thức, trích Ăngghen); bản lần 3: Ch.XIV, mục I","c":2,"v":"khớp","k":"Cụm «tiên quyết, cần thiết và chủ yếu» không thấy nguyên văn trong giáo trình đã đối chiếu; nội dung vẫn khớp đáp án lao động."},{"q":"Trường phái triết học nào sau đây cho rằng tinh thần khách quan có trước, tồn tại độc lập với giới tự nhiên và con người?","o":["Duy vật thô sơ","Duy ý chí","Duy tâm chủ quan","Duy tâm khách quan"],"a":[3],"e":"Chủ nghĩa duy tâm khách quan thừa nhận tính thứ nhất của ý thức nhưng coi đó là thứ tinh thần khách quan có trước và tồn tại độc lập với con người; thực thể này thường gọi là ý niệm, ý niệm tuyệt đối, lý tính thế giới. ([Giáo trình Triết học Mác-Lênin 2021, Chương 1, mục I.2.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Duy vật thô sơ là hình thức đầu tiên của chủ nghĩa duy vật, coi vật chất có trước.","Duy ý chí là khuynh hướng chủ quan trong hành động, không phải trường phái về tinh thần khách quan.","Duy tâm chủ quan coi cảm giác, ý thức của cá nhân là cái có trước, không phải tinh thần khách quan.",""],"s":"GT Triết học Mác-Lênin 2021, Ch.1, mục I.2.2 (chủ nghĩa duy vật và chủ nghĩa duy tâm)","c":1,"v":"khớp"},{"q":"Biện chứng là phương pháp xem xét thế giới trong trang thái nào?","o":["Bất động, bất biến","Luôn vận động, biến đối và phát triển không ngừng","Đứng im","Không ngừng thay đổi"],"a":[1],"e":"Phép biện chứng nhận thức đối tượng ở trạng thái luôn vận động, biến đổi, nằm trong khuynh hướng phổ quát là phát triển, đối lập với phương pháp siêu hình xem xét sự vật trong trạng thái tĩnh, cô lập. ([Giáo trình Triết học Mác-Lênin 2021, Chương 1, mục I.3.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Bất động, bất biến là cách nhìn của phương pháp siêu hình.","","Đứng im cũng là cách nhìn siêu hình.","Gần đúng nhưng thiếu: chỉ nói «thay đổi», chưa nêu vận động và khuynh hướng phát triển; phương án B mới là cách diễn đạt đầy đủ."],"s":"GT Triết học Mác-Lênin 2021, Ch.1, mục I.3.1 (khái niệm biện chứng và siêu hình)","c":2,"v":"khớp"},{"q":"Theo quan điểm duy vật lịch sử, phạm trù nào sau đây ra đời là kết quả của những mâu thuẫn giai cấp không thể điều hòa được?","o":["Tôn giáo","Đảng phái","Nhà nước","Nhóm xã hội"],"a":[2],"e":"Nhà nước ra đời khi mâu thuẫn giai cấp không thể điều hòa được: theo Lênin, nhà nước là sản phẩm và biểu hiện của những mâu thuẫn giai cấp không thể điều hòa được. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục III.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Tôn giáo có nguồn gốc từ nhận thức và tâm lý (sợ hãi, bất lực trước tự nhiên, xã hội), không phải kết quả trực tiếp của mâu thuẫn giai cấp.","Đảng phái là tổ chức chính trị xuất hiện muộn trong xã hội có giai cấp, không phải kết quả trực tiếp của mâu thuẫn giai cấp không thể điều hòa.","","Nhóm xã hội là khái niệm rộng, tồn tại cả trước khi có giai cấp."],"s":"GT Triết học Mác-Lênin 2021, Ch.3, mục III.1; bản lần 3: Ch.XII, mục I","c":3,"v":"khớp"},{"q":"Một sinh viên tâm sự với bạn về hoàn cảnh gia đình mình trong 10 năm đổi mới như sau: gia đình trước đây rất khó khăn. Khi bố từ quân đội về hưu có ít tiền, gia đình đầu tư mua máy và thiết bị sản xuất đậu phụ và làm tương bán. May quá, mặt hàng làm ra có thị trường tiêu thụ ngày càng đông. Gia đình còn tận dụng các sản phẩm phụ để nuôi heo. Thế là thu nhập của gia đình tăng dần. đến nay bố tôi đã trở thành một chủ xưởng sản xuất có 20 lao động thuê ngoài. mẹ mình làm trợ lý, mình làm kế toán giúp mẹ. Mặc dù cuộc sống có những lúc khó khăn nhưng gia đình mình đã nỗ lực vượt qua để có cuộc sống sung túc. Nhà mình bây giờ khang trang, đủ tiện nghi sinh hoạt. Phân tích sự việc trên theo bình diện triết học thì vận dụng theo nguyên lý, quy luật nào là phù hợp?","o":["Quy luật phủ định của phủ định","Nguyên lý về mối liên hệ phổ biến","Quy luật mâu thuẫn","Quy luật lượng - chất"],"a":[3],"e":"Gia đình tích lũy dần vốn, máy móc, lao động (lượng) đến mức trở thành chủ xưởng thuê 20 lao động và sống sung túc (chất mới). Đây là sự thay đổi về lượng dẫn đến thay đổi về chất qua điểm nút và bước nhảy, nên vận dụng quy luật lượng - chất. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quy luật phủ định của phủ định nói về chu kỳ phủ định, kế thừa; tình huống không có vòng phủ định nổi bật.","Nguyên lý về mối liên hệ phổ biến nói chung, không nêu được cơ chế chuyển hóa từ tích lũy sang chất mới.","Quy luật mâu thuẫn nhấn mạnh sự đấu tranh của các mặt đối lập, không phải trọng tâm của tình huống.",""],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục II (quy luật lượng - chất); bản lần 3: Ch.VIII, mục II","c":2,"v":"khớp","id":"5u8zfi"},{"q":"Chủ nghĩa duy tâm khách quan có tư tưởng như thế nào?","o":["Cho rằng đầu óc con người quyết định tất cả hoạt động của con người","Cho rằng con người có thể biết được thế giới khi ở trong bốn bức tường trắng","Cho rằng ý thức con người chi phối hoạt động của bản thân họ","Cho rằng tinh thần khách quan chi phối hoạt động của con người"],"a":[3],"e":"Duy tâm khách quan cho rằng có tinh thần khách quan (ý niệm, lý tính thế giới) tồn tại trước và độc lập với con người, rồi chi phối hoạt động của con người và thế giới. ([Giáo trình Triết học Mác-Lênin 2021, Chương 1, mục I.2.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Đầu óc, ý thức con người quyết định hoạt động của họ là tư tưởng duy tâm chủ quan.","Biết thế giới chỉ trong «bốn bức tường» là cách nói duy tâm chủ quan, quy nhận thức về cảm giác cá nhân.","Ý thức con người chi phối bản thân họ là duy tâm chủ quan, không phải tinh thần khách quan.",""],"s":"GT Triết học Mác-Lênin 2021, Ch.1, mục I.2.2","c":1,"v":"khớp"},{"q":"Theo quan điểm của triết học Mác - Lênin, cấu trúc của một hình thái kinh tế - xã hội gồm các yếu tố cơ bản hợp thành nào?","o":["Lĩnh vực vật chất và lĩnh vực tinh thần","Cơ sở hạ tầng, kiến trúc thượng tầng, tồn tại xã hội và ý thức xã hội","Lực lượng sản xuất, quan hệ sản xuất và kiến trúc thượng tầng","Quan hệ sản xuất, cơ sở hạ tầng, cơ cấu kinh tế và kiến trúc thượng tầng"],"a":[2],"e":"Cấu trúc của hình thái kinh tế - xã hội gồm ba yếu tố cơ bản: lực lượng sản xuất, quan hệ sản xuất (cơ sở hạ tầng) và kiến trúc thượng tầng, tác động biện chứng tạo nên sự vận động, phát triển của xã hội. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục I.4](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Lĩnh vực vật chất và tinh thần là cách chia đời sống xã hội, không phải cấu trúc của hình thái kinh tế - xã hội.","Lẫn khái niệm: tồn tại xã hội và ý thức xã hội là cặp phạm trù khác; cơ sở hạ tầng gồm cả quan hệ sản xuất.","","Lẫn lộn: quan hệ sản xuất chính là cơ sở hạ tầng; thiếu lực lượng sản xuất, một yếu tố cơ bản."],"s":"GT Triết học Mác-Lênin 2021, Ch.3, mục I.4; bản lần 3: Ch.X","c":3,"v":"khớp","id":"nkczka"},{"q":"Theo chủ nghĩa duy vật biện chứng, giữa LLSX và QHSX có mối quan hệ như thế nào với nhau?","o":["Biện chứng","Một chiều","Độc lập","Tách rời"],"a":[0],"e":"Lực lượng sản xuất và quan hệ sản xuất là hai mặt của phương thức sản xuất, tồn tại không tách rời nhau và tác động qua lại một cách biện chứng: lực lượng sản xuất quyết định quan hệ sản xuất, quan hệ sản xuất tác động trở lại lực lượng sản xuất. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục I.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Quan hệ không phải một chiều: quan hệ sản xuất tác động mạnh mẽ trở lại lực lượng sản xuất.","Hai mặt gắn bó trong một phương thức sản xuất, không độc lập với nhau.","Chúng tồn tại không tách rời nhau, nên «tách rời» trái với giáo trình."],"s":"GT Triết học Mác-Lênin 2021, Ch.3, mục I.2; bản lần 3: Ch.X, mục II","c":3,"v":"khớp"},{"q":"..là phương thức tồn tại và phát triển của sự vật, là hệ thống các mối liên hệ tương đối bên vững giữa các yếu tố của sự vật đó:","o":["Kết quả","Nguyên nhân","Nội dung","Hình thức"],"a":[3],"e":"Hình thức là phạm trù chỉ phương thức tồn tại, biểu hiện và phát triển của sự vật, là hệ thống các mối liên hệ tương đối bền vững giữa các yếu tố cấu thành nội dung của sự vật. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Kết quả là phạm trù trong cặp nguyên nhân - kết quả, chỉ sự biến đổi do nguyên nhân gây ra.","Nguyên nhân là yếu tố tác động gây ra biến đổi nhất định, thuộc cặp nguyên nhân - kết quả.","Nội dung là tổng thể tất cả các mặt, yếu tố tạo nên sự vật, đối lập với hình thức.",""],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục II (cặp nội dung - hình thức); bản lần 3: Ch.VII, mục V","c":2,"v":"khớp"},{"q":"Theo quan điểm của chủ nghĩa duy vật lịch sử, thì suy đến cùng, trình độ phát triển của nền sản xuất ra của cải vật chất của xã hội được quyết định bởi trình độ:","o":["Phát triển của phương thức sử dụng lao động","Phát triển của các nguồn lực sử dụng trong quá trình sản xuất","Phát triển của lực lượng sản xuất","Phát triển của quan hệ sản xuất"],"a":[2],"e":"Sự phát triển của sản xuất vật chất xét đến cùng bắt nguồn từ sự biến đổi và phát triển của lực lượng sản xuất, trước hết là công cụ lao động; trình độ lực lượng sản xuất thể hiện trình độ chinh phục tự nhiên của con người. ([Giáo trình Triết học Mác-Lênin tái bản lần 3, Chương X, mục II](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["«Phương thức sử dụng lao động» không phải khái niệm của giáo trình.","«Các nguồn lực» là cách nói chung chung; giáo trình nêu cụ thể trình độ lực lượng sản xuất.","","Quan hệ sản xuất do lực lượng sản xuất quyết định, nên không phải yếu tố quyết định cuối cùng."],"s":"GT Triết học Mác-Lênin tái bản lần 3, Ch.X, mục II; bản 2021: Ch.3, mục I.2","c":3,"v":"khớp"},{"q":"Trong hoạt động thực tiễn, cần khắc phục sự trì trệ, bảo thủ trong việc thực hiện bước nhảy là ý nghĩa phương pháp luận rút ra từ việc nghiên cứu quy luật nào?","o":["Quy luật mâu thuẫn","Quy luật lượng chất","Quy luật tự nhiên","Quy luật xã hội"],"a":[1],"e":"Từ quy luật lượng - chất rút ra: phải biết tích lũy về lượng để có biến đổi về chất, không nôn nóng; và khi lượng đã đến điểm nút thì phải thực hiện bước nhảy, không bảo thủ, trì trệ. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quy luật mâu thuẫn dẫn đến yêu cầu phát hiện, giải quyết mâu thuẫn, không nói về bước nhảy.","","«Quy luật tự nhiên» không phải tên một quy luật cơ bản của phép biện chứng.","«Quy luật xã hội» không phải quy luật cơ bản của phép biện chứng, không nói về điểm nút và bước nhảy."],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục II (ý nghĩa phương pháp luận của quy luật lượng - chất); bản lần 3: Ch.VIII, mục II","c":2,"v":"khớp"},{"q":"Câu tục ngũ \"Tốt gỗ hơn tốt nước sơn\" thể hiện cặp phạm trù nào sau đây của Triết học Mác-Lênin?","o":["Cái chung, cái riêng","Tất nhiên, ngẫu nhiên","Nội dung, hình thức","Nguyên nhân, kết quả"],"a":[2],"e":"Trong cặp nội dung - hình thức, nội dung giữ vai trò quyết định hình thức. Câu «Tốt gỗ hơn tốt nước sơn» đề cao chất lượng thực chất (gỗ, nội dung) hơn vẻ ngoài (nước sơn, hình thức). ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Không nói về cái chung - cái riêng (quan hệ giữa cái phổ biến và cái đơn lẻ).","Không nói về tất nhiên - ngẫu nhiên.","","Không nói về quan hệ nguyên nhân - kết quả."],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục II (cặp nội dung - hình thức); bản lần 3: Ch.VII, mục V","c":2,"v":"khớp","k":"Câu tục ngữ không có trong giáo trình; đáp án suy ra từ nguyên tắc nội dung quyết định hình thức."},{"q":"Chủ nghĩa duy vật lịch sử cho rằng, trên cơ sở yếu tố nào làm phát sinh những mối quan hệ xã hội khác: chính trị, pháp luật, đạo đức, nghệ thuật, tôn giáo?","o":["Cơ sở vật chất","Lực lượng sản xuất","Quan hệ sản xuất","Quan hệ xã hội"],"a":[3],"e":"Giáo trình nêu sản xuất vật chất là cơ sở hình thành quan hệ kinh tế - vật chất (quan hệ sản xuất) giữa người với người, từ đó hình thành các quan hệ xã hội khác như chính trị, pháp luật, đạo đức, tôn giáo; quan hệ sản xuất là quan hệ cơ bản, quyết định mọi quan hệ xã hội khác. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục I.1 và I.3](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Cơ sở vật chất» không phải thuật ngữ giáo trình dùng để chỉ nền tảng làm phát sinh các quan hệ xã hội khác.","Lực lượng sản xuất là quan hệ người với tự nhiên, không phải trực tiếp nền tảng của các quan hệ xã hội khác.","Quan hệ sản xuất mới đúng với giáo trình (quan hệ cơ bản, quyết định các quan hệ xã hội khác), nhưng đề không chọn phương án này.",""],"s":"GT Triết học Mác-Lênin 2021, Ch.3, mục I.1 (sản xuất vật chất là cơ sở hình thành các quan hệ xã hội khác) và mục I.3 (quan hệ sản xuất quyết định mọi quan hệ xã hội khác)","c":3,"v":"nghi vấn","k":"nghi vấn: Đáp án D «Quan hệ xã hội» mang tính lặp ý (các quan hệ xã hội khác phát sinh trên cơ sở «quan hệ xã hội»); theo giáo trình, nền tảng là quan hệ sản xuất (C) hoặc sản xuất vật chất. Nên kiểm tra lại đề gốc.","id":"9zhr7s"},{"q":"Ý nghĩa phương pháp luận rút ra từ việc nghiên cứu cặp phạm trù khả năng - hiện thực là trong thực tế, chúng ta phải dựa vào điều gì sau đây?","o":["Hiện thực và bỏ qua các khả năng","Mối quan hệ giữa khả năng và hiện thực","Hiện thực vì khả năng là cái chưa tồn tại","Khả năng vì khả năng có thể chữa hiện thực"],"a":[1],"e":"Giáo trình nêu: khả năng và hiện thực tồn tại trong mối liên hệ không tách rời, luôn chuyển hóa cho nhau; vì vậy trong hoạt động thực tiễn cần dựa vào hiện thực, đồng thời tính đến mọi khả năng và xem xét mối quan hệ giữa chúng. Đề chọn B. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Dựa vào hiện thực nhưng bỏ qua khả năng là sai: khi đề kế hoạch phải tính đến các khả năng.","","Phần «dựa vào hiện thực» có trong giáo trình, nhưng lý do «khả năng là cái chưa tồn tại» và bỏ khả năng thì thiếu; khả năng là cái hiện chưa có nhưng sẽ có khi đủ điều kiện.","Chỉ dựa vào khả năng dễ rơi vào ảo tưởng, vì khả năng chưa phải hiện thực."],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục II (cặp khả năng - hiện thực, ý nghĩa phương pháp luận); bản lần 3: Ch.VII, mục VII","c":2,"v":"dễ nhầm","k":"Phương án C cũng có phần đúng (giáo trình nhấn mạnh dựa vào hiện thực); đề chọn B vì nói đủ mối quan hệ khả năng - hiện thực. Trùng chủ đề với Câu 102 và 209.","id":"wm00sy"},{"q":"Ai là người đã phủ nhận tính hiện thực khách quan của điện tử?","o":["E.Makhơ","Piêcson","Anhxtanh","Béccơren"],"a":[0],"e":"Giáo trình nêu: E. Makhơ phủ nhận tính hiện thực khách quan của điện tử; Ốtvan phủ nhận sự tồn tại thực tế của nguyên tử và phân tử; Piếcsơn có định nghĩa riêng về vật chất. Đây là biểu hiện của chủ nghĩa duy tâm lợi dụng cuộc khủng hoảng vật lý. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục I.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Piếcsơn có quan niệm riêng về vật chất, nhưng giáo trình gán việc phủ nhận tính hiện thực của điện tử cho Makhơ.","Anhxtanh là nhà vật lý, không phải người bị Lênin nêu là phủ nhận hiện thực của điện tử.","Béccơren là nhà vật lý phát hiện hiện tượng phóng xạ, không phủ nhận điện tử."],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục I.1; bản lần 3: Ch.III mục II và Ch.V mục I (cuộc khủng hoảng vật lý, chủ nghĩa Makhơ)","c":2,"v":"khớp","id":"10952zj"},{"q":"Sự khác nhau căn bản của chủ nghĩa vật với chủ nghĩa duy tâm về sự thống nhất của thế giới là gì?","o":["Không thừa nhận tính tồn tại của thế giới","Thừa nhận tính tồn tại của thế giới","Tất cả đều sai","Thừa nhận vật chất và ý thức là bản nguyên của thế giới"],"a":[2],"e":"Chủ nghĩa duy vật khẳng định thế giới thống nhất ở tính vật chất; chủ nghĩa duy tâm cho thế giới thống nhất ở ý thức, tinh thần. Cả hai đều thừa nhận thế giới tồn tại ở một nghĩa nào đó, nên A, B, D đều không nêu đúng điểm khác biệt căn bản; đề chọn «tất cả đều sai». ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục I.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Không đúng: duy vật và duy tâm không khác nhau ở chỗ có hay không thừa nhận tồn tại của thế giới, và giáo trình lấy việc thừa nhận tồn tại làm tiền đề cho thống nhất.","Thừa nhận tồn tại của thế giới là điểm chung, chưa phải điểm khác nhau căn bản.","","Coi vật chất và ý thức cùng là bản nguyên là quan điểm nhị nguyên, không phải của chủ nghĩa duy vật."],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục I.1 (tính thống nhất vật chất của thế giới); bản lần 3: Ch.V, mục I","c":2,"v":"dễ nhầm","k":"Đề kiểu loại trừ, câu hỏi có lỗi diễn đạt («chủ nghĩa vật»); đáp án C chỉ đúng vì không có phương án nêu «thống nhất ở tính vật chất» và «thống nhất ở ý thức».","id":"1e6tdrk","f":1},{"q":"Khi V.I. Lênin phát triển chủ nghĩa Mác trong giai đoạn để quốc chủ nghĩa, ông đã bổ sung lý luận nào cho phù hợp với bối cảnh xã hội mới? Chọn 2 đáp án.","o":["Khả năng của cách mạng vô sản chỉ có thể xảy ra đồng thời trên toàn cầu","Khả năng cách mạng vô sản có thể xảy ra ở một hoặc một số nước có điều kiện thích hợp","Chủ nghĩa đế quốc là giai đoạn phát triển cao nhất và là giai đoạn suy tàn của chủ nghĩa tư bản","Chủ nghĩa đế quốc phát triển sẽ làm giảm căng thẳng giữa các quốc gia tư bản, từ đó ổn định xã hội"],"a":[1,2],"e":"Lênin phát triển chủ nghĩa Mác ở giai đoạn đế quốc: nêu khả năng thắng lợi của cách mạng vô sản ở một số ít nước, thậm chí ở một nước riêng lẻ (B); phân tích chủ nghĩa đế quốc là giai đoạn tột cùng của chủ nghĩa tư bản, đêm trước của cách mạng xã hội chủ nghĩa (C). ([Giáo trình Triết học Mác-Lênin 2021, Chương 1, mục II.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Trái với Lênin: ông cho cách mạng có thể thắng ở một hoặc một số nước từ quy luật phát triển không đều của chủ nghĩa tư bản, không đòi hỏi xảy ra đồng thời toàn cầu.","","","Sai: chủ nghĩa đế quốc làm sâu sắc mâu thuẫn và đối kháng, nên là đêm trước của cách mạng xã hội chủ nghĩa."],"s":"GT Triết học Mác-Lênin 2021, Ch.1, mục II.1 (sự ra đời và phát triển của triết học Mác-Lênin); bản lần 3: Ch.III, mục II","c":4,"v":"dễ nhầm","k":"Phương án C dùng cụm «giai đoạn suy tàn», còn giáo trình dùng «giai đoạn tột cùng», «đêm trước của cách mạng xã hội chủ nghĩa»; ý nghĩa gần nhau, đề chọn B và C.","id":"jhi6mh"},{"q":"Loại hình hoạt động thực tiền nhằm mục đích cải biến các đối tượng của giới tự nhiên theo nhu cầu tồn tại và phát triển của con người và xã hội là gì?","o":["Khoa học","Sản xuất vật chất","Thực nghiệm khoa học","Nghiên cứu khoa học"],"a":[1],"e":"Giáo trình nêu các hình thức cơ bản của hoạt động thực tiễn: hoạt động sản xuất vật chất, hoạt động chính trị - xã hội và hoạt động thực nghiệm khoa học; trong đó sản xuất vật chất là hình thức có sớm nhất, cơ bản nhất, cải biến giới tự nhiên theo nhu cầu của con người và xã hội. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục III](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Khoa học là hệ thống tri thức, chưa phải hình thức hoạt động thực tiễn cải biến tự nhiên.","","Thực nghiệm khoa học là hình thức đặc biệt của thực tiễn, con người chủ động tạo điều kiện nhân tạo để nghiên cứu, không phải hoạt động cải biến tự nhiên theo nhu cầu tồn tại.","Nghiên cứu khoa học là hoạt động nhận thức, không phải hoạt động thực tiễn cải biến tự nhiên chủ yếu."],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục III (thực tiễn và các hình thức cơ bản của thực tiễn); bản lần 3: Ch.IX, mục I","c":2,"v":"khớp","id":"n5ck21"},{"q":"Khái niệm quan hệ sản xuất được hiểu như thế nào?","o":["Mối quan hệ giữa con người với giới tự nhiên","Tổng hợp các quan hệ kinh tế giữa con người với con người trong quá trình sản xuất vật chất","Mối quan hệ giữa con người với con người trong quá trình lao động","Mối quan hệ kinh tế trong quá trình sản xuất và tái sản xuất của xã hội"],"a":[1],"e":"Theo giáo trình 2021, quan hệ sản xuất là tổng hợp các quan hệ kinh tế - vật chất giữa người với người trong quá trình sản xuất vật chất. Bản tái bản lần 3 diễn đạt là quan hệ giữa người với người trong quá trình sản xuất (sản xuất và tái sản xuất xã hội), gồm quan hệ sở hữu, tổ chức - quản lý, phân phối. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục I.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quan hệ người với giới tự nhiên thuộc lực lượng sản xuất, không phải quan hệ sản xuất.","","Thiếu tính chất kinh tế - vật chất và tính tổng hợp; không phải mọi quan hệ trong lao động đều là quan hệ sản xuất.","Gần với bản lần 3 nhưng bỏ chủ thể «giữa người với người» và chỉ nói «quan hệ kinh tế», nên diễn đạt chưa chuẩn; B khớp bản 2021."],"s":"GT Triết học Mác-Lênin 2021, Ch.3, mục I.2; bản lần 3: Ch.X, mục II","c":3,"v":"dễ nhầm","k":"B khớp bản 2021; D gần với cách diễn đạt bản cũ (sản xuất và tái sản xuất xã hội) nên dễ gây nhầm."},{"q":"Điền vào dấu \"... tồn tại khách quan, độc lập với ý thức của con người\":","o":["Tất nhiên và ngẫu nhiên","Chỉ có tất nhiên","Chỉ có ngẫu nhiên","Tất nhiên và ngẫu nhiên đều không"],"a":[0],"e":"Giáo trình khẳng định tất nhiên và ngẫu nhiên đều tồn tại khách quan, độc lập với ý thức con người, thống nhất hữu cơ với nhau: tất nhiên vạch đường đi cho mình thông qua vô số ngẫu nhiên. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Phủ nhận ngẫu nhiên là sai: ngẫu nhiên cũng tồn tại khách quan và có vai trò nhất định.","Phủ nhận tất nhiên là sai: tất nhiên đóng vai trò chi phối sự phát triển.","Sai, vì cả hai đều tồn tại khách quan."],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục II (cặp tất nhiên - ngẫu nhiên); bản lần 3: Ch.VII, mục IV","c":2,"v":"khớp"},{"q":"Theo định nghĩa chung nhất, tồn tại là phạm trù dùng để chỉ tính ... của thế giới xung quanh.... Từ thích hợp trong dấu \"...\" là gì?","o":["Có thực/ Con người","Có thực chính xác/con người","Tâm linh/ Trái đất","Chính xác/ Nhận thức"],"a":[0],"e":"Theo nghĩa chung nhất, tồn tại là phạm trù dùng để chỉ tính có thực của thế giới xung quanh con người. Vậy chỗ trống là «có thực» và «con người». ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục I.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Cụm «có thực chính xác» không có trong giáo trình.","Tâm linh mang màu sắc duy tâm, tôn giáo; và «trái đất» không phải cụm giáo trình dùng.","«Chính xác» và «nhận thức» không đúng thuật ngữ: tồn tại chỉ tính có thực, không phụ thuộc vào nhận thức."],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục I.1; bản lần 3: Ch.V, mục I","c":2,"v":"khớp"},{"q":"Theo chủ nghĩa duy vật biện chứng, lao động và ngôn ngữ là sự kích thích chủ yếu dẫn đến các chuyển biến nào trong các chuyển biến sau đây?","o":["Sự chuyển biến dần bộ óc của loài vượn người thành bộ óc con người","Sự chuyển biến dần tâm lý động vật thành ý thức con người","Sự chuyển biến hay mã hóa các đối tượng tinh thần phi vật chất thành các ý tưởng vật chất","Sự chuyển biến mô hình từ tư duy đến hình ảnh tinh thần"],"a":[1],"e":"Ph. Ăngghen chỉ rõ lao động và ngôn ngữ là hai sức kích thích chủ yếu làm bộ óc vượn dần biến chuyển thành bộ óc người; giáo trình tóm lại: làm chuyển biến dần bộ óc của loài vượn người thành bộ óc con người và tâm lý động vật thành ý thức con người. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục I.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Cũng đúng theo giáo trình (bộ óc vượn thành bộ óc người), nhưng đề chọn B, vế còn lại của câu đã nêu.","","Không có cơ sở: ý thức không phải sự mã hóa đối tượng phi vật chất thành ý tưởng vật chất.","«Mô hình từ tư duy đến hình ảnh tinh thần» không phải nội dung của luận điểm Ăngghen."],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục I.2 (nguồn gốc xã hội của ý thức); bản lần 3: Ch.V, mục II","c":2,"v":"dễ nhầm","k":"Đề chọn B, nhưng giáo trình nêu cả A và B như hai vế của cùng một câu; A cũng đúng, nên đề có thể gây tranh cãi."},{"q":"V.I.Lênin đã định nghĩa phạm trù vật chất với tư cách là một phạm trù triết học bằng cách đem đối lập với phạm trù nào sau đây?","o":["Phạm trù ý thức","Phạm trù thực tiễn","Phạm trù nhận thức","Phạm trù quy luật"],"a":[0],"e":"Lênin định nghĩa vật chất là một phạm trù triết học bằng cách đem đối lập với ý thức (giải quyết mặt thứ nhất vấn đề cơ bản): vật chất là thực tại khách quan, được cảm giác chép lại, chụp lại, phản ánh và tồn tại không lệ thuộc vào cảm giác. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục I.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Thực tiễn không phải phạm trù dùng để đối lập khi định nghĩa vật chất.","Nhận thức là quá trình phản ánh, không phải phạm trù đối lập trực tiếp với vật chất ở cấp độ vấn đề cơ bản.","Quy luật là mối liên hệ bản chất, không phải phạm trù đối lập với vật chất."],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục I.1 (định nghĩa vật chất của Lênin); cụm «đối lập với ý thức» là ý trong tác phẩm của Lênin, chưa đối chiếu nguyên văn trong bản này","c":2,"v":"khớp"},{"q":"Quy luật nào là quy luật cơ bản nhất, chi phối, quyết định toàn bộ quá trình vận động và phát triển của lịch sử xã hội loài người?","o":["Đấu tranh giai cấp","Phát triển khoa học và công nghệ","Phát triển kinh tế thị trường","Quan hệ sản xuất phụ thuộc vào trình độ phát triển của lực lượng sản xuất"],"a":[3],"e":"Quy luật quan hệ sản xuất phù hợp với trình độ phát triển của lực lượng sản xuất được giáo trình gọi là quy luật cơ bản nhất của sự vận động, phát triển xã hội. ([Giáo trình Triết học Mác-Lênin tái bản lần 3, Chương X, mục II](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Đấu tranh giai cấp là động lực quan trọng trong xã hội có giai cấp, không phải quy luật cơ bản nhất của toàn bộ lịch sử.","Khoa học - công nghệ là yếu tố của lực lượng sản xuất, không phải quy luật.","Kinh tế thị trường là cơ chế vận hành kinh tế, không phải quy luật chi phối toàn bộ lịch sử.",""],"s":"GT Triết học Mác-Lênin tái bản lần 3, Ch.X, mục II; bản 2021: Ch.3, mục I.2","c":3,"v":"khớp","id":"1teqwyu"},{"q":"Khẳng định nào sau đây là đúng theo quan điểm của triết học Mác?","o":["Vận động là một thuộc tính bắt buộc để chúng ta phát triển","Vận động là một thuộc tính cố hữu và là phương thức tồn tại của vật chất","Vận động là một thuộc tính tồn tại của vật chất trong thế giới con người","Vận động là vận động tự thân nhưng cần sự giúp đỡ của con người"],"a":[1],"e":"Vận động là thuộc tính cố hữu và là phương thức tồn tại của vật chất (Ăngghen); không có vật chất không vận động, nên vận động tồn tại vĩnh viễn gắn với vật chất. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục I.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Vận động không phải thuộc tính «bắt buộc để chúng ta phát triển»; nó là thuộc tính vốn có của vật chất.","","Sai vì vận động là thuộc tính của vật chất nói chung, không chỉ trong thế giới con người.","Vận động là tự thân, không cần sự giúp đỡ của con người."],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục I.1 (vận động - phương thức tồn tại của vật chất); bản lần 3: Ch.V, mục I","c":2,"v":"khớp"},{"q":"Nền tảng quan hệ giữa cá nhân và xã hội là gì?","o":["Lợi ích","Pháp luật","Đạo đức","Tình cảm"],"a":[0],"e":"Giáo trình nêu quan hệ cá nhân - xã hội có thống nhất và mâu thuẫn; thực chất việc tổ chức xã hội là giải quyết quan hệ lợi ích nhằm tạo khả năng cao nhất cho mỗi cá nhân phát triển. Vì vậy lợi ích là nền tảng của quan hệ giữa cá nhân và xã hội. ([Giáo trình Triết học Mác-Lênin tái bản lần 3, Chương XIV, mục II](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Pháp luật là công cụ điều chỉnh quan hệ, không phải nền tảng.","Đạo đức là chuẩn mực điều chỉnh hành vi, hình thành trên cơ sở lợi ích.","Tình cảm là yếu tố tâm lý, không phải nền tảng của quan hệ cá nhân - xã hội."],"s":"GT Triết học Mác-Lênin tái bản lần 3, Ch.XIV, mục II (quan hệ giữa cá nhân và xã hội); bản 2021: Ch.3, mục V.3 chưa tìm thấy cụm «nền tảng»","c":3,"v":"khớp","k":"Giáo trình không dùng nguyên cụm «nền tảng quan hệ cá nhân - xã hội là lợi ích»; đáp án suy ra từ việc tổ chức xã hội là giải quyết quan hệ lợi ích."},{"q":"Đâu là yếu tố vật chất \"trung gian\", \"truyền dẫn\" giữa người lao động và đối tượng lao động trong tiến hành sản xuất?","o":["Công cụ lao động","Cơ sở hạ tầng","Phương tiện sản xuất","Kỹ năng lao động"],"a":[0],"e":"Công cụ lao động là yếu tố vật chất «trung gian», «truyền dẫn» giữa người lao động và đối tượng lao động trong tiến hành sản xuất; là «khí quan» của bộ óc, và giữ vai trò quyết định năng suất lao động, chất lượng sản phẩm. ([Giáo trình Triết học Mác-Lênin 2021, Chương 3, mục I.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Cơ sở hạ tầng là tổng hợp quan hệ sản xuất hợp thành cơ cấu kinh tế, không phải yếu tố vật chất nối người lao động với đối tượng lao động.","Phương tiện lao động cùng công cụ lao động thuộc tư liệu lao động; cụm «trung gian, truyền dẫn» giáo trình gán cho công cụ lao động.","Kỹ năng lao động là yếu tố thuộc người lao động, không phải yếu tố vật chất trung gian."],"s":"GT Triết học Mác-Lênin 2021, Ch.3, mục I.2 (lực lượng sản xuất: tư liệu lao động, công cụ lao động)","c":3,"v":"khớp"},{"q":"Hệ thống các quan điểm duy vật biện chứng về xã hội, làm rõ nguồn gốc, động lực và những quy luật chung của sự vận động, phát triển của xã hội loài người là gì?","o":["Chủ nghĩa duy vật lịch sử","Lịch sử xã hội","Quan điểm lịch sử hiện đại","Biện chứng của lịch sử"],"a":[0],"e":"Chủ nghĩa duy vật lịch sử là nội dung chủ yếu của bước ngoặt cách mạng trong triết học do Mác và Ăngghen thực hiện, là hệ thống quan điểm duy vật biện chứng về xã hội, làm rõ nguồn gốc, động lực và quy luật chung của sự vận động, phát triển xã hội loài người. ([Giáo trình Triết học Mác-Lênin 2021, Chương 1, mục II.1](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","«Lịch sử xã hội» là đối tượng nghiên cứu, không phải tên hệ thống quan điểm duy vật biện chứng về xã hội.","«Quan điểm lịch sử hiện đại» không phải thuật ngữ của triết học Mác-Lênin.","«Biện chứng của lịch sử» không phải tên gọi chuẩn của học thuyết này."],"s":"GT Triết học Mác-Lênin 2021, Ch.1, mục II.1 (chủ nghĩa duy vật lịch sử là nội dung chủ yếu của bước ngoặt cách mạng) và Ch.3","c":3,"v":"khớp","k":"Cụm định nghĩa dài trong câu hỏi chưa thấy nguyên văn trong giáo trình 2021 đã đối chiếu; nội dung khớp đáp án."},{"q":"Đâu là một trong những trường phái triết học ở Trung Quốc thời cổ đại?","o":["Thuyết Ngũ hành","Thuyết Nguyên tử","Phái Vedanta","Phái Lokayata"],"a":[0],"e":"Triết học Trung Quốc cổ đại có nhiều trường phái và học thuyết: Nho gia, Mặc gia, Đạo gia, Âm Dương gia (gắn với thuyết Âm Dương, Ngũ hành), Pháp gia, Danh gia... Trong các phương án chỉ Thuyết Ngũ hành thuộc Trung Quốc; thuyết nguyên tử là của Hy Lạp, còn Vedanta và Lokayata là của Ấn Độ. ([Giáo trình Triết học Mác-Lênin tái bản lần 3, Chương II, mục II](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["","Thuyết nguyên tử là học thuyết của Đêmôcrít (Hy Lạp cổ đại).","Vedanta là một phái triết học của Ấn Độ.","Lokayata là trường phái duy vật của Ấn Độ cổ đại."],"s":"GT Triết học Mác-Lênin tái bản lần 3, Ch.II, mục II (Trung Hoa cổ đại, Âm Dương - Ngũ hành) và mục I (Hy Lạp, thuyết nguyên tử); phần Ấn Độ chưa đối chiếu nguyên văn","c":1,"v":"dễ nhầm","k":"Ngũ hành thường gọi là học thuyết, giáo trình xếp cùng thuyết Âm Dương (Âm Dương gia); cách chép «trường phái» của đề hơi rộng."},{"q":"Sự thay đổi về lượng đạt đến giới hạn nào thì sẽ dẫn đến sự thay đổi về chất?","o":["Điểm nút","Khoảng độ","Bước nhảy","Mâu thuẫn"],"a":[0],"e":"Điểm nút là phạm trù triết học chỉ điểm giới hạn mà tại đó sự thay đổi về lượng đã đủ làm thay đổi về chất của sự vật; độ được giới hạn bởi hai điểm nút, và khi lượng đạt tới điểm nút thì chất mới ra đời qua bước nhảy. ([Giáo trình Triết học Mác-Lênin 2021, Chương 2, mục II](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Khoảng độ (độ) là giới hạn trong đó lượng đổi mà chất chưa đổi căn bản.","Bước nhảy là sự chuyển hóa về chất xảy ra sau khi lượng đạt điểm nút, không phải giới hạn của lượng.","Mâu thuẫn là phạm trù của quy luật thống nhất và đấu tranh của các mặt đối lập, không phải giới hạn của lượng."],"s":"GT Triết học Mác-Lênin 2021, Ch.2, mục II (quy luật lượng - chất); bản lần 3: Ch.VIII, mục II","c":2,"v":"khớp","id":"11prcoj"},{"q":"Về hình thức cơ bản, loại chủ nghĩa nào khẳng định mọi sự vật, hiện tượng chỉ là phức hợp những cảm giác của cá nhân, của chủ thể?","o":["Duy vật siêu hình","Duy tâm khách quan","Duy tâm chủ quan","Duy vật máy móc"],"a":[2],"e":"Chủ nghĩa duy tâm chủ quan phủ nhận sự tồn tại khách quan của hiện thực và khẳng định mọi sự vật, hiện tượng chỉ là phức hợp những cảm giác của cá nhân, của chủ thể. ([Giáo trình Triết học Mác-Lênin 2021, Chương 1, mục I.2.2](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Duy vật siêu hình thừa nhận vật chất tồn tại khách quan (nhìn máy móc, tĩnh tại), không quy sự vật về cảm giác.","Duy tâm khách quan cho tinh thần khách quan có trước, không phải cảm giác của cá nhân.","","Duy vật máy móc là một dạng duy vật siêu hình, thừa nhận vật chất tồn tại khách quan."],"s":"GT Triết học Mác-Lênin 2021, Ch.1, mục I.2.2; bản lần 3: Ch.I, mục II","c":1,"v":"khớp"},{"q":"\"Muốn xây dựng chủ nghĩa xã hội phải có những con người xã hội chủ nghĩa\", theo Hồ Chí Minh con người xã hội chủ nghĩa là vừa:","o":["Vừa tài vừa trí.","Vừa hồng và vừa chuyên.","Vừa nhân, lễ nghĩa, trí, tín.","Cần, kiệm, liêm, chính, chí công vô tư."],"a":[1],"e":"Giáo trình nêu «con người toàn diện là con người có cả đức và tài (vừa hồng vừa chuyên)», trong đó đức là gốc. Theo Hồ Chí Minh, con người xã hội chủ nghĩa vừa «hồng» (đạo đức, lập trường) vừa «chuyên» (tài năng, chuyên môn). ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Vừa tài vừa trí» không phải cách diễn đạt chuẩn; thiếu vế «hồng» (đức) vốn là gốc.","","«Nhân, lễ, nghĩa, trí, tín» là các đức tính của Nho giáo, không phải mô hình con người xã hội chủ nghĩa theo Hồ Chí Minh.","«Cần, kiệm, liêm, chính, chí công vô tư» là yêu cầu cơ bản của đạo đức cách mạng (một vế «hồng»), chưa nêu đủ cả đức lẫn tài."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục V.4 (vấn đề con người trong sự nghiệp cách mạng ở Việt Nam)","c":4,"v":"khớp"},{"q":"Theo V.I.Lênin, vật chất có mấy hình thức tồn tại?","o":["1","2","3","4"],"a":[1],"e":"V.I. Lênin khẳng định trong thế giới không có gì ngoài vật chất đang vận động, và vật chất vận động không thể ở ngoài không gian và thời gian. Không gian và thời gian là hai thuộc tính, hai hình thức tồn tại của vật chất vận động. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Chỉ nêu 1 là thiếu: có đủ cả không gian lẫn thời gian.","","3 là thừa: giáo trình chỉ nêu hai hình thức tồn tại (không gian, thời gian).","4 là thừa; vận động là phương thức tồn tại, không tính vào hai hình thức này."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.2, mục I.1","c":2,"v":"khớp"},{"q":"Chọn câu trả lời sai. Trong một hình thái kinh tế xã hội, lực lượng sản xuất có các vai trò sau đây:","o":["Là nền tảng vật chất- kỹ thuật của xã hội","Tiêu biểu cho bộ mặt xã hội ở mỗi giai đoạn phát triển","Là nhân tố, xét đến củng, quyết định sự hình thành và phát triển của mọi xã hội","Thể hiện năng lực chinh phục tự nhiên của con người"],"a":[1],"e":"Câu hỏi tìm câu SAI. Giáo trình viết lực lượng sản xuất là nền tảng vật chất của xã hội, tiêu chuẩn khách quan để phân biệt các thời đại kinh tế, yếu tố xét đến cùng quyết định sự vận động, phát triển của hình thái kinh tế - xã hội; đồng thời thể hiện năng lực thực tế chinh phục tự nhiên. Cụm «tiêu biểu cho bộ mặt...» trong giáo trình được dùng cho kiến trúc thượng tầng («bộ mặt tinh thần»), nên B là câu sai. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Đúng: lực lượng sản xuất là nền tảng vật chất - kỹ thuật của xã hội.","","Đúng theo hướng «xét đến cùng quyết định sự vận động, phát triển» của hình thái kinh tế - xã hội (đề nói «mọi xã hội»).","Đúng: lực lượng sản xuất thể hiện năng lực thực tế của con người trong cải biến, chinh phục tự nhiên."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục I.2 và I.4","c":3,"v":"dễ nhầm","k":"Giáo trình 2021 không có nguyên văn cả 4 phương án; B bị chọn là sai vì cụm «bộ mặt» gắn với kiến trúc thượng tầng, còn quan hệ sản xuất mới là «tiêu chuẩn quan trọng nhất để phân biệt bản chất các chế độ xã hội». Ý B không sai hẳn trong một số giáo trình cũ nên dễ nhầm.","id":"498xjo"},{"q":"Từ phương diện chính trị và xã hội, nhà nước thực hiện mấy chức năng?","o":["2","3","4","5"],"a":[0],"e":"Giáo trình viết nhà nước thực hiện nhiều chức năng, trong đó có hai chức năng xét theo phương diện chính trị - xã hội: chức năng thống trị chính trị của giai cấp và chức năng xã hội (bên cạnh cặp đối nội - đối ngoại). Vì vậy đáp án là 2. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","3 không đúng: không có chức năng thứ ba trong cách chia chính trị - xã hội.","4 không đúng; nhầm với việc cộng cả hai cặp chức năng (thống trị - xã hội, đối nội - đối ngoại).","5 không có căn cứ trong giáo trình."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục III.1 (d. Chức năng cơ bản của nhà nước)","c":3,"v":"khớp"},{"q":"Trong xã hội nào, với sự tồn tại của cộng đồng thị tộc, bộ lạc, chưa có nhà nước với tư cách là cơ quan quyền lực của giai cấp?","o":["Phong kiến.","Cộng sản nguyên thủy.","Chiếm hữu nô lệ.","Tư bàn chủ nghĩa."],"a":[1],"e":"Giáo trình nêu trong xã hội nguyên thủy, với sự tồn tại của cộng đồng thị tộc, bộ lạc, chưa có nhà nước với tư cách là cơ quan quyền lực của giai cấp; xã hội tồn tại theo thể chế tự quản. Nhà nước chỉ xuất hiện khi có tư hữu và phân hóa giai cấp. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Xã hội phong kiến đã có giai cấp và nhà nước phong kiến.","","Xã hội chiếm hữu nô lệ đã có giai cấp đối kháng và nhà nước chủ nô.","Xã hội tư bản chủ nghĩa có nhà nước tư sản."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục III.1","c":3,"v":"khớp"},{"q":"Nguyên nhân nào dẫn đến việc cộng đồng nhân loại chưa hình thành rõ nét và vẫn để nhân loại chưa được thực sự đặt ra trong xã hội cộng sản nguyên thủy?","o":["Vì trong xã hội này con người mới tách khỏi giới động vật","Vì trong xã hội này trình độ phát triển về mọi mặt còn rất lạc hậu","Vì trong xã hội này các cộng đông người tạo lập được các mối liên hệ rộng rãi","Vì trong xã hội này tồn tại chế độ đẳng cấp cực đoan, chế độ phân biệt chủng tộc"],"a":[1],"e":"Giáo trình giải thích: trong xã hội cộng sản nguyên thủy, trình độ phát triển về mọi mặt, đặc biệt là sản xuất vật chất, còn rất lạc hậu nên các cộng đồng người sống biệt lập, chưa tạo lập được các mối liên hệ rộng rãi; vì thế cộng đồng nhân loại chưa hình thành rõ nét. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Con người mới tách khỏi giới động vật» là một vế nêu trong giáo trình nhưng đề hỏi nguyên nhân bao quát nhất là trình độ phát triển lạc hậu về mọi mặt.","","Ngược lại: các cộng đồng nguyên thủy không tạo lập được mối liên hệ rộng rãi.","Chế độ đẳng cấp cực đoan, phân biệt chủng tộc là của các xã hội có giai cấp về sau, không phải của xã hội nguyên thủy."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục II.3 (giai cấp - dân tộc - nhân loại)","c":3,"v":"khớp","k":"A cũng là một vế được nêu trong giáo trình nên dễ nhầm; B là phương án bao quát hơn.","id":"1a5qics"},{"q":"Theo quan điểm của Các Mác, học thuyết của các ông là một học thuyết có tính chất gì?","o":["Tuyệt đối đúng","Hoàn thiện","Đóng kín","Mở"],"a":[3],"e":"Giáo trình khẳng định triết học Mác là một hệ thống mở, luôn được bổ sung, phát triển bởi thành tựu khoa học và thực tiễn, không được coi là giáo điều; Lênin cũng nói chủ nghĩa Mác không phải học thuyết đóng kín và cứng nhắc. Vậy tính chất của học thuyết là mở. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Không có học thuyết nào «tuyệt đối đúng»; chân lý mang tính tương đối và được bổ sung theo thực tiễn.","«Hoàn thiện» trái với tính chất liên tục được bổ sung, phát triển.","«Đóng kín» bị Lênin bác bỏ: chủ nghĩa Mác không phải học thuyết đóng kín, cứng nhắc.",""],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.1, mục II","c":1,"v":"khớp"},{"q":"Lý luận nhận thức ra đời để trả lời câu hỏi nào dưới đây? (Lựa chọn phương án đúng nhất)","o":["Con người có phải do thần linh tạo nên hay không.","Con người có thể nhận thức được thế giới hay không.","Con người là thực thể xã hội - sinh học.","Bản nguyên của thế giới là vật chất hay ý thức."],"a":[1],"e":"Lý luận nhận thức gắn với mặt thứ hai của vấn đề cơ bản của triết học: con người có khả năng nhận thức được thế giới hay không. Triết học Mác - Lênin trả lời khẳng định, theo thuyết khả tri. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Câu hỏi về nguồn gốc con người do thần linh hay không thuộc nhân loại học và tôn giáo, không phải câu hỏi của lý luận nhận thức.","","Con người là thực thể xã hội - sinh học là vấn đề triết học về con người.","Đó là mặt thứ nhất của vấn đề cơ bản (vật chất hay ý thức có trước), thuộc bản thể luận."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.1, mục I.2.1 và I.2.3; Ch.2, mục III.2","c":2,"v":"dễ nhầm","k":"Giáo trình không có câu nguyên văn «lý luận nhận thức ra đời để trả lời...»; đáp án B suy ra từ mặt thứ hai của vấn đề cơ bản."},{"q":"Khái niệm nào dùng để chỉ khoảng giới hạn trong đó sự thay đổi về lượng chưa dẫn đến sự thay đổi căn bản chất của sự vật ấy?","o":["Chất","Lượng","Độ","Điểm nút"],"a":[2],"e":"Giáo trình định nghĩa độ là giới hạn tồn tại của sự vật, hiện tượng mà trong đó sự thay đổi về lượng chưa dẫn đến sự thay đổi về chất; sự vật vẫn là nó. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Chất là tính quy định khách quan vốn có của sự vật, không phải khoảng giới hạn.","Lượng là quy mô, trình độ, nhịp điệu... của sự vật, không phải khoảng giới hạn.","","Điểm nút là điểm giới hạn mà tại đó lượng đổi làm phá vỡ độ cũ; độ được giới hạn bởi hai điểm nút."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.2, mục II.2 (quy luật lượng - chất)","c":2,"v":"khớp","k":"Trùng nội dung với câu 408.","id":"e47trv"},{"q":"Phủ định siêu hình là sự phủ định như thế nào?","o":["Làm cho sự vật thay đổi hình thái","Làm xuất hiện sự vật mới","Tạo ra điều kiện, tiền đề cho sự phát triển","Thủ tiêu hoàn toàn sự vật cũ"],"a":[3],"e":"Giáo trình nêu sự phát triển không thể là sự phủ định tuyệt đối, phủ định sạch trơn, còn phủ định biện chứng là sự phủ định làm tiền đề, tạo điều kiện cho phát triển. Phủ định siêu hình (phủ định sạch trơn) là thủ tiêu hoàn toàn cái cũ, không kế thừa. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Làm thay đổi hình thái chưa nói lên tính chất thủ tiêu hoàn toàn; đây không phải đặc trưng của phủ định siêu hình.","Làm xuất hiện sự vật mới là kết quả của phủ định biện chứng.","Tạo ra điều kiện, tiền đề cho sự phát triển chính là đặc trưng của phủ định biện chứng.",""],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.2, mục II.2 (quy luật phủ định của phủ định)","c":2,"v":"khớp","k":"Giáo trình 2021 dùng cụm «phủ định tuyệt đối, phủ định sạch trơn»; thuật ngữ «phủ định siêu hình» có thể không xuất hiện nguyên văn."},{"q":"Theo quan điểm của các nhà sáng lập chú nghĩa Mắc, hiện tượng tha hóa của con người là một hiện tượng lịch sử đặc thù, chỉ diễn ra trong những xã hội nào và nguyên nhân nào gây nên hiện tượng tha hóa? (lựa chọn hai đáp án)","o":["Xã hội có sự phân chia giai cấp","Xã hội có sự phân chia lãnh thổ và nhà nước","Chế độ tư hữu về tư liệu sản xuất không còn","Chế độ tư hữu về tư liệu sản xuất"],"a":[0,3],"e":"Giáo trình viết: theo các nhà sáng lập chủ nghĩa Mác, tha hóa là hiện tượng lịch sử đặc thù, chỉ diễn ra trong xã hội có phân chia giai cấp; nguyên nhân là chế độ tư hữu về tư liệu sản xuất (lên cao nhất trong chủ nghĩa tư bản). ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Phân chia lãnh thổ và nhà nước là đặc trưng của nhà nước, không phải điều kiện hay nguyên nhân của tha hóa.","Ngược lại: chính chế độ tư hữu về tư liệu sản xuất gây ra tha hóa; khi nó không còn thì cơ sở của tha hóa mất đi.",""],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục V.2","c":3,"v":"khớp","id":"19k312r"},{"q":"Theo quan điểm của chủ nghĩa duy vật biện chứng, luận điểm nào sau đây chưa đúng?","o":["Một nguyên nhân chỉ có thể đưa đến một kết quả","Nguyên nhân khác nhau cũng có thể đưa đến kết quả như nhau","Nguyên nhân giống nhau trong điều kiện giống nhau luôn luôn đưa đến kết quả như nhau","Nguyên nhân khác nhau thì đưa ra kết quả không giống nhau"],"a":[0],"e":"Câu hỏi tìm luận điểm chưa đúng. Giáo trình nói «một nguyên nhân nhất định trong hoàn cảnh nhất định chỉ có thể gây ra một kết quả nhất định», nhưng đồng thời một kết quả có thể do nhiều nguyên nhân sinh ra. Đề chọn A vì «chỉ có thể đưa đến một kết quả» bỏ điều kiện «trong hoàn cảnh nhất định», tức tuyệt đối hóa. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Phù hợp với việc một kết quả có thể do nhiều nguyên nhân sinh ra.","Đúng với nguyên tắc quyết định luận: cùng nguyên nhân, cùng điều kiện thì cùng kết quả.","Đề coi là đúng; giáo trình chỉ nêu nguyên nhân càng ít khác nhau thì kết quả càng ít khác nhau (cách nói của D hơi tuyệt đối)."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.2, mục II.2 (cặp phạm trù nguyên nhân - kết quả)","c":2,"v":"nghi vấn","k":"nghi vấn: Giáo trình 2021 có câu «một nguyên nhân nhất định trong hoàn cảnh nhất định chỉ có thể gây ra một kết quả nhất định», nên A có thể bị coi là đúng nếu bỏ qua điều kiện; D cũng tuyệt đối hóa. Đáp án A của đề chỉ chắc nếu đọc đề theo nghĩa «một nguyên nhân nói chung chỉ gây một kết quả».","id":"tz4qrd"},{"q":"Phép biện chứng duy vật có hai nguyên lý cơ bản là:","o":["Nguyên lý về mối liên hệ khách quan và nguyên lý về mối liên hệ chủ quan","Nguyên lý về mối liên hệ phổ biến và nguyên lý về sự phát triển","Nguyên lý về mối liên hệ vật chất và nguyên lý về mối liên hệ tinh thần."],"a":[1],"e":"Giáo trình nêu nội dung phép biện chứng duy vật gồm hai nguyên lý, sáu cặp phạm trù và ba quy luật cơ bản; hai nguyên lý là nguyên lý về mối liên hệ phổ biến và nguyên lý về sự phát triển. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Không có nguyên lý «mối liên hệ chủ quan»; mối liên hệ được xét là khách quan, phổ biến.","","Không có nguyên lý «liên hệ vật chất» và «liên hệ tinh thần» trong phép biện chứng duy vật."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.2, mục II.2 (a. Hai nguyên lý)","c":2,"v":"khớp","k":"Đề chỉ có 3 phương án A, B, C (thiếu D).","id":"lxkrea"},{"q":"Theo V.I.Lênin, để có quan niệm đúng, vững chắc về sự phát triển của các hình thái kinh tế - xã hội là một quá trình lịch sử - tự nhiên thì cần phải:","o":["Quy những mối quan hệ xã hội vào những quan hệ sản xuất","Quy những quan hệ sản xuất vào các quan hệ chính trị, pháp luật","Quy những quan hệ xã hội vào những quan hệ sản xuất và quy những quan hệ sản xuất vào trình độ phát triển của kỹ thuật, công nghệ hiện thời","Quy những quan hệ xã hội vào những quan hệ sản xuất và quy những quan hệ sản xuất vào trình độ phát triển của lực lượng sản xuất"],"a":[3],"e":"Lênin viết: chỉ có đem quy những quan hệ xã hội vào những quan hệ sản xuất, và đem quy những quan hệ sản xuất vào trình độ của những lực lượng sản xuất, thì mới có cơ sở vững chắc để quan niệm sự phát triển của các hình thái xã hội là một quá trình lịch sử - tự nhiên. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT, bản tái bản lần 3](https://kmacle.duytan.edu.vn/uploads/75770b9b-cdbf-4038-90e2-f25e1f4426fe_triethocmaclenin.pdf))","w":["Mới là bước thứ nhất; thiếu bước quy quan hệ sản xuất vào trình độ lực lượng sản xuất.","Sai chiều: quan hệ chính trị, pháp luật thuộc kiến trúc thượng tầng, bị quy định bởi quan hệ sản xuất.","Kỹ thuật, công nghệ chỉ là một yếu tố của lực lượng sản xuất; Lênin nói «trình độ phát triển của lực lượng sản xuất».",""],"s":"V.I. Lênin, trích trong GT Triết học Mác-Lênin (bản tái bản lần 3), mục về hình thái kinh tế - xã hội; chưa đối chiếu số chương","c":3,"v":"khớp","id":"1tn1aqd"},{"q":"Vì sao nói triết học là hạt nhân của thế giới quan? Lựa chon 3 đáp án đúng.","o":["Vì bản thân triết học chính là thế giới quan","Vì thế giới quan triết học như thế nào sẽ quy định các thế giới quan và các quan niệm khác như thế","Vì triết học bao giờ cũng là thành phần quan trọng, đóng vai trò là nhân tố cốt lõi trong các thế giới quan khác","Vì triết học luôn luôn ảnh hướng và chi phối một cách tự giác đối với các loại thế giới quan"],"a":[1,2,3],"e":"Giáo trình nêu triết học là hạt nhân lý luận của thế giới quan vì: triết học là thành phần quan trọng, nhân tố cốt lõi trong các thế giới quan khác; có ảnh hưởng và chi phối các loại thế giới quan khác; và thế giới quan triết học như thế nào sẽ quy định các thế giới quan, quan niệm khác như thế. Đề chọn B, C, D. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Giáo trình 2021 thực ra có nêu ý «bản thân triết học chính là thế giới quan» ở lý do thứ nhất, nhưng đề chỉ cho chọn 3 đáp án nên loại A; cần lưu ý thế giới quan còn có huyền thoại, tôn giáo, kinh nghiệm.","","",""],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.1, mục I.1.4","c":1,"v":"nghi vấn","k":"nghi vấn: Giáo trình 2021 liệt kê 4 lý do, trong đó lý do thứ nhất đúng là «bản thân triết học chính là thế giới quan» (tức A), còn D khác nguyên văn ở chỗ giáo trình viết triết học chi phối «dù có thể không tự giác», đề lại viết «một cách tự giác». Đề yêu cầu chọn 3 nên đáp án B, C, D không khớp hoàn toàn giáo trình.","id":"rgphic"},{"q":"Đâu là biểu hiện thứ hai của hiện tượng tha hóa con người?","o":["Quan hệ giữa người với người dẫn mất đạo đức và nhân cách.","Quan hệ giữa người với người bị thay thế bởi quan hệ giữa người và vật.","Quan hệ giữa người với người bị thay thế bởi tiền với tiền.","Quan hệ giữa người với người ngày càng biến chất và vụ lợi."],"a":[1],"e":"Giáo trình viết: quan hệ giữa người với người đã bị thay thế bằng quan hệ giữa người với vật (thông qua sản phẩm lao động và tiền công); đó là biểu hiện thứ hai của tha hóa. Biểu hiện đầu tiên là lao động của con người trở thành hoạt động của con vật. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Mất đạo đức, nhân cách» là hệ quả diễn giải thêm, không phải biểu hiện thứ hai theo giáo trình.","","Không phải: giáo trình nói thay bằng quan hệ giữa người với vật, không phải «tiền với tiền».","«Biến chất và vụ lợi» là cách nói chung chung, không phải biểu hiện được nêu."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục V.2","c":3,"v":"khớp","id":"y02d25"},{"q":"Vấn đề cơ bản của triết học trà lời câu hỏi lớn nào?","o":["Mặt thứ nhất: giữa vật chất và ý thức cái nào có trước, cái nào có sau, cái nào quyết định cái nào?","Mặt thứ hai: con người có khả năng nhận thức được thế giới hay không?","Mặt thứ nhất: Khi tìm ra nguyên nhân cuối cùng của sự vận động vật chất là cái quyết định là đúng hay sai?","Mặt thứ hai: Con người về cơ bản có thể nhận thức được toàn bộ các sự vật hiện tượng hay không?"],"a":[0,1],"e":"Giáo trình: vấn đề cơ bản của triết học có hai mặt. Mặt thứ nhất: giữa ý thức và vật chất cái nào có trước, cái nào có sau, cái nào quyết định cái nào. Mặt thứ hai: con người có khả năng nhận thức được thế giới hay không. Đề chọn A, B. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","","Bóp méo mặt thứ nhất: biến thành câu hỏi đúng - sai về «nguyên nhân cuối cùng của sự vận động vật chất».","Bóp méo mặt thứ hai: giáo trình hỏi con người có nhận thức được thế giới hay không, không phải «toàn bộ các sự vật hiện tượng»."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.1, mục I.2.1","c":1,"v":"khớp","id":"1qwjbum"},{"q":"Theo quan niệm duy vật biện chứng về lịch sử thì cơ sở hạ tầng và kiến trúc thượng tầng là hai mặt cơ bản của đời sống xã hội. Cơ sở hạ tầng đóng vai trò gì đối với kiến trúc thượng tầng?","o":["Chi phối","Chủ đạo","Quyết định","Thống trị"],"a":[2],"e":"Theo chủ nghĩa duy vật lịch sử, cơ sở hạ tầng quyết định kiến trúc thượng tầng; kiến trúc thượng tầng có tác động trở lại to lớn đối với cơ sở hạ tầng. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Chi phối» không phải thuật ngữ chuẩn, chưa nêu vai trò quyết định.","«Chủ đạo» không phải thuật ngữ dùng cho quan hệ này.","","«Thống trị» là vai trò của giai cấp/nhà nước, không phải của cơ sở hạ tầng đối với kiến trúc thượng tầng."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục I.3","c":3,"v":"khớp","id":"wk1bf"},{"q":"Lý luận hình thái kinh tế - xã hội là cơ sở khoa học để:","o":["Giài thích đầy đủ mọi hiện tượng xã hội","Giải thích chính xác và đầy đủ mọi hiện tượng xã hội","Xác lập phương pháp luận khoa học chung nhất để giải thích các hiện tượng xã hội","Xác lập phương pháp luận chung nhất ở tầm \"duy nhất khoa học\" cho mọi quá trình nghiên cứu"],"a":[2],"e":"Giáo trình nêu học thuyết hình thái kinh tế - xã hội là phương pháp luận khoa học để nhận thức, cải tạo xã hội và là cơ sở thế giới quan, phương pháp luận khoa học cho đường lối, chính sách. Do đó nó là cơ sở để xác lập phương pháp luận khoa học chung để giải thích các hiện tượng xã hội, không phải để giải thích mọi hiện tượng. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Đầy đủ mọi hiện tượng» là tuyệt đối hóa.","«Chính xác và đầy đủ mọi hiện tượng» là tuyệt đối hóa.","","«Duy nhất khoa học» cho mọi quá trình nghiên cứu là tuyệt đối hóa; học thuyết là phương pháp luận chung, không thay các khoa học cụ thể."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục I","c":3,"v":"dễ nhầm","k":"Cụm «phương pháp luận khoa học chung nhất» không có nguyên văn trong giáo trình 2021; đáp án C đúng theo tinh thần không tuyệt đối hóa.","id":"18gs4u"},{"q":"Điền vào chỗ trống: \"... là một phạm trù triết học dùng để chỉ thực tại khách quan được đem lại cho con người trong cảm giác, được cảm giác của chúng ta chép lại, chụp lại, phản ánh, và tồn tại không lệ thuộc vào cảm giác\"","o":["Vật chất","Ý thức","Năng lực","Thế giới"],"a":[0],"e":"Đây là định nghĩa vật chất của Lênin: vật chất là phạm trù triết học dùng để chỉ thực tại khách quan được đem lại cho con người trong cảm giác, được cảm giác của chúng ta chép lại, chụp lại, phản ánh, và tồn tại không lệ thuộc vào cảm giác. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Ý thức là sự phản ánh thế giới khách quan, là hình ảnh chủ quan, phụ thuộc vào vật chất.","Năng lực không phải phạm trù triết học được định nghĩa như vậy.","«Thế giới» là khái niệm rộng, không phải định nghĩa của Lênin về vật chất."],"s":"V.I. Lênin, «Chủ nghĩa duy vật và chủ nghĩa kinh nghiệm phê phán», trích trong GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.2, mục I.1","c":2,"v":"khớp","id":"1w1wsie"},{"q":"\"Triết học\" là thuật ngữ được sử dụng lần đầu tiên trong trường phái nào?","o":["Socrates","Heraclitus","Thales","C. Mac"],"a":[0],"e":"Giáo trình viết: «Triết học» là thuật ngữ được sử dụng lần đầu tiên trong trường phái Socrates (Xôcrát); còn thuật ngữ «triết gia» (Philosophos) đầu tiên xuất hiện ở Heraclitus. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Heraclitus được giáo trình gắn với thuật ngữ «triết gia», không phải «triết học».","Thales là triết gia Hy Lạp cổ đại đầu tiên nhưng giáo trình không gắn thuật ngữ «triết học» với ông.","C. Mác sống ở thế kỷ XIX, rất lâu sau khi thuật ngữ ra đời."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.1, mục I.1.1","c":1,"v":"dễ nhầm","k":"Đáp án A khớp giáo trình 2021 (và cũng khớp câu 584 về «triết gia» - Heraclitus). Cách nói phổ biến khác gắn thuật ngữ philosophia với Pythagoras, nên cần thi theo giáo trình."},{"q":"C.Mác và Ph.Ăngghen là người nước nào?","o":["Đức","Áo","Liên Xô","Tiệp Khắc"],"a":[0],"e":"Giáo trình ghi C. Mác sinh ngày 5-5-1818 tại Trier, Vương quốc Phổ; Ph. Ăngghen sinh ngày 28-11-1820 ở Bácmen, tỉnh Ranh (Phổ). Cả hai đều là người Đức. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Áo không phải quê hương của hai ông.","Liên Xô thành lập năm 1922, sau khi cả hai đã qua đời.","Tiệp Khắc hình thành năm 1918, sau khi Mác (mất 1883) và Ăngghen (mất 1895) qua đời, cũng không phải quê hương hai ông."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.1, mục II.1","c":4,"v":"khớp"},{"q":"Những phát minh nào của khoa học tự nhiên đã ảnh hưởng đến sự phát triển của chủ nghĩa duy vật biện chứng?","o":["Định luật bảo toàn và chuyển hóa năng lượng","Thuyết tế bào","Thuyết tiến hóa của Charles Darwin","Lý thuyết về tương đối của Albert Einstein"],"a":[0,1,2],"e":"Giáo trình nêu ba phát minh của khoa học tự nhiên giữa thế kỷ XIX là tiền đề khoa học tự nhiên của triết học Mác: định luật bảo toàn và chuyển hóa năng lượng, thuyết tế bào và thuyết tiến hóa của Đácuyn. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","","","Thuyết tương đối của Anhxtanh ra đời đầu thế kỷ XX, sau khi triết học Mác hình thành, nên không phải tiền đề ban đầu."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.1, mục II.1","c":1,"v":"khớp"},{"q":"Thế giới quan duy vật biện chứng bao gồm:","o":["Tri thức khoa học, niềm tin khoa học và lý tưởng cách mạng","Tri thức khoa học, tiềm tin khoa học và hệ giá trị cộng đồng","Tri thức khoa học, tình cảm khoa học và lý tưởng khoa học","Tri thức khoa học, niềm tin khoa học và lý tưởng khoa học"],"a":[0],"e":"Giáo trình viết: thế giới quan duy vật biện chứng bao gồm tri thức khoa học, niềm tin khoa học và lý tưởng cách mạng. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","«Hệ giá trị cộng đồng» không thuộc cấu trúc này.","«Tình cảm khoa học» không phải thuật ngữ trong cấu trúc.","Sai ở vế cuối: là «lý tưởng cách mạng», không phải «lý tưởng khoa học»."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.1, mục I.1.4","c":1,"v":"khớp"},{"q":"Cái bàn cái ghế là vật chất. Đây là quan niệm của các nhà triết học thời kỳ nào?","o":["Duy vật chất phác thời cổ đại","Duy tâm chất phác thời cổ đại","Duy vật trung đại","Duy tâm trung đại"],"a":[0],"e":"Chủ nghĩa duy vật chất phác thời Cổ đại thừa nhận tính thứ nhất của vật chất nhưng đồng nhất vật chất với một hay một số chất cụ thể; quan niệm coi vật chất là các vật thể cụ thể như cái bàn, cái ghế là cách hiểu trực quan, chất phác của thời kỳ này. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Duy tâm cổ đại coi tinh thần, ý niệm là bản nguyên chứ không coi vật thể là vật chất.","Giáo trình chỉ nêu ba hình thức của chủ nghĩa duy vật: chất phác, siêu hình, biện chứng; không có hình thức «duy vật trung đại».","Duy tâm trung đại đặt nền tảng ở thần học, không coi bàn ghế là vật chất."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.1, mục I.2.2","c":2,"v":"dễ nhầm","k":"Giáo trình không nhắc ví dụ «cái bàn cái ghế»; đáp án suy ra từ việc đồng nhất vật chất với vật thể cụ thể."},{"q":"Phép biện chứng là phương pháp nghiên cứu, khái quát thế giới thành hệ thống các nguyên lý, quy luật là phép biện chứng gì?","o":["Biện chứng chủ quan","Biện chứng khách quan","Siêu hình học","Ý muốn con người"],"a":[0],"e":"Giáo trình chia biện chứng thành biện chứng khách quan (biện chứng của bản thân thế giới) và biện chứng chủ quan (tư duy biện chứng, phản ánh biện chứng khách quan). Phép biện chứng với hệ thống nguyên lý, quy luật khái quát của tư duy là biện chứng chủ quan. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Biện chứng khách quan là biện chứng của bản thân thế giới tồn tại độc lập với ý thức, không phải phương pháp nghiên cứu.","Siêu hình học là phương pháp đối lập với phép biện chứng.","«Ý muốn con người» không phải loại hình biện chứng."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.2, mục II.1","c":2,"v":"khớp"},{"q":"Quan điểm toàn diện đặt ra yêu cầu phải xem xét tất cả các mối liên hệ của sự vật để làm gì?","o":["Chống quan điểm siêu hình","Chống quan điểm duy tâm","Chống quan điểm chủ nghĩa chiết trung và thuyết ngụy biện","Đề phòng cho chúng ta khỏi phạm sai lầm và sự cứng nhắc"],"a":[3],"e":"Quan điểm toàn diện yêu cầu xem xét tất cả mặt, mối liên hệ của sự vật, đối lập với quan điểm phiến diện, một chiều, tránh ngụy biện và chủ nghĩa chiết trung. Cách diễn đạt «đề phòng sai lầm và sự cứng nhắc» là lời Lênin về tính toàn diện, nên đề chọn D. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Chống siêu hình là ý nghĩa gián tiếp, không phải mục đích trực tiếp của đề.","Quan điểm toàn diện không nhằm «chống duy tâm».","Chống chủ nghĩa chiết trung và ngụy biện cũng là một yêu cầu trong giáo trình, nhưng đề chọn D theo cách nói của Lênin.",""],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.2, mục II.2 (nguyên lý về mối liên hệ phổ biến)","c":2,"v":"dễ nhầm","k":"Giáo trình 2021 có nguyên văn ý ở C (tránh ngụy biện, chiết trung), còn D là lời Lênin về tính toàn diện (chưa kiểm nguyên văn trực tuyến); A, C cũng không sai nên dễ nhầm."},{"q":"Theo quan điểm của triết học Mác - Lênin, trong ba mặt của quan hệ sản xuất thì mặt nào quyết định nhất?","o":["Quan hệ tổ chức, quản lý","Tất cả các quan hệ có vị trí ngang nhau","Quan hệ phân phối sản phẩm","Quan hệ sở hữu tư liệu sản xuất"],"a":[3],"e":"Trong quan hệ sản xuất, quan hệ sở hữu về tư liệu sản xuất là quan hệ xuất phát, cơ bản, trung tâm, luôn có vai trò quyết định các quan hệ khác (tổ chức quản lý, phân phối sản phẩm). ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quan hệ tổ chức, quản lý bị quan hệ sở hữu quy định.","Ba mặt không ngang nhau: quan hệ sở hữu quyết định hai mặt còn lại.","Quan hệ phân phối sản phẩm cũng bị quan hệ sở hữu quy định.",""],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục I.2","c":3,"v":"khớp"},{"q":"“Phát triển diễn ra theo còn đường tròn khép kín, là sự lặp lại đơn thuần cái cũ”. Luận điểm này thuộc lập trường triết học nào?","o":["Quan điểm duy vật biện chứng","Quan điểm siêu hình","Quan điểm biện chứng duy tâm","Quan điểm duy tâm khách quan"],"a":[1],"e":"Quan điểm siêu hình nhận thức đối tượng ở trạng thái tĩnh, coi biến đổi chỉ là biến đổi về số lượng và nguyên nhân nằm bên ngoài. Phát triển theo vòng tròn khép kín, lặp lại đơn thuần là quan điểm siêu hình; trong khi phát triển biện chứng theo đường xoáy ốc, có kế thừa và nâng cao. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Quan điểm duy vật biện chứng coi phát triển theo đường xoáy ốc, không phải vòng tròn khép kín.","","Biện chứng duy tâm (như Hêghen) vẫn thừa nhận phát triển biện chứng, không phải vòng tròn lặp lại.","Đề hỏi về lập trường biện chứng/siêu hình, không về duy tâm khách quan."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.1, mục I.3 và Ch.2, mục II.2","c":2,"v":"khớp"},{"q":"Con chó, con mèo có ý thức không?","o":["Có. Vì nó được con người dạy","Không. Vì nó không được dạy","Có. Vì nó được rèn luyện qua quá trình tiếp xúc với con người","Không. Vì nó chỉ có bản năng"],"a":[3],"e":"Giáo trình viết tâm lý động vật chưa phải là ý thức mà vẫn là trình độ phản ánh mang tính bản năng, xuất phát từ nhu cầu sinh lý tự nhiên của cơ thể. Ý thức chỉ có ở con người; con chó, con mèo không có ý thức vì chúng chỉ có bản năng. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Được con người dạy không làm cho động vật có ý thức; chỉ là tập tính, phản xạ có điều kiện.","Sai lý do: không phải vì «không được dạy» mà vì chỉ có tâm lý, bản năng.","Rèn luyện qua tiếp xúc với con người không biến tâm lý động vật thành ý thức.",""],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.2, mục I.2","c":2,"v":"khớp"},{"q":"Theo chủ nghĩa duy vật lịch sử, sự tác động trở lại đối với tồn tại xã hội của các hình thái ý thức xã hội mạnh hay yếu còn phụ thuộc vào yếu tố nào? Chọn 3 đáp án đúng.","o":["Những điều kiện lịch sử cụ thể","Vai trò lịch sử của giai cấp đại diện cho ngọn cờ tư tưởng đó","Trình độ phản ánh và sức lan tỏa của ý thức đối với các nhu cầu khác nhau của sự phát triển xã hội","Các quan hệ chính trị vốn là cơ sở hình thành các hình thái ý thức xã hội"],"a":[0,1,2],"e":"Giáo trình viết sự tác động trở lại của các hình thái ý thức xã hội mạnh hay yếu còn phụ thuộc vào điều kiện lịch sử cụ thể, các quan hệ kinh tế vốn là cơ sở hình thành chúng, trình độ phản ánh và sức lan tỏa của ý thức, và vai trò lịch sử của giai cấp đại diện cho ngọn cờ tư tưởng đó. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","","","Giáo trình nêu «các quan hệ kinh tế» là cơ sở hình thành các hình thái ý thức xã hội; D đổi thành «quan hệ chính trị»."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục IV.2","c":3,"v":"khớp"},{"q":"Nhận định nào sau đây SAI khi khẳng định về tính thống nhất vật chất của thế giới?","o":["Thế giới vật chất không do ai sinh ra và cũng không tự mất đi","Thế giới vật chất tồn tại khách quan, có trước và độc lập với ý thức","Chỉ có một thế giới duy nhất và thống nhất là thế giới vật chất","Đa số bộ phận của thế giới có mối quan hệ vật chất thống nhất với nhau"],"a":[3],"e":"Câu hỏi tìm nhận định SAI. Giáo trình viết «mọi bộ phận của thế giới có mối quan hệ vật chất thống nhất với nhau», không phải «đa số bộ phận», nên D sai. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Đúng: thế giới vật chất không do ai sinh ra và không tự mất đi.","Đúng: thế giới vật chất tồn tại khách quan, có trước và độc lập với ý thức.","Đúng: chỉ có một thế giới duy nhất và thống nhất là thế giới vật chất.",""],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.2, mục I.1 (tính thống nhất vật chất của thế giới)","c":2,"v":"khớp"},{"q":"Tính quần chúng của tôn giáo cho thấy điều gì?","o":["Tôn giáo là một hiện tượng cứu rỗi dành cho những người yếu thế trong xã hội","Tôn giáo là một hiện tượng xã hội phổ biến ở tất cả các quốc gia, dân tộc và châu lục","Tôn giáo tồn tại trong suốt hàng nghìn năm lịch sử và được quần chúng nhân dân xây dựng và phát triển","Tôn giáo là một hiện tượng tâm linh, tín ngưỡng của các dân tộc, cộng đồng"],"a":[1],"e":"Tính quần chúng của tôn giáo thể hiện ở chỗ tôn giáo là hiện tượng xã hội phổ biến ở các dân tộc, quốc gia, châu lục, có số lượng tín đồ đông đảo, đồng thời là nơi sinh hoạt văn hóa tinh thần của một bộ phận quần chúng. ([Cứu Dương Thần Công, Bản chất, nguồn gốc, tính chất của tôn giáo](https://cuuduongthancong.com/atc/774/ban-chat,-nguon-goc-va-tinh-chat-cua-ton-giao))","w":["Cứu rỗi người yếu thế là chức năng/nguồn gốc xã hội của tôn giáo, không phải tính quần chúng.","","Thời gian tồn tại hàng nghìn năm nói về tính lịch sử, không phải tính quần chúng.","Hiện tượng tâm linh, tín ngưỡng là bản chất, không nêu tính quần chúng."],"s":"GT Chủ nghĩa xã hội khoa học (vấn đề tôn giáo); nguồn thứ cấp, chưa đối chiếu số chương","c":4,"v":"khớp"},{"q":"Vì sao lại nói kiểu nhà nước vô sản là kiểu nhà nước \"đặc biệt\" ?","o":["Là nhà nước của số đông thống trị số ít","Là nhà nước của giai cấp công nhân và nông dân cùng làm chủ","Là nhà nước hiếm hoi đứng về nhân dân lao động","Là nhà nước gắn liền với lợi ích của giai cấp bị bóc lột"],"a":[0],"e":"Giáo trình viết kiểu nhà nước vô sản là kiểu nhà nước «đặc biệt», là nhà nước của số đông thống trị số ít; giai cấp vô sản liên minh với nông dân, trí thức tiến bộ và nhân dân lao động thiết lập nền chuyên chính của mình. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Cùng làm chủ của công nhân và nông dân là cách nói hẹp, không nêu được điểm «đặc biệt»: đa số thống trị thiểu số.","«Hiếm hoi» không phải lý do về bản chất.","Chưa đầy đủ: nhà nước vô sản đại diện lợi ích của số đông nhân dân lao động, không chỉ của giai cấp bị bóc lột."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục III.1","c":4,"v":"khớp"},{"q":"Yếu tố nào là cơ sở cho mọi liên hệ?","o":["Tính thống nhất vật chất của xã hội","Tính thống nhất giữa tôn giáo và xã hội","Tính thống nhất vật chất của thế giới","Tính chất xã hội và tôn giáo"],"a":[2],"e":"Giáo trình viết tính thống nhất vật chất của thế giới là cơ sở cho mọi liên hệ; nhờ đó các đối tượng không tồn tại cô lập mà tác động qua lại, chuyển hóa lẫn nhau. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Tính thống nhất vật chất của xã hội quá hẹp, chỉ là một bộ phận của thế giới.","Thống nhất giữa tôn giáo và xã hội không phải cơ sở của mọi liên hệ.","","Tính chất xã hội và tôn giáo không phải cơ sở của mọi mối liên hệ."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.2, mục II.2 (nguyên lý về mối liên hệ phổ biến)","c":2,"v":"khớp"},{"q":"Ai là đại diện tiêu biểu cho trường phái nhị nguyên luận?","o":["Descartes","Socrates","Heraclitus","Thales"],"a":[0],"e":"Giáo trình nêu những học thuyết giải thích thế giới bằng cả hai bản nguyên vật chất và tinh thần được gọi là nhị nguyên luận, điển hình là Descartes (Đề-các-tơ). ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Socrates nổi tiếng về phương pháp biện luận, không phải nhị nguyên luận.","Heraclitus là nhà biện chứng cổ đại, thường gắn với duy vật.","Thales là triết gia duy vật cổ đại (nước là bản nguyên)."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.1, mục I.2.2","c":1,"v":"khớp","id":"1rh4tu3"},{"q":"Lựa chọn cụm từ đúng điền vào chỗ trống. \"Trong tính . . . của nó, bản chất con người là . . . những quan hệ xã hội\" (C. Mác và Ph. Ăngghen. Toàn tập, t.13, tr.11)","o":["Hiện thực; tổng hòa","Xã hội; tổng hợp","Cụ thể; tổng thể","Tự nhiên; tổng số"],"a":[0],"e":"Mác viết: «Trong tính hiện thực của nó, bản chất của con người là tổng hòa các quan hệ xã hội» (Luận cương về Phoiơbắc). ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","«Xã hội; tổng hợp» sai cả hai cụm so với nguyên văn.","«Cụ thể; tổng thể» không đúng nguyên văn.","«Tự nhiên; tổng số» không đúng nguyên văn; bản chất con người là xã hội chứ không phải tự nhiên."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục V.1","c":3,"v":"khớp"},{"q":"Đâu là cơ sở chủ yếu nhất cho sự ra đời của triết học Mác?","o":["Thực tiễn cách mạng của giai cấp vô sản","Nguồn gốc lý luận","Tiền đề khoa học tự nhiên","Nhân tố chủ quan của C.Mác và Ph.Ăngghen"],"a":[0],"e":"Giáo trình khẳng định thực tiễn cách mạng của giai cấp vô sản là cơ sở chủ yếu nhất cho sự ra đời triết học Mác. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Nguồn gốc lý luận là điều kiện, tiền đề lý luận, không phải cơ sở chủ yếu nhất.","Tiền đề khoa học tự nhiên là điều kiện, không phải cơ sở chủ yếu nhất.","Nhân tố chủ quan (tài năng, phẩm chất của Mác - Ăngghen) là điều kiện, không phải cơ sở chủ yếu."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.1, mục II.1","c":1,"v":"khớp"},{"q":"Nguyên nhân trực tiếp dẫn tới sự xuất hiện nhà nước là do đâu?","o":["Do giai cấp thống trị trong xã hội mong muốn.","Do một đấng siêu nhiên yêu cầu.","Do mâu thuẫn giai cấp trong xã hội gay gắt không thể điều hòa được.","Do lực lượng sản xuất và quan hệ sản xuất đã phát triển."],"a":[2],"e":"Giáo trình viết nguyên nhân trực tiếp dẫn tới sự xuất hiện nhà nước là mâu thuẫn giai cấp trong xã hội gay gắt không thể điều hòa được; nguyên nhân sâu xa là sự phát triển của lực lượng sản xuất dẫn tới dư thừa của cải, xuất hiện tư hữu. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Nhà nước ra đời tất yếu khách quan, không do ý muốn chủ quan của giai cấp thống trị.","Quan điểm duy tâm, thần học, không đúng với chủ nghĩa Mác - Lênin.","","Đây là nguyên nhân sâu xa chứ không phải nguyên nhân trực tiếp."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục III.1","c":3,"v":"khớp"},{"q":"Thuật ngữ lý luận nhận thức có nguồn gốc từ trong ngôn ngữ nào?","o":["Ngôn ngữ Hy Lạp cổ","Ngôn ngữ Anh","Ngôn ngữ Nhật","Ngôn ngữ Phạn cổ"],"a":[0],"e":"Thuật ngữ lý luận nhận thức (gnoseology) có gốc Hy Lạp cổ: gnosis là tri thức, logos là lý lẽ, học thuyết. ([Học viện Đa Minh, Tri thức luận (Gnoseology)](https://hocviendaminh.com/bai-viet/triet-tay-phuong/tri-thuc-luan-gnoseology))","w":["","Tiếng Anh dùng thuật ngữ dịch về sau, không phải nguồn gốc.","Tiếng Nhật không phải nguồn gốc của thuật ngữ.","Tiếng Phạn cổ là ngôn ngữ của Ấn Độ cổ đại, không phải nguồn gốc thuật ngữ này."],"s":"Chưa đối chiếu giáo trình; nguồn thứ cấp","c":2,"v":"khớp","k":"Giáo trình Triết học Mác-Lênin không giải thích nguồn gốc ngôn ngữ của thuật ngữ này; căn cứ là nguồn tham khảo về từ nguyên."},{"q":"Những yếu tố nào đã thúc đẩy sự ra đời của triết học Mác trong bối cảnh Cách mạng công nghiệp ở Châu Âu?","o":["Sự tăng trưởng nhanh chóng của tầng lớp trung lưu với quyền lực kinh tế ngày càng lớn","Sự phát triển mạnh mẽ của lực lượng sản xuất và các mâu thuẫn xã hội gia tăng","Sự cần thiết phải có một lý thuyết mới để soi sáng vai trò của giai cấp tư sản","Sự xuất hiện của giai cấp vô sản như một lực lượng chính trị - xã hội độc lập"],"a":[1,3],"e":"Giáo trình nêu bối cảnh những năm 1840: lực lượng sản xuất phát triển rất mạnh nhờ cách mạng công nghiệp, đồng thời mâu thuẫn xã hội gay gắt hơn; sự xuất hiện của giai cấp vô sản trên vũ đài lịch sử với tính cách lực lượng chính trị - xã hội độc lập là nhân tố chính trị - xã hội quan trọng cho sự ra đời triết học Mác. Đề chọn B và D. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["Giáo trình không nêu tầng lớp trung lưu là nhân tố thúc đẩy; giai cấp tư sản lúc đó không còn là giai cấp cách mạng.","","Triết học Mác gắn với yêu cầu soi sáng thực tiễn cách mạng của giai cấp vô sản, không phải vai trò của giai cấp tư sản.",""],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.1, mục II.1","c":1,"v":"khớp"},{"q":"Nguyên nhân sâu xa của sự xuất hiện giai cấp là gì?","o":["Là sự phát triển của lực lượng sản xuất","Là sự phát triển của quan hệ sản xuất","Là sự phát triển của công cụ lao động","Là sự phát triển của phân công lao động xã hội"],"a":[0],"e":"Giáo trình kết luận nguyên nhân sâu xa của sự xuất hiện giai cấp là sự phát triển của lực lượng sản xuất (dư thừa sản phẩm, tư hữu tư liệu sản xuất). ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Quan hệ sản xuất thay đổi theo sự phát triển của lực lượng sản xuất, không phải nguyên nhân sâu xa.","Công cụ lao động chỉ là một yếu tố của lực lượng sản xuất.","Phân công lao động xã hội là nguyên nhân trực tiếp hơn, chưa phải nguyên nhân sâu xa."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.3, mục II.1","c":3,"v":"khớp"},{"q":"Nhận thức kinh nghiệm là nhận thức dựa trên sự quan sát trực tiếp các sự vật hiện tượng hay các thí nghiệm, thực nghiệm khoa học.Vì vậy, kết quả của nhận thức kinh nghiệm là những tri thức nào sau đây ?","o":["Những tri thức kinh nghiệm thông thái","Những tri thức kinh nghiệm thông thường hoặc tri thức thực nghiệm khoa học","Thuần túy là những tri thức kinh nghiệm thông thường","Những tri thức mang tính trực quan bề ngoài không bản chất"],"a":[1],"e":"Giáo trình viết nhận thức kinh nghiệm dựa trên sự quan sát trực tiếp hay thí nghiệm, thực nghiệm khoa học; kết quả là những tri thức kinh nghiệm thông thường hoặc tri thức thực nghiệm khoa học. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["«Kinh nghiệm thông thái» không phải thuật ngữ trong giáo trình.","","Chưa đủ: thiếu tri thức thực nghiệm khoa học.","Tri thức kinh nghiệm có hạn chế là bề ngoài, rời rạc nhưng đề không hỏi hạn chế mà hỏi kết quả."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.2, mục III.2","c":2,"v":"khớp"},{"q":"Thuật ngữ “triết gia” đầu tiên xuất hiện được dùng để chỉ người nghiên cứu về","o":["Bản chất của sự vật","Bản chất của thế giới","Bản chất của con người","Bản chất của thực tại khách quan"],"a":[0],"e":"Giáo trình viết thuật ngữ «triết gia» (Philosophos) đầu tiên xuất hiện ở Heraclitus, dùng để chỉ người nghiên cứu về bản chất của sự vật. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Bản chất của thế giới là cách nói khác, không phải nguyên văn.","Bản chất của con người không phải đối tượng nghiên cứu trong định nghĩa đầu tiên này.","Thực tại khách quan không phải nguyên văn giáo trình."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.1, mục I.1.1","c":1,"v":"khớp"},{"q":"Những hoạt động tâm lý diễn ra bên ngoài sự kiểm soát của ý thức, góp phần giảm bớt sự quá tải của đầu óc khi công việc lặp lại nhiều lần mà vẫn đảm bảo độ chính xác cao gọi là gì?","o":["Tiềm thức","Vô thức","Tự ý thức","Trí tuệ nhân tạo"],"a":[0],"e":"Giáo trình viết tiềm thức là những hoạt động tâm lý diễn ra bên ngoài sự kiểm soát của ý thức; khi hoạt động, tiềm thức góp phần giảm bớt sự quá tải của đầu óc khi công việc lặp lại nhiều lần mà vẫn đảm bảo độ chính xác cao. ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Vô thức là hiện tượng tâm lý không do lý trí điều khiển, thiên về bản năng, thói quen, giấc mơ; không phải chức năng giảm tải khi lặp lại công việc chính xác.","Tự ý thức là ý thức về bản thân.","Trí tuệ nhân tạo không phải khái niệm tâm lý của ý thức."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.2, mục I.2","c":2,"v":"khớp","id":"l2zaaa"},{"q":"Nguyên lý là thuật ngữ đa nghĩa khá bất định có nguồn gốc từ tiếng nào?","o":["Hy Lạp","Trung Quốc","Nga","Việt Nam"],"a":[0],"e":"Giáo trình viết nguyên lý là thuật ngữ đa nghĩa khá bất định, có nguồn gốc từ một từ Hy Lạp cổ (archē, La tinh principium) với nghĩa đen là «đầu tiên nhất». ([Giáo trình Triết học Mác-Lênin, Bộ GD&ĐT 2021](https://fbs.upt.edu.vn/wp-content/uploads/2021/06/GT-Triet-hoc-Mac-Lenin-Khong-chuyen-7.pdf))","w":["","Không phải gốc tiếng Trung Quốc.","Không phải gốc tiếng Nga.","Không phải gốc tiếng Việt."],"s":"GT Triết học Mác-Lênin (Bộ GD&ĐT, 2021), Ch.2, mục II.2 (a. Hai nguyên lý)","c":2,"v":"khớp"}];
